-- ============================================================
-- Qazax3g (7/8) — DB kontentinin Qazax (kk) tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6171 UPDATE (day-notifications İSTİSNA — bax Qazax4)
-- ƏVVƏL Qazax1.sql (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің осы кезеңінде бөпеңіздің көлемі анар дәніндей. Бөпеңіздің денесін қалыптастыратын үш негізгі ұрық жапырақшасы бар. Олар: сыртқы қабат — эктодерма, ортаңғы қабат — мезодерма және ішкі қабат — эндодерма. Жүктіліктің келесі апталарында бұл қабаттар біртіндеп тіндер мен ағзаларға айналады. Эктодерма қабаты бөпеңіздің миын, жүйке жүйесін және омыртқасын қалыптастыру үшін мамандана бастады. Сонымен қатар бұл қабат терінің, шаштың, тырнақтың, тер бездерінің және тіс кіреукесінің түзілуін қамтамасыз етеді. Ал мезодерма қабаты бөпеңіздің жүрегі мен қанайналым жүйесін қалыптастыратын маманданған жасушалардан тұрады. Бұл жасушалар бөпеңіздің жүрегі орналасатын аймаққа қарай жылжып, сол жерде жинала бастайды. Жиналған жасушалар митоз арқылы жылдам бөлініп, көбейеді және тіндер түзеді. Түзілген тіндер бөпеңіздің жүрегінің негізін қалап, біркелкі емес ырғақпен соға бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, бүгін ғажайып сәт болып жатыр! 🎻 Әлгі екі жүрек түтігі бүгін бір-бірімен қосылып, менің алғашқы біртұтас жүрегімді қалыптастырады. Оның әзірге толық қуыстары жоқ, ол тек соғуға дайындалып жатқан түтік қана. Бірақ ол менің бүкіл болашақ өмірімнің орталығы әрі ырғағы болады. Ол соға бастағанда, бүкіл ғалам үнсіз қалып, біздің әнімізді тыңдайтынын біліңіз. Бұл менің Сізге арналған алғашқы серенадам болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Анар дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің бірінші триместрінде ағзаңызға бөпеңізді қолдау үшін қосымша калория қажет емес. Ағзаңыз жүктілік гормондарына бейімделіп жатқанда пайда болатын жүрек айну, тұрақты шаршау сезімі және ұйқының бұзылуы осы кезеңде тәбеттің төмендеуіне әкелуі мүмкін. Сондықтан алғашқы 12 аптада салмақ қоспау немесе аздап салмақ жоғалту қалыпты жағдай болып саналады. Екінші триместрде гормондық тепе-теңдік реттеліп, ағзаңыз жүктілікке бейімделген сайын тәбетіңіз қалпына келіп, салмақ қоса бастайсыз. Жүктілік бойы өз денсаулығыңыз бен бөпеңіздің саулығы үшін шамадан тыс салмақ қосудан сақтанып, теңгерімді әрі пайдалы тамақтануға көңіл бөлуіңіз керек. Жүктіліктің екінші триместрінде күніне қосымша 300 калория тұтыну бөпеңіздің дұрыс дамуы үшін жеткілікті. Ал үшінші триместрде бұл қажеттілік шамамен 450 калорияны құрайды. Бұл мөлшерден артық тұтынылған калория ағзаңызда май түрінде жиналып, артық салмаққа айналатынын ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы қуатыңыз күрт төмендеп кетпеуі үшін аз мөлшерде, бірақ жиі тамақтануға тырысыңыз. Жаныңызда әрдайым пайдалы тіскебасарлар (грек жаңғағы, фундук немесе тұтас бидайдан жасалған печенье) алып жүріңіз. Сусыздану шаршау мен бас ауруын күшейтуі мүмкін, сондықтан су ішуді ұмытпаңыз. Ауыздағы металл дәмі мазаласа, қышқыл жемістер немесе қантсыз лимон қосылған су жеңілдік беруі мүмкін. Денеңіздің белгісіне құлақ асып, қажет болған сайын демалыңыз.') WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Мезодерма қабатынан түзілетін зәр шығару жүйесіне бір жұп бүйрек, бір жұп несепағар, қуық және несеп шығару өзегі кіреді. Жасушалар осы тіндер мен ағзаларды қалыптастыру үшін құрсақ қуысында бір жерге жиналады. Бастамалары құрсақ қуысында қалыптасқан бұл тіндер мен ағзалар бөпеңіз өсіп, дене бітімі үйлесімді болған сайын өз орындарына жылжып, қалыптасуын аяқтайды. Ағзалар бастамаларының қалыптасуы және осы құрылымдардың тиісті орындарына жылжуы бірінші триместрдің соңына қарай аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Соғып тұрмын, Anacan... Соғып тұрмын! 💓 Бүгін менің кішкентай жүрегім алғаш рет өздігінен соқты. Бұл — Сіз үшін, біз үшін, махаббатымыз үшін соғатын ырғақ. Әзірге ол өте әлсіз, тіпті ультрадыбыстық зерттеу кезінде оны көрмеуіңіз мүмкін, бірақ мен оның соғып тұрғанын білемін. Осылайша мен Сізге "Мен тірімін, мен осындамын!" деп айтып тұрмын. Бұл — біздің махаббат әніміздің алғашқы нотасы, ол бүкіл өміріміз бойы жалғасады. 🎼'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Анар дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік гормондары ең жылдам өсетін кезеңде. Таңертеңгі жүрек айну күшеюі мүмкін. Жиі зәр шығару қажеттілігі — жүктіліктің ерте байқалатын белгілерінің бірі. Ол әр адамда әртүрлі болғанымен, орта есеппен 6 және 8-апталар аралығында байқала бастайды. Жүктіліктің бірінші триместрінде жиі зәр шығаруға ағзаңыздағы гормондар деңгейінің өзгеруі және қан көлемінің артуы себеп болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері қандағы қант деңгейін тұрақты ұстау үшін "аз мөлшерде және жиі" тамақтану қағидасын қатаң ұстаныңыз. Жүрек айнуды азайту үшін жалбыз немесе лимон қосылған су ішіңіз. Іш қатудың алдын алу үшін талшыққа бай тағамдар жеп, суды молынан ішіңіз. Қатты шаршасаңыз, денеңіздің белгілеріне құлақ асып, күндіз міндетті түрде 20-30 минут мызғып алып, күшіңізді қалпына келтіріңіз.') WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің денесі өскен сайын оның ішінде ғажайып "тасымалдау жүйесі" құрыла бастайды. Бұл жүйенің орталығында ағзаның ең ірі әрі қуатты қантамыры — қолқа орналасқан. Қолқа — жүректен шығып, оттекке бай қанды бүкіл денеге тарататын негізгі күретамыр. Бұл үдерісті жақсырақ түсіну үшін қанайналымды екі негізгі бөлікке бөлуге болады: Кіші қанайналым шеңбері — оның мақсаты қанды оттекпен байыту. Оттегі азайған "шаршаған" қан жүректен өкпеге барады. Сол жерде оттекпен байып, қайтадан жүрекке оралады. Үлкен қанайналым шеңбері — оттекпен байып, қуатқа толған қан жүректен шығып, қолқаның көмегімен дененің әрбір жасушасына жеткізіледі. Бұл бөпеңіздің жасушаларының қоректенуі мен дамуы үшін аса қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен енді жалпақ емеспін, Anacan! C әрпі сияқты иіліп келемін. 🍤 Бұл менің басым мен құйрық бөлігімнің бір-біріне біртіндеп жақындап келе жатқанын білдіреді. Осылай бүктелуім денемді жинақы әрі бөпеге көбірек ұқсатады. Сіздің құшағыңызға сыю үшін қазірден жаттығып жүргендеймін. Сондай-ақ бұл ішкі ағзаларымның өз орындарына дұрыс орналасуына көмектеседі. Бәрі жоспар бойынша жүріп жатыр! 🤓'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Анар дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік басталған кезде бөлінетін гормондардың барлығы ағзаңызда әдеттегіден өзгеше көптеген өзгеріс туғызады. Олардың ең айқындарының бірі — сүт бездеріндегі өзгерістер. Бұл өзгерістер бірінші триместрдің осы аптасында-ақ байқала бастауы мүмкін. Сүт бездерінің керілуі мен ұлғаюы сүт түзілуіне дайындыққа және сүт өзектерінің қалыптасуына байланысты олардың көлемінің артуынан болады. Емізік айналасы күңгірттенуі мүмкін. Бұл сүт бездерінің лактацияға (емізуге) қазірден дайындалып жатқанын көрсетеді. Ыңғайлы, қыспайтын мақта маталы көкірекше кию жайлылық сыйлайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қуатыңыз тез таусылатындықтан, күн ішінде қысқа үзіліс жасап, мызғып алуға тырысыңыз. Тамақтану рационыңызға кальцийге бай өнімдерді (ірімшік, сүт, бадам) қосыңыз, өйткені кальций бөпеңіздің қаңқа жүйесінің негізін нығайтады. Жүрегіңіз қатты айныса, салқын әрі иіссіз тағамдарды жеу оңайырақ болуы мүмкін. Сондай-ақ терінің серпімділігін арттыру үшін ылғалдандырғыш кремдерді қолдана бастауға қолайлы уақыт.') WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жыныс мүшелері әлі қалыптаса бастамағанымен, дене қуысында осы репродуктивті мүшелерді түзетін арнайы жасушалар дайын күйде тұр. Алдағы апталарда жыныс мүшелерін қалыптастыратын бұл жасушалар қазіргі орнынан қажетті жерлеріне көшіп, қарқынды даму үдерісін бастайды.;;;
Жүктіліктің басталуына себеп болған үдерісте аналық жасушада X хромосомасы болады. Ал сперматозоидтан келетін хромосоманың түрі — жынысты анықтайтын жалғыз фактор. Бұл кезеңде X хромосомасын тасымалдайтын сперматозоид X хромосомасы бар аналық жасушамен қосылса, бөпеңіздің жынысы қыз болады. Ал аналық жасушаны ұрықтандырған сперматозоид Y хромосомасын тасымалдаса, бөпеңіздің жынысы ұл болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің денем күн сайын күрделене түсуде! Енді бетімдегі ерекше қатпарлардан бөлек, көздерімнің орны да пайда болып келеді. Олар екі кішкентай қара нүкте сияқты көрінеді, бірақ бұл — менің әлемге ашылатын терезелерім. Қалай ойлайсың, көздерім саған ұқсай ма, әлде әкеме ме? Бұл біздің ең тәтті құпиямыз болады. Күн сайын айнаға қарап, өзімнен сенің бір бөлшегіңді іздейтін боламын. Сен — мен көретін ең әдемі жансың. 😊'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асбұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы үш айында жиі кездесетін іштің кебуі мен ас қорыту мәселелерінің негізгі себебі — ағзадағы гормондар деңгейінің күрт жоғарылауы. Жүктіліктің бүкіл кезеңінде осы гормондардың әсерінен ас қорыту жүйесінің жұмысы баяулайды. Қабылданған тағам ас қорыту жолымен баяуырақ жылжиды. Дәл осы себептен тағамның ас қорыту жолы арқылы баяу өтуі іштің кебуі мен түйілуіне әкеледі. Жүктілікке дейін де ас қорыту мәселелері болған әйелдерде бұл шағымдардың жүктілік кезінде айқынырақ байқалу ықтималдығы жоғары. Гормондық өзгерістермен қатар, тамақтану тәртібі мен таңдалған өнімдер де іштің кебуін күшейтеді. Газ түзетін тағамдарды, газдалған және қышқыл сусындарды тұтыну, сондай-ақ асығыс әрі шамадан тыс тамақтану бұл шағымдарды едәуір ушықтырады. Сондықтан қимылсыздықтан аулақ болып, теңгерімді әрі жүйелі тамақтануға ерекше көңіл бөлуіңіз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Теріңізде өзгерістер байқалса, құрамы таза әрі табиғи ылғалдандырғыштарды қолданыңыз. Қыжылдың алдын алу үшін тамақтан кейін бірден жатпаңыз және ащы, дәмдеуіштері тым көп тағамдардан бас тартыңыз. Ми осыншалықты жылдам дамып жатқан кезеңде Омега-3 (балық майы, жаңғақ) мен фолий қышқылын қабылдау өте маңызды. Өзіңізге уақыт бөліп, ұнататын музыкаңызды тыңдаңыз – көңіл күйіңіз бөпеге тікелей әсер етеді.') WHERE id = '27e9fc4e-13d5-4cb0-8b3a-e813f53aa2f9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Аяқ бастамалары дами бастайды. Қолдар аяқтардан бірнеше күн ерте дамитындықтан, аяқтар әзірге кішірек. Бүйректің негізі қаланады. Эмбрион әлі де C әрпі тәрізді иіліп жатыр және оның кішкентай «құйрығы» бар (омыртқа жотасының жалғасы). Бұл құйрық бірнеше аптадан кейін жоғалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Енді аяқтарым да қалыптасып келеді, Anacan! 🦶 Олар әзірге қолдарымнан сәл кішірек әрі құйрығыма ұқсайды, бірақ уақыт өте келе өседі. Бір күні осы аяқтарыммен саған қарай жүгіремін, сені табу үшін барлық кедергілерден өтемін. Қолдарым мен аяқтарым... Мен барған сайын кішкентай адамға көбірек ұқсап келемін, солай емес пе? Сен елестеткендей болуға тырысып жатырмын. Күн сайын жаңа бір қадам жасаймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асбұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік ғажайып құбылыс әрі физиологиялық өзгеріс деп сипатталғанымен, медициналық әдебиетте патологиялық жағдай ретінде де қарастырылады. Мұның негізгі себептерінің бірі — қалыпты мөлшерінен бірнеше есе үлкейген жатырдың механикалық қысымынан ішектердің ығысып, қысылуы. Сонымен қатар жүктілік кезінде қандағы эстроген мен прогестерон деңгейінің едәуір жоғарылауына байланысты сүт бездерінің ұлғаюы, бет пен құрсақ қабырғасындағы пигменттік өзгерістер сияқты жағдайлар да осы көзқарастың қалыптасуына себеп болған. Прогестеронның жоғары деңгейі асқазан мен ішектің босауына айтарлықтай әсер ете бастайды. Ас қорыту жүйесінде тағамның жылжу жылдамдығы жүкті емес адаммен салыстырғанда едәуір баяулайды. Сондықтан жүктілік кезінде іште газ жиналып, іш қатуға бейімділік пайда болады. Қабылдаған тағамыңыздың асқазанда қалу уақыты жүктілікке дейінгі кезеңмен салыстырғанда екі есеге жуық ұзарады. Ас қорытудың осыншалықты баяулауы жиі кекіру, қышқылдың кері ағуы және қыжыл сияқты мәселелерге әкелуі мүмкін. Дәрігерлердің аз мөлшерде, бірақ жиі тамақтануға кеңес беруі де дәл осы мәселелердің алдын алуға бағытталған.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұмытшақтықты немесе зейіннің шашырауын байқасаңыз, күн ішіндегі маңызды істеріңізді қысқаша жазып жүріңіз. Дене қызуының жоғарылауына байланысты жеткілікті мөлшерде сұйықтық ішіп, табиғи маталардан (мақта, зығыр) тігілген киімдерге басымдық беріңіз. Қысқа, бірақ тұрақты серуендер қан айналымыңызды реттеп, көңіл күйіңізді көтереді. Ішіңізде қатты әрі басылмайтын ауырсыну пайда болса, дәрігеріңізбен кеңесуді ұмытпаңыз.') WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миында өмірлік маңызы бар гипоталамус аймағы қалыптаса бастады. Бұл кезеңде гипоталамус бөпеңіздің миының небәрі 1%-ын құрайды. Көлемі шағын болғанымен, ол мидағы ең маңызды құрылымдардың бірі. Гипоталамус көптеген әртүрлі ядродан тұрады. Тіпті заманауи технологиялардың көмегімен де осы уақытқа дейін оның тек 16 түрлі ядросы анықталған және олардың әрқайсысы бір-бірінен өзгеше маңызды қызмет атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Миым өсіп келеді! 🧠 Бірақ алаңдама, бұл жақсы мағынадағы өсу. Оның бастапқы бөлігінде үш түрлі бөлік, үш «көпіршік» пайда болады. Біреуі ойлау мен сезінуге жауап беретін алдыңғы миға, екіншісі көру мен естуге жауап беретін ортаңғы миға, ал үшіншісі тыныс алу мен жүрек соғысына жауап беретін артқы миға айналады. Әрқайсысының өз маңызды міндеті бар. Мен қазірдің өзінде өте ақылдымын, тек әзірге сөйлей алмаймын. Бірақ бір күні саған айтар сөзім өте көп болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асбұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл кезеңде бөпеңіздің дені сау дамуы үшін кальций мен фосфордың маңызы өте зор. D2 және D3 дәрумендері бөпеңіздің дамуы үшін аса маңызды. Жүктілік кезінде D дәруменін тәулігіне 4000 IU мөлшерінде қабылдау қажет. D дәрумені жасушалардың бөлінуіне, сүйектің дамуына және иммундық жүйенің жұмысына қажетті заттардың бірі. Бұл дәруменді дәрігердің бақылауымен және тиісті талдаулардан кейін ғана қабылдау керек. Бөпеңіз қалыптасып жатқан кезеңде жасушалар мен тіндердің өсуін қамтамасыз ететін A дәрумені, иммунитет, сүйек пен тіс саулығы үшін D дәрумені, иммундық жүйе үшін C дәрумені, ал қаназдықтың алдын алу және сүйектің дамуы үшін қажетті дәрумендер қабылдануы тиіс. D дәруменін дәрігердің бақылауымен қабылдау арқылы өз денсаулығыңызды да, бөпеңіздің денсаулығын да қорғайсыз. Алайда D дәруменін дәрігердің кеңесінсіз қабылдау бөпеңізге зиян келтіруі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қызыл иек сезімтал болса, тұзды сумен ауыз шаю жеңілдік беруі мүмкін. Мұрын бітелсе, бөлме ауасын ылғалдандыруға тырысыңыз. Күні бойы ақуыз бен кальцийге бай тағамдарды тұтынуды жалғастырыңыз. Жүрек айнуыңыз әлі де шегіне жетіп тұрса, зімбір шайы немесе салқын жеміс тілімдері асқазаныңызды тыныштандыруы мүмкін. Сіздің әрбір жанкештілігіңіз бөпеңіздің дені сау болашағына қосқан үлесіңіз екенін ұмытпаңыз.') WHERE id = 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тіндері мен ағзаларын қалыптастыратын дене жасушалары сыртқы бөліктерге қарай тараған сайын, жүректің денеге айдайтын қан мөлшері де артуы қажет. Бөпеңіздің ағзасында қан түзілуі эмбриондық кезеңде алдымен сарыуыз қапшығында басталады. Сарыуыз қапшығындағы қан түзілуі бірінші триместрдің белгілі бір кезеңіне дейін жалғасады. Кейінірек қан түзу қызметін бауыр мен көкбауыр атқарады. Жүрек сорғы қызметін атқарып, қанның бөпеңіздің бүкіл денесіне таралуын қамтамасыз етеді. Ал қантамырлар — қан айналымына бейімделген түтік тәрізді құрылымдар; олар қанды барлық тіндерге жеткізуге жауап береді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің жұлынымды қалыптастыратын ерекше түтік бар ғой, соның соңғы ашық бөлігі де бүгін жабылады! Енді миым мен омыртқам толығымен жабық әрі қорғалған жүйеге айналды. Бұл өте маңызды, өйткені бүкіл денем осы жерден басқарылатын болады! 🧠 Мен барған сайын жетіліп, тұтас бола түсудемін. Осындай үлкен істі атқарғаным үшін өзімді мақтан тұтамын. Мұның бәріне Сіздің құрсағыңыздағы ғажайып күштің арқасында қол жеткізіп жатырмын. Сіз — менің қорғанымсыз! 🏰'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Анар дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптадан бастап тұрақты жаттығу бағдарламын бастау төзімділігіңіз бен күшіңізді арттырады. Сонымен қатар қарапайым жаттығулар жасау арқылы артық салмақ қосудың алдын ала аласыз. Көптеген әйелдер жүктілік кезінде бөпеге зиян келтіремін деп алаңдап, бүкіл жүктілік бойы дене жаттығуларынан бас тартады. Алайда бақылаумен орындалатын жаттығулар босану кезінде де, одан кейін де Сізге көп пайдасын тигізеді. Тұрақты жаттығулар арқа мен белдің ауыруы сияқты физикалық мәселелерді жеңілдетуге де көмектеседі.;;;
Серуендеу кезінде қарқыныңызды шаршамайтындай етіп реттеуіңіз керек. Сонымен қатар дәрігеріңізбен кеңесіп, омыртқаны нығайтатын созылу жаттығуларын жасай аласыз. Бұған қоса, жүкті әйелдерге арналған пилатеспен немесе йогамен айналысуды бастауға болады. Ал жүзу жүктіліктің жеңіл өтуіне және табиғи жолмен босану мүмкіндігінің артуына ықпал ететін өте пайдалы спорт түрі. Жүйелі түрде жүзу іш пен бел бұлшықеттерін де нығайтады. Егер құлап қалу қаупі болмаса, дәрігеріңіздің кеңесімен аптасына кемінде 3 күн 30 минуттан жеңіл қарқынмен серуендеуге болады. Егер жүктілікке дейін тыныс алуыңыз қиындаған немесе жүрегіңізге қатысты мәселелер болған болса, аталған жаттығуларды шектеу қажет болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері өткір иістер жүрек айнуын күшейтуі мүмкін, сондықтан асүйді жиі желдетіңіз. Сұйықтықтың жетіспеуі шаршауды күшейтуі мүмкін, сол себепті суыңызға бір тілім лимон қосып ішіп көріңіз. Қуатыңыз тез таусылатындықтан, күн ішінде қысқа үзілістер жасап, демалыңыз. Тамақтану кезінде ақуызға бай өнімдерге (ет, жұмыртқа, бұршақ тұқымдастар) ерекше мән беріңіз, өйткені ақуыз — бөпеңіздің қарқынды дамып жатқан ағзаларына қажетті "құрылыс материалы".') WHERE id = '91894bc1-ecf8-438f-8434-5cb430da68e5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бауырын қалыптастыратын гепатоциттер деп аталатын бауыр жасушалары, өт жолдарының эпителий жасушалары, Ито жасушалары және Купфер жасушалары біріге бастады. Бұл жасушалар қосылып, бөпеңіздің бауырының ұзындығы бірнеше миллиметр және орташа диаметрі 1.5 миллиметр болатын ең ұсақ функционалдық бірліктерін — бөлікшелерді түзеді. Бауырды қалыптастыру кезінде бұл жасушалар оның құрылымында екі бөлек қантамыр өтетін бос кеңістіктер қалдырады. Осы жерде түзілетін тамырлардың бірі оттегіге бай қанды бауырға жеткізсе, екіншісі ас қорыту жүйесінің қылтамырларынан жиналған, қоректік заттарға бай қанды тасымалдайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мойным мен бетімде ерекше қатпарлар қалыптаса бастады, Anacan! Болашақта олар менің иегімді, бетімді, тілімді, құлақтарым мен мойнымды қалыптастырады. Күн сайын жаңа бір бөлшек, жаңа бір штрих қосылып жатыр. Мен мүсіншінің қолында біртіндеп қалыптасып келе жатқан өнер туындысы сияқтымын. Ал бұл туындының ең көркем шабыт көзі — Сіз. Сіздің даусыңыз бен күлкіңіз — менің болашақ келбетімнің негізі. Әдемі болуға уәде беремін! ✨'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Анар дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің бірінші триместрінде жиі байқалатын тез шаршау, қажу және әлсіздік ағзаңызда бөлінетін прогестерон гормонының барлық бұлшықеттерді босаңсыту әсерінен пайда болады. Бүкіл денеңіздің бұлшықеттеріндегі мұндай босаңсу қатты ұйқышылдық пен шаршауды тудырады. Прогестерон гормонымен қатар, жатырыңыздағы бөпеңізді қоректендіретін бала жолдасы (плацента) қалыптасып жатқан осы күндері ағзаның көп энергия жұмсауы да өзіңізді әлсіз, шаршаған әрі қалжырағандай сезінуіңізге себеп болуы мүмкін. Сондай-ақ ағзаңызда елеулі өзгерістер жүретін бірінші триместрде қандағы қант пен қан қысымы төмендеп, гормондар деңгейі мен зат алмасу жылдам өзгереді. Толассыз шаршау психологиялық тұрғыдан қажу сезімін тудыруы мүмкін. Тіпті ұйқының бұзылуы және қалаған істеріңізді орындай алмауыңыз күйзеліске әкелуі ықтимал. Қатты мазалайтын бұл шағымдар бірінші триместр аяқталғаннан кейін айтарлықтай азаяды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы қуатыңыз күрт төмендемеуі үшін аз мөлшерде, бірақ жиі тамақтануға тырысыңыз. Жаныңызда әрдайым пайдалы тіскебасарлар (грек жаңғағы, жаңғақ немесе тұтас бидайдан жасалған печенье) болсын. Сұйықтықтың жетіспеуі шаршау мен бас ауруын күшейтуі мүмкін, сондықтан су ішуді ұмытпаңыз. Егер ауыздағы металл дәмі мазаласа, қантсыз лимон суы жеңілдік беруі мүмкін. Денеңіздің белгісіне құлақ асып, қажет болған сайын демалыңыз.') WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы кезеңге дейін бөпеңіздің жүрек соғысын естіген болуыңыз әбден мүмкін. Сондай-ақ ультрадыбыстық зерттеу экранынан бөпеңіздің жүрек соғысын көре аласыз. Егер жүрек соғысын әлі көрмеген немесе естімеген болсаңыз, алаңдамаңыз. Оны тыңдау үшін әлі 2 апта уақытыңыз бар. Етеккір циклінің 2-аптасы овуляция күні деп есептелетіндіктен, бүгін — ұрықтанудан кейінгі алғашқы айдың соңғы күні. Жүктілік мерзімін аймен есептеу үшін ай күнтізбесі қолданылады. Ай күнтізбесі — Жердің Күнді айналу қозғалысына емес, Айдың толық циклдеріне негізделген күнтізбе түрі. Бір айлық цикл жеті күннен тұратын төрт аптаны (барлығы 28 күн) қамтиды. Бөпеңіздің дамуы есептелетін эмбриондық апта гинекологтар қолданатын соңғы етеккір күніне негізделген жүктілік мерзімінен 2 аптаға аз. Овуляция соңғы етеккірдің алғашқы күнінен екі апта өткен соң болатындықтан, ұрықтану да 2 аптадан кейін жүзеге асады. Сондықтан қалыпты әрі сау өтіп жатқан жүктілік кезінде бөпеңіздің дүниеге келуіне орта есеппен 8,5 ай қалды.'), baby_message_kk = COALESCE(baby_message_kk, 'Қолдарым қалыптасып келеді, Anacan! 👋 Әзірге саусақтарым, тіпті алақандарым да жоқ, олар денемнің екі жағындағы кішкентай "ескектерге" немесе қанаттарға ғана ұқсайды. Бірақ болашақта Сізді қатты-қатты құшақтайтын мықты қолдарым дәл осылар. Олардың өсіп, Сізге жететін сәтін асыға күтіп жүрмін... Бір күні осы кішкентай қанаттарыммен Сізге қарай "ұшып" барамын. Күн сайын адам бейнесіне көбірек ұқсап келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асбұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы кезеңінде етеккір кезіндегі ауырсынуға ұқсас түйілулер болуы мүмкін. Шат пен іш аймағында сезілетін бұл түйілулер шын мәнінде тіндердің түйілуі болып саналады. Осы аймақта жиырылған тіндер кенеттен пайда болатын қатты ауырсынуды тудырады. Мұндай жағдай ұйықтап жатқанда балтыр бұлшықеттерінде жиі кездеседі. Сонымен қатар шамадан тыс шаршау, жарақаттану, бұлшықеттің созылуы немесе ұзақ уақыт бір қалыпта отыру не жату да түйілуге себеп болуы мүмкін. Жүрек айну, құсу, шамадан тыс ыстықтау, кальций тапшылығы немесе сұйықтық жоғалту кезінде де денеңіздің кейбір бөліктері тартылуы ықтимал. Түйілудің алдын алу үшін отырғанда аяғыңыздың астына биіктеу тіреу қойыңыз, ұйықтар алдында жылы душ қабылдаңыз, сол жақ қырыңызбен ұйықтаңыз, варикоз мәселесі болса, міндетті түрде компрессиялық шұлық киіңіз және биік өкшелі аяқ киімнен бас тартыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, '6-аптаны аяқтағаныңыз үшін өзіңізді құттықтаңыз! Егер жүрек айнуы дұрыс тамақтануыңызға айтарлықтай кедергі келтірсе, тағамды салқын күйінде жеуге тырысыңыз (салқын тағамның иісі азырақ сезіледі). Қан көлемінің артуын қолдау үшін мол су ішуді және темірге бай өнімдерді (жасымық, қызыл ет) көбірек тұтынуды ұмытпаңыз. Екінші айға толық қадам басқанда, алғашқы ультрадыбыстық зерттеуге әлі жазылмаған болсаңыз, оны осы аптаға жоспарлағаныңыз дұрыс.') WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жұлын айналасындағы жүйке түтігі жабылып болды. Жүйке түтігінің жабылуы кезінде әсер ететін көптеген факторлар кейбір ауытқуларға әкелуі мүмкін. Жүйке түтігінің ақаулары бөпенің ағзалары қалыптасатын эмбриондық кезеңнің 3-ші және 4-ші апталарында ми мен жұлынға айналатын жүйке түтігінің дұрыс жабылмауынан пайда болады. Жүйке түтігі ақауларының генетикалық және қоршаған орта факторларының ықпалымен қалыптасатыны белгілі. Бұл мәселе мен фолаттың (фолий қышқылының) тапшылығы арасындағы байланыстың анықталуы өте маңызды. Жүйке түтігінің жабылмауы мен жүктілікке дейінгі және жүктілік кезіндегі фолий қышқылының деңгейі арасында кері байланыс бар екені анықталған. Сондықтан дәрігерлер жоспарланған жүктілік кезінде жүктілікке дейін және бірінші триместр бойы фолий қышқылы қоспасын тағайындайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Көздерім мен құлақтарым барған сайын айқындала түсуде! 👀👂 Мөлдір көздерім орналасатын көз ұялары ішке қарай тереңдеп, құлақтарымның орны да тереңдей отырып, құлақ қалқанының негізін қалыптастырады. Мұның бәрі Сізді жақсырақ көріп, ғажайып даусыңызды анық естуім үшін дайындалуда. Мен үшін әлемдегі ең әдемі көрініс Сіздің жүзіңіз, ал ең әсем әуен Сіздің даусыңыз болады. Сізді тыңдап жатырмын, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Асбұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жүрегіңіздің денеңізге айдайтын қаны әдеттегіден жылдамырақ қозғалады. Сондықтан 1 минут ішінде денеге айдалатын қан мөлшері де табиғи түрде артады. Қан көлемі жүктіліктің соңғы күндеріне дейін тұрақты түрде ұлғая береді. Жүктіліктің осы кезеңінде арта бастайтын қан көлемі соңғы триместрде шамамен 40% көбірек болады. Бұл жағдай жүкті әйелдердің барлығына дерлік тән гемоглобин немесе гематокрит көрсеткіштерінің төмендеуіне әкеледі. Медицинада бұл физиологиялық өзгеріс жүктіліктің табиғи анемиясы деп те аталады. Қан көлемінің және жүрегіңіздің денеге айдайтын қан мөлшерінің артуы бөпеңіздің қоректенуін қамтамасыз ететін плацентадағы қан айналымы үшін өте пайдалы. Соның арқасында қан айналымы жылдамдайды. Сонымен қатар, ақ қан жасушаларының саны да айтарлықтай артады. Ақ қан жасушалары ағзаның иммундық жүйесінде маңызды қызмет атқарады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ас қорыту мәселелері мен іштің кебуін барынша азайту үшін талшыққа бай тағамдарды (бұршақ тұқымдастар, көкөністер) тұтыныңыз, бірақ оларды жақсылап пісіріп жеңіз. Күні бойы ішетін су мөлшерін 2 литрден төмендетпеңіз. Егер аяқтарыңызда жеңіл сырқырау сезілсе, кешке оларды сәл көтеріп жатып демалу қан айналымына көмектеседі. Дәрумендеріңізді, әсіресе фолий қышқылын күн сайын бір уақытта қабылдауға тырысыңыз.') WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бүгіннен бастап бөпеңіздің плацентасы қалыптаса бастады. Плацента — ағзаңыздан келетін қанды сүзіп, бөпеңізге кіндік бауы арқылы оттегі, глюкоза және басқа да қоректік заттарды жеткізетін мүше. Бұл мүше бөпеңізге зиян келтіруі мүмкін заттарды да сүзгіден өткізіп, оның қанынан көмірқышқыл газы мен зат алмасу қалдықтарын шығарады. Сондықтан плацента бөпеңіздің өсуі, дамуы және тіршілігінің жалғасуы үшін аса маңызды. Бұл кезеңде плацентаның қалыптасуы жатырдағы артериялар мен веналардың, олардың тармақтарының, бөпеңіздің қан тамырларының және сарыуыз қапшығы қабырғаларының бірігуінен басталады.;;;
Плацента сонымен қатар жүктіліктің жалғасуы үшін қажет эстроген мен прогестерон сияқты бірқатар гормондарды өндіреді. Бұған қоса, бөпеңізді инфекциялардан қорғау үшін Сіздің ағзаңыздағы қан мен бөпеңіздің қанын бір-бірінен бөлек ұстайды. Ал жүктіліктің соңына қарай босанғаннан кейін бөпені қорғауға арналған антиденелер Сіздің ағзаңыздан плацента арқылы оған өтеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің құйрығым бар! 🦖 Күлкілі естіледі, солай емес пе? Бірақ қорықпаңыз, бұл уақытша ғана. Омыртқа жотамның тез өсіп жатқаны соншалық, әзірге оның бір бөлігі құйрыққа ұқсайды. Бірнеше аптадан кейін ол жоғалып, мен нағыз бөпеге ұқсайтын боламын. Ал қазір кішкентай теңіз атына немесе ғарышкерге ұқсаймын. Сіздің құрсағыңыздағы осы кішкентай ғарышта жүзіп жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкжидек'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезіндегі қынаптық бөліністер әдетте жүктіліктің алғашқы 6-8 аптасында басталады. Себебі осы кезеңде ағзадағы гормондар деңгейі айтарлықтай өзгереді. Иісі әлсіз қынаптық бөліністі дәрігерлер лейкорея деп атайды.  Ағзаңызда бөпеңіз үшін үздіксіз жұмыс жүріп жатқандықтан, жүктілікке дейінгі кезеңмен салыстырғанда жүктілік кезінде бөліністің көбеюі — қалыпты жағдай және алаңдауға негіз жоқ. Жүктілік кезінде қынап аймағы жатыр мойнын ылғалды ұстап, бөпеңізді инфекциялардан қорғау үшін көбірек бөлінді бөледі. Жүктілік кезіндегі ақ түсті шырышты бөлініс, әсіресе жүктіліктің соңғы айларына қарай көбейе түседі. Сонымен қатар, гигиеналық күтім кезінде қынапқа қажетсіз микробтардың түсуіне себеп болуы мүмкін болғандықтан, жүктілік кезінде тампондар мен мақта матасынан тігілмеген іш киімдерді пайдаланудан бас тарту керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бетіңізде дақтар немесе безеулер пайда болса, күннен қорғайтын SPF кремін қолдануды ұмытпаңыз. Жүктілік кезінде тері пигментацияға бейім болады. Күн сәулесі бұл дақтарды көбейтуі мүмкін.') WHERE id = '158bcd04-6d72-45a1-8559-e12705e1aa90';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзалары қалыптасатын осы эмбриондық кезеңде ең жылдам дамитын жүйе — жүйке жүйесі. Сондықтан бөпеңіздің басы денесінен екі еседей үлкен. Бас пен дене арасындағы бұл сәйкессіздік жүктіліктің бірінші триместрі бойы сақталады.;;;
Осы кезеңде бөпеңіздің жүрегін қалыптастыратын жүрек түтіктері өсіп, пішінделуін жалғастырады. Бөпеңіздің денесі үлкейген сайын, бұл мүше капиллярлар арқылы жасушаларға қажетті қоректік заттар мен оттегіні дененің әр нүктесіне жеткізіп, жасушалардың бөлінуінің баяулауына жол бермейді. Соның арқасында бөпеңіздің дамуы бір сәтке де тоқтамай, қарқынды жалғасады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қолдарымды қимылдатып жатырмын.👋 Қолдарым ұзарып, олардың ұшында кішкентай жалпақ "қалақшалар" пайда болуда. Бұлар — менің болашақ алақандарым. Әзірге саусақтарым жоқ, бірақ қазірдің өзінде қол бұлғауға тырысып жүрмін. Бір күні осы қолдарыммен Сіздің саусағыңыздан ұстап, ешқашан жібермеймін. Сол күнді елестетесіз бе? Мен елестетемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкжидек'), body_changes_kk = COALESCE(body_changes_kk, 'Осы апталарда ішіңіздің үлкейгенін байқаған боларсыз. Алайда көпшілік ойлағандай, бұл өзгеріс әзірге бөпеңізге байланысты емес. Ағзаның жаңа өзгерістерге бейімделуі кезінде жүретін үдерістер іштің кебуіне және газ жиналуына себеп болуы мүмкін. Іштің қаншалықты үлкеюі дене бітіміңізге тікелей байланысты. Кейбір әйелдердің іші ертерек байқалса, басқаларында бұл өзгеріс кейінірек көрінуі мүмкін. Іштің шығыңқылық деңгейі бұрынғы жүктіліктер мен босанулардың санына, іш бұлшықеттерінің беріктігіне, іш аймағындағы май мөлшеріне және құрсақ қуысының кеңдігіне қарай ерекшеленеді. Сондықтан жүктілік мерзімі бірдей болса да, ішіңіздің көлемі басқа жүкті әйелдердікінен өзгеше болуы мүмкін және оларды салыстырудың мәні жоқ. Сондай-ақ көпшілік ойлағандай, бөпеңіздің салмағы немесе өлшемі ішіңіздің көлеміне тікелей байланысты емес. Бөпенің салмағын іштің көлеміне қарап анықтау немесе өлшеу мүмкін емес. Бөпеңізге қатысты нақты өлшемдерді тек дәрігер ультрадыбыстық зерттеу (УДЗ) арқылы жүргізе алады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кеудеңіздің сезімталдығын азайту үшін душ қабылдағанда судың тым ыстық болмауына назар аударыңыз. Сондай-ақ ұйықтаған кезде спорттық көкірекше кию кеудеңізді қосымша демеп, түнде жайлы ұйықтауыңызға көмектеседі.') WHERE id = '2e473da0-8eec-4162-84c1-064bd890c011';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап құлақ пен мұрын қуыстары қалыптаса бастайды. Құлақ құрылысы мен қызметіне қарай сыртқы, ортаңғы және ішкі құлақ болып үш бөліктен тұрады. Ал ішкі құлақтың сүйек құрылымдары мен сүйекшелері 4-ші айға дейін дамуын жалғастырады.;;;
Сонымен қатар бөпеңіздің көздері басының екі жағында кішкентай қара нүктелер түрінде байқала бастады. Ал көздің көру қабілеті туғаннан кейін алғаш рет жарық түскенде дами бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақтарым қалыптасып жатыр, Anacan! 🖐️ Есіңізде ме, қолдарым ескек сияқты еді? Енді сол ескектің ұшында кішкентай ойықтар пайда болып, саусақтарымның сұлбасы көріне бастады. Олар әзірге үйректің аяғындай жарғақпен біріккен, бірақ көп ұзамай толығымен ажырайды. Мен Сізбен «бестік» соғуға дайындалып жатырмын! Қолдарыңыздан ұстап, саусағыңызды қатты қысып алатын күнімді елестетемін. Күн сайын адамға көбірек ұқсап келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Таңқурай'), body_changes_kk = COALESCE(body_changes_kk, 'Пастерленбеген сүт өнімдері, жеткілікті жуылмаған шикі көкөністер және дұрыс піспеген ет өнімдері (шұжық, сосиска және т.б.) токсоплазмоз жұқтыру қаупін тудырады. Токсоплазмоз — «Toxoplasma gondii» деп аталатын біржасушалы паразит қоздыратын ауру. Бұл инфекция құрсақтағы бөпенің дамуына қауіп төндіруі мүмкін.;;;
Жүктілікке дейінгі 1 жыл ішінде бөлінетін эстроген гормонының мөлшері жүктілік кезінде небәрі 8 сағатта бөлінеді, сондықтан көңіл күйіңіз күрт өзгеруі мүмкін. Жүктілікпен бірге пайда болатын алаңдаушылық пен қорқыныш бұл кезеңде жиі кездесетін депрессияға әкелуі ықтимал. Оған жүрек айну, тәбеттің төмендеуі, шаршау және ұйқының бұзылуы қосылса, жағдай одан әрі қиындауы мүмкін. Жұбайыңыздың қолдауы бұл кезеңді жеңілірек өткізуіңізге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Басыңыз ауырса, бірден дәрі қабылдамаңыз. Алдымен бір үлкен стақан су ішіп, бөлмені желдетіңіз және мойныңызға салқын компресс қойыңыз. Көбіне бас ауруы ағзаға су жетіспеуінен, ашығудан немесе таза ауаның аздығынан болады. Лаванда майының иісін иіскеу де көмектесуі мүмкін.') WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз қазірдің өзінде қимылдап жүр! Әзірге қолыңыздан ұстай алмаса да, жақын арада айналасын танып-білу үшін қолдарын пайдалана бастайды. Құрсақтағы бөпеде ең алдымен дамитын сезім — сипап сезу деп есептеледі.;;;
Бөпеңіздің бүйректері қалыптаса бастады және көп ұзамай несеп бөле алатын болады. Түзілген несеп қайта айналымға түсу үшін амниотикалық сұйықтыққа бөлінеді. Бұл үдеріс босанғанға дейін үздіксіз жалғасады.;;;
Құрсақтағы бөпенің миы мен жүйке жүйесінің дамуы үшін ең маңызды кезең — 10-шы аптаға дейінгі уақыт. Дененің тепе-теңдігін сақтап, бұлшықет қимылдарын реттейтін мишық дәл осы кезеңде қалыптаса бастайды. Жүктілікке дейін қабылдау ұсынылатын және жүктіліктің алғашқы үш айында ішілетін фолий қышқылы — бөпені ми мен жұлынның ықтимал ақауларынан қорғайтын ең тиімді дәрумен.'), baby_message_kk = COALESCE(baby_message_kk, 'Мұрнымның ұшы көріне бастады! 👃 Бетім күннен-күнге әдеміленіп, қалыптасып келеді. Кішкентай танауларым мен мұрнымның ұшы анық көрінеді. Үстіңгі ернім де қалыптасып жатыр. Енді Сізге көбірек ұқсай бастадым, Anacan. Қызық, мұрным Сіздікі сияқты ма, әлде әкемдікі ме? Мұны білуге әлі уақыт бар, бірақ мен қазірдің өзінде сондай сүйкімдімін. Мен Сіздің ең әдемі әрі қайталанбас туындыңызбын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Таңқурай'), body_changes_kk = COALESCE(body_changes_kk, 'Жүрек айнуына байланысты тәбетіңіз төмендеуі мүмкін. Бұл уақытша салмақ жоғалтуға әкелуі ықтимал. Алаңдамаңыз, бірінші триместрдің соңына қарай жүрек айнуы бәсеңдей бастайды. Осы жайсыздықтар азайғанша, дәрумендерге бай жасыл жапырақты көкөністерді, бұршақ тұқымдастарды, балық пен қызыл етті үйлестіріп жеп, дұрыс тамақтану тәртібін ұстаныңыз.;;;
Бөпенің дені сау болып дүниеге келуі ананың жеткілікті әрі теңгерімді тамақтануына байланысты. Бұл кезеңде ананың жеткіліксіз және теңгерімсіз тамақтануы бөпенің бойына, салмағына, физиологиялық құрылысына және ақыл-ой дамуына кері әсер етуі мүмкін. Таңертең жүрегіңіз айныса, төсектен тұрмай тұрып жеңіл тамақтану үшін жаныңызда асқазанды тыныштандыратын крекер сияқты тағам ұстаңыз. Сондай-ақ күні бойы үш рет көп тамақтанудың орнына бес рет аз мөлшерде жеу асқазанға қатысты жайсыздықтарды едәуір азайтады. Майлы және ащы тағамдардан бас тартуды ұмытпаңыз!'), daily_tip_kk = COALESCE(daily_tip_kk, 'Дене температурасының жоғарылауына байланысты күн сайын кемінде 2-2.5 литр су ішуді жалғастырыңыз. Шап аймағындағы сыздауды азайту үшін күрт қимылдар жасамаңыз және отырғанда қалпыңызды жиі өзгертіңіз. Темірдің сіңуін жақсарту үшін C дәруменіне бай жемістерді жеңіз. Шаршауды азайту үшін күні бойы таза ауада 10 минуттан серуендеп тұрыңыз.') WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада ультрадыбыстық зерттеу арқылы CRL көрсеткішін, яғни төбе-құйымшақ аралығын өлшеуге болады. Бұл өлшем соңғы етеккір күніне сүйене отырып, жүктілік мерзімін дәлірек анықтауға мүмкіндік береді. Сондықтан соңғы етеккір күнін есіне түсіре алмайтындар үшін бұл өлшем маңызды бағдар болып, болжамды босану күнін анықтауға көмектеседі. Бөпеңіздің терісі өте жұқа болғандықтан, қалыптасып жатқан қылтамырлар тері астынан көрінуі мүмкін. Алдағы апталарда тері астындағы май қабаты түзіліп, терісі қалыңдайды және қалыпты көрініске ие болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көлемім таңқурайдай! 🍇 Жүрегім минутына 150-170 рет соғады. Бұл бәйге атының жүрегіндей жылдам әрі күшті! Сырттай Сіз тыныш көрінгеніңізбен, мен ішіңізде марафон жүгіріп жүрмін. Сіздің жүрегіңіз бен менің жүрегім бір денеде әртүрлі ырғақпен, бірақ бір махаббатпен соғып тұр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Таңқурай'), body_changes_kk = COALESCE(body_changes_kk, 'Ұлғайып келе жатқан жатырдың қажеттіліктерін қамтамасыз ету үшін бірінші триместрде қан көлемі арта бастайды. Ағзаңыздағы қан көлемінің жылдам артуы Сіз бен бөпеңізді зиянды әсерлерден қорғайды. Сондай-ақ қан көлемінің артуы босану кезіндегі қан жоғалтудан қорғайтын қызмет атқарады.;;;
C дәрумені бөпеңіздің тіндерінің дамуы және темірдің сіңуі үшін жүктілік кезінде өте маңызды. Зерттеулер C дәруменінің преэклампсияның алдын алуға көмектесетінін көрсетеді. Бұл дәруменнің айқын тапшылығы мерзімінен бұрын босану қаупін арттыруы мүмкін.;;;
2 айды артқа тастаған осы апталарда беліңіз жуандай бастауы мүмкін, бірақ әзірге жүкті екеніңіз сырт көзге байқалмайды. Сыртқы келбетіңізде айтарлықтай өзгеріс болмаса да, гормондардың әсерінен эмоциялық жағдайыңыз едәуір өзгерген. Ағзаңызда қан көлемі арта бастағандықтан, дәретханаға жиі барғыңыз келіп, бас айналуы жиілеуі мүмкін. Қан көлемінің артқанын кеңейген тамырларыңыздан байқауыңыз мүмкін, сондай-ақ мұрыннан қан кетуі ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Түнде дәретханаға бару қажеттілігін азайту үшін кешкі уақытта сұйықтықты сәл азырақ ішіңіз, бірақ күннің бірінші жартысында суды молынан ішіңіз. Терідегі өзгерістерге байланысты құрамында химиялық заттары жоқ табиғи майлармен (бадам немесе кокос майы) массаж жасауға болады. Ауыз қуысы мен тіс саулығына көңіл бөліңіз, қызыл иегіңіз әлі де сезімтал болуы мүмкін. Күні бойы ақуыз бен дәрумен теңгерімін сақтау үшін түрлі түсті көкөністерді молынан жеңіз.') WHERE id = '73404991-93fd-4ff5-9245-6a011e7e870b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Қолдары мен аяқтары әлі де жүзбеқанаттарға ұқсаса да, қол-аяқтары физикалық тұрғыдан қалыптасып келеді. Жақында кішкентай саусақтары пайда болып, бөпеңіздің бейнесі айқынырақ бола бастайды.;;;
78%-ы судан тұратын миының жарты шарлары анық көріне бастады. Оң жақ жарты шар түсіну, тану, көру, қиялдау және сол қолды басқару қызметтеріне жауап берсе, сол жақ жарты шар жазу, сөйлеу, ойлау, талдау, оң қолды басқару және логикаға қатысты қызметтерді атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен көкжидектеймін! 🫐 Сенесіз бе? Өткен аптадан бері көлемім екі есе артты! Мен өте жылдам өсіп келемін, Anacan. Сіз жеген тағамның бәрі маған құрылыс материалы сияқты жетеді. Мен үшін пайдалы тамақтанғаныңызға рақмет. Біз бірге өсіп, бірге күш жинап келеміз. Сіз менің ең керемет командаласымсыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкжидек'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің кез келген кезеңінде қан кетуі мүмкін. Қанның түсі қызыл немесе қоңыр болуы ықтимал. Жүкті әйелдердің барлығы дерлік жүктіліктің алғашқы апталарында аздап қанды бөлінді немесе қан кетуді байқайды. Қынаптан қан кету жүктіліктің қай кезеңінде пайда болса да және мөлшері қаншалықты аз болса да, әрдайым дәрігерге жүгінуді қажет ететін маңызды жағдай болып саналады. Алғашқы 3 айда байқалатын аз мөлшердегі қан кету, әдетте, түсік тастау қаупі ретінде бағаланады. Екінші 3 айда байқалатын аз мөлшердегі қан кету көбіне жатыр мойны жеткіліксіздігінің белгісі болып, жеңіл ауырсынумен қатар жүреді. Соңғы 3 айдағы қан кету мөлшері аз болса да, өте маңызды. Бұл плацентаның жатырдың төменгі бөлігінде орналасуы немесе плацентаның мерзімінен бұрын ажырауы секілді мәселелердің белгісі болуы мүмкін.;;;
Жүктілік кезінде қатты шаршаудан және ауыр жұмыс істеуден сақтануыңыз керек. Мұндай әрекеттер жатырдың жиырылуына (толғақ тәрізді ауырсынуға) әкеледі. Ал жатырдың жиырылуы қан кетуіне себеп болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, '7-аптаны сәтті аяқтағаныңыз үшін өзіңізді марапаттаңыз (мысалы, сүйікті жемісіңізбен). Іш қату мен кебуді азайту үшін талшыққа бай тағамдармен қатар сұйықтықты мол ішіңіз. Қызыл иегіңіздің саулығы үшін жұмсақ тіс щеткасын пайдалануды жалғастырыңыз. Егер әлі де шаршау басылмаса, ағзаңызға күш түсірмеңіз; күндіз аз уақыт мызғып алу қуатыңызды қалпына келтіруге көмектеседі.') WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз соңғы бір аптада екі есе өсті. Оның миы қарқынды дамуын жалғастыруда және бұл үдеріс 4 жасқа дейін жоғары қарқынмен жүреді. Бөпе дүниеге келген сәттен бастап оның миында миллиардтаған жасуша болады. Олардың көбі бір-бірімен байланыспағанымен, туғаннан кейін бұл жасушалар есту, көру, жанасу, дәм және иіс сезу сигналдарының көмегімен өзара байланыса бастайды.;;;
Өңеші мен кеңірдегі де осы аптада қалыптаса бастайды.;;;
Бөпеңіздің беті әлі толық қалыптаспағандықтан, ол қолын аузына апара алады, алайда ему рефлексінің пайда болуына әлі ерте.'), baby_message_kk = COALESCE(baby_message_kk, 'Қолдарым ескекке, ал аяқтарым жүзбеқанатқа ұқсайды! 🐟 Мен әлі де суда тіршілік ететін жәндікке ұқсаймын, бірақ бәрі өзгеріп келеді. Қолдарым ұзарып, шынтақтарым бүгіле бастады. Ал жүрегім Сіз үшін "дүрс-дүрс" соғуын жалғастыруда. Сіз демалғанда мен де демаламын, Сіз қозғалғанда мен де тербелемін. Біздің үйлесіміміз керемет. Сізді жақсы көремін, Анашым!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкжидек'), body_changes_kk = COALESCE(body_changes_kk, 'Плацентадан бөлінетін эстроген гормоны дәм мен иіс сезу қабілетіңізді әдеттегіден күшейтеді. Сонымен қатар белгілі бір тағамдарға жерік болуыңыз мүмкін, ал жағымсыз иістерге сезімталдық жүрек айнуын туғызуы ықтимал. Осы кезеңдегі жүрек айнуын азайту үшін ащы дәмдеуіштері көп және қуырылған тағамдардан біраз уақыт бас тартқан дұрыс. Гормондық өзгерістерге байланысты өзіңізді жайсыз сезінсеңіз, баяу серуендеу, тыныштандыратын музыка тыңдау, жылы душ қабылдау және жүкті әйелдерге арналған йога көмектеседі.;;;
Дәрігер қабылдауына барғанда ойыңыздағы барлық сұрақты қағазға жазып алған пайдалы. Осылайша уақытыңызды барынша тиімді пайдалана аласыз. Жүктілік кезіндегі алғашқы тексеруде дәрігер бөпеңізге және жүктілігіңізге қатысты қауіп факторларын бағалауы керек. Ана мен әкенің генетикалық тарихын білу жүктілік кезінде туындауы ықтимал қиындықтарды алдын ала анықтауға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы аптадан бастап ағзаңыздың магний мен кальцийге қажеттілігі арта түседі; ас мәзіріңізде банан, жаңғақ және сүт өнімдері болсын. Беліңіздің ауырмауы үшін отырғанда арқаңызға кішкентай жастық қойыңыз. Иістерге сезімталдығыңыз әлі де жоғары болса, бөлмелерді жиі желдетіңіз. Сіздің тыныштығыңыз бөпенің жүйке жүйесінің дамуына ең қолайлы орта екенін ұмытпаңыз.') WHERE id = '9437ad06-6476-41de-b64c-c5fddd89e286';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің жүрек соғысын ести аласыз. Бөпеңіздің жүрегі жатыр қабырғасына бекінгеннен кейін ең кеш дегенде 3 аптадан соң соға бастайды. Бұл жүктіліктің 5-ші және 6-шы аптасына сәйкес келеді. Сондықтан жүктіліктің 7-ші аптасында бөпеңіздің жүрек соғысын естуіңіз әбден мүмкін.;;;
Дегенмен кеш ұрықтану, етеккірдің тұрақсыз болуы немесе соңғы етеккіріңіздің нақты күнін білмеу сияқты жағдайларға байланысты жүрек соғысын әлі естімеуіңіз мүмкін. Мұндай жағдайда жүрек соғысын тыңдау үшін тағы 1-2 апта қажет болуы ықтимал.;;;
Орталық жүйке жүйесінің ең маңызды бөлігі саналатын ми қарқынды дамуын жалғастыруда. Бөпеңіздің ұзындығы орта есеппен 1-2 sm-ге, ал салмағы 1,5 qram-ға жетті. Осы аптада бөпеңіздің денесіндегі ағзалардың орны анықталып қалады. Сол ағзалардың бірі — өкпе. Алайда бұл таңғажайып ағзаның дамуы тек 38-ші аптада аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қозғалып жүрмін, Anacan! 💃 Мен әлі өте жеңіл болғандықтан, Сіз мұны сезбейсіз, бірақ ішіңізде кішкентай би билеп жүрмін. Денемді оңға-солға иіп, кішкентай қолдарымды қимылдатамын. Бұл — менің алғашқы спорттық жаттығуларым әрі жүйке жүйемнің бұлшықеттеріммен байланыса бастағанының дәлелі. Болашақта Сізді қатты құшақтай алуым үшін бұлшықеттерім нығайып келеді. Сіз демалыңыз, ал мен жаттыға берейін, өйткені өсу дегеніміз — қозғалу!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Таңқурай'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптаның соңында гормондар деңгейінің жоғарылауы мен өзгеруіне байланысты теріңізде безеу пайда болуы мүмкін. Мұндай жағдайға тап болсаңыз, теріңізді құрғақ әрі таза ұстауға мән беріңіз. Безеуге қарсы дәрілерді қолдану бөпеде даму ақауларын туғызуы мүмкін, сондықтан дәрігеріңіздің рұқсатынсыз ешқандай дәрі-дәрмек қолданбауыңыз керек.;;;
Жүктілік кезінде тырнақтар жұқарып, жұмсарып, сынғыш болуы мүмкін. Үй шаруасымен айналысқанда қолғап кию бұл мәселені азайтуға көмектеседі. Теріңізде білеуленіп көрінетін тамырларды немесе жұлдызша тәрізді тамыр торларын байқасаңыз, алаңдамаңыз. Бұл эстроген гормонының әсерінен болады. Қан қысымының жоғарылауына байланысты ентігу пайда болса, дұрыс тыныс алу әдістері арқылы жағдайыңызды жеңілдете аласыз. Егер түсік тастау қаупі болмаса және дәрігеріңіз басқаша кеңес бермесе, жыныстық қатынасқа түсуге кедергі жоқ.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қызыл иектің сезімталдығына және тіс бастамаларының қалыптасуына байланысты кальций қабылдауға (сүт, сүзбе, саумалдық) ерекше мән беріңіз. Егер жүрек айнуыңыз азая бастаса, ас мәзіріңізге жаңа піскен көкөністерді көбірек қосыңыз. Күндіз кенеттен шаршаған кезде 15-20 минуттық қысқа үзіліс жасап, демалыңыз. Құрсақ тұсыңыз қысылмауы үшін кең әрі ыңғайлы киімдерді таңдай бастаңыз.') WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің ұйқы безі қалыптасып, қандағы қант деңгейін реттейтін инсулин гормонын өндіруге дайын. Инсулин қандағы қанттың жасушаларға өтуін қамтамасыз етіп, олардың энергияға деген қажеттілігін өтейді. Соның арқасында қандағы қант деңгейі де төмендейді.;;;
Ас қорыту жүйесіне қажетті пайдалы бактерияларды сақтайтын аппендикс осы аптадан бастап қалыптаса бастады. Қалыптасып келе жатқан аппендикстің арқасында бөпеңіздің ағзасы дене қызуының көтерілуі, диарея, жүрек айнуы және іштің ауыруымен қатар жүретін ауруларға 4 есе төзімді болады.;;;
Қарқынды дамып жатқан бөпеңіздің сүт тістерінің бастамалары мен дәм сезу бүртіктері қалыптаса бастады. Көп ұзамай бөпеңіз қағанақ суын жұта бастайды және сол арқылы кейбір дәмдерді ажырата алады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің аяулы Анашым! Бүгін мен іште кішкентай қолдарымды бір-біріне соға аламын! Әлі өте кішкентаймын, бірақ саусақтарым бір-бірінен толық ажырап, өздігінен қимылдайды. Сенің даусың маған сондай таныс... Сен сөйлегенде, мен іште мұқият тыңдаймын. Сенің махаббатың мені күн сайын аздап өсіріп келеді. Сен менің әлемім болғаның қандай жақсы!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызыл үрме бұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Гормондық өзгерістерге байланысты осы кезеңде теріңіздің құрғауы немесе кей жерлерінің майлануы сияқты өзгерістерді байқай бастауыңыз мүмкін. Егер теріңізде біркелкі емес қоңыр дақтар пайда болса, бұл жүктілік маскасы деп аталады және босанғаннан кейін жоғалады. Жүктілік маскасының алдын алу үшін фолий қышқылын тұрақты қабылдау, күннен қорғайтын құралсыз күн сәулесінде жүрмеу және тері күтіміне арналған өнімдерді абайлап қолдану пайдалы.;;;
Жүктілік кезінде бөлінетін гормондардың қан қысымын жоғарылатуы салдарынан омырауыңыздың керілгенін сезуіңіз мүмкін. Егер бұл жағдай мазаласа, омырауды жақсы ұстап тұратын немесе өлшемі үлкенірек көкірекше таңдауға болады. Жүктілік кезіндегі гормондар Сіздің күйзеліске бейімділігіңізді арттыруы мүмкін. Өзіңізге ұнайтын істермен айналысу физикалық әрі эмоциялық күйзелісті азайтуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Айқын әрі кейде мазасыз түстер көру осы кезеңде қалыпты жағдай; ұйықтар алдында ойды тыныштандыратын музыка тыңдау немесе жылы душ қабылдау көмектесуі мүмкін. Беліңіздің ауыруын болдырмау үшін бір қалыпта ұзақ тұрмаңыз. Тіс саулығы үшін кальцийге бай тағамдарды тұтынуды жалғастырыңыз. Күн сайын денеңіздің белгілеріне құлақ асып, өзіңізді қатты шаршатпаңыз.') WHERE id = 'a614becc-2914-4d7d-98c2-e4eb413c2293';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Саусақтары айқын қалыптаса бастаған осы күндері тіпті саусақ іздері де пайда бола бастады. Саусақ ізі — саусақтардың соңғы буыны мен ұшындағы қатпарлардан түзілетін, әр адамда қайталанбайтын өрнек. Бөпеңіздің қолдары мен аяқтары тез сүйектеніп, шынтақтары қалыптаса бастады. Соған қарамастан, оның әлі де кішкентай "құйрығы" бар. Бұл құйрық алдағы бірнеше аптада кішірейіп, жоғалады. Құйрығы сақталған кезде бөпеңіз эмбрион деп аталады. Құйрығы толығымен жоғалатын 11-ші және 12-ші аптадан кейін ұрықтық кезең басталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүгін 8-ші аптаны аяқтаймыз! 🎉 Енді мен ресми түрде "Эмбрионнан" "Ұрық" кезеңіне өтуге дайындалып жатырмын. Барлық маңызды ағзаларым – жүрегім, миым, асқазаным, өкпем – өз орнында. Енді тек өсіп, жетіліп, сүйкімді бола түсуім керек. Жүктіліктің ең қиын әрі қауіпті кезеңін артта қалдырдық, Anacan. Сен мені өте жақсы қорғадың, саған рақмет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызыл үрме бұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің бірінші триместрінің соңына жақындаған осы күндері жүрегіңіз қан тамырларына көбірек қан айдай бастады. Жүктілік кезінде жүрек соғысы әдеттегіден жиілейді. Осылайша, 1 минут ішінде ағзаға айдалатын қан мөлшері де табиғи түрде артады. Қан қысымы жүктіліктің 3-ші триместрінде ең жоғары деңгейіне жетеді.;;;
Жүктілік кезінде теріде ең жиі кездесетін өзгерістердің бірі — пигментацияның өзгеруі. Бұл жағдай әдетте қараторы әйелдерде емізік айналасының, жыныс аймағының, кіндік маңындағы және жалпы тері реңінің сәл күңгірттенуі түрінде байқалады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Екінші айды сәтті аяқтағаныңыз үшін өзіңізге шағын сыйлық жасап, демалыңыз. Қан көлемі артқандықтан, темір мен ақуызға бай тағамдарға (жасымық, қызыл ет, жұмыртқа) ерекше мән беріңіз. Беліңіз ауырса, ұйықтаған кезде аяқтарыңыздың арасына жастық қою жеңілдік беруі мүмкін. Келесі аптада бізді үшінші айдың алғашқы қадамдары күтіп тұр. Эмоциялық тұрғыдан ширыққаныңызды сезсеңіз, терең тыныс алып, бөпеңізбен сөйлесіңіз.') WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ми тінінің дамуы өте жоғары қарқынмен жалғасуда. Мидың бұлшықет қимылдарын басқаратын аймағы жұмыс істей бастады. Яғни бөпеңіз енді қозғала алады. Әзірге оның осы кішкентай қимылдарын сезе алмайсыз.;;;
Бөпеңіз осы кезеңнің өзінде тітіркендіргішке тап болса, оған жауап бере алады. Дамып келе жатқан жүйке жүйесі бұлшықеттермен байланыс орната бастады. Бүкіл денесіндегідей, бетінде де сүйектер мен шеміршектер біртіндеп қалыптасып, әсіресе ауыз қуысы мен таңдайы айқындала бастады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ықылық атып жатырмын! 🤭 Сенбейтін шығарсың, бірақ менің диафрагмам (тыныс алу бұлшықетім) қалыптасып, мен ықылық ата бастадым. Сен мұны әлі сезбейсің, өйткені мен өте кішкентаймын әрі дыбыссыз ықылықтаймын. Бұл — болашақ тыныс алуға арналған жаттығуым. Өмірге дайындық жүріп жатыр! Мен сенің құрсағыңда өскен сайын жаңа дағдыларды көбірек үйреніп келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызыл үрме бұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Ұдайы ұйқы келу, бас ауыруы, асқазанның түйілуі және әлсіздік сияқты шағымдарыңыз болуы мүмкін. Бұл жүктілік кезінде қанда эстроген мен прогестерон гормондарының көп мөлшерде бөлінуіне байланысты. Осы апталарда шап аймағының ауыруы көптеген болашақ аналарға тән және көбіне қауіп төндірмейді.;;;
Бөліндінің көбеюі Сізді алаңдатпасын. Екі есе ұлғайған жатырыңыз бөпеңізге қолайлы әрі қауіпсіз орта қалыптастыру үшін көп мөлшерде бөлінді бөледі.;;;
Ағзаңызға бұрынғыдан да көп су қажет. Күніне кемінде 10 стақан су ішу осы қажеттілікті өтеуге көмектеседі.;;;
Кейбір тағамдарды шамадан тыс қалау халық арасында жерік болу деп аталады. Жеріктіктің нақты себептері толық анықталмаса да, оған жүктілік кезінде болатын гормондық өзгерістер мен соған байланысты қандағы қант деңгейінің ауытқуы әсер етеді деп есептеледі. Жерік болу 12-ші аптадан бастап бәсеңдейді. Одан ұзаққа созылатын жеріктік әдетте психологиялық себептермен байланысты. Ағзаға қажетті тағамдарға тәбеттің мүлде болмауы және оларды жеткілікті тұтынбау жағдайларын қоспағанда, жеріктіктің белгілі бір зияны жоқ.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы аптада өзіңізді әдеттегіден де шаршаңқы сезінуіңіз мүмкін; күн ішінде жиі, бірақ қысқа уақыт демалыңыз. Ағзаңыз бөпеңіздің қарқынды өсуіне көп энергия жұмсайды, сондықтан рационыңыздағы ақуызға бай тағамдарды (жасымық, жаңғақ, жұмыртқа) көбейтіңіз. Қызыл иектің сезімталдығына байланысты ауыз қуысының гигиенасына ерекше көңіл бөліңіз. Егер токсикоз әлі де мазаласа, күні бойы аз-аздан тамақтануға тырысыңыз.') WHERE id = 'bef0eb9c-a062-4017-9195-e0a1a182972b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бастың екі жағында кішкентай қара нүктелер түрінде орналасқан көздер пигменттердің көбеюіне байланысты енді анық көріне бастады. Бөпеңіздің қабақтары қалыптаса бастады, бірақ олар әлі ұзақ уақыт жабық болады.;;;
Бөпеңіз таңғаларлық жылдамдықпен қалыптасып, өсіп келеді. Жасушаларға қажетті энергияны алу үшін бөпеңізге глюкоза қажет. Әлі де эмбрион деп аталатын бөпеңіз бұл қажеттілігін жатырда пайда болған плацента арқылы өтейді. Сіз жеген тағамдардың қоректік заттары қан арқылы, плацентаның көмегімен бөпеңізге жеткізіледі.;;;
Бөпеңіздің ішектері жылдам ұзарғандықтан, иіріліп орналасқан және дамуы аяқталғанға дейін иіріле береді. Тоқ ішек баяуырақ ұзарғандықтан, оның құрылымы түзуірек болады. Ішектердің құрсақ қуысында толық орнығуы үшін тағы біраз уақыт қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Қабақтарым қалыптасып жатыр! 👁️ Көздерімді қорғау үшін қабақтарым пайда болып, жақын арада бірігіп жабылады. Шамамен 27-ші аптаға дейін көздерімді ашпаймын. Қазір ішкі әлеміме назар аударып, ұзақ ұйқы режиміне ауысып жатырмын. Бірақ уайымдамаңыз, көздерім жабық болса да, жарықты сезе аламын. Сізді түсімде елестетемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызыл үрмебұршақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілікке дейін салмағы шамамен 60 грамм болған жатырыңыз екі есе үлкейді. Өсіп келе жатқан жатыр қуыққа қысым түсіретіндіктен, дәретханаға бару жиілігі артуы мүмкін. Жүктілік ілгерілеп, жатыр жоғары көтерілген сайын қуыққа түсетін қысым азайып, жиі зәр шығару шағымыңыз бәсеңдейді.;;;
Ішінде бөпеңіз жылдам өсіп жатқан жатыр — жүктілік кезінде іштің үлкеюіне әсер ететін негізгі фактор. Сізде әлі де омыраудың сезімталдығы мен шап аймағындағы ауырсыну сияқты ерте жүктілік белгілері болуы мүмкін. Омырауыңыздың түсі қоюланып, емізік айналасында қоңыр нүктелер пайда болуы ықтимал. Монтгомери төмпешіктері деп аталатын бұл түзілістер — емізік айналасында орналасқан ұсақ май бездері. Олар теріңіздің pH тепе-теңдігін сақтайтын және емізікті кез келген инфекциядан қорғайтын табиғи май бөледі.;;;
Осы аптада ағзаңыздағы қан көлемі жүктілікке дейінгі кезеңмен салыстырғанда 12% артық. Бұл бейімделу кезінде қан қысымының жоғарылауына байланысты мұрыннан қан кетуі мүмкін. Дегенмен мұрныңыздан жиі қан кетсе, дәрігеріңізбен кеңескен жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылдың алдын алу үшін тамақ ішкен бойда жатпаңыз және кешкі асты ұйықтардан кемінде 2-3 сағат бұрын ішіп қойыңыз. Жүрек соғысыңыз сәл жиілесе, уайымдамаңыз: бұл ағзаңыздың бөпеге көбірек қан жеткізу үшін жасап жатқан жұмысы. Омега-3-ке қажеттілік артқандықтан, дәрігеріңізбен кеңесіп, рационыңызға жаңғақ немесе балық қоса аласыз. Күн ішінде терең тыныс алып, медитация жасау Сіздің де, бөпеңіздің де жүйке жүйесін тыныштандырады.') WHERE id = 'b8a881d9-b2c4-4857-81a9-360b7ca73418';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жыныс мүшелері әлі жетіле қоймағанымен, жасушалар аналық без немесе аталық без ретінде қалыптаса бастады. Бөпеңіздің қолдарында жүйке тіндері пайда болып, жұмыс істей бастады. Сонымен қатар жұлын да қарқынды дамып келеді. Қаңқа тіні әлі шеміршек күйінде болғанымен, алдағы бірнеше апта ішінде толықтай сүйектенеді.;;;
Бөпеңіздің кішкентай жүрегі қан айналымын қамтамасыз ету үшін минутына орта есеппен 150-160 рет соғады. Осы аптадан бастап бөпеңіздің жүрек қақпақшалары қалыптаса бастады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қызбын ба, әлде ұлмын ба? 🩷💙 Денемде жыныс мүшелерім (аналық бездер немесе аталық бездер) қалыптасып жатыр. Бірақ сырттай әзірге байқалмайды. Дәрігерлер де әлі айта алмайды, бұл — менің кішкентай құпиям. Сіз қызды қалайсыз ба, әлде ұлды ма? Ең бастысы — денім сау болып, Сіздің бөпеңіз болайын. Қай жағдайда да Сізді қатты жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Зәйтүн'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпеңіз өскен сайын жатырыңыз созылып, түйілу тәрізді ауырсыну тудыруы мүмкін. Мұндай ауырсыну күтілетін және қалыпты жағдай болып саналады. Егер түйілулер өте жиі болып, ұзаққа созылса, бұл туралы дәрігеріңізге хабарлаған жөн. Қаныңыздағы гормондар деңгейінің өте жоғары болуына байланысты жүрек айну мен құсу қалыпты саналады. Соның салдарынан салмақ жоғалтуыңыз мүмкін. Алайда салмақ жоғалту айтарлықтай болса, дәрігеріңізбен кеңесіңіз: ол Сізге қосымша тағамдық қоспалар ұсынуы мүмкін. Киімдеріңіз де тар бола бастауы ықтимал. Әсіресе ішіңізді қыспайтын киімдерді таңдаған жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Теріңіздің қышуы мен тартылуын азайту үшін табиғи құрамды ылғалдандырғыштарды немесе бадам майын қолдана бастаңыз. Бөпеңіздің сүйектері берік болуы үшін тамақтанудағы кальций мен D дәруменінің тепе-теңдігіне (сүт өнімдері, жұмыртқаның сарысы) назар аударыңыз. Түнгі ұйқыңыздың сапасын жақсарту үшін ұйықтар алдында бөлмені желдетіңіз. Күн сайын өзіңізге бірнеше минут бөліп, бөпеңізбен сөйлесу араларыңыздағы байланысты одан әрі нығайтады.') WHERE id = '1e725a51-c2e7-489a-9924-d2713767d7e6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тілі мен ерні дами бастады. Тілді және онда орналасқан дәм сезу бүртіктерін көпқабатты жалпақ жасушалар қалыптастырады. Дәм сезу бүртіктері тіл бетіндегі кішкентай төмпешіктерде орналасады. Олар жеген тағамымыздың ащы, қышқыл, тәтті немесе тұзды екенін сезуге мүмкіндік береді. Жақын арада ауыз қуысында дамитын сілекей бездері жұп-жұбымен өз орындарына орналаса бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің «үйім» өзгеріп жатыр, Anacan! 🏠 Осы уақытқа дейін мені қоректендірген «Сарыуыз қапшығы» біртіндеп кішірейіп келеді, өйткені енді жұмысты керемет Плацентам қабылдап жатыр. Бұл плацента — Сіз бен менің арамыздағы көпір. Ол мені қорғайды, қоректендіреді және оттегімен қамтамасыз етеді. Біздің байланысымыз бұрынғыдан да күшті әрі берік. Мұның бәрі Сіздің арқаңызда!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Зәйтүн'), body_changes_kk = COALESCE(body_changes_kk, 'Қалқанша бездің міндеті — гормондарды синтездеу, жинақтау және қан айналымына бөлу. Бұл гормондардың түзілуіне қажет йод тұз, ауызсу немесе тағам арқылы ағзаға түседі және денедегі барлық жасушаларға әсер етіп, ағза қызметтерін басқаруда маңызды рөл атқарады. Егер қандағы қалқанша без гормондарының мөлшері аз болса, ағзаның жұмысы баяулайды. Бұл жағдай гипотиреоз деп аталады. Ал қанда бұл гормондардың мөлшері көп болса, ағза жылдамырақ жұмыс істейді. Бұл жағдай гипертиреоз деп аталады. Қалқанша без өндіретін гормондардың мөлшерін гипофиз деп аталатын басқа без және мидың гипоталамус деп аталатын аймағы реттейді. Жүктіліктің басталуынан босануға дейін ағза жүйелерінде құрылымдық және қызметтік өзгерістер жүреді. Жүктілік бойы гормондық жүйелердің өзгеруі нәтижесінде кейбір жүкті әйелдерде гипотиреоз дамуы мүмкін. Бұл жағдай ана мен бөпеге жағымсыз әсер етуі ықтимал болғандықтан, оны дер кезінде анықтап, емдеу маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Іштің кебуі мен ас қорыту мәселелерін азайту үшін тамақты мұқият шайнаңыз және газдалған сусындардан бас тартыңыз. Аяқтарыңыз ісінсе, күн ішінде бірнеше рет оларды жоғары көтеріп, 10 минут демалыңыз. Тұз тұтынуды реттеңіз, бірақ оны толықтай алып тастамаңыз. Бірінші триместрдің соңына жақындағандықтан, эмоционалдық жағдайыңызға көбірек көңіл бөліңіз; күйзелістен аулақ болу бөпеңіздің жүйке жүйесі үшін өте маңызды.') WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзалары тұрақты дамуын жалғастырып жатқан осы аптада көкбауыр мен бауыр құрсақ қуысындағы өз орындарына жайғаса бастайды. Иммундық жүйенің қосалқы ағзасы ретінде қызмет атқаратын көкбауыр, сондай-ақ тыныс алу ағзаларынан тіндерге оттегін, ал тіндерден тыныс алу ағзаларына көмірқышқыл газын тасымалдайтын гемоглобин ақуыздары ыдырағанда түзілетін сары-қызғылт сары түсті билирубин пигментінің ағзадан шығарылуын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің құйрығым жоғалып кетті! 🐇 Есіңізде ме, Сізге кішкентай құйрығым бар екенін айтқан едім? Енді ол жоқ! Қазір арқам түзу әрі тегіс, нағыз адам омыртқасы бар. Мен күн өткен сайын Сізге көбірек ұқсап келемін, Anacan. Енді мен кішкентай теңіз атшасы емеспін, Сіздің кішкентай адамыңызбын. Бұл өзгеріс мені қатты қуантады, ал Сізді ше?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүзім'), body_changes_kk = COALESCE(body_changes_kk, 'Жатырыңыз ұлғаюын жалғастырып келеді және әлі де жамбас сүйектерінің артында орналасқандықтан, ішіңіз байқалмайды, бірақ Сіз ауырлықты сезесіз. Қуыққа түсетін қысым артқандықтан, дәретханаға жиі бару қажеттілігі әлі де сақталады. Сондай-ақ қан қысымыңыз аздап ауытқуы мүмкін, сондықтан орныңыздан кенет тұрған кезде басыңыз айналуы ықтимал. ;;;
Жүктіліктің басында 60-70 грамм болатын жатырдың салмағы жүктіліктің соңында 1000 грамнан асады. Басқаша айтқанда, жүктілікке дейін шабдалыдай болған жатыр жүктіліктің соңында қарбыздай болады. Жұдырықтан да кішкентай жатыр бөпе өскен сайын оған орын босату үшін ішінен созыла бастайды және 5 килограмм салмақты көтере алатындай ұлғаяды. Ішіңіздің өсу қарқыны құрсақ бұлшықеттерінің құрылымына байланысты өзгергенімен, 12-ші аптаға дейін салыстырмалы түрде баяу, ал соңғы триместрде өте жылдам өседі. Екінші рет жүкті болған әйелдердің құрсақ бұлшықеттері бұған дейін созылғандықтан, олардың іші алғаш рет жүкті болған әйелдерге қарағанда ертерек байқалады. Жатыр бірнеше есе ұлғаятын 9 айлық жүктіліктен кейін босанғаннан кейінгі 2 ай ішінде бұрынғы көлеміне қайта оралады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде қан көлемі артатындықтан, темірге бай тағамдарды (жасымық, жасыл жапырақты көкөністер, қызыл ет) көбірек тұтынуға тырысыңыз. Егер ішіңіздің терісі қышып немесе құрғап жүрсе, оны ылғалдандырғыш кремдермен немесе табиғи майлармен уқалаңыз. Күні бойы су ішуді ұмытпаңыз, өйткені су ас қорытуды жақсартып қана қоймай, қағанақ суының жаңаруы үшін де маңызды. Өзіңізді қатты шаршатпай, қысқа серуендеу көңіл күйіңізді көтереді.') WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің құлағында естуге қатысы жоқ, дене тепе-теңдігін сақтауға көмектесетін арнайы өзектер қалыптасады. Осы жүйенің арқасында ол болашақта құламай қозғала алады. Сонымен қатар құлақтары біртұтас механизм ретінде қалыптасып келеді: сыртқы құлақ дыбысты жинайды, ортаңғы құлақ оны күшейтеді, ал ішкі құлақ миға жеткізеді.;;;
Ал бөпеңіздің миы қазір қарқынды электр толқындары арқылы жұмыс істейді. Бұл толқындар жай ғана жанама өнім емес, мидың әртүрлі бөліктерінің бір-бірімен байланысып, ақпарат алмасуына арналған негізгі "жол" болып табылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен шынтақтарымды бүге аламын! 💪 Енді қолдарым жай ғана түзу таяқша емес. Шынтақ буындарым қалыптасты, енді қолдарымды кеудеме қарай бүге аламын. Өзімді құшақтап жатқандаймын. Бір күні осы қолдарыммен Сізді құшақтаймын. Қимылдарым барған сайын күрделеніп келеді: енді мен жай ғана жүзіп қоймай, денемді басқаруды да үйреніп жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүзім'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік туралы ойға келген алғашқы белгілердің бірі — жерік болу. Жүкті әйелдердің көпшілігінде кездесетін жерік болу — кейбір тағамдарды шамадан тыс қатты қалау. Негізінен ақуызды тағамдармен қоректенетіндер көмірсуы мол тәттілерді, ал көмірсуы басым тағамдарды тұтынатындар ақуызға бай өнімдерді қатты қалауы мүмкін. Жеміс жегіңіз келуі дәрумендерге, ал сүт өнімдерін қалауыңыз кальцийге қажеттілікті білдіруі ықтимал. Жүктіліктің әр кезеңінде әртүрлі тағамға жерік болуыңыз мүмкін. Калорияға қажеттілік артқан кезде тәттілер мен шоколад сияқты калориясы жоғары тағамдар көбірек тарта бастайды. Сондай-ақ кейбір дәрумендер жетіспегенде шоколадқа деген құштарлықтың артатыны белгілі. Бұл кезеңде әр тағамды мөлшерімен тұтыну пайдалы, ал артығы денеңізге қосымша салмақ болып жиналатынын ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы қандағы қант деңгейі төмендеп кетпеуі үшін аз мөлшерде, бірақ жиі тамақтануды жалғастырыңыз. Жаныңызда әрдайым бірнеше жаңғақ немесе бадам алып жүріңіз. Мұрынның бітелуі мазаласа, бөлме ауасын ылғалдандыру көмектесуі мүмкін. Күн сайын кемінде 10-15 минут тыныш жерде терең тыныс алып, бөпеңізбен байланыс орнатуға тырысыңыз. Сіздің тыныштығыңыз оның дамуы үшін ең маңызды фактор екенін ұмытпаңыз.') WHERE id = 'a019329d-4564-4a4c-a50f-391f0feef37e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің кішкентай саусақтары жылдам ұзарып келеді. Бұл күндер қолдар мен аяқтардың қалыптасуы үшін аса маңызды кезең болып саналады. Саусақтармен бірге қолдары мен аяқтары ұзарып, шынтақтары бүгіле бастады. Жүйке желісі бөпеңіздің қолдары мен аяқтарын белсенді қимылдатып, тітіркендіргіштерге жауап беруіне жеткілікті дәрежеде дамыған. Сәті түссе, ультрадыбыстық зерттеу кезінде бөпеңіздің қимылдап жатқанын көре аласыз! Бөпеңіз енді толықтай адам кейпіне ене бастады. Басы денесіне қарағанда үлкенірек болғанымен, ағзалары жылдам өсіп, дамып, өз орындарына жайғасуын жалғастырып келеді.;;;
Осы аптадан бастап бөпеңіздің репродуктивті ағзалары қалыптаса бастады, алайда сыртқы жыныс мүшелерінде жынысын айқын көрсететін белгілер әлі пайда болған жоқ. Сондықтан бөпеңіздің жынысын білгіңіз келсе, тағы бірнеше апта күтуіңіз керек.'), baby_message_kk = COALESCE(baby_message_kk, 'ҚҰТТЫҚТАЙМЫН, ANACAN! МЕН КЕЛЕСІ КЕЗЕҢГЕ ӨТТІМ! 🎓 Бүгін мен үшін тарихи күн. Енді мен "Эмбрион" емеспін, ресми түрде "Ұрық" деп аталамын! Бұл менің барлық ағзаларым қалыптасып болғанын білдіреді. Енді тек өсіп, салмақ қосып, күш жинайтын уақыт келді. Ең қауіпті кезеңнен өттік! Біз мұны бірге еңсердік. Сіз менің қаһарманымсыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүзім'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы үш айында қосымша калория қажет емес, алайда дұрыс тамақтану маңызды. Бұл кезеңдегі дұрыс тамақтану бөпенің зияткерлік дамуы үшін өте маңызды. Бөпенің өсуі мен ақыл-ойының дамуын қамтамасыз ету үшін қажетті қоректік заттардың барлығын жеткілікті мөлшерде қабылдау керек. Жүктілік кезіндегі мінсіз салмақ қосу, яғни барлығына ортақ жалғыз "дұрыс салмақ" деген түсінік жоқ. Ананың жүктілік кезіндегі салмақ қосуы жүктілік басталғандағы салмағына байланысты әр әйелде әртүрлі болады. Мақсатты салмақ өсімі жүктілікке дейінгі дене салмағының индексі, яғни салмақтың бойға арақатынасы бойынша есептеледі. Салмағы қалыпты әйелге жүктілік кезінде қажет қосымша энергия тәулігіне орта есеппен 300 калорияны құрайды. 300 калория шамамен 3 дана бананға, 5 дана алмаға, 100 грамм жасымық тағамына, 1 кесе майлы йогуртқа немесе 3-4 тілім нанға тең. Күні бойы бұдан артық қабылдаған калориялар денеңізде май қоры түрінде жиналып, көздеген салмақ мөлшерінде қалуыңызға кедергі келтіреді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бірінші триместрдің соңына жақындағандықтан, өзіңізді бұрынғыдан да көбірек күтіңіз. Зат алмасуыңыз жылдамдағандықтан, жиі ашығуыңыз мүмкін; сондықтан жаныңызда пайдалы тіскебасарлар алып жүріңіз. Беліңіз ауырса, ұйықтағанда бір қырыңызбен жатып, тізелеріңіздің арасына жастық қою омыртқаңызға түсетін жүктемені азайтады. 10-шы аптаға өтерде алғашқы скринингтік тексерулер туралы дәрігеріңізбен сөйлесуді ұмытпаңыз.') WHERE id = '65677248-c635-4f55-8483-617e735f69ca';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тістері туғаннан кейін шамамен 6 айдан соң көрінгенімен, олардың негізі қазірден қалана бастайды. Ауыз қуысында пайда болған арнайы қалыңдаған тіннің үстінде кішкентай төмпешіктер, яғни тіс бүршіктері қалыптаса бастайды.;;;
Төменгі және жоғарғы жақтың әрқайсысында 10-нан, барлығы 20 сүт тісінің бүршігі пайда болады. Бұл үдеріс белгілі бір ретпен жүреді: алдымен алдыңғы тістердің, содан кейін бүйірдегі, ең соңында артқы тістердің бүршіктері қалыптасады. Бір қызығы, дәл осы тін болашақта сүт тістерін алмастыратын тұрақты тістердің дамуына да негіз болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жүзуден чемпионмын! 🏊‍♂️ Судың ішінде тынымсыз қимылдап жүрмін. Аяғыммен тебемін, бұрыламын, сальто жасаймын. Сіз мұның бәрін әзірге сезбейсіз, өйткені айналамдағы су жастық сияқты соққыларды жұмсартады. Бірақ іште үлкен олимпиада өтіп жатқанын біліп жүріңіз. Сізбен кездескенде мықты болу үшін жаттығып жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Орман жаңғағы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің 3-ші айына аяқ басқан осы аптада омырауыңыздың толысқанын сезген боларсыз. Ана сүтін өндіруге дайындық ретіндегі омырау тініндегі алғашқы өзгерістер жүктіліктің осы кезеңінде басталады, алайда сүттің өндірілуі жүктіліктің ортасына қарай ғана басталады. Жүктілік кезінде ана сүтін өндіруге дайындыққа көптеген гормон қатысады. Бұл гормондар бездер мен сүт жолдарын сүт өндіруге және өндірілген сүттің бөлінуіне бейімдеуде маңызды рөл атқарады. Омырау ішіндегі бездер мен сүт жолдарының көбеюіне байланысты жүктілік кезінде омырау көлемі тез ұлғайып, жүктіліктің соңында салмағы шамамен 1 килограмға жетеді. Мидың төменгі бөлігінде орналасқан гипофиз безінен бөлінетін пролактин гормоны омырау тініндегі арнайы жасушалармен байланысып, сүт өндіруде негізгі рөл атқарады. Ал гипофизден бөлінетін тағы бір гормон — окситоцин, әсіресе бөпе омырауды еме бастағанда бөлінеді. Сүттің сүт жолдары арқылы омырау ұшына ағуын да осы гормон қамтамасыз етеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бас айналудың алдын алу үшін кенет қимыл жасамаңыз, әсіресе төсектен тұрғанда алдымен бірнеше секунд отырып алыңыз. Ас қорыту жүйесінің жұмысын жеңілдету үшін жасұныққа бай тағамдарды (кептірілген жемістер, сұлы, көкөністер) жеп, суды молынан ішіңіз. Егер қуатыңыз қалпына келсе, жүкті әйелдерге арналған жеңіл йогамен немесе тыныс алу жаттығуларымен айналысу өзіңіздің де, бөпеңіздің де саулығы үшін өте пайдалы.') WHERE id = '12d3b899-0764-4ab2-902c-2efe92103462';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз қазір аузын ашып-жұму, басын бұру және орнын ауыстыру сияқты қимылдарды жасай алатындай дамыған. Оның үстіне, бөпеңіз қолайлы қалыпта жатса, бұл қимылдарды ультрадыбыстық зерттеу кезінде көре алатындай өсті!;;;
Жүктіліктің 7-ші және 9-шы апталары аралығында бөпеңіз бүкіл денесімен серпіліп, секіргендей қимылдайды. Омыртқадағы нейрондардың дамуының арқасында осы аптадан бастап қолдары, аяқтары мен денесі бір-біріне тәуелсіз, жеке-жеке қозғала алады. Бөпеңіздің аяғымен тебу, аяғын ұстау, велосипед тепкендей қимылдау және бұрылу сияқты әрекеттерді орындай алуы үшін тағы 2-3 апта қажет.;;;
Сонымен қатар, бұл — қолдары мен аяқтары ұзарып, аяқ саусақтары пайда бола бастайтын, шынтақтары мен білектері анық көрінетін кезең.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көлемім кептірілген өріктей! 🍓 Күн сайын өсіп, өзгеріп келемін. Құлақтарым басымның жанынан біртіндеп жоғары көтеріліп, өз орындарына орналасып жатыр. Көздерім әлі жұмулы, бірақ торлы қабығым (ретина) жарықты ажырата алады. Сіз күнге шыққанда, мен оның жылуы мен жарығын сезе аламын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Жатыр ұлғайған сайын жамбас сүйектерінен жоғары көтеріле бастайды. Бұл қуыққа түсетін қысымды сәл азайтуы мүмкін. Ішіңіздің төменгі жағында қатайған жерді сезуіңіз ықтимал.;;;
Жүктілік кезінде гемоглобин көрсеткішінің жоғарғы шегі босану кезінде орта есеппен 11-12% деңгейінде болады деп есептеледі. Көрсеткіштер бұдан төмен болса, темірді қосымша қабылдау қажет болады. Мидың қорегі деп саналатын темір — жүктілік кезіндегі дұрыс тамақтанудың ең маңызды элементтерінің бірі және бөпеңіздің танымдық дамуы үшін қажет. Сау эритроциттердің жеткілікті болуы анемия қаупін азайтады. Кейде темір тапшылығы деп те аталатын анемия шаршау, қалжырау және әлсіздік тудырады. Жүктілік кезіндегі темірге деген қажеттілікті өтеу үшін қызыл ет, саумалдық, брокколи, жасыл жасымық, жапырақты қырыққабат, ноқат және үрмебұршақ сияқты тағамдарды тұтынған пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Интимдік гигиенаға көңіл бөліңіз, бірақ сабын немесе душқа арналған гельдерді қолданғанда абай болыңыз. Табиғи pH теңгерімін бұзбайтын құралдарды таңдаңыз. Күнделікті төсемдерді қолдансаңыз, оларды жиі ауыстырыңыз.') WHERE id = '56fa6e29-fd7a-4a03-984e-0590d982556b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Қаңқа жүйесі мен сүйектену қарқынды дамитын осы кезеңде D дәруменін қабылдау өте маңызды. Бұл дәрумен кальций мен фосфордың ағзаға сіңуін қамтамасыз етіп, бөпеңіздің сүйектерінің дұрыс қалыптасуына көмектеседі. D дәруменінің қызметі сүйектерді нығайтумен ғана шектелмейді; ол иммунитетті күшейтіп, жүйке жүйесінің жұмысын реттейді және жүрек соғысын қалыпқа келтіреді. Оның тапшылығы бөпенің дамуының баяулауына, сондай-ақ ананың бұлшықеттерінің әлсіреуі мен шаршауына әкелуі мүмкін. D дәруменінің ең маңызды көзі — күн сәулесі. Сонымен қатар ол балық майы, асшаян, устрица, сүт және сүт өнімдері, картоп пен таңғы асқа арналған дәнді дақылдарда кездеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүйректерім жұмыс істеп тұр! 🚽 Иә, бұл сәл оғаш естілуі мүмкін, бірақ мен қазірдің өзінде зәр шығарамын. Қағанақ суын жұтамын, бүйректерім оны сүзіп, қайтадан суға бөледі. Бұл айналым ас қорыту және зәр шығару жүйелерімнің дұрыс жұмыс істеуі үшін өте маңызды. Мен өз-өзімді тазартатын жүйемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Құйрықтың жойыла бастауымен бөпеңіз үшін жаңа кезең басталады. Бұған дейін эмбрион деп аталған бөпеңіз енді ұрық (фетус) кезеңіне өтті және босанғанға дейін ұрық деп аталады. Эмбриондық кезең — ағза жүйелері қалыптасатын уақыт. Ал ұрықтық кезең — қалыптасқан ағзалар, тіндер мен құрылымдар өсіп, дамитын кезең. Бірінші триместрдің соңғы айына аяқ басқан осы уақытта жүктілікке тән жайсыздықтар әлі де мазалауы мүмкін. Жүктілік кезіндегі депрессияны емдеуден бұрын оның алдын алу маңызды. Осы кезеңде сүйікті істеріңізбен айналысу, жақсы көретін адамдарыңызбен уақыт өткізу, жұбайыңыз бен жақындарыңыздан қолдау алу пайдалы болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан көлемінің артуына байланысты жиі шаршауыңыз мүмкін; күндізгі 15 минуттық "күш беретін ұйқы" қуатыңызды қалпына келтіреді. Түнде аяқтарыңыз кенеттен құрысып қалмауы үшін магний мен кальцийді жеткілікті қабылдауға көңіл бөліңіз. Күн сайын кемінде 2 литр су ішіңіз. Егер өткір иістерден әлі де қашқақтасаңыз, жалбыз шайы немесе лимон қосылған су асқазаныңызды тыныштандыруы мүмкін.') WHERE id = '17780e60-9b95-4f39-9e38-8371589b8dad';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миы көбірек ақпаратты шағын кеңістікке сыйғызу үшін қатпарланып, иірімді пішінге ене бастайды. «Сұр зат» деп аталатын бұл сыртқы қабат миды қаптама секілді жауып, дамыған сайын бедері айқынырақ бола түседі. Бұл аймақ мидың басқару орталығы болып саналады.;;;
Сонымен қатар, бөпеңіздің жүрегі 4 камерадан тұратын толық пішінге енді. Жүректің ішіндегі қақпақшалар бір бағытта ашылатын есік қызметін атқарады. Жүрек жиырылып, қанды айдаған сайын бұл қақпақшалар ашылып, қанның тек алға қарай ағуын қамтамасыз етеді және кері қайтуына жол бермейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Тістеріме дайындық жүріп жатыр! 🦷 Аузымда әлі бірде-бір тіс жоқ, бірақ қызыл иегімнің астында кішкентай тіс бүршіктері пайда болуда. Олар болашақта шығатын сүт тістерімнің негізі. Сізге күлімсірейтін күнімді қазірден жоспарлап жүрмін. Сіз де тістеріңізге жақсы күтім жасаңыз, Anacan, өйткені кальций қорыңызды маған беріп жатырсыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Орман жаңғағы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің 2 айын артқа қалдырған осы күндері Сізде кейбір жайсыздықтар болуы мүмкін. Солардың бірі — зәр ұстай алмау. Зәр ұстай алмау дегеніміз — адамның өз еркінен тыс зәрін ұстап тұра алмауы. Жүктілік кезінде жиі кездесетін бұл жағдай алғашқы 3 айда үлкейіп келе жатқан жатырдың дәл астында орналасқан қуыққа қысым түсіруінен туындайды. Сондай-ақ қуық толық босай алмайтындықтан, жиі зәр шығару қажеттілігі болуы мүмкін. Соңғы триместрде пайда болатын зәр ұстай алмау бөпенің қуыққа қысым түсіруінен болады және жүкті әйелдердің шамамен 35%-інде байқалады деп есептеледі. Бұл — физиологиялық жағдай және әдетте жүктілік аяқталғаннан кейін жоғалады. Зәр шығаруды кейінге қалдырмау, құрсақішілік қысымды арттыратын оқыс қимылдардан аулақ болу және ауыр жүк көтермеу бұл шағымды азайтуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы аптада өзіңізді сәл сергек сезінуіңіз мүмкін, өйткені гормондар тұрақтана бастайды. Қызыл иектің сезімталдығы әлі де сақталатындықтан, кальцийге бай тағамдарға басымдық беріңіз. Егер беліңіз ауыра бастаса, дене қалпыңызға мән беріп, тым ұзақ уақыт тік тұрып қалмаңыз. Бірінші триместрдің соңына жақындағандықтан, дәрігеріңізбен «Қосарланған тест» (скрининг) туралы кеңесуге дәл қазір қолайлы уақыт.') WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бет әлпеті енді анығырақ көріне бастады; аузы, мұрны және құлақтары өз орындарына қарай жылжуда. 9-шы аптада көздің дамуы айтарлықтай ілгеріледі. Көздің ішінде көруді қамтамасыз ететін, миллиондаған жасушадан тұратын жұқа торқабық қабаты қалыптасып, ондағы қан тамырлары жасушаларды қоректендіре бастайды.;;;
Сонымен қатар, көздің түсті бөлігі — нұрлы қабық та дамуын аяқтауға жақын. Қазір бұл құрылым көгілдір түсті. Жаңа туған бөпелердің алғашқы айларда көздерінің әдетте көк болып көрінуі де осы бастапқы түс пигментіне байланысты.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүрегім Сіздікінен екі есе жылдам соғады! 💓 Минутына шамамен 170 рет! Дәрігерге барсаңыз, доплер аппараты арқылы менің жүрек соғысымды ести аласыз. Сол «дүрс-дүрс-дүрс» деген дыбыс шауып келе жатқан аттың тұяқ дүбіріне ұқсайды. Бұл дыбыс Сізге «Мен осындамын, мен күштімін!» дейді. Менің ырғағым — Сіздің өміріңіздің әуені.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Орман жаңғағы'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңізде «газ көпіршіктеріне» ұқсас сезімдер болуы мүмкін, бірақ оны бөпенің қимылымен шатастырмаңыз — оған әлі ерте. Бұл тек ішектің қозғалысы. Прогестеронның әсерінен ас қорыту жүйесі өте баяу жұмыс істейді, соның салдарынан іш кебеді. ;;;
Жүктілік кезінде шалқадан жатқанда қан қысымы ең төмен деңгейге дейін түсуі мүмкін. Сонымен бірге жүрек соғу жиілігі артуы ықтимал. Ал бүйректің қанмен қамтамасыз етілуі шамамен екі есе азаяды. Жатқан қалыпта дененің төменгі бөлігінен жүрекке қан тасымалдайтын төменгі қуыс вена бөпенің салмағынан қысымға ұшырайды. Бұл жағдай «Қуыс венаның қысылу» синдромын туындатуы мүмкін және қан ағымының бөгелуінен пайда болатын жайсыздық ретінде сипатталады. Сондай-ақ жатқан кезде дененің төменгі бөлігінен жүрекке қан жеткізетін төменгі қуыс венаның бөпе салмағынан қысылуы осы жағдайдың туындауына себеп болуы мүмкін. Сондықтан дәрігерлер болашақ аналарға, әсіресе соңғы триместрде, шалқасынан жатпауға кеңес береді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Сүйектер қалыптасып жатқан осы кезеңде кальций мен магнийдің жеткілікті мөлшерде түсуіне ерекше мән беріңіз (бадам, грек жаңғағы, сүт өнімдері). Басыңыз ауырса, таза ауада қысқа уақыт серуендеп, мол су ішіңіз. Жүкті әйелдерге арналған киімге ауысуға әлі ерте болса да, кең әрі созылғыш шалбар таңдасаңыз, өзіңізді жайлырақ сезінесіз. Өзіңізді күйзелістен қорғаңыз; тыныш әуен тыңдау Сізге де, бөпеңізге де жақсы әсер етеді.') WHERE id = 'd416ae4b-bb0c-425b-b304-d18dd9ac3813';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бауыры, өт қабы, көкбауыры және бүйректері де жылдам өсуін жалғастыруда. Бөпеңіздің ауыз қуысы мен жұтқыншағының бірігуі аяқталды. Осы аптада ауыз және мұрын қуыстары бір-бірінен толық ажырап, жұтқыншақпен байланысы қалыптасады. Тілі де қалыптасу үстінде. Бет құрылымдары бірігетін осы нәзік кезеңде даму баяуласа, кейде ерін немесе таңдай жырығы деп аталатын ақаулар пайда болуы мүмкін. Бұл жағдай кішкентай саңылаудан бастап, ерінге дейін созылатын жырыққа дейін әртүрлі түрде кездеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақ іздерім пайда болып жатыр! 👆 Тек өзіме ғана тиесілі, дүниеде ешкімде қайталанбайтын бірегей белгі қалыптасуда. Саусақтарымның ұшында ерекше өрнектер пайда болып келеді. Бұл іздер — менің бірегейлігімнің таңбасы. Мен Сіздің теңдессіз ғажайыбыңызбын, Anacan. Барлығының ұсақ-түйегіне дейін қаншалықты мінсіз жаратылғанын көріп тұрсыз ба?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Орман жаңғағы'), body_changes_kk = COALESCE(body_changes_kk, 'Қуатыңыздың сәл артқанын сезуіңіз мүмкін, өйткені плацента гормон өндіру қызметін толықтай өз қолына алуға жақын. Бұл «сары денеге» тәуелділіктің азайғанын білдіреді. Алайда емшектің сезімталдығы мен көлемінің ұлғаюы жалғасады. Кейде емізіктен сарғыш сұйықтық (уыз) бөлінуі мүмкін — қорықпаңыз, бұл қалыпты жағдай.;;;
Жүктілік кезінде кейбір гормондардың көбеюі қынаптағы pH тепе-теңдігінің бұзылуына әкеледі. Соның салдарынан қынап ішіндегі флора деп аталатын қорғаныш тосқауылдың әсері әлсірейді. Бұл жағдай жүктілік кезінде қынаптан бөлінетін бөліндінің мөлшерін арттырады. Жүктілік кезіндегі физиологиялық қалыпты құбылыс саналатын мұндай бөліндіні емдеу қажет емес. Жалпы гигиена шараларын мұқият сақтау жеткілікті. Егер бөліндінің түсі өзгеріп, жағымсыз иіс пайда болса, болашақ ана дәрігерге қаралуы керек.;;;
Жүктілік кезіндегі зеңдік инфекция ағзаның төзімділігі мен қынап флорасындағы қорғаныш бактериялар санының азаюынан туындайды. Ол ақ түсті, ірімшік тәрізді бөліндімен бірге қатты қышу және ашыту сезімімен білінеді. Оны қауіпсіз суппозиторийлер мен кремдер арқылы емдеуге болады. Сондай-ақ жүкті әйелдерге алдын алу шарасы ретінде мақта маталы іш киім кию, киімдерін кір жуғыш ұнтақпен емес, сабынмен жуып, үтіктеп пайдалану ұсынылады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Суды жақсы көріңіз! Жүзу — жүктілік кезіндегі ең қолайлы спорт түрлерінің бірі. Судың көтеруші күші беліңізге түсетін салмақты азайтып, бойыңызға жеңілдік сыйлайды. Сондай-ақ ісінуді азайтады.') WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бүйректері жұмыс істей бастады. 4-ші аптада кішкентай жасушалар тобы ретінде қалыптасқан бұл ағзалар қазір несеп түзіп, оны амниотикалық сұйықтыққа бөле алатындай дамыды.;;;
Құрсақ қуысында орналасқан бүйректер алдағы апталарда бір-бірінен алшақтап, соңғы пішініне келу үшін 90 градустық бұрышпен бұрылады. Осы аптадан бастап қолқадан тарайтын арнайы бүйрек артериясы қалыптасады. Ол бүйректердің қанмен тікелей қамтамасыз етіліп, толық қуатында жұмыс істеуіне мүмкіндік береді.'), baby_message_kk = COALESCE(baby_message_kk, '10 АПТА! КҮНТІЗБЕДЕГІ ЕКІ ТАҢБАЛЫ САН! 🔟 Anacan, біз 10-шы аптаға жеттік. Мен ресми түрде өсіп келемін. Қазір көлемім қара өріктей. Дамуымның ең маңызды кезеңдерін аяқтадым. Енді тек салмақ қосып, бойымды ұзартып, Сізбен кездесуге дайындалуым қалды. Біз жолдың төрттен бір бөлігін аяқтауға жақынбыз! Сізді мақтан тұтамын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде өз денсаулығыңыз бен бөпеңіздің дұрыс дамуы үшін жеткілікті әрі теңгерімді тамақтанып, қажетті дәрумендердің барлығын қабылдау өте маңызды. Мысалы, С дәрумені, кальций мен фолий қышқылына деген күнделікті қажеттілікті өтеу үшін брокколи, кальций үшін сүт пен сүт өнімдерін, калий үшін банан, ал омега-3 пен омега-6 үшін қуырылмаған жаңғақтар мен дәндерді тұтыну пайдалы. Күн сайын сүт пен сүт өнімдерін жеткілікті мөлшерде тұтыну ана мен бөпенің сүйек жүйесі үшін аса маңызды екенін ұмытпаған жөн. Сонымен қатар үлкен негізгі ас ішудің орнына, күнделікті тағам мөлшерін 5-6 бөлікке бөліп жеу қандағы қант деңгейін тұрақтандыруға көмектеседі. Жүктілік кезінде су ішу де дұрыс тамақтану сияқты маңызды. Су, әсіресе, жүктілік кезінде жиілейтін іш қатуды азайтуға, терінің құрғауы мен созылу іздерінің алдын алуға, несеп жолы инфекцияларының қаупін төмендетуге және бөпенің денсаулығы үшін маңызды қағанақ суының (амниотикалық сұйықтықтың) қалыпты мөлшерін сақтауға белсенді ықпал етеді. Сондықтан тәулігіне 2,5-3 литр су ішу керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Екінші триместрге бір-ақ қадам қалғаны үшін өзіңізді марапаттап, демалыңыз. Қаназдықтың алдын алу үшін тағамыңыздағы темір мен С дәруменінің үйлесіміне (мысалы, ет пен мол көк салатқа) көңіл бөліңіз. Егер әлі де шаршап жүрсеңіз, күндізгі қысқа ұйқы күш-қуатыңызды қалпына келтіреді. Келесі аптада бізді дамудың ең қызықты кезеңдерінің бірі күтіп тұр.') WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Денеміздегі ең үлкен ағза — тері дамудың 3-ші аптасында-ақ үш қабат болып қалыптасады. Осы қабаттардың ең сыртқысы теріні, сондай-ақ оның туындылары болып саналатын түктер мен тырнақтарды түзеді.;;;
9-шы аптадан бастап бөпеңіздің денесінде алғашқы түк фолликулдары қалыптаса бастайды. Лануго деп аталатын бұл жіңішке түктер алдымен үстіңгі ерін, қас және иек аймағында пайда болады. Олар әзірге өте нәзік болғандықтан, ультрадыбыстық зерттеу кезінде тек 20-шы аптаға қарай байқалады. Бұл түктер бөпені ана құрсағында қорғайды және әдетте босануға аз уақыт қалғанда түсіп қалады. Сонымен қатар бөпеңіздің қол және аяқ тырнақтары да біртіндеп өсе бастайды. Қатты кератин қабатынан тұратын тырнақтар тек сыртқы көрініс үшін емес, саусақ ұштарын жарақаттан қорғап, олардың сезімталдығын арттыратын маңызды қалқан қызметін де атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Басым денемнің жартысындай! 🤯 Anacan, мен күлкілі көрінуім мүмкін, бірақ бұл — менің данышпан болуға дайындалып жатқанымның белгісі. Миымның тез өсіп жатқаны сонша, басым денеме қарағанда әлдеқайда үлкен. Бірақ уайымдамаңыз, уақыт өте денем де өсіп, басыма сай болады. Қазір мен кішкентай ғалымға ұқсаймын. Сізбен сөйлесетін күндерді асыға күтемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Бірінші триместрдің соңына қарай жүрек айнуыңыз бәсеңдей бастайды. Сондықтан өзіңізді сергек әрі қуаттырақ сезінуіңіз мүмкін. 3-ші ай басталатын осы аптадан бастап ағзаңыз жүктілікке толық бейімделген күйде болады. Ағзадағы қан көлемінің артуы мен сұйықтықтың жиналуына байланысты ісіну пайда болуы мүмкін. Тамақтану әдеттерін қайта қарап, тұзды азайтып және көбірек қимылдау арқылы бұл ісінуді мазаламайтын деңгейге дейін төмендетуге болады.;;;
Егер жүрек айнуыңыз әлі де жалғасса, аз мөлшерде, бірақ жиі тамақтанып, майсыз әрі көбіне қою тағамдарды таңдау оны бақылауға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күш-қуатыңыз біртіндеп қалпына келе бастағандықтан, жеңіл жаяу серуендеуге кірісе аласыз. Зат алмасуыңыз жылдамдағандықтан, мол су ішуді (күніне кемінде 2-2.5 литр) ұмытпаңыз. Теріңіздегі өзгерістер мен созылу іздеріне қарсы табиғи құрамды ылғалдандырғыштарды қолдануды жалғастырыңыз. Күн сайын өзіңізге 10 минут бөліп, болашақтағы армандарыңыз туралы ойлану екеуіңізге де жақсы әсер етеді.') WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бет әлпеті біртіндеп қалыптасып келеді. Басы денесіне қарағанда әлі де үлкен болғанымен, қазір ол толықтай адам кейпіне енді. Ағзалары тез өсіп, дамуын жалғастыруда. Сол ағзалардың бірі — бауыр 10-шы аптада бөпеңіздің дене салмағының шамамен 10%-ын құрайды. Көптеген қызмет атқаратын бауыр бөпеңіз ана құрсағында жатқанда сүйек кемігі қан түзе бастағанға дейін, яғни жүктіліктің соңғы екі айына дейін оның қанға деген қажеттілігін қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Терім әлі мөлдір, Anacan! 👻 Егер мені көре алсаңыз, барлық қан тамырымды, сүйектерім мен ағзаларымды байқар едіңіз. Терім шыны секілді өте жұқа. Бірақ уайымдамаңыз, май қабатым қалыптасқан сайын терім қалыңдап, Сіздікіне ұқсай түседі. Мен күн сайын аздап күшейіп келемін. Ал жүрегім Сізге деген махаббатымды айдауды жалғастыруда.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігеріңізбен бірге, қажет болған жағдайда тамақтану маманының көмегіне жүгініп, тамақтану жоспарын құруыңыз керек. Мұндай жоспар әр тағамның пайдасын жеткілікті алуға көмектесіп қана қоймай, артық салмақ қосудың да алдын алады. Жоспардың күнделікті өмірде ыңғайлы болуы үшін жүктілікке дейінгі салмағыңыз, күнделікті белсенділігіңіз, өмір салтыңыз бен күн тәртібіңіз ескерілуі тиіс.;;;
Жүктілік бойы қосылатын жалпы салмақ әр әйелде әртүрлі болады. Дегенмен мамандар ұсынатын белгілі бір салмақ аралықтары бар. Осыған сәйкес қалыпты жүктілік кезінде болашақ ананың 9-12 кг салмақ қосуы қалыпты саналады. Бұл аралық дене салмағы төмен немесе артық болашақ аналар үшін өзгеше болуы мүмкін. Құрсағыңызда өсіп жатқан бөпенің өлшемі де салмақ қосуыңызға тікелей әсер етеді. Кішірек бөпе босанатын аналар азырақ, ал ірі бөпе босанатын аналар көбірек салмақ қосады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Енді киімдеріңізді қайта қарайтын уақыт келді. Тар шалбарлар мен белдіктер қан айналымын қиындатуы мүмкін. Жүкті әйелдерге арналған белі созылмалы шалбарлар немесе кең көйлектер сатып ала бастаңыз. Ең бастысы — жайлылық.') WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Миы дамыған сайын бөпеңіз саналы қимылдай бастайды. Соның нәтижесінде бөпеңіз күндіз белсендірек болады. Ол енді қолдарын бүгіп, бір-бірінен ажырап қалыптасқан кішкентай аяқ саусақтарын қимылдата алады.;;;
Адам ағзасында бұлшықеттің үш түрі бар. Олар: жүрек бұлшықеті, бірыңғай салалы және көлденең жолақты бұлшықеттер. Көлденең жолақты бұлшықеттер — адам өз еркімен басқара алатын жалғыз бұлшықет түрі. Олар қолымызда, арқамызда және аяқтарымызда орналасқан. Белгілі бір мөлшерде энергия жұмсағаннан кейін бұл бұлшықеттер шаршайды. Ал жүрек бұлшықетінің өзіндік ерекше тіндік құрылымы бар. Ол өздігінен жиырылып, адам өмірінің соңына дейін тоқтаусыз жұмыс істейді. Бұлшықеттің соңғы түрі — бірыңғай салалы бұлшықеттер ас қорыту жүйесінде маңызды рөл атқарады. Олар еркімізден тыс жиырылып, ағзадағы ас қорыту үдерістеріне белсенді қатысады. Осы үш түрлі бұлшықет құрылымына ортақ қасиеттер — серпімділік, жиырылу, қозғыштық және өткізгіштік қабілеті.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен есінеп жатырмын! 🥱 Мүмкін, мұны оқығанда сен де есінеген шығарсың? Иә, мен енді аузымды кең ашып, есіней аламын. Бұл ұйқым келгендіктен емес, жақ бұлшықеттерім мен өкпемді дамыту үшін қажет. Кейде ықылық та атаймын. Сен бұл кішкентай дірілдерді әзірге сезбейсің, бірақ мен мұнда тыным таппай жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құрма'), body_changes_kk = COALESCE(body_changes_kk, 'Адамдар тарих бойы дүниеге келетін бөпенің жынысын болжау үшін әртүрлі жорамал айтқан. Соның бірі — қышқыл тағамға жерік болса, қыз, ал тәттіге жерік болса, ұл туады деген түсінік. Зерттеулерге сәйкес, жерік болған немесе жиіркеніш тудырған тағамдар мен бөпенің жынысы арасында ешқандай байланыс жоқ.;;;
Ішіңізде «Қара сызық» деп аталатын күңгірт сызық анық көрінуі мүмкін. Ол кіндіктен төмен қарай, кейде жоғары қарай да созылады. Бұл — гормондық өзгерістердің қалыпты нәтижесі және ешқандай зияны жоқ. Босанғаннан кейін бірнеше ай ішінде өздігінен біртіндеп жоғалады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Іштің кебуін азайту үшін тамақтанып отырғанда сөйлемеуге тырысыңыз, сонда ауа жұтпайсыз. Тамақты жақсылап шайнаңыз. Бұршақ тұқымдастар мен газдалған сусындардан уақытша бас тарту көмектесуі мүмкін.') WHERE id = '1980273b-7820-40aa-b793-4b715fda3015';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жынысы ұрықтану сәтінде-ақ әкеден келген сперматозоидтың X немесе Y хромосомасын тасымалдауына байланысты анықталады. Алайда жыныс мүшелерінің физикалық қалыптасуына біраз уақыт қажет. 5-ші аптада ұл мен қыз эмбрионында да сыртқы көрінісі бірдей кішкентай төмпешік пайда болады. Ал 8-ші аптада жыныс мүшелерін қалыптастыратын арнайы жасушалар осы аймаққа жылжи бастайды. Бір қызығы, 12-ші аптаға дейін бөпеңіздің сыртқы көрінісінен жыныстық айырмашылықты ажырату іс жүзінде мүмкін емес.;;;
Егер бөпеңізде Y хромосомасы болса, жасушалар аталық бездерге (тестиске) айналып, 12-ші аптаға дейін тестостерон гормонын өндіре бастайды. Ұл бөпенің сыртқы жыныс мүшелерінің қалыптасуын дәл осы гормон қамтамасыз етеді. Егер бөпеңізде XX хромосомалары болса (яғни қыз болса), жасушалар жатыр мен жатыр түтіктерін қалыптастырады. Бұл үдерісте эстроген гормоны маңызды рөл атқарып, қыз бөпелерге тән ішкі және сыртқы құрылымдардың қалыптасуын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көлемім құлпынайдай! Енді соншалықты кішкентай емеспін, солай ғой? Денем түзеліп, омыртқам ұзарып келеді. Сенің ішің әлі қатты білінбесе де, мен онда өзіме кең орын алып қойдым. Біз бірге өсіп келеміз, Anacan. Мені қорғап жүргенің үшін саған рақмет.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құлпынай'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде ауыз қуысының күтіміне көбірек мән беруіңіз керек. Ағзадағы өзгерістерге байланысты тіс пен қызыл иек мәселелері туындауы мүмкін. Жүктілік кезінде тісті дұрыс күту ана мен бөпенің денсаулығы үшін өте маңызды. Кальцийге бай тағамдарды қажетті мөлшерде тұтыну ауыз қуысы мен тіс мәселелерінің алдын алып, босанудың сәтті өтуіне ықпал етеді. Бұл кезеңде өзіңіз бен бөпеңіз үшін теңгерімді тамақтануға көңіл бөліңіз. Тамақтан кейін тістеріңізді тазалап, тіс жібін пайдалану арқылы ауыз қуысын тиімді күтіп, тіс қағының жиналуына жол бермеңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бірінші триместрдің соңына жақындағандықтан, өзіңізді сергек сезінуіңіз мүмкін; жеңіл дене жаттығуларын немесе жүзуді бастауға қолайлы уақыт. Қызыл иегіңіздің сезімталдығы сақталуы мүмкін, сондықтан ауыз қуысының гигиенасына назар аударыңыз. Рационыңызда ақуыз бен кальций жеткілікті болсын. Келесі аптада бізді 12-ші апта — алғашқы маңызды кезеңнің аяқталуы күтіп тұр!') WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бүйректері дамуын жалғастырып қана қоймай, несеп өндіре алатын деңгейге жетті. Алайда бұл кезеңде бүйректер қалдық заттарды ағзадан толық шығаруға әлі жеткілікті дамымаған. Алдағы апталарда бүйрек өндіретін несеп бөпе жатқан қағанақ сұйықтығына бөлінеді. Біртүрлі естілгенімен, бұл несептің құрамында несепнәр жоқ және зерттеулерге сәйкес, біз ішетін судан да стерильдірек. Сонымен қатар ол инфекциялардан қорғайтын қызмет атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мені қытықтай аласың ба? (Әзілдеп тұрмын!) 😂 Бірақ терімнің қаншалықты сезімтал болғанын білсең ғой... Егер біреу (мысалы, дәрігер ультрадыбыстық құрылғымен) ішіңе тигізсе, мен бірден жауап беріп, шегініп кетемін. Рефлекстерімнің жетілгені сонша, бәрін сеземін. Мен енді жай ғана жасушалар жиынтығы емес, сезіне алатын тіршілік иесімін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құлпынай'), body_changes_kk = COALESCE(body_changes_kk, 'Гормондар теңгеріліп, жүрек айнуыңыз азайғандықтан, тәбетіңіз артуы мүмкін. Енді өзіңіз үшін де, бөпеңіз үшін де тамақтанасыз. Сондықтан зиянды тағамдардан, темекі мен алкогольді сусындардан аулақ болуыңыз керек. Артық калориясы бар тағамдардың мөлшерін шектеу шамадан тыс салмақ қосудың алдын алады. Түнде тамақ жегіңіз келуі — көптеген болашақ аналарда кездесетін жағдай. Алайда түнде тамақтану салдарынан қандағы қантты реттеуге қатысатын лептин гормонының бөлінуі бұзылуы мүмкін. Лептин гормонының жеткілікті бөлінбеуі салмақтың тез қосылуына әкелуі ықтимал. Сондықтан кешкі сағат 9-дан бастап судан басқа ештеңе ішіп-жемеу асқазан саулығы мен салмақты бақылау үшін маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүрек айнуыңыз басылса, рационыңызды байытудың дәл уақыты келді; жасыл көкөністерді молынан жеп, сапалы ақуыз тұтынуға көңіл бөліңіз. Терінің созылуына қарсы ылғалдандыратын майларды қолдануды тоқтатпаңыз. Қуатыңыз қалпына келсе, күн сайын 20 минут баяу серуендеу өзіңіздің де, бөпеңіздің де оттегімен қамтамасыз етілуін жақсартады.') WHERE id = '726669c0-162f-4b1a-a70b-ca60baf4c509';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің сыртқы құлақтары қазірдің өзінде соңғы пішінін алды. Әзірге сәл төмен орналасқанымен, бөпеңіз өскен сайын олар жоғары көтеріліп, өз орнына келеді. Ал көздерінде көруді қамтамасыз ететін негізгі оптикалық бөліктер қалыптасқан; қабақтары көздерін толығымен жауып тұр.;;;
Ауыз қуысында тіс бастамалары дамып, бетінде алғашқы жіңішке қас түктері пайда бола бастайды. Бұл кезеңде бөпеңіз енді "C" әрпіне ұқсас пішіннен арылып, адам денесіне тән кескінге көбірек ие болады.;;;
Сонымен қатар, плацента ұзарып, дамуын жалғастырады. Бұл құрылым ана мен бөпе арасындағы байланыста аса маңызды рөл атқарады. Оның негізгі міндеттеріне газ алмасуды қамтамасыз ету, қоректік заттарды бөпеге жеткізу, ал зат алмасу қалдықтарын бөпеден анаға тасымалдау және бөпенің өсуінде маңызды рөл атқаратын кейбір гормондарды бөлу жатады. Сондай-ақ плацента глюкозаны, аминқышқылдарын, май қышқылдарын, кальцийді, D дәруменін және оттегін анадан бөпеге жеткізіп, көмірқышқыл газы мен басқа да қалдықтарды бөпеден анаға тасымалдайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен акробатикамен айналысып жүрмін! 🤸‍♂️ Anacan, мен жай ғана жатпаймын: керілемін, бұрыламын, тіпті сальто жасаймын. Жатыр әзірге мен үшін кең бассейн сияқты, сондықтан оның мүмкіндігін толық пайдаланып жүрмін. Бұл қимылдар бұлшықеттерім мен буындарымды дамытады. Сіз әлі сезбейсіз, бірақ мен мұнда нағыз шоу көрсетіп жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кептірілген өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Прогестерон гормонының әсерінен жүктілік кезінде мөлдір қабықтың, яғни көздің ең алдыңғы жағындағы мөлдір қабаттың суды ұстап тұру қасиеті өзгереді. Соның салдарынан көру бұлдырап, әсіресе жанаспалы линза тағатын адамдарда линзаға шамадан тыс сезімталдық пайда болуы мүмкін. Бұл кезеңде линза тағуды мүмкіндігінше кейінге қалдырған дұрыс.;;;
Жүкті әйелдерде көру мәселелері физиологиялық себептерден туындауы мүмкін, дегенмен көруге қатысты шағымы бар барлық болашақ аналар белгілі бір аралықпен офтальмологиялық тексеруден өтуі керек. Жүктілік кезінде гормондардың әсерінен көздегі қан тамырларына қатысты өзгерістер туындауы ықтимал. Олардың қатарына бассүйекішілік тамырлар құрылымының бұзылыстары, көздің торлы қабығы (ретина) артериясының бітелуі, өздігінен пайда болатын көз ұясының қанталауы және гипофизге қан құйылу жатады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'C дәрумені қызыл иекті нығайтады. Апельсин, киви, қызыл бұрыш сияқты тағамдарды жеңіз. Тісіңізді тазалағанда қатты қимыл жасамаңыз, жұмсақ тіс щеткасын пайдаланыңыз және тіс жібін қолдануды ұмытпаңыз.') WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде қарқынды дамитын тағы бір мүше — тері. Әзірге терісі өте мөлдір болғандықтан, қан тамырлары мен ағзалары көрініп тұрады, бірақ ол тез қалыңдай береді. Бөпеңіздің терісі дененің жанасуды сезуін қамтамасыз ететін мүше болады. Ол денені сыртқы соққылардан қорғайды, май мен тердің бөлінуін қамтамасыз етеді, ағзаның D дәруменін қабылдауына көмектеседі, дене температурасын реттейді және судың жоғалуына жол бермейді. Бөпеңіз, плацента және қағанақ суы орналасқан жатырыңыз жүктіліктің басынан бері шамамен екі есе үлкейді. Осы аптада қағанақ суының мөлшері шамамен 30 ml болады және бұл кезеңде ол ана қанының сұйық бөлігінен сүзілу арқылы түзіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Иіс сезу қабілетім оянып келеді! 👃 Anacan, сену қиын шығар, бірақ мен мұрныммен тыныс алу жаттығуларын жасап жүрмін (ауаның орнына сумен). Мен тіпті қағанақ суының иісін сезе аламын! Сіз жеген тағамдардың иісі мұнда да жетеді. Сіз сарымсақ жесеңіз де, шоколад жесеңіз де, мен оны білемін! Талғамымыз қазірден қалыптасып жатыр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құрма'), body_changes_kk = COALESCE(body_changes_kk, 'Қан көлемі мен эритроциттер саны артады. Алайда қанның сұйық бөлігі көбірек ұлғайғандықтан, салыстырмалы анемия пайда болуы мүмкін. Мұндай жағдайда темір препараттарын қабылдау қажет болуы ықтимал. Сонымен қатар жүрек жылдамырақ жұмыс істейді. Сол себепті кейде жүрек қағуы байқалуы мүмкін. Бұл жағдай жүктіліктің ерте кезеңдерінде басталып, 20-24-апталарда ең жоғары деңгейге жетеді. ;;;
Бөлінетін гормондардың әсерінен қан қысымы аздап төмендеуі мүмкін. Жүктілік ұлғайған сайын, әсіресе оң жақ қырыңызбен жатқанда, жатыр төменгі қуыс венаға қысым түсіріп, қан қысымының кенет төмендеуіне себеп болуы ықтимал. Сондықтан дәрігерлер жүкті әйелдерге, әсіресе жүктіліктің соңғы кезеңінде, сол жақ қырымен жатуды ұсынады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Сөмкеңізде әрдайым бір бөтелке су алып жүріңіз. Егер жай су ішкенде жүрегіңіз айныса, оған бір тілім лимон, қияр немесе жалбыз жапырағын қосыңыз. Бұл судың дәмін өзгертіп қана қоймай, өзіңізді сергек сезінуге де көмектеседі.') WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миы ерекше жылдамдықпен өсіп келеді. Бұл кезеңде ми әр 4 минут сайын 1 миллион нейрон түзеді. Анасы мен әкесінен берілген генетикалық кодтан бастап, барлық жағдай бөпеңіздің жүйке жүйесінің дамуына әсер етеді.;;;
Фолий қышқылы — бөпеңізді миының дамуы кезінде пайда болуы мүмкін жүйке жүйесі ауруларынан қорғайтын ең маңызды дәрумендердің бірі. B тобына жататын фолий қышқылы брюссель қырыққабатында, бұйра қырыққабатта, саумалдықта, қояншөпте, қызылшада, салат жапырағында және қызыл бұрышта мол кездеседі. Дегенмен фолий қышқылының өзі ғана жеткіліксіз. Сонымен қатар барлық қажетті қоректік заттарды қабылдап, жеткілікті мөлшерде су ішу керек.;;;
Ақуызға бай тағамдарды, балғын жемістер мен көкөністерді тұтыну бөпенің сау дамуы үшін маңызды. Сондай-ақ көңіл күйдің жақсы болуы да бөпе миының дамуына әсер ететін маңызды факторлардың бірі.;;;
Жүктілік кезінде жүргізілетін барлық тексерулер бөпенің жүйке жүйесі мен миы туралы ақпарат береді. Жүктіліктің 11-14-апталарында жасалатын "қосарланған тест" пен 16-18-апталарында жасалатын "үштік тест" бөпеде ықтимал генетикалық ауытқудың болу қаупін бағалау үшін маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жұдырығымды аша аламын! ✊🖐️ Саусақтарым енді бір-бірінен толық ажыраған, сондықтан қолымды жұдырық етіп түйіп, қайта аша аламын. Бұл мен үшін жаңа ойыншық сияқты. Кейде қолымды бетіме тигіземін, кейде кіндік бауын ұстауға тырысамын. Ұстау рефлексім дамып келеді. Сіздің саусағыңыздан ұстайтын күнімді асыға күтемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құрма'), body_changes_kk = COALESCE(body_changes_kk, 'Жатырдағы бөпенің жүрек соғысы орта есеппен 6-7-апталарда байқала бастайды. Жүктілік ілгерілеген сайын бастапқыда минутына 90-110 рет болатын жүрек соғу жиілігі бірінші триместрдің соңында 140-тан асады. Бұл ересек адамның қалыпты жүрек соғу жиілігінен шамамен екі есе жоғары. Дәрігердің бақылауында бөпеңіздің жүрек соғысын естігенде, ол Сізге өте жылдам болып көрінуі мүмкін. ;;;
Босанғаннан кейін ұйқысыз өтетін күндерді ескерсек, бұл кезеңде көбірек ұйықтаудың еш зияны жоқ. Дұрыс ұйқы тәртібі гормондарыңыздың қалыпқа келуіне көмектеседі.;;;
Қалыпты жағдайда жұдырығыңыздан да кішкентай болатын жатырыңыз осы аптадан бастап үлкен грейпфрут көлеміне жетті.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ас қорыту жүйесін қолдау үшін талшыққа бай тағамдар тұтынып, көп су ішіңіз. Егер беліңіз ауыра бастаса, аяқ киім таңдауға мән беріңіз; тым биік өкшелі де, тым жалпақ та емес, ыңғайлы аяқ киім киіңіз. Күн ішінде демалуға уақыт бөліп, мүмкіндігінше сол жақ қырыңызбен жатып, қан айналымын жақсартыңыз.') WHERE id = 'e6ecf1e2-7281-4cf6-94ac-a3478b23c498';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бойы қазірдің өзінде 6 см, ал салмағы 7-8 грамм. Құйрық бөлігі толығымен жойылып, эмбриондық кезең аяқталды. Енді барлық ағзалары өз орнында және қарқынды өсу кезеңі басталады. Алдағы 8 апта ішінде оның салмағы қазіргіден 30 есе артып, бойы 3 есе ұзарады. Бұл өсуді қамтамасыз ету үшін ағзаңыздағы қан көлемі мен қан тамырларының саны көбейеді. Қазір басы денесіне қарағанда үлкен болып көрінгенімен, көп ұзамай дене мүшелерінің пропорциясы үйлесімді бола түседі. Саусақтары ұзарып қалды; енді ол жұдырығын түйіп қана қоймай, қолдарын ашып, айналасын зерттей бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қызбын ба, әлде ұлмын ба? Құпияның ашылар сәті жақындап келеді! 🩷💙 Менің сыртқы жыныс мүшелерім бір-бірінен ерекшелене бастады. Бірнеше апта бұрын бәріміз бірдей көрінетінбіз, ал қазір жыныс төмпешігінің бұрышы өзгеріп жатыр. Дәрігерлер әзірге нақты айта алмауы мүмкін, бірақ үдеріс жүріп жатыр. Сіз не сезесіз? Ана жүрегі алдамайды дейді ғой.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құлпынай'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде, әсіресе бірінші триместрде, прогестерон гормонының әсерінен кейбір бірыңғай салалы бұлшықет жасушалары босаңсиды. Соның салдарынан тағам ас қорыту жолымен баяу қозғалып, асқазан мен ішекте ұзағырақ қалады да, ас қорытуға қатысты мәселелер туындауы мүмкін. Егер іштің кебуі қатты мазаласа, ем алу үшін дәрігеріңізбен кеңесіңіз. Дәрігердің бақылауынсыз дәрі-дәрмек немесе өсімдік тектес дәрілерді қолдану бөпеңіздің дамуына кері әсер етуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңіздегі ауырсынуды азайту үшін арқаңызды тік ұстап отыруға және ұйықтағанда сол жақ қырыңызбен жатуға тырысыңыз. Артқан тәбетіңізді пайдалы тіскебасарлармен басыңыз. Темірдің сіңуін жақсарту үшін рационыңызға С дәруменіне бай тағамдарды қосыңыз. Күніне кемінде 10 минут тыныш жерде терең тыныс алып, бөпеңізбен байланыс орнатуға тырысыңыз.') WHERE id = '8c65943a-4d31-4534-b028-6c3f95fa6988';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ми жасушалары адам сенгісіз жылдамдықпен көбейіп жатыр. Бұл жасушалар туғаннан кейін бір-бірімен байланыс құра бастайды және бұл үдеріс өмір бойы жалғасады. Адам өскен сайын мида жасушалардың өзінен гөрі олардың арасындағы байланыстар көбірек орын алады. Бөпеңіздің жүйке жүйесі қазірдің өзінде соншалықты дамыған, сезім мүшелерінен келетін ақпаратты миға жеткізе алады.'), baby_message_kk = COALESCE(baby_message_kk, 'Даусым шығады! 🎤 (Әзірге дыбыссыз). Менің дауыс байламдарым қалыптаса бастады. Қазір судың ішінде болғандықтан дыбыс шығара алмаймын, бірақ дүниеге келгенде Сізге алғаш рет "Іңгәә!" деген даусымды естіртуге дайындалып жатырмын. Сол сәтті елестете аласыз ба? Менің даусым Сіз үшін әлемдегі ең әдемі әуен болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Інжір'), body_changes_kk = COALESCE(body_changes_kk, 'Күн ішінде құрысу жиі мазалауы мүмкін. Құрысу шап аймағында, сондай-ақ аяқтарыңыз бен балтырларыңызда байқалуы ықтимал. Аяқтың құрысуының нақты себебі толық анықталмағанымен, кальций мен магний тапшылығы негізгі себептердің қатарына жатады. Сондықтан жүктілік кезінде магний мен кальцийді жеткілікті мөлшерде алу өте маңызды. Дәрігеріңізбен кеңесіп, тиісті дәрумендік қоспаларды қабылдауға болады.;;;
Жүктілік кезінде ұлғайған жатырдың веналық жүйеге түсіретін қысымынан туындайтын қан айналымы бұзылыстары да құрысудың маңызды себептерінің бірі. Ағзаңыздағы минералдар плацента арқылы бөпеңізге берілетіндіктен, тамыр ішіндегі сұйықтық көлемі артып, қандағы магний деңгейі төмендейді. Құрысу кезінде сабыр сақтап, тізеңізді бүкпей, аяғыңызды баяу жоғары көтеріңіз. Аяқ бұлшықеттерін созып, босаңсуға тырысыңыз. Құрысқан жерді жеңіл уқалау, бұлшықетке жылы сүлгі басу және аяқ саусақтарын жоғары қарай тарту құрысуды азайтуға көмектеседі. Сонымен қатар сүт өнімдерін, балықты, бадам секілді жаңғақтарды, үрме бұршақ пен жасымықты және күнжіт секілді тұқымдарды тұтыну ағзадағы магний мен кальций деңгейін арттырып, құрысудың алдын алуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Басыңыз айналмауы үшін отырған немесе жатқан жеріңізден асықпай тұрыңыз. Қан көлемі артатындықтан, жеткілікті мөлшерде сұйықтық ішу маңызды. Егер "Қосарланған тест" (скрининг) үшін әлі дәрігерге бармаған болсаңыз, осы апта — ең қолайлы уақыт. Тәбетіңіз артса, рационыңызда кальций мен магнийге бай өнімдерге ерекше мән беріңіз.') WHERE id = '1a115c93-d622-40f8-b3f4-8d1be6d3b8e9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миы дамыған сайын ол рефлекстік қимылдар жасай бастайды. Бұл қимылдар еріксіз орындалып, бөпеңіздің болашақтағы дене дағдыларының негізін қалайды. Мысалы, жатыр ішінде бір нәрсеге жанасқанда аузын ашуы — алғашқы рефлекстердің бірі.;;;
Бұл даму екі кезеңнен тұрады:;;;
Ақпарат жинау: Қазір басталған бұл кезеңде бөпеңіз қимылдар арқылы қорек іздеу және өзін қорғау рефлекстерін меңгереді. Мысалы, кенет шайқалғанда селк етіп, қолдарын жоғары көтеріп, кейін біріктіреді (Моро рефлексі).;;;
Ақпаратты өңдеу: Туғаннан кейін 4 айдан соң басталатын бұл кезеңде мидың орталықтары одан әрі жетіледі.;;;
Нәтижесінде ана құрсағында қалыптасқан бұл еріксіз рефлекстер біртіндеп отыру, ұстау және аяққа тұру секілді саналы, ерікті қимылдарға ұласады.'), baby_message_kk = COALESCE(baby_message_kk, 'Ішектерім өз үйіне оралды! 🏠 Anacan, есіңізде ме, ішім кішкентай болғандықтан ішектерім кіндік бауының ішіне шығып кеткен еді ғой? Бүгін олар ресми түрде құрсақ қуысына, өз орындарына қайта оралды. Енді менің ішім тегіс әрі әдемі. Барлық ішкі ағзаларым өз орындарында және жұмыс істеп тұр. Мен күн сайын кемелденіп келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Інжір'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы аптасынан бастап, яғни бірінші триместрдің соңына жақындағанда, бөпеде туа біткен ақаулардың пайда болу қаупін бағалау үшін қосарланған скринингтік тест өткізуге болады. Бұл қосарланған скрининг бірінші триместр тесті деп те аталады. Бағалау егжей-тегжейлі ультрадыбыстық зерттеу және қандағы екі маңызды ақуыздың мөлшері мен деңгейін өлшеу арқылы жүргізіледі. Ультрадыбыстық зерттеу кезінде бөпенің мойын қатпарының қалыңдығы мен мұрын сүйегі тексеріледі. Қалыпты өтіп жатқан жүктілікте мойын қатпарының қалыңдығы 2.5 мм-ден аспауы керек. Мойын қатпары неғұрлым қалың болса, хромосомалық ауытқу ықтималдығы соғұрлым жоғары болады. Сонымен қатар қосарланған тест кезінде мұрын сүйегінің болуы бөпенің дені сау дамуының маңызды көрсеткіші саналады. Хромосомалық ауытқулар кезінде мұрын сүйегі мүлде болмауы немесе қалыптыдан әлдеқайда кішкентай болуы мүмкін.;;;
Қосарланған тест нәтижесі бөпеде ауытқудың бар-жоғын нақты анықтай алмайды. Бұл тест тек ауытқу ықтималдығын бағалайды. Егер қауіп деңгейі қалыптыдан жоғары болса, дәрігеріңіз нақты жауап алу үшін амниоцентез секілді әдістерді ұсынуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қандағы қант деңгейін тұрақты ұстауға тырысыңыз. Ұзақ уақыт аш жүру бас айналу мен әлсіздікке әкелуі мүмкін. Сөмкеңізде әрдайым кептірілген жемістер, жаңғақ немесе алма секілді пайдалы тіскебасарлар алып жүріңіз.') WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің таңдайы қалыптаса бастады. Таңдай — бөпеңіздің ауыз қуысын қоршап тұратын және белгілі бір дыбыстарды шығаруға қатысатын күмбез тәрізді құрылым. Таңдайдың алдыңғы жағындағы қатты төбе түзетін бөлігі қатты таңдай, ал артқы бөлігі жұмсақ таңдай деп аталады.;;;
Таңдай екі жағында орналасқан қос жұп бұлшықет арқылы бөпеңіздің бас сүйегінің негізіне бекіген. Сондай-ақ таңдай бөпеңіздің ауыз және мұрын қуыстарын бір-бірінен бөліп тұрады. Қозғалмалы жұмсақ таңдай жұтынған кезде жоғары көтеріліп, мұрын қуысын жабады да, тағамның оған өтіп кетуіне жол бермейді. Жұмсақ таңдайдың артқы жиегінің ортасында тілшік (uvula) орналасқан, ол сөйлеу кезінде кейбір дыбыстарды шығаруға көмектеседі. Таңдайдың артқы бөлігі бөпеңіздің "қ, к, ғ" сияқты жуан дауыссыз дыбыстарды қалыптастыруына қатысады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен бет-аузымды тыржита аламын! 😝 Бет бұлшықеттерімнің дамығаны сонша, енді түрлі эмоцияларды көрсете аламын. Қабағымды түйемін, ернімді бүрістіріп, жымиып немесе таңғала аламын. Бұл мен үшін ойын. Дүниеге келгенде Сізді күлдіру үшін қазірден жаттығып жүрмін. Сіз де маған жымиып жүрсіз бе?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Інжір'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде салмақ тастау және диета ұстау бөпенің дамуы тұрғысынан ұсынылмайды. Алайда салмақтың шамадан тыс артуы да кейде бөпеңізге кері әсер етуі мүмкін. Салмақтың тез қосылуына жол бермей, жүктілік кезінде салмақты қажетті мөлшерде арттыру үшін тамақтануыңызға мән беруіңіз керек.;;;
Сонымен қатар қант қосылған дайын тағамдардан, қатты майлардан және тағамдық құндылығы төмен, тек бос калория беретін өнімдерден бас тартқан жөн. Көмірсуларды шамадан тыс тұтыну мен түнде тамақтану әдеті де салмақ қосудың себептеріне жатады. Бұған қоса, гормондардың әсерінен жүктілік кезінде зат алмасу баяулайды, ал қимыл-қозғалыс шектелсе, салмақтың артуы сөзсіз болуы мүмкін. Күн ішінде кенеттен пайда болатын аштық сезімін басу үшін пайдалы тіскебасарлар жеу артық салмақ қосудың алдын алуға көмектеседі. Денсаулығыңызға қатысты қандай да бір мәселе болмаса, жүкті әйелдерге арнайы әзірленген кейбір жаттығуларды орындау да салмақтың тез қосылуына жол бермейді.;;;
Сондай-ақ пастерленбеген сүт пен сүт өнімдерінің барлық түрінен бас тартуыңыз керек. Көпшілік ойлағандай емес, пастерлеу ғасыр жаңалығы саналады: ол сүттің тағамдық құндылығын жоғалтпай, құрамындағы зиянды микроорганизмдерді, әсіресе ауру тудыратын бактерияларды жоюға мүмкіндік береді. Шикі сүтті үйде қайнату оның құрамындағы пайдалы және зиянды микроорганизмдердің бәрін жойғанымен, кейбір төзімді бактериялардың толық залалсыздануына кепілдік бермейді. Сондықтан шикі немесе ұзақ сақталатын қораптағы сүттің орнына пастерленген күнделікті сүтті тұтынғаныңыз жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қызыл иегіңіздің сезімталдығы басылмаса, С дәруменіне бай жемістерді тұтыныңыз. Тәбетіңіз артса, тағамыңыздағы ақуыз бен кальций теңгерімін сақтаңыз. Күн сайын кемінде 2 литр су ішуді әдетке айналдырыңыз. Беліңіз ауырса, ыңғайлы аяқ киім киіп, денеңізді тік ұстап отыруға тырысыңыз. Күн сайын өзіңізге уақыт бөліп, баяу музыка тыңдау Сізге де, бөпеңізге де жағымды қуат сыйлайды.') WHERE id = 'f769e4b1-414a-408e-8810-543b96add6b7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ему рефлексі дамып келеді. Ұрық саусақтарын аузына апарып, ему қимылдарын жасайды. Бұл — дүниеге келгеннен кейінгі қоректену түйсігінің негізі. Сондай-ақ ұрық қағанақ суын жұтады, ол ас қорыту жүйесінен өтіп, бүйрек арқылы сүзіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ему рефлексін үйреніп жүрмін! 🍼 Бас бармағымды аузыма апарып, соруға тырысамын. Бұл дүниеге келгенде Сіздің сүтіңізді емін-еркін емуім үшін ең маңызды дағды. Кейде қолымнан келеді, ал кейде қолым аузымнан шығып кетеді. Бірақ мен берілмеймін, жаттыға беремін. Сіз де мен үшін дайындала беріңіз, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Інжір'), body_changes_kk = COALESCE(body_changes_kk, 'Омега-3 және Омега-6 май қышқылдарына өте бай балықты жүктілік кезінде тұтыну бөпеңіздің миы мен көзінің дамуы үшін аса маңызды. Ақуыз бен D дәруменіне де бай балық бөпенің дамуына елеулі үлес қосады. Жеңіл қорытылатындықтан, жүктіліктің қалыпты өтуі үшін дәрігерлер аптасына екі рет балық жеуге кеңес береді. Алайда бұл кез келген балықты жеуге болады дегенді білдірмейді. Кейбір балықтардың құрамындағы сынап мөлшері жоғары болғандықтан, олар бөпеңіздің дамуына кері әсер етуі мүмкін. Албырт, тунец, сардина, бақтақ және скумбрияны жүктілік кезінде қауіпсіз тұтынуға болады; олардың тағамдық құндылығымен қатар, фолий қышқылы да мол. Бұл балықтарда Омега-3 және Омега-6 май қышқылдары көп, ал сынап деңгейі төмен. Аптасына шамамен 300-400 грамм піскен балық жеу жеткілікті. Жүктілік кезінде шикі балық пен тағамдық қоспалары бар консервілерден бас тартуыңыз керек. Қуырып пісіргенде балықтың дәрумендері толығымен жойылады, сондықтан оны буға пісіру, грильде немесе пеште дайындау әдістерін таңдағаныңыз жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Тәбетіңіз артса, қандағы қант деңгейін тұрақты ұстау үшін аз мөлшерде, бірақ жиі тамақтаныңыз. Теріңізде созылу белгілерінің пайда болуына жол бермеу үшін ылғалдандыратын майларды (бадам немесе кокос майын) қолдануды жалғастырыңыз. Жүкті әйелдерге арналған киімдерге ауысу үшін сауда жасай бастасаңыз болады – қазір ең маңыздысы — жайлылық. Күніңізді көтеріңкі көңіл күйде өткізу үшін сүйікті фильміңізді көріңіз.') WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілігіңіздің 11-ші аптасы аяқталған осы күндері ультрадыбыстық зерттеу кезінде бөпеңізді бұрынғыдан анық көре аласыз. Бұл кезеңде бөпеңіздің жыныс мүшелері қалыптаса бастайды. Бұрын кішкентай ғана тін бөлігі болған бұл аймақ енді пениске немесе клиторға айналады. Егер бөпеңіз жатырыңызда қолайлы қалыпта жатса, оның жынысы ультрадыбыстық зерттеуде көрінуі мүмкін.;;;
Сонымен қатар құлақтары дамуын жалғастырып, бастың екі бүйіріндегі өз орнына қарай жылжиды. Сыртқы және ортаңғы құлақтың арасында дабыл жарғағы пайда болады. Бұл жарғақ бактериялардың ішке өтуіне кедергі болатын тосқауыл қызметін атқарып қана қоймай, бөпеңіздің сыртқы әлемдегі дыбыстармен алғаш танысуына мүмкіндік береді. Бөпеңіз дыбыстарды ести алады, бірақ әзірге оларды бір-бірінен ажырата алмайды.;;;
Бірінші триместрдің соңына жақындаған сайын бөпеңіздің дене қалпы да өзгереді. Мойны ұзарып, иегі кеудесінен ажырайды және басын тігірек ұстай бастайды. Осылайша ол бұрынғы иілген "C" пішінінен шығып, денесі біртіндеп түзеле түседі.'), baby_message_kk = COALESCE(baby_message_kk, '12 АПТА ТОЛДЫ! 🎉 Anacan, біз бірінші триместрді сәтті аяқтадық! Бұл жүктіліктің ең қиын әрі ең маңызды кезеңі болды. Менің барлық мүшелерім пайда болып, қалыптасты. Енді мен ресми түрде "кішкентай адаммын". Алда бізді жайлырақ әрі қуатқа толы күндер күтіп тұр. Сізді мақтан тұтамын, біз керемет командамыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Інжір'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгіннен бастап плацента толық жұмыс істей бастайды және гормон өндіру қызметін "сары денеден" қабылдайды. Бұл ауысу әдетте жүрек айнудың азаюына және күш-қуаттың артуына әкеледі. Өзіңізді сергек сезінуіңіз мүмкін. Жүктіліктің ең қауіпті кезеңі артта қалды!;;;
Жүктілік кезінде гормондардың өзгеруіне байланысты кейбір тері мәселелері пайда болуы мүмкін. Экзема мен псориаздың пайда болуы немесе бұрыннан бар осы аурулардың асқынуы ықтимал. Экзема мен псориаздың алдын алу үшін терінің ылғалдылық деңгейін барынша арттырып, мол су ішіп, балғын жемістер мен көкөністерді тұтыну керек.;;;
Жүктіліктің соңғы апталарында іш аймағының едәуір үлкеюіне байланысты кейбір бөртпелер пайда болуы мүмкін. Мұндай бөртпелер әсіресе алғаш рет жүкті болған әйелдерде жиі кездесіп, қышитын дақтар тудыруы ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бірінші триместрдің аяқталғанын өзіңізге ұнайтын рәсіммен атап өтіңіз! Қуатыңыз қайта оралғандықтан, белсенді өмір салтына орала аласыз, бірақ ауыр зат көтермеңіз. Тәбетіңіз ашылғандықтан, "екі адамның орнына" емес, "екі адам үшін сапалы" тамақтануға көңіл бөліңіз. Егер әлі "Қосарланған тесттен" өтпесеңіз, оны тапсырудың соңғы мерзімін дәрігеріңізден нақтылап алыңыз. Екінші триместрдің (бал айы кезеңінің) қызығын көруге дайындалыңыз!') WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасындағы ең нәзік мүшелердің бірі — дауыс желбезектері толық қалыптасып болды. Ол оларды алғаш рет тек дүниеге келгенде (алғаш жылағанда) пайдаланатын болса да, бәрі дайын. Дауыс желбезектері көмейде орналасқан екі жұқа жарғақшаға ұқсайды. Бұл жарғақшалар тербелген сайын олардың арасындағы саңылау тарылып-кеңейіп, дауыс ырғағын реттейді. Саңылау тар болғанда жіңішке, ал кең болғанда жуан дыбыстар шығады. Босану кезінде өкпеден шыққан ауа осы желбезектерді тербетіп, бөпеңіздің дауысы естіледі. Қызықты дерек: қыздардың дауыс желбезектері қысқалау әрі жіңішке, ал ұлдардыкі ұзынырақ әрі қалыңырақ болып қалыптасады. Бөпеңіз дүниеге келгенде бұл желбезектердің ұзындығы небәрі 6 мм болады. Сонымен қатар бөпеңіз саусағын сора бастады! Бұл — оның ең алғашқы әрі сүйкімді әдеттерінің бірі, алайда оны ультрадыбыстық зерттеуден көруге әлі сәл ертерек.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тағамдардың дәмін сезіп жүрмін! 🍲 Сіз не жесеңіз, қағанақ суының дәмі соған қарай өзгереді. Тәтті, қышқыл, сарымсақты... Мен бәрін жұтып, дәмін сеземін. Болашақта қандай тағамдарды жақсы көретінім қазірден қалыптасып жатыр. Сондықтан мен де көкөністерді жақсы көруім үшін оларды көбірек жеңізші!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лайм'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде болатын физиологиялық және психологиялық өзгерістерге байланысты бөпеңізге зиян тиеді деп алаңдап, жыныстық қатынастан бас тартуыңыз мүмкін. Алайда жүктілік қалыпты өтіп жатса және дәрігеріңіз басқаша айтпаса, жыныстық қатынасқа ешқандай шектеу қойылмайды. Оның үстіне, жүктілік ілгерілеп, гормондар тұрақтанған сайын жыныстық құштарлық артуы мүмкін.;;;
Бұрын бірнеше рет түсік тастаған немесе мерзімінен бұрын босанған әйелдерге бірінші триместрде дәрігердің кеңесімен жыныстық қатынасқа шектеу қойылуы мүмкін. Сондай-ақ жүктіліктің кез келген кезеңінде түсік тастау немесе мерзімінен бұрын босану қаупі бар не қынаптан қан кетіп жүрген әйелдерге дәрігер жыныстық қатынасқа қатаң тыйым салады. Бұл тыйым қауіптің толық жойылғаны расталғанға дейін сақталады. Қауіпті жүктілік тобына жататын «плацента превиа», яғни плацента бөпеден төмен орналасып, жатыр мойнын жауып тұрған жағдайларда да қан кету қаупіне байланысты жыныстық қатынастан бас тарту қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылдың алдын алу үшін тамақтанғаннан кейін бірден жатпаңыз және ащы, дәмдеуіші тым көп тағамдардан бас тартыңыз. Аз мөлшерде, бірақ жиі тамақтануға көшіңіз. Темірді көбірек алу үшін рационыңызға қызыл ет, жасымық және қою жасыл түсті көкөністерді қосыңыз. Қуатыңыз жеткілікті болғандықтан, өзіңізді қуантатын істерге, мысалы, бөпеңізге алғашқы заттарды сатып алуды жоспарлауға уақыт бөле аласыз.') WHERE id = '18d4758f-242c-49df-ab25-cc0a8449dd65';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасындағы ең нәзік мүшелердің бірі — дауыс желбезектері толық қалыптасып болды. Ол оларды алғаш рет тек дүниеге келгенде (алғаш жылағанда) пайдаланатын болса да, бәрі дайын. Дауыс желбезектері көмейде орналасқан екі жұқа жарғақшаға ұқсайды. Бұл жарғақшалар тербелген сайын олардың арасындағы саңылау тарылып-кеңейіп, дауыс ырғағын реттейді. Саңылау тар болғанда жіңішке, ал кең болғанда жуан дыбыстар шығады. Босану кезінде өкпеден шыққан ауа осы желбезектерді тербетіп, бөпеңіздің дауысы естіледі. Қызықты дерек: қыздардың дауыс желбезектері қысқалау әрі жіңішке, ал ұлдардыкі ұзынырақ әрі қалыңырақ болып қалыптасады. Бөпеңіз дүниеге келгенде бұл желбезектердің ұзындығы небәрі 6 мм болады. Сонымен қатар бөпеңіз саусағын сора бастады! Бұл — оның ең алғашқы әрі сүйкімді әдеттерінің бірі, алайда оны ультрадыбыстық зерттеуден көруге әлі сәл ертерек.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім қатайып келеді! 🦴 Бұрын тек шеміршектен тұратын қаңқам енді нағыз сүйекке айналып жатыр. Қолдарым мен аяқтарым ұзарып келеді. Дене бітімім біртіндеп үйлесімді бола бастады. Басым әлі де үлкен, бірақ денем оны қуып жетуге тырысып жатыр. Мен мықты бала боламын, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алхоры'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде прогестерон эстроген гормонының көмегімен жатыр қабырғасын қалыңдатып, бөпенің бекінуіне көмектеседі; жатыр бұлшықеттерінің окситоцин гормонына сезімталдығын төмендетіп, олардың жиырылуына жол бермеу арқылы түсіктің алдын алады; жүктіліктің сақталуын қамтамасыз етеді және коллаген өндірілуіне ықпал етіп, терінің серпімділігін арттырады. Қаныңыздағы прогестерон деңгейінің жоғарылауы асқазан қақпақшасының босаңсуына және асқазан қышқылының бір бөлігінің өңешке өтуіне себеп болады. Соның салдарынан қыжылдап, аузыңызда қышқылтым дәм сезілуі мүмкін. Қыжылды барынша азайту үшін сұйықтықты тамақпен бірге емес, тамақтану аралығында ішіңіз, аз мөлшерде әрі жеңіл қорытылатын тағамдарды таңдаңыз және әрбір тістемді жақсылап шайнап жұтыңыз. Сондай-ақ ащы тағамдардан, қышқыл жеміс шырындарынан, кофе мен шоколадтан бас тартыңыз, ұйықтағанда басыңыз бен кеудеңізді денеңізден биігірек ұстаңыз және ағзаңыз тамақты қорытып үлгеруі үшін кешкі асты ертерек ішіңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан көлемінің артуына байланысты ағзаға көбірек сұйықтық қажет; күн сайын кемінде 2.5 литр су ішетініңізге көз жеткізіңіз. Беліңізде кернеу сезілсе, биік өкшелі аяқкиімнен толық бас тартып, ортопедиялық әрі ыңғайлы аяқкиімге ауысыңыз. Бөпеңіздің сүйектері қатайып, өзіңіздің тістеріңіз бен сүйектеріңіз қорғалуы үшін кальцийді көбірек қабылдаңыз.') WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Құттықтаймыз! Бүгін жүктіліктің ең маңызды кезеңдерінің бірі — бірінші триместрді, яғни алғашқы үш айды сәтті аяқтадыңыз. 😊 Өткен 12 апта ішінде бөпеңіздің барлық мүшелері толық қалыптасып, өз орындарына орналасты. Енді оның басы мен денесінің арақатынасы және бет әлпеті адам кейпіне толық ұқсайды. Бұл ең сезімтал кезең де еді, өйткені бөпенің сыртқы әсерлерге аса осал және түсік тастау қаупі жоғары уақыты артта қалды.;;;
Физикалық тұрғыдан да өзіңізді жеңіл сезінетін кезең басталады. Бөпеңіз өсіп жатқан жатыр жамбас сүйектеріне сыймай, жоғары қарай көтеріледі. Соның арқасында қуыққа түсетін қысым азайып, дәретханаға жиі бару қажеттілігі біршама төмендейді.'), baby_message_kk = COALESCE(baby_message_kk, '13-ші апта аяқталып келеді! 👋 Сәлем, нағыз жайлылық! Мен қазір соншалықты қимылдаймын... Аяғыммен тебемін, айналамын, қолдарымды ашып-жұмамын. Сіз ішіңізде кішкентай «көбелек қалықтағандай» бірдеңе сезуіңіз мүмкін (бірақ әлі сезбесеңіз де, уайымдамаңыз). Мен осындамын және өсіп келемін. Біз бірге тамаша жолдан өттік.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алхоры'), body_changes_kk = COALESCE(body_changes_kk, '13-ші аптаның соңы. Сіз екінші триместрге толық бейімделдіңіз. Ұйқыңыз түзеліп, тәбетіңіз қалпына келді. Ішіңіз енді кішкентай «жүкті іш» сияқты көрінеді. Киім таңдау жағымдырақ бола түсуі мүмкін. Өзіңізді бұрынғыдан да нәзік әрі сұлу сезінуіңіз ықтимал. «Бал айы» саналатын осы кезеңнен ләззат алыңыз! Емшегіңізден «уыз» (алғашқы сүт) бөлінуі жалғасуы немесе енді басталуы мүмкін. Бұл қою, сарғыш сұйықтық бөпенің алғашқы вакцинасы саналады. Егер киіміңізге дақ түсірсе, емшекке арналған арнайы төсемдерді қолдануға болады. Сүт бездері босануға қарқынды дайындалып жатыр.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Төсек режимін емес, белсенді өмір салтын таңдаңыз. Жүкті әйелдерге арналған йога немесе пилатес бұлшықеттеріңізді нығайтып, босануға дайындайды. Сондай-ақ бұл топтарда басқа жүкті әйелдермен танысып, тәжірибе алмаса аласыз.') WHERE id = '451a1e44-829c-4f45-9442-ac30329fca22';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасындағы зәр шығару жүйесі қарқынды дамып келеді. Бұл жүйе екі бүйректен, несепағарлардан және қуықтан тұрады. Оның негізгі міндеті — қанды зиянды заттардан тазарту және ағзадағы су-тұз теңгерімін сақтау. Осы аптадан бастап бөпеңіз зәр бөле бастайды, ал бұл сұйықтық оны қоршаған қағанақ суына араласады. Бүйректің ішінде қанды сүзетін нефрон деп аталатын миллиондаған ұсақ сүзгі қалыптасады. Қазір бүйректе қысқа және ұзын құрылымды нефрондар жұмыс істейді. Бөпеңіз толық дамып жетілгенде, оның әр бүйрегінде осындай 1 миллионнан астам ұсақ сүзгі болады. Түтікше пішінді осы жасушалардың арқасында бөпеңіздің қаны үнемі тазартылып, зат алмасуы реттеледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Екінші триместрге қош келдіңіз! ☀️ Мұны "Алтын кезең" деп атайды. Өйткені Сіз өзіңізді жақсырақ сезіне бастайсыз, ал мен тез өсемін. Қазір менің көлемім лаймдай. Қимылдарым үйлесімді бола түсті. Енді мен кездейсоқ емес, өз қалауыммен қозғаламын. Сізге қолымды тигізгім келеді, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лайм'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде пайда болатын кез келген шағымға мұқият қарауыңыз керек. Мысалы, аллергиялық реакция салдарынан теріңізде бөртпе, қызыл дақтар және қышу пайда болуы мүмкін. Жүктіліктің алғашқы айларында мұндай бөртпе мен қышу прогестерон гормонының әсерінен туындауы ықтимал. Алайда жүктіліктің кейінгі кезеңдерінде жалғаса берсе, міндетті түрде қан талдауларын тапсыру қажет. Бұл талдаулар арқылы бауыр ферменттері, гепатит көрсеткіштері, өт пен қалқанша без гормондары тексеріледі. Егер талдау нәтижелері қалыпты көрсеткіштерден өзгеше болса, Сіздің де, бөпеңіздің де денсаулығы үшін ем қабылдау қажет.;;;
Сонымен қатар тәбеттің болмауы, әлсіздік, шаршау, көздің қызаруы немесе сарғаюы, зәрдің иісі мен түсінің өзгеруі сияқты шағымдар бауыр көрсеткіштерінде мәселе бар екенін білдіруі мүмкін. Бұл жағдай жүктілік холестазы деп аталады. Жүктілік холестазы бар әйелдер мұқият бақылауда болып, NST, доплер және ультрадыбыстық зерттеу арқылы жиі тексерілуі керек.;;;
Әсіресе жүктіліктер арасындағы үзіліс қысқа болса, мұндай шағымдардың пайда болу ықтималдығы едәуір жоғары болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жыныстық өміріңізге қатысты дәрігеріңізбен кеңесіңіз. Егер ешқандай қауіп (қан кету, түсік тастау қаупі) болмаса, жүктілік кезінде жыныстық қатынас толықтай қауіпсіз және тіпті пайдалы болуы мүмкін (окситоцин гормонының әсерінен).') WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішектері айтарлықтай дамып үлгерді. Алғашқы апталарда қарапайым тін болған ішектер енді қатпарланып, алдыңғы және ортаңғы бөліктерге бөлінді әрі жүрек пен өкпемен қатар қарқынды ұзарып келеді. Осы кезеңде бөпеңізді қоршаған қағанақ суының мөлшері шамамен 50 ml-ге жетеді. Сонымен бірге мида "бас без" деп аталатын гипофиз жұмыс істей бастайды. Бұл кішкентай без бойдың өсуіне, зат алмасуға және болашақта жыныстық жүйенің қызметіне қажетті көптеген гормонды өндіреді. Гипофизді мидың басқа бөлігі — гипоталамус басқарады. Олар бірге ағзаның ішкі теңгерімін сақтайды. Яғни ағзадағы қандай да бір үдеріс қалыпты жағдайдан ауытқыса, бұл бездер гормондардың көмегімен жағдайды дереу қалыпқа келтіреді.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақ іздерім дайын! 🧬 Тек өзіме ғана тән, әлемде қайталанбайтын саусақ іздерім толық қалыптасты. Бұл — менің жеке куәлігім. Тіпті егізім болса да, оның саусақ іздері менікінен өзгеше болар еді. Мен жалғызбын, бірегеймін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лайм'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде шамадан тыс су ішкіңіз келсе, өте жиі зәр шығарсаңыз, аяқтарыңыз ұйып, салмағыңыз кенет өзгерсе, қант диабеті пайда болған болуы мүмкін. Егер бұрын қант диабеті болмаған болса, жүктілік кезінде туындаған бұл жағдай “гестациялық диабет” деп аталады. Гестациялық диабеті бар әйелдерде қан қысымының жоғарылауы, бас айналу және бас ауыруы байқалуы мүмкін. Көпшілік ойлағандай, бұл жағдай тек артық салмағы бар жүкті әйелдерде ғана кездеспейді. Отбасында қант диабеті бар адамдардың қауіп деңгейі жоғарырақ. Гестациялық диабет плацентаның жүктілік бойы бөпені қолдау үшін өсуіне және ол бөлетін гормондардың ана ағзасындағы инсулин әсерін төмендетуіне байланысты пайда болады. Бұл жағдай инсулинге төзімділік деп аталады. Егер инсулин жеткілікті әсер етпесе, қандағы қант энергияға айнала алмай, қандағы қант деңгейі жоғарылайды. Соның салдарынан гестациялық диабет дамиды.;;;
Емдеу кезінде арнайы тамақтану тәртібі тағайындалып, қажет болса, инсулин қолданылады. Жүктілік бойы ең маңыздысы — дұрыс тамақтану тәртібін сақтау. Емделмеген жағдайда бұл түсік тастауға, мерзімінен бұрын босануға, бөпенің шамадан тыс тез салмақ қосуына және дамуындағы кейбір мәселелерге әкелуі мүмкін. Гестациялық диабеттің бар-жоғы жүктіліктің 24-28-ші апталарында жасалатын глюкозаға төзімділік сынағы арқылы анықталады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Екінші триместрде артқан тәбетті пайдалы тағамдармен — жаңғақтармен, балғын жемістермен және сүзбемен басыңыз. Егер беліңіз аздап ауыра бастаса, отырғанда арқаңызға тіреу үшін кішкентай жастық қойыңыз. Теріңізде жүктілікке байланысты пигментті дақтар пайда болмауы үшін тікелей күн сәулесінен қорғанып, қорғаныс факторы жоғары күннен қорғайтын кремдерді қолданыңыз.') WHERE id = 'ec212007-cf13-4d3e-9523-fa6762234108';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ұйқы безі инсулин өндіре бастады. Бұл бездің 99%-ы ас қорытуға көмектесетін ферменттерді түзеді, ал қалған 1%-ын құрайтын шағын жасушалар тобы инсулин бөледі. Инсулин ағзаның негізгі энергия көзі болып саналатын қантты (глюкозаны) жасушалардың пайдалануына мүмкіндік береді. Оның негізгі міндеті — қандағы қант деңгейінің шамадан тыс жоғарылауына жол бермеу. Инсулин қантты қаннан алып, энергия ретінде пайдалану үшін бұлшықет пен май жасушаларына жеткізеді. Егер қандағы қант азайса, инсулин өндірісі тоқтап, ағза қант деңгейін қалыпты ұстау үшін басқа гормондарды іске қосады. Осылайша бөпеңіздің ағзасындағы қант, май және ақуыз теңгерімі мінсіз реттеледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен дыбыстарды ести бастадым ба? 👂 Құлақтарымның дамуы жалғасып жатыр, енді тербелістерді сезе аламын. Сіздің жүрек соғысыңыз, қаныңыздың ағысы мен асқазаныңыздың дыбыстары — менің бесік жырым. Жақында Сіздің даусыңызды да ажырата алатын боламын. Менімен сөйлесіңіз, Anacan, мен Сізді тыңдап жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лайм'), body_changes_kk = COALESCE(body_changes_kk, 'Теріңізде созылу белгілерінің пайда болу қаупі артады. Ішіңіз, сандарыңыз және омырауыңыз үлкейген сайын тері созылады. Бұл жерде генетиканың рөлі зор, бірақ теріні ылғалдандыру оның серпімділігін арттырып, қышуды азайтады. Құрғақ теріде созылу белгілері тезірек пайда болады. Сондықтан теріні күн сайын ылғалдандырып, аптасына 1-2 рет массаж жасау маңызды.;;;
Жүктілік кезінде тамақтану мәзіріңізге жаңғақтар мен дәндерді қосуды ұмытпаңыз. Майлы дақылдарға жататын жаңғақтар мен дәндердің тағамдық құндылығы жоғары. Олардың пайдасын толық алу үшін қуырылған емес, шикі күйінде тұтынған жөн. Олардың ішіндегі ең маңыздылары — грек жаңғағы, бадам, пісте, кешью, орман жаңғағы, кептірілген інжір, асқабақ дәні, кептірілген өрік және жержаңғақ. Грек жаңғағы бөпенің миының дамуына көмектеседі; орман жаңғағы құрамындағы кальций арқылы бөпеңіздің сүйектерінің дамуын қолдайды; бадам мырышқа деген күнделікті қажеттілікті өтейді; ал жержаңғақ B және E дәрумендерімен қатар калий, фосфор, натрий және магнийге деген қажеттілікті қамтамасыз етеді. Сонымен бірге табиғи жолмен кептірілген інжір мен өрік Сізге және бөпеңізге жүктілік кезінде қажетті көптеген дәрумендер мен минералдарды қамтитындықтан, оларды теңгерімді мөлшерде тұтыну керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жатырдың жұмыр байламы ауыруын азайту үшін кенет қимыл жасамауға тырысыңыз; төсектен тұрарда алдымен бір қырыңызға бұрылыңыз. Қызыл иегіңіздің саулығы үшін кальцийге бай тағамдарды тұтынып, жұмсақ тіс щеткасын пайдалануды жалғастырыңыз. Егер тәбетіңіз артса, аяқ бұлшықеттеріңіз құрыспауы үшін тағамыңыздағы магний мөлшеріне назар аударыңыз.') WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бауыры өт өндіре бастады. Бұл сұйықтық ас қорыту жүйесі үшін өте маңызды, өйткені тағаммен бірге түсетін майлар мен маңызды витаминдердің (A, D, E, K) ағзаға сіңуіне көмектеседі. Өттің арқасында бөпеңіздің сүйек саулығына (D витамині), көру қабілетіне (A витамині), жасушаларды қорғауға (E витамині) және қанның ұюына (K витамині) қажетті заттар қанға өтеді. Сонымен қатар бұл сұйықтық ағзадағы кейбір зиянды заттарды шығаруға көмектеседі. Бауырда күн сайын түзілетін өт негізгі өзек арқылы он екі елі ішекке жеткізіледі. Ал оның бір бөлігі бауырдың астында орналасқан, алмұрт пішінді өт қабында жиналады. Қажет болғанда өт қабы бұл сұйықтықты аш ішекке шығарып, ас қорытуға көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, '13 АПТА! СӘЛЕМ, 2-ТРИМЕСТР! 🎉 Anacan, қуанышты жаңалық! Біз жүктіліктің үштен бірін (1/3) аяқтадық. Ең қиын күндер артта қалды. Енді Сіз де, мен де еркінірек тыныстайтын кезең басталады. Мен қазір қара өріктеймін. Дауыс байламдарым дамып қалды. Сізбен әлі сөйлесе алмасам да, дауысымды дайындап жатырмын. Осы жаңа кезеңде бізді одан да тамаша күндер күтіп тұр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қара өрік'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жиі кездесетін жағдайлардың бірі — қынаптық бөліндінің көбеюі. Ағзаңыздағы эстроген гормонының деңгейі жоғарылағандықтан, қынаптық бөліндінің артуы көбіне қалыпты жағдай болып саналады. Бөліндінің түсі ақ, сары немесе сәл күңгірт болуы мүмкін. Жүктілікке дейінгі кезеңмен салыстырғанда қандағы гормондар мөлшерінің артуына байланысты бөліндінің сыртқы көрінісі мен құрылымының өзгеруі табиғи құбылыс. Мына белгілерге назар аударыңыз: егер қынаптық бөлінді қою сары немесе жасыл түске айналса, консистенциясы тым қою болса және ең бастысы, бұзылған балықтың иісіндей жағымсыз иіс шықса, бұл қынап инфекциясының белгісі болуы мүмкін және емдеуді қажет етеді. Қынаптық бөліндінің көбеюі мен инфекциялардың алдын алу үшін душ қабылдағанда қынаптың ішіне су жібермеңіз, ішкі немесе сыртқы бөлігін хош иісті майлықтармен және сабынмен тазаламаңыз, дезодоранттар мен парфюмериялық құралдарды қолданбаңыз. Мұндай әрекеттер қынаптың табиғи микрофлорасын бұзатындықтан зиянды. Бұл кезеңде мақта маталы іш киім киіп, қажет болса, оны күніне 2-3 рет ауыстырыңыз. Ауа өткізбейтіндіктен, күнделікті төсеме қолданбаған жөн. Сондай-ақ іш киімнің тазалығын сақтау үшін оны жоғары температурада үтіктеңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезең саяхаттауға ("Babymoon") ең қауіпсіз әрі жайлы уақыт саналады. Қуатыңыз жеткілікті, ал ішіңіз әлі қатты үлкейген жоқ. Дәрігеріңізбен кеңесіп, шағын демалыс жоспарлай аласыз.') WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бірінші триместрдің соңында бөпеңіздің құрсағыңыздағы ең жақын серігі — плацента толық қалыптасып үлгерді. Бірнеше ай ғана қызмет ететін бұл уақытша ағза бөпеңіздің өмір сүруі мен өсуінде аса маңызды рөл атқарады. Осы кезеңге дейін жүктілікті сақтауға көмектесетін прогестерон гормонын ағзаңыздағы "сары дене" өндірсе, енді бұл жауапты міндетті плацента өз мойнына алады. Плацента ана қанындағы оттегіні, суды және глюкозаны бөпеге жеткізеді, бөпенің ағзасында түзілген қалдық заттарды шығарады, ана қанындағы кейбір инфекциялардан қорғайтын тосқауыл қызметін атқарады және бөпеге қажетті заттарды ғана өткізеді. Қысқаша айтқанда, плацента бөпеңіз үшін өкпе, бүйрек әрі қорғаныс жүйесі ретінде қызмет етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Денеме түк шығып жатыр! 🐻 Anacan, менің терімде "Лануго" деп аталатын өте жіңішке әрі жұмсақ түктер өсе бастады. Қазір мен кішкентай шабдалыға ұқсаймын. Бұл түктер мені судың ішінде тоңудан қорғайды әрі дене жылуымды сақтайды. Мен дүниеге келгенде олардың көбі түсіп қалады, бірақ әзірге маған осы "тон" қажет. Сіз мені жылы ұстайсыз, мен де өзімді жылы ұстаймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Киви'), body_changes_kk = COALESCE(body_changes_kk, 'Екінші триместрге қадам басқан осы күндері іштің төменгі бөлігінде немесе шап тұсында кенеттен шаншып ауыратын сезім пайда болуы мүмкін. Бұл ауырсыну бөпеңіз жатқан әрі өсіп келе жатқан жатырды қоршаған байламдардың созылуынан туындайды. Солардың бірі — "round ligament" (жатырдың жұмыр байламы). Мұндай ауырсыну көбіне орныңыздан тұрған кезде, төсекте оңға-солға аунағанда, кенет қимыл жасағанда немесе жөтелгенде пайда болады. Бұл әрекеттер жатырды қоршаған байламдарды керетіндіктен, ауырсыну сезіледі. Демалу, дене қалпын өзгерту, кенет қимыл жасамау, жылы душ қабылдау және ауырған жерге жылы компресс қою сияқты қарапайым шаралар жеңілдік береді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Тәбетіңіз ашылғандықтан, рационыңызды алуан түрлі етіңіз; бөпеңіз әртүрлі дәмдермен танысуы үшін түрлі көкөністер мен жемістер жеңіз. Қаназдықтың алдын алу үшін темірге бай тағамдарды (майсыз ет, жасымық, саумалдық) көбірек тұтыныңыз. Қуатыңыз жеткілікті болғандықтан, күн сайын 15-20 минут баяу серуендеу көңіл күйіңізге де, ас қорытуыңызға да жақсы әсер етеді.') WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесі құрылымдық жағынан қалыптасқанымен, ол дамуын ең соңында аяқтайтын ағза саналады. Өкпенің толық жетілуі жүктіліктің 38-ші аптасына дейін жалғасады. Қазір бөпеңіз амниотикалық сұйықтықтың ішінде болғандықтан, өкпесімен тыныс алмайды. Ол қажетті оттегіні тікелей Сіздің қаныңыздан алады да, көмірқышқыл газын қайтадан Сіздің қаныңызға өткізеді. Яғни ол Сіздің өкпеңізбен тыныс алып жатқандай.;;;
Соған қарамастан, бөпеңіз қазірдің өзінде тыныс алу жаттығуларын жасап жүр. Ол ауаның орнына суды (сұйықтықты) мұрны мен аузына тартып, қайта шығару арқылы тыныс алу бұлшықеттерін нығайтады. Бұл кішкентай қимылдарды ультрадыбыстық зерттеу кезінде көруге болады. Осы жаттығулардың арқасында ол дүниеге келген бойда алғашқы демін оңай ала алады.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақ іздерімнен кейін енді тырнақтарым да пайда болды! 💅 Anacan, саусақтарымның ұшында кішкентай әрі жұқа тырнақтар қалыптаса бастады. Олар әлі өте жұмсақ, бірақ дүниеге келгенше өседі. Кейде өз бетімді тырнап алуым мүмкін, сондықтан туған соң маған қолғап кигізуіңіз керек болады. Бәрім Сізге ұқсайды, ал тырнақтарым ше?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Киви'), body_changes_kk = COALESCE(body_changes_kk, 'Фолат — суда еритін B витаминдерінің бір түрі, ал оның тағамдық қоспалар мен байытылған өнімдерде қолданылатын синтетикалық түрі фолий қышқылы деп аталады. Фолий қышқылын ауыз арқылы қабылдау немесе ағзаға инъекция түрінде енгізу көпшілік үшін қауіпсіз. Оны әсіресе жүктілік кезінде қабылдау бөпенің жүйке жүйесінің дамуы және жүйке түтігінің жабылуы үшін өте маңызды. Жүктіліктің алғашқы апталарында ол қан түзілуіне, жаңа жасушалардың қалыптасуына, жасушалардың тіршілігін сақтауға, ДНҚ мен РНҚ түзілуіне үлкен ықпал етеді.;;;
Фолий қышқылын жүктіліктен кемінде үш ай бұрын қабылдай бастап, жүктіліктің ортасына дейін жалғастыру ұсынылады. Егер препарат қабылдау мүмкін болмаса, бамия, қояншөп, үрмебұршақ, ашытқы, саңырауқұлақ, ет, банан, саумалдық, брокколи және жапырақты салат сияқты фолатқа бай тағамдарды көбірек тұтыныңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Дене қалпыңызға мән беріңіз; тік жүру тыныс алуды жеңілдетіп, белдің ауырсынуын азайтады. Егер қызыл иегіңіз сезімтал болса, C витаминіне бай тағамдарды тұтыныңыз. Тәбетіңіз артса, тіскебасарға жаңғақтар сияқты пайдалы майларға бай өнімдерді таңдаңыз. Күн сайын бөпеңізбен сөйлесуге бірнеше минут бөліңіз.') WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізді қоршаған қағанақ суының көлемі шамамен 80 мл-ге жетті. Қазір бөпеңіздің басы денесінің жартысындай, себебі оның миы мен жүйке жүйесі өте жылдам дамып келеді. Уайымдамаңыз, алдағы апталарда денесі жылдамырақ өсіп, бұл арақатынас теңеседі. Дүниеге келгенде басы денесінің төрттен біріндей ғана болады. Жүйке жүйесінің жетілуінің арқасында бөпеңіздің ему және жұту рефлекстері күшейе түсуде. Ал жүрегі өсіп келе жатқан бүкіл денесіне қан жеткізу үшін өте жылдам соғып, қан айналымын жеделдетеді. Сіз әлі сезбесеңіз де, кішкентайыңыз құрсағыңызда қазірдің өзінде өте белсенді: есінейді, аяқтарымен тебеді, аунайды және саусақтарын қимылдатады. Егер бөпеңіз жатыр қабырғасына бір секундтан ұзақ жанасса, бәлкім, бұл кішкентай қимылдарды жақын арада сезе бастайсыз.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ұлмын ба, әлде қызбын ба? Бұл енді анық! 🩷💙 Менің жыныс мүшелерім толық қалыптасты. Егер мен қыз болсам, аналық бездерімде қазірдің өзінде 2 миллион жұмыртқа жасушасы бар. Ал ұл болсам, қуықасты безім қалыптасып жатыр. Дәрігерлер сапалы ультрадыбыстық аппаратпен қараса, бәлкім, жынысымды көре алар. Сіз не сезесіз? Ананың түйсігі мықты болады!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Киви'), body_changes_kk = COALESCE(body_changes_kk, 'Жатырыңыз кіндігіңізден бірнеше сантиметр төмен тұста сезіледі. Қан көлемі артқандықтан, жүрегіңіз жылдамырақ соғады, бұл қалыпты жағдай. Гормондардың әсерінен теріңіздегі пигментация (мысалы, секпілдердің немесе меңдердің күңгірттенуі) айқынырақ байқалуы мүмкін. Тәбетіңіз күрт арта бастауы ықтимал. Таңертеңгі жүрек айну басылғандықтан, тағамдардың дәмін қайтадан сезіне бастайсыз. Алайда абай болыңыз: тәттілер мен қамырдан жасалған тағамдарға құмарлық артық салмақ қосуға әкелуі мүмкін. Пайдалы тағамдардан алынатын калорияларға басымдық беріңіз.;;;
Сүт бездеріңіздегі тамырлар айқынырақ көрініп, емізік айналасы одан әрі күңгірттеніп, кеңейеді. Бұл — бөпеңіз дүниеге келгеннен кейін емшекті оңай табуы үшін табиғат қалыптастырған өзіндік бір "нысана" механизмі. Емшегіңізден сарғыш сұйықтықтың бөлінуі де, бөлінбеуі де қалыпты жағдай.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бөпеңіздің жынысын білуге асығып жүрсеңіз, келесі ультрадыбыстық зерттеуді күтіңіз. Бірақ бөпеңіздің жату қалпы кейде жынысын көруге мүмкіндік бермейтінін ұмытпаңыз. Зерттеу алдында тәтті нәрсе жеу бөпеңіздің қимылдауына ықпал етуі мүмкін.') WHERE id = '35661bc0-afeb-48b5-9303-88d093e85d1a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жаңадан дамып келе жатқан мүшелерінің бірі — көкбауыр. Құрылымы жұмсақ әрі кеуекке ұқсайтын көкбауыр бауырдың кейбір маңызды қызметтерін өз мойнына алатындай деңгейге дейін өсті. Көкбауыр бөпеңіздің ағзасында өзіндік бір "қауіпсіздік және қор сақтау" орталығы ретінде жұмыс істейді. Ол микробтармен күресетін ақ қан жасушаларын өндіреді. Ескірген және қызметін жоғалтқан қызыл қан жасушаларын ыдыратады. Қажет болған кезде пайдалану үшін қызыл қан жасушаларын сақтайды. Энергия шығыны артқанда, көкбауыр жиырылып, осы қан қорын қан айналымы жүйесіне жібереді. Сонымен қатар бөпеңіздің денесін лануго деп аталатын өте жіңішке, жұмсақ әрі түссіз түктер қаптап келеді. Бұл түктер бөпеңіз үшін өмірлік маңызы бар қорғаныш қабат болып саналады. Қазір бөпеңіздің денесіндегі май қабаты әлі толық қалыптаспағандықтан, лануго түктері оның дене температурасын тұрақты ұстауға көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сіздің даусыңызды тыңдап жатырмын! 👂 Құлақтарым мойнымның тұсынан жоғары көтеріліп, басымның екі жанына, яғни өз орнына келді. Енді Сізді жақсырақ естимін. Маған ертегі айтып, ән шырқап беріңізші. Сіздің даусыңыз мені тыныштандырады. Әкем де менімен сөйлессін, оның да даусын танығым келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мандарин'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңге дейін орта есеппен 3-4 келі қосуыңыз мүмкін. Жүктілік кезінде әр әйел дене бітіміне байланысты әртүрлі мөлшерде салмақ қосады. Жүктілік бойы орта есеппен 8-12 келі қосу қалыпты деп есептеледі. Алайда әр әйелдің дәл осындай мөлшерде салмақ қоспауы мүмкін. Бұл — толықтай табиғи үдеріс.;;;
Жүктілік кезінде аз немесе көп салмақ қосқанына қарамастан, әйелдің белінің жуандауы — табиғи жағдай. Жүктілік бойы ішіңізді қысып тұратын киімдерден, аяғыңызды қысып тұратын шұлықтардан, беліңізді қысатын белдіктерден және биік өкшелі аяқ киімнен бас тартып, киім таңдағанда жайлылыққа басымдық беруіңіз керек. Ішкиім таңдау да жайлылық пен гигиена тұрғысынан өте маңызды. Сондықтан синтетикалық және нейлон матадан тігілген ішкиімдерден бас тартып, мақта маталы ішкиімдерді таңдағаныңыз жөн. Сондай-ақ көкірекше таңдағанда әсіресе ыңғайлы әрі созылмалы үлгілерге басымдық беріңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Көбейген энергияңызды шығармашылыққа немесе болашақ жоспарларыңызға бағыттаңыз. Егер ішіңіз қышыса, бұл терінің созылып жатқанының белгісі болуы мүмкін; табиғи майлармен (бадам немесе зәйтүн майымен) үнемі ылғалдандырып отырыңыз. Бөпеңіздің сүйектері нығаюы үшін кальций мен D дәруменін жеткілікті мөлшерде қабылдауға көңіл бөліңіз. Күн сайын тыныш ортада 10 минут бойы бөпеңізге кітап оқу немесе музыка тыңдату онымен арадағы байланысты одан әрі нығайтады.') WHERE id = 'a57894a0-cfe4-43ea-b3a3-609e569ae8e7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің таңдай сүйегі мен ауыз қуысының төбесі толық қалыптасты. Ал ұртында дүниеге келген бойда сүт емуіне көмектесетін арнайы бұлшықеттер дамып жатыр. Ему — жай ғана қимыл емес, ол бөпеңіздің қоректенуі, иммунитеті және өзін қауіпсіз сезінуі үшін ең маңызды дағдылардың бірі. Ол құрсағыңызда саусағын сорып, қазірдің өзінде жаттығып жүр. Осы жаттығулардың арқасында дүниеге келген сәттен бастап емшегіңізді емуге қажетті күші мен әдісі болады. Ему үдерісі былай жүреді: бөпеңіз еріндерімен, үстіңгі таңдайымен және тілімен емізік ұшын ұстап, ауыз қуысында күшті вакуум (ауа өткізбейтін қуыс) қалыптастырады. Тілі артқа қарай тартылып, ауыз қуысында сүтке орын ашады, ал аузы сұйықтық сыртқа ағып кетпейтіндей тығыз жабылады. Бұл рефлекстің күшті болғаны сонша, алдағы апталарда осы қимылдардың арқасында бөпеңіздің аузында сілекей түзіле бастайды. Бұл дүниеге келгеннен кейін ас қорытуды жеңілдетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жүзіп жүрмін! 🏊‍♂️ Сенбейтін шығарсыз, бірақ мен қолдарымды қимылдатып, аяқтарыммен теуіп жүрмін. Бассейнде жүзіп жүрген кішкентай бақа сияқтымын. Бұл қимылдар миымның дамуы үшін өте маңызды. Сіз мені әлі сезбейсіз, өйткені айналамдағы су соққыларымды жұмсартады, бірақ мен өте күштімін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мандарин'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы аптасынан бастап шап тұсының ауыруы қалыпты болуы мүмкін. Бұл тіпті етеккір басталатындай сезім тудыруы ықтимал. Әр жүктілікте кездесуі мүмкін мұндай ауырсыну алғашқы айларда жатырдың өсуі мен жатыр бұлшықеттерінің созылуынан, ал соңғы айларда өсіп келе жатқан бөпеңіздің жатыр мен іштің төменгі бөлігіне түсіретін қысымынан пайда болуы мүмкін. Сонымен қатар жүктілік мерзімі ұлғайған сайын бөпеңіздің қимылдарына байланысты ауырсыну туындауы ықтимал. Мұндай ауырсыну кезінде дәрігердің бақылауымен магний қабылдау шағымдарыңызды азайтуы мүмкін. Әсіресе соңғы айларда пайда болып, тыныққаннан кейін де басылмайтын қатты шап ауыруы босанудың жақындағанын білдіруі мүмкін. Егер мерзімінен бұрын босану қаупі болса, мұндай жағдайда ауруханаға бару қажет болуы ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күннен қорғайтын кремді (SPF 50) қолдануды ұмытпаңыз. Тіпті қыста да! Бұл бетіңізде кетпейтін дақтардың пайда болуына жол бермеудің ең тиімді тәсілі. Күнге бас киімсіз шықпаңыз.') WHERE id = 'f4ba8684-d553-4733-84cb-3f9f1059e979';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің дене бітімі біртіндеп үйлесімді бола түсуде. Қолдары қажетті ұзындыққа жетті, енді денесімен бірге бірдей қарқынмен өсе береді. Ал аяқтарының жетілуіне әлі біраз уақыт қажет. Медицинада бөпеңіздің бойын өлшеуге мүмкіндік беретін ең маңызды көрсеткіш — денедегі ең ұзын әрі берік сүйек саналатын сан сүйегі. Бұл сүйек тексеру кезінде анық көрінеді және бөпенің жалпы бойы туралы нақты мәлімет береді. Соңғы жылдары бойды есептеудің тағы бір қызықты әдісі қолданылып жүр: аяқ ұзындығын өлшеу. Әсіресе 20-шы аптадан кейін сан сүйегінің немесе табанның ұзындығын 7-ге көбейту арқылы бөпенің шамамен бойын (аздаған қателік ықтималдығымен) білуге болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен бет-әлпетімді құбылта аламын! 😜 Бет бұлшықеттерімнің дамығаны сонша, қабағымды түйіп, көзімді сығырайтып немесе күлімсірей аламын. Кейде аузымды ашып, есінеймін. Бұл жай ғана көңіл көтеру емес, Сізбен қарым-қатынас жасауға дайындығым. Мені көргеніңізде, Сізге ең тәтті күлкімді сыйлаймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Мандарин'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде базалдық метаболизм жылдамдығыңыз қалыпты деңгейден орта есеппен 20 пайызға артады. Басқаша айтқанда, жүктілік барысында энергияға деген қажеттілігіңіз тәулігіне шамамен 300 калорияға көбейеді. Сонымен қатар май алмасуында да айтарлықтай өзгерістер болады. Әсіресе екінші триместрде майдың жиналуы артады, ал үшінші триместрде бөпеңіздің майға қажеттілігі өскендіктен, бұл май тінінің бір бөлігі бөпеге беріліп, жиналған май мөлшері азаяды. Бұдан бөлек, жүктіліктің соңына дейін ағзаңыздағы жалпы ақуыз мөлшері шамамен 1 kq-ға артады. Жүктілік кезінде ағзаңызда шамамен 6-7 litr су жиналып, аяқтарыңызда шамамен 1-2 litr ісіну сұйықтығы түзіледі. Айналымдағы қан көлемі 40-50 пайызға артады. Бұл өзгеріс артта қалған бірінші триместрде басталады. Қан көлемінің ұлғаюына байланысты жүрек соғу жиілігі шамамен 10 пайызға артып, қан қысымы төмендейді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Байламдардың ауыруын азайту үшін кенет қимылдардан аулақ болыңыз және төсектен тұрарда алдымен бір қырыңызға бұрылыңыз. Қызыл иектің сезімталдығына байланысты кальцийге бай тағамдарды (ірімшік, йогурт, күнжіт) тұтынуды жалғастырыңыз. Келесі аптада бөпенің бойы бұрынғыдан да жылдам өседі, сондықтан жеткілікті мөлшерде сұйықтық ішіп, дұрыс тамақтану тәртібін сақтаңыз.') WHERE id = 'e561aed2-5768-4e9c-b71e-e052866b75f4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада ультрадыбыстық зерттеу кезінде бөпеңіздің алақандарын, қолдары мен аяқтарын қаншалықты белсенді қимылдатып жатқанын анық көре аласыз. Ол құрсағыңызда үнемі қозғалып жүрсе де, бұл «биді» сезіну үшін әлі бірнеше апта қажет. Әдетте жүктіліктің 16-17-ші апталарында қимылдары сезілетіндей күшейеді. Алайда бұл мерзім әр адамда әртүрлі: Алғашқы жүктілікте: Құрсақ бұлшықеттері мықтырақ болғандықтан, қимылдарды сезіну 22-ші аптаға дейін созылуы мүмкін. Қайталама жүктілікте: Тәжірибелі аналар бұл сезімді ертерек, кейде 16-шы аптадан-ақ тани бастайды. Алғашқы қимылдар қатты тебу емес, көбіне «жеңіл қытықтау», «көбелектің ұшуы» немесе «құстың қанат қағуы» секілді нәзік сезіледі. Ал бұл қимылдар орта есеппен 24-26-шы апталардан бастап тұрақты болып, күн сайын сезіле бастайды.'), baby_message_kk = COALESCE(baby_message_kk, '14 АПТА! 📏 Менің көлемім шабдалыдай! Енді денем басыма қарағанда жылдамырақ өсіп жатыр, сондықтан кішкентай балаға көбірек ұқсаймын. Мойным ұзарып, иегім қалыптасты. Күн сайын аздап өсіп, күн сайын Сізбен қауышатын сәтке жақындай түсудемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Шабдалы'), body_changes_kk = COALESCE(body_changes_kk, 'Таңертеңгі жүрек айну мен кенеттен құсу әлі де жалғасуы мүмкін. Бұл әрбір жүкті әйелде болуы ықтимал қалыпты жағдайлардың бірі және көбіне емдеуді қажет етпейді.;;;
 Жүкті әйелдердің жартысына жуығында бұл жағдай әртүрлі ауырлық дәрежесінде байқалады. Алайда егіз күтіп жүрген әйелдерде ол ұзағырақ әрі ауыр өтуі мүмкін. Әсіресе жүктіліктің алғашқы апталарында байқалатын таңертеңгі жүрек айну гормондардың өз қызметін дұрыс атқарып жатқанының белгісі. Дегенмен жүрек айну мен құсудың нақты себептері белгісіз. Таңертеңгі жүрек айнудың ауырлығы әртүрлі болуына гормондар деңгейі, күйзеліс дәрежесі және шаршау сияқты факторлар әсер етуі мүмкін.;;;
Бұл жайсыздықты жеңілдету үшін бірнеше шара қолдануға болады. Ақуыз бен көмірсуларға бай тамақтану тәртібін ұстану, құсу кезінде жоғалған сұйықтықтың орнын толтыру үшін көп сұйықтық ішу, дәрумендеріңізді үзбей қабылдау, жүрек айнуын тудыруы мүмкін кез келген иіс, дәм немесе көріністен аулақ болу — сол шаралардың кейбірі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Киім сатып алуға таптырмас уақыт! Өзіңізді жайлы әрі әдемі сезіндіретін бірнеше жүкті әйелдерге арналған киім алыңыз. Тар киім қан айналымын нашарлатып, варикозды көктамырлардың пайда болуына себеп болуы мүмкін.') WHERE id = 'a6400bac-f975-43dc-a8f8-6c0a5411246c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бетіндегі кішкентай бұлшықеттер әртүрлі мимикалық қимылдар жасай алатындай деңгейге дейін дамыды. Бұл бұлшықеттер ауыз, көз, мұрын және құлақ маңында орналасқан және болашақта эмоцияларды білдіруге көмектеседі. Бөпеңіздің бетіндегі кейбір маңызды бұлшықеттер мыналар: Көз айналасындағы бұлшықеттер: Қабақты ашып-жұмуға және қабақты түюге көмектеседі. Ауыз айналасындағы бұлшықеттер: Ерінді жабуға және алға созуға мүмкіндік береді. Бұл бұлшықет дыбыс шығару үшін де маңызды. «Үрлеу» бұлшықеттері (ұрт бұлшықеттері): Ұртта орналасады, болашақта тағамды шайнауға және үрлеу қимылын жасауға қатысады. Бөпеңіз бұл мимикаларды әлі саналы түрде (мысалы, әдейі күлімсіреу) жасамаса да, миы дамыған сайын қуанышын, ашуын, қарны ашқанын немесе шаршағанын дәл осы бұлшықеттер арқылы Сізге көрсететін болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен дәм сеземін! 🍭 Тілімдегі дәм сезу бүртіктері жұмыс істей бастады. Сіз жеген тағамдардың дәмі қағанақ суына өтеді. Тәтті жесеңіз, мен сұйықтықты көбірек жұтамын, өйткені тәттіні жақсы көремін! Ащы немесе қышқыл жесеңіз, бетімді тыжырайтуым мүмкін. Сіз менің алғашқы аспазымсыз, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Шабдалы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүкті әйелдердің 30%-інде әдетте жеуге жарамсыз заттарды жегісі келумен сипатталатын пика синдромы деп аталатын тамақтану бұзылысы байқалуы мүмкін. «Пика» сөзі латын тілінен шыққан және тапқан нәрсесінің бәрін жейтін сауысқан құсын білдіреді. Бұл синдромы бар адамдар көбіне мұз, күл, сазды топырақ, сабын, қағаз, шаш, кірпіш ұнтағы, әктеу сылағы, жапырақ және қарындаш ұшы сияқты заттарды жейді. Мұндай заттарды жейтін жүкті әйелдердің бөпелерінде күрделі мәселелер туындауы мүмкін. Әйелдерде пика ұстамаларының неліктен пайда болатыны нақты белгісіз. Алайда мамандардың пікірінше, бұл ұстамалар темір тапшылығымен байланысты болуы немесе ағзаның қалыпты тамақтану арқылы жеткілікті мөлшерде ала алмаған дәрумендер мен минералдарды басқа жолмен алуға тырысуынан туындауы мүмкін.;;;
Себептердің қатарына психологиялық мазасыздық, сүйіспеншіліктің жетіспеуі, сенімсіздік және эмоциялық қолдаудың жеткіліксіздігі де жатады. Темір тапшылығына байланысты қаназдық болса, оны емдеу қажет. Ананың да, бөпенің де денсаулығы үшін мұндай заттарды жеуді тоқтату керек. Психологиялық мәселеге себеп болған факторларды жою қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Іш қатудың алдын алу үшін жасұныққа бай тағамдарды (өрік, қара өрік, сұлы, көкөністер) жеңіз. Таңертең ашқарынға бір стақан жылы су ішу ішектің жұмысын іске қосады. Қимыл-қозғалыстың аздығы ішектің жұмысын одан әрі баяулатады, сондықтан серуендеуге шығыңыз.') WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің терісі қарқынды дамып, қалыңдай түсуде және дене температурасын сақтау үшін лануго түктерімен жабылуын жалғастыруда. Денедегі ең үлкен мүше саналатын тері жүктіліктің үшінші аптасынан-ақ қалыптаса бастайды. Терінің ең сыртқы қабатында түктердің өсуі жеделдеді. Осы кезеңде түктер жылдамырақ өсіп, қалыңдайды. Сонымен қатар теріде меланоциттер деп аталатын ерекше жасушалар пайда болады. Бұл жасушалар тері мен шаштың түсін анықтайтын меланин пигментін өндіреді. Меланоциттер ағзаның табиғи "күннен қорғайтын кремі" іспетті. Олар бізді күннің зиянды сәулелерінен қорғайды:;;;
Күн сәулесі көп болғанда: Меланоциттер тері бетіне қарай көтеріліп, теріні күңгірттендіреді және зиянды сәулелердің ішке өтуіне жол бермейді.;;;
Күн сәулесі аз болғанда: Бұл жасушалар терінің төменгі қабаттарына қарай жылжиды. Соның арқасында терінің түсі ашық болып, ағза күн сәулесін (мысалы, D дәруменін түзу үшін) тиімдірек пайдалана алады.'), baby_message_kk = COALESCE(baby_message_kk, '100 КҮН! 💯 Anacan, сену қиын, бірақ бірге болғанымызға 100 күн толды! Менің көлемім бір алақандай. Қазір бас бармағымды соруды үйреніп жүрмін. Бұл мені тыныштандырады. Сіз алаңдағанда немесе шаршағанда, мен оны сеземін де, өзімді тыныштандыру үшін бармағымды сорамын. Біз бір-бірімізді сеземіз. Сізді қатты жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лимон'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің кейбір кезеңдерінде мұрынның бітелуі айтарлықтай жайсыздық тудыруы мүмкін. Жүкті әйелдердің шамамен үштен бірінде аллергия, суық тию немесе тұмау сияқты аурулар болмаса да, мұрынның бітелуі байқалады. Бұл жағдай жүкті әйелдердің риниті деп аталады.;;;
Сонымен қатар мұрынның бітелуімен бірге мұрыннан су ағуы мүмкін. Мұрын бітелгенде түнде ауызбен тыныс алуға тура келетіндіктен, тамақ құрғауы ықтимал. Сондай-ақ түнгі ентігу мен жөтел ұйқысыздыққа әкелуі мүмкін. Шырышты қабықтың ісінуі және соның салдарынан мұрын қуыстарының желдетілуі төмендеуі бас ауруын туындатуы мүмкін. Жүктілік кезінде деңгейі жоғарылайтын аналық гормондардың бірі — эстроген мұрын ішіндегі тіндердің ісінуіне және бөліндінің көбеюіне ықпал етеді. Бұған қоса, жүктілік кезінде ағзадағы айналымдағы қан көлемінің артуы қан тамырларын кеңейтіп, мұрынның шырышты қабығының ісінуіне әкеледі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы ерекше күнді шағын рәсіммен атап өтіңіз! Бәлкім, бөпеңізге алғашқы хатыңызды жазарсыз? Кальцийге қажеттілік артқандықтан, ас мәзіріңіздегі сүзбе, ірімшік және йогурт мөлшерін көбейтіңіз. Беліңіз ауырса, ұйықтағанда аяқтарыңыздың арасына жастық қойыңыз – бұл омыртқаға түсетін жүктемені азайтады. Суды молынан ішуді және таза ауада серуендеуді ұмытпаңыз.') WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасында таңғажайып қан түзілу үдерісі жүріп жатыр. Жүктіліктің алғашқы апталарында қанды сарыуыз қапшығы, кейін бауыр түзсе, 12-аптадан бастап бұл маңызды міндетті сүйек кемігі атқара бастады. Бөпеңіз дүниеге келгенде оның ағзасында шамамен 350 ml қан болады. Қазір бөпеңіздің денесі тұтастай дерлік "судан" тұрады. Оның денесінің шамамен 94%-ы — су. Сүйектері қатайып, бұлшықеттері көбейген сайын бұл көрсеткіш аздап төмендейді: 2-триместрдің ортасында: 80-85% су. Босануға жақын: 70% су (себебі бұл кезеңде май қабаты тез көбейеді). Салыстыру үшін, ересек адамның денесінде небәрі 60% су болады.;;;
Бөпеңіз дүниеге келген сәттен бастап ағзасындағы су теңгерімін сақтау үшін мидағы гипофиз безі вазопрессин (ADH) деп аталатын гормон бөле бастайды. Бұл гормон бүйректе судың қайта сіңуін қамтамасыз етіп, бөпеңіздің сусыздануына жол бермейді және ағзадағы сұйықтық теңгерімін сақтайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, Anacan! 👋 Мен бүгін су астында нағыз гимнастика жасап жүрмін. Сіз әзірге сезбейсіз, бірақ мен аунап, айналып, аяқтарымды созып жатырмын. Мұнда маған әлі де орын көп, сондықтан қалағанымша қозғала аламын. Бұл қимылдар бұлшықеттерімді нығайтып, сүйектерімді қатайтады. Сіз демала беріңіз, ал мен жаттығуымды жалғастырайын. Бір күні осы тепкілерімді Сіз де сезесіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лимон'), body_changes_kk = COALESCE(body_changes_kk, 'Әрбір әйел жүктіліктің белгілі бір кезеңінде іш қату мәселесіне тап болуы мүмкін. Жүктілік кезіндегі іш қатудың бір себебі — плацента әсерінен қандағы мөлшері артатын және ас қорыту жүйесін қоса алғанда, бірыңғай салалы бұлшықеттерді босаңсытатын прогестерон гормоны. Сондай-ақ үлкейіп келе жатқан жатырдың ішекке түсіретін қысымынан іш қату күшеюі мүмкін. Ішек бұлшықеттерінің босаңсуы тағам мен қалдықтардың ас қорыту жолымен баяуырақ жылжуына әкеледі. Темір қоспалары, әсіресе жоғары дозада қабылданса, жүктілік кезіндегі іш қатуды одан әрі күшейтуі мүмкін. Бұған қоса, дәрет кезінде қатты күшену немесе қатты нәжістің шығуы тік ішектегі қан тамырларының ісінуіне әкеліп, геморрой туындатуы ықтимал. Егер ішіңіз қатып, темір қоспаларын қабылдап жүрсеңіз, суды жеткілікті мөлшерде ішетініңізге көз жеткізіңіз. Соған қарамастан шағымыңыз басылмаса, дәрігердің кеңесімен темір препаратының басқа түріне ауысу қажет болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Есту қабілеті жақсарып келе жатқандықтан, бөпеңізге баяу музыка тыңдатыңыз немесе ертегі айтып беріңіз. Маңызды істерді ұмытып кетпеу үшін оларды қойындәптерге жазып жүріңіз. Терідегі пигментация өзгерістеріне алаңдамаңыз, олар босанғаннан кейін басылады. Сұйықтықты молынан ішіп, кальцийге бай тағамдарды (бадам, брокколи, сүт өнімдері) тұтынуды жалғастырыңыз.') WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ұзарып, иіріліп жатқан ішегінде меконий (алғашқы нәжіс) жинала бастайды. Меконий — бөпеңіздің жүктілік бойы жұтқан амниотикалық сұйықтығы, түскен лануго түктері мен ішек бөлінділерінің қоспасынан түзілетін жабысқақ, иіссіз зат. Оның 90%-ы судан тұрады және бөпеңіз дүниеге келгенге дейін ішегінде жиналады. Әдетте бөпе туғаннан кейінгі алғашқы 24 сағат ішінде осы нәжісті шығарады. Ауамен жанаспағандықтан, ол стерильді және құрсағыңыздағы бөпеге еш зиян келтірмейді. Түсі әдетте қою жасыл немесе қара болады, алайда бөпе қоректене бастағаннан кейін түсі ашықтанып, сарыға айналады. Кейде, әсіресе мерзімінен асып туған бөпелерде, меконий әлі жатырдың ішінде жатқанда бөлінуі мүмкін. Мұндай жағдайда дәрігерлер босанғаннан кейін бұл зат өкпеге өтіп, қиындық туғызбауы үшін бөпенің тыныс жолдарын дереу тазартады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жарықты сеземін! 💡 Anacan, сену қиын болар, бірақ қабақтарым жабық болса да, жарықты жақсы сезе аламын. Егер ішіңізге жарығы күшті қолшам түсірсеңіз, мен бетімді сол жаққа бұруым немесе жарық көзімді қарықтырғандықтан, бетімді қолыммен жабуым мүмкін. Менің әлемім енді мүлде қараңғы емес. Сіздің әлеміңіз қандай түрлі түсті екен?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лимон'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпе жатырға бекінгеннен кейін емшектегі сүт өзектері мен емшек көлемі ағзаны босануға дайындау үшін дами бастайды және сүттің түзілуін қамтамасыз етеді. Жүктіліктің 16-аптасынан бастап емшегіңізден анда-санда сарғыш сұйықтық бөлінетінін байқауыңыз мүмкін. Емшектен бөлінетін бұл сұйықтық иіссіз, сары немесе мөлдір болады. Бұл уыздың құрамында иммундық жүйесі әлі жетілмеген бөпеңізге қажетті көптеген антидене бар және ол бөпеңізді әртүрлі вирустар мен микробтардан қорғайды. Бұл сұйықтықта кәдімгі ана сүтіне қарағанда ақуыз мөлшері жоғары болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңіз үлкейген сайын ұйықтау қалпыңызды өзгерте бастаңыз. Шалқаңыздан жату жатырдың негізгі қан тамырларына қысым түсіруіне себеп болуы мүмкін. Сол жақ қырыңызбен жату — Сіз бен бөпеңіздің қан айналымы үшін ең қолайлы қалып.') WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүйке жүйесі қолдарын, білектерін және аяқтарын саналы түрде басқара алатындай деңгейге жетті. Енді ол жай ғана қимылдамайды: жұдырығын түйеді, саусақтарын жеке-жеке қозғалтады, білектерін бүгеді және бір нәрсені ұстап алғысы келгендей қармау қимылдарын жасайды. Бөпеңіздің алғашқы қимылдары 7-8-апталарда-ақ омыртқасының қозғалуынан басталған еді. Ол кезде бөпеңіз тым кішкентай болғандықтан сезілмеген алға иілу және жанға қарай бүгілу қимылдары қазір күшейіп, мақсатты сипатқа ие болды. Бұл ғажайып сезімді бастан кешіруге аз ғана уақыт қалды! Әдетте аналар бөпесінің алғашқы қимылдарын 16-20-апталар аралығында сезіне бастайды. Алғаш сезілетін қимылдар бөпеңіздің тебуі, шынтағымен түртуі немесе денесін артқа қарай керуі салдарынан пайда болатын кішкентай томпаюлар болуы мүмкін. Егер бұл Сіздің алғашқы жүктілігіңіз болса немесе салмағыңыз сәл артық болса, бұл қимылдарды сезіну 24-аптаға дейін созылуы мүмкін — бұл қалыпты жағдай. Мұндайда кішкентай бір әдісті қолданып көруге болады: тәтті жеу қандағы қант деңгейін көтеріп, бөпеңізді белсендірек етуі және оның қимылдарын тезірек сезуіңізге көмектесуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тыныс алуды жаттықтырып жүрмін! 🌬️ Әрине, мұнда ауа жоқ, тек су бар. Бірақ мен қағанақ суын өкпеме тартып, қайта шығарамын. Бұл өкпемдегі көпіршіктердің ашылуына көмектесіп, оларды болашақтағы алғашқы тынысыма дайындайды. Кейде бұл сұйықтық тамағыма кетіп қалса, ықылық атаймын. Сіз осы ырғақты ықылықты бірнеше аптадан кейін сезуіңіз мүмкін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Лимон'), body_changes_kk = COALESCE(body_changes_kk, 'Ұйқысыздық деп аталатын ұйықтап кетудің және ұйқыны үзбей жалғастырудың қиындауы жүктілік кезінде жиі кездесетін мәселе. Ұйқысыздық жүкті әйелдердің барлығына дерлік әсер етеді және іш айтарлықтай үлкейетін, жүктілік анық байқалатын соңғы үш айда күшейе түседі. Жүктіліктің басынан бастап ағзаңыздағы өзгерістерге байланысты миыңыз көбірек демалу қажет екені туралы белгі бере бастайды. Күні бойы өзіңізді шаршаңқы сезініп, көбірек демалуға және ұйықтауға мұқтаж боласыз. Алайда әсіресе жүктіліктің соңғы айларында пайда болатын кейбір жайсыздықтар ұйқы тәртібін бұзуы мүмкін. Жүктілік кезіндегі ұйқысыздыққа қыжыл, аяқтың ісінуі, жиі зәр шығару, жүрек соғуының жиілеуі, ентігу, аяққа түсетін қосымша салмақтан туындайтын құрысулар мен ауырсыну, сондай-ақ ас қорыту жүйесінің баяулауынан болатын асқазан қышқылының кері ағуы себеп болуы мүмкін. Сонымен қатар шамадан тыс күйзеліс пен көңіл күйдің нашар болуы да жүктілік кезінде ұйқысыздыққа әкелуі ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңыздың шаршауын азайту үшін күні бойы дене қалпыңызды жиі өзгертіп, ұзақ уақыт тік тұрып қалмаңыз. Кешке аяқтарыңызды жүрек деңгейінен жоғары көтеріп, 15 минут демалдырыңыз. Дұрыс тамақтану тәртібін сақтаңыз (ақуыз бен тағамдық талшыққа бай тағамдарға басымдық беріңіз). Егер өкшелі аяқкиім киіп жүрсеңіз, енді аласа әрі ортопедиялық үлгілерге ауысатын уақыт келді.') WHERE id = 'ad6452f4-e2be-4e97-a304-4ef7692bd10b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүрегі 4-аптада-ақ, небәрі бірнеше жасушаның ғажайып түрде жиырылып-босаңсуының арқасында соға бастаған. Бұл кішкентай қозғалтқыш небәрі 40 күн ішінде дамып, толық қалыптасқан төрт камералы мүшеге айналды. Қазір, яғни төртінші айда, бөпеңіздің жүрегі оның кішкентай денесіне тәулігіне шамамен 20-25 литр қан айдайды. Ал дүниеге келген кезде бұл көрсеткіш таңғаларлықтай артып, тәулігіне 250-300 литрге жетеді. Бөпеңіздің жүрегі Сіздің жүрегіңізден шамамен екі есе жылдам соғады (минутына 140-160 рет). Жүктілік бойы бұл кішкентай жүрек 1.5 миллионнан астам рет соғып, бөпеңіздің әрбір жасушасын қанмен және тіршілік нәрімен қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сіздің жүрегіңізді тыңдап жатырмын! ❤️ Менің есту қабілетім күн сайын жақсарып келеді. Жүрегіңіздің соғуы, қаныңыздың тамырлармен ағу дыбысы және асқазаныңыздың шұрылдауы мен үшін үздіксіз әуен іспетті. Бұл дыбыстар мені тыныштандырады. Дүниеге келгеннен кейін де мені құшағыңызға алғанда жүрегіңіздің соғуын естіп тынышталамын, өйткені бұл дыбыс маған "үйді" еске салады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құба алмасы'), body_changes_kk = COALESCE(body_changes_kk, 'Әдетте адам тәулігіне шамамен 2 литр су ішуі керек. Алайда жүктілік кезінде бұл мөлшер 3-3.5 литрге дейін артуы мүмкін. Себебі жүктілік кезіндегі физиологиялық өзгерістерге бөпенің өсуі де қосылатындықтан, ағзаға көп мөлшерде су қажет болады. Жүктіліктің басынан соңына дейін қан көлемі шамамен 1-1.5 литрге артып, бөпеңіз жатқан жатырда қағанақ суы түзіледі. Бұл сұйықтық тәулік бойы үнемі жаңарып отыруы керек. Қағанақ суы белгілі бір уақыт аралығында ана ағзасындағы сумен алмасып, тазарады. Бөпені қоршап тұрған қағанақ суының жеткілікті болуы оның қозғалысы мен өкпесінің дамуы үшін өте маңызды. Сондай-ақ бөпе жасушаларының шамамен 80%-ы судан тұратындықтан, ананың ішетін су мөлшері бөпеге тікелей әсер етеді. Бұл кезеңде су дене температурасын реттеу, буындардың қалыпты жұмыс істеуі, терінің әдемілігі және ас қорыту жүйесі үшін де аса маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Мақтадан тігілген ішкиім киіп, тар шалбардан бас тартыңыз. Күнделікті төсемелерді қолдансаңыз, ылғалды ортада бактериялар көбеймес үшін оларды әр 3-4 сағат сайын ауыстырыңыз. Интимдік аймақты құрғақ ұстау маңызды.') WHERE id = '170cfd85-3741-42d0-81e6-fb29eb61eb4e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіздің салмағы шамамен 50 грамм, ал бойы 11-12 см. Қазір ол бас терісінен қасына дейін қалың лануго түктерімен жабылған, кішкентай құлақтары мен жұмулы қабақтары бар, тынығып жатқан кішкентай адамға ұқсайды. Бөпеңіздің көздері құрылымдық жағынан толық қалыптасқанымен, қызметі жағынан ең соңғы болып жетілетін мүше саналады. Мұның қызықты себебі бар: жүйке жасушалары (нейрондар) көп болғанымен, олардың айналасындағы миелин қабығы әлі қалыптаспаған. Миелин қабығы — жүйкелерді қаптайтын арнайы майлы қабат. Оны электр сымдарының сыртындағы оқшаулағыш қабатпен салыстыруға болады. Бұл қабат болмаса, электрлік сигналдар нейрондар арасында жылдам беріле алмайды. Миелин қабығы қалыптасқан сайын бөпеңіз сырттан келетін бейнелер мен сигналдарды жылдамырақ қабылдап, түсіне бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, менің терім әлі өте жұқа, бірақ денемдегі "лануго" деп аталатын түктер мені жылы ұстайды. Аяқтарым қолдарымнан ұзынырақ бола бастады. Енді дене бітімім біршама үйлесімді көрінеді. Өсу өте шаршатады, бірақ менің қолымнан келеді!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құба алмасы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде бөпеңіздің де, өзіңіздің де денсаулығыңыз үшін жеткілікті мөлшерде су ішуіңіз керек. Бұл кезеңде ішетін су мөлшері бөпеңізге қаншалықты әсер етсе, Сізге де соншалықты әсер етеді. Жүктілік кезінде жеткілікті су ішу көптеген мәселені жеңілдетіп қана қоймай, кей жағдайда олардың алдын алуға да көмектеседі. Суды жеткілікті мөлшерде ішу жатырдың жиырылуын азайтып, мерзімінен бұрын босану қаупінің алдын алады. Теріңіздің жарқын әрі сау көрінуіне көмектесіп, созылу белгілерінің пайда болуын азайтады. Зәр шығару жолдарының инфекцияларының, іш қатудың және геморройдың алдын алады. Бөпеңізді қоршап тұрған қағанақ суының азаюы немесе жеткілікті жаңармауы сияқты мәселелерден қорғайды. Әсіресе жаздың ыстық айларында терлеу арқылы жоғалған сұйықтықтың орнын толтырады. Жүрек айнуын, қыжылды және денедегі ісінуді азайтады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылды басу үшін бадам жеу немесе бір стақан жылы сүт ішуге болады — бұл табиғи тыныштандырушы құралдар.') WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз дүниеге келген сәттен бастап ести, жылай және кейбір рефлекстерін көрсете алғанымен, көру, сөйлеу және жүру сияқты дағдыларды меңгеруі үшін әлі уақыт қажет. Мұның басты себебі — жүйке жүйесінің сыртқы тітіркендіргіштермен әлі жеткілікті деңгейде бетпе-бет келмеуі. Мидың дамуы белгілі бір мағынада «тәжірибе жинау» арқылы аяқталады. Әсіресе көру сезімі ең кеш дамитын жүйе саналады. Дүниеге келген кезде көздің торлы қабығы да, мидағы көру орталығы да әлі толық жетілмеген болады. Ана құрсағында бөпеңіз жарықты ажырата алады, бірақ мұны толыққанды көру деуге болмайды. Алғашқы 3 айда айнала әлі де бұлыңғыр көрінеді. Бөпеңіз тек 50-70 см қашықтықтағы заттарды ғана ажырата алады (шамамен құшағыңызда жатқанда жүзіңізді көре алатын аралық). Көзін бір нүктеге шоғырландыру қабілеті әлі әлсіз. 5-6 айға толғанда қимыл-қозғалысы артқан сайын көруі де айқындала түседі. Ол енді қозғалып тұрған заттарды көзімен қадағалап, көз бен қол үйлесімінің арқасында көрген ойыншығына қолын созады. Көз бен көру жүйкелерінің дамуы 7 жаста толық аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Дәмдерді ажырата аламын! 🍬 Anacan, Сіз тәтті нәрсе жегенде қағанақ суының дәмі тәттіленіп, мен оны көбірек жұтамын. Ал дәмі қышқыл немесе ащы болса, бетімді тыржитамын. Менің дәм сезу қабілетім ересек адамдікіндей дерлік күшті. Болашақта қандай көкөністерді ұнататыным қазірден-ақ Сіздің тамақтануыңызға байланысты. Мен де сау болуым үшін пайдалы тағамдар жеңіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құба алмасы'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігеріңіз келесі аптада үштік скринингтен өтуіңізді ұсынуы мүмкін. Үштік скрининг — барлық жүкті әйелдерге жүктіліктің 16-шы және 18-ші апталары аралығында ұсынылатын қан талдауы. Болашақ анадан алынған қан үлгісінде 3 түрлі гормонның деңгейі өлшенеді. Бұл гормондардың көрсеткіштері ананың жасы, салмағы, темекі шегетін-шекпейтіні және жүктілік мерзімі сияқты деректермен бірге арнайы компьютерлік бағдарламаға енгізіліп, өңделеді. Бұл зерттеу жүктілік кезінде бөпеде болуы мүмкін хромосомалық ауытқуларды, әсіресе Даун синдромы деп аталатын 21-трисомияны, Эдвардс синдромы деп аталатын 18-трисомияны, сондай-ақ жүйке түтігінің ақаулары деп аталатын ауытқуларды анықтауға арналған скрининг болып табылады. Әсіресе отбасылық анамнезінде туа біткен ақаулар бар, жасы 35-тен асқан, жүктілік кезінде зиянды дәрі-дәрмек немесе таблетка қабылдаған, инсулин қолданатын немесе қант диабеті бар, жүктілік кезінде вирустық инфекциямен ауырған және бұрын туа біткен ақауы бар бала босанған әйелдердің бұл тексеруден өтуі маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, '15-ші аптаның аяқталуын өзіңізді аздап еркелетіп атап өтіңіз! Белдің ауырсынуын болдырмау үшін ыңғайлы аяқ киім киіп, ауыр зат көтермеңіз. Қызыл иектің саулығы үшін кальцийді тұрақты қабылдауды ұмытпаңыз. Келесі аптада бөпеңіздің қимылдары одан әрі күшейеді, сондықтан күн сайын онымен бірнеше минут тыныш сөйлесуді әдетке айналдырыңыз.') WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің өсуін бақылау үшін тек бойын өлшеу жеткіліксіз болады. Дәрігерлер егжей-тегжейлі көрсеткіштерге — басы мен ішінің шеңберіне, сондай-ақ сан сүйегінің ұзындығына назар аударады. Бұл сандар бөпеңіздің дамуы жүктілік мерзіміне сәйкес келетін-келмейтінін нақты көрсетеді. Бөпеңіз енді басы мен мойнын тік ұстай алады. Бұған мойынның екі жағындағы күшті бұлшықеттер мүмкіндік береді. Бұл бұлшықеттер бас сүйегін тіреп, бөпеңіздің басын еркін қозғалтуына жағдай жасайды. Сүйектер бір-біріне үйкеліп, тозбауы үшін қозғалмалы буындарда буын сұйықтығы болады. Бұл сұйықтық сүйектердің майланғандай жеңіл әрі ауырсынусыз қозғалуын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Аяқтарым ұзарып келеді! 🦵 Осы уақытқа дейін қолдарым мен аяқтарымның ұзындығы бірдей еді, ал енді аяқтарым денеме қарағанда жылдамырақ өсіп жатыр. Мен қазірдің өзінде нағыз модель сияқты көрінемін! Аяқтарымды бүгіп, тізелерімді өзіме қарай тартамын. Осы ұзын аяқтарыммен Сізді жақсылап тебуге дайындалып жатырмын. Әзілдеп тұрмын, Сізді ауыртпаймын, тек «сәлем» деймін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Құба алмасы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы кезеңінен кейін бөпеңіздің жылдам өсуі және шат аймағындағы қан тамырларына қысым түсіруі салдарынан аяқтағы қан айналымы баяулайды. Бұған жаз айларындағы ыстық ауа қосылғанда, денеңіздің әртүрлі аймақтарында, әсіресе аяқта, тобықта және балтырда ісіну пайда болуы мүмкін. Мүмкіндік болған сайын демалу, жайлы төсекке немесе диванға жатып, аяғыңыздың астына жастық қойып жоғары көтеру, қажет болғанда қолыңыз бен тобығыңызға жеңіл массаж жасау және аяқ киіміңіздің ыңғайлы болуына мән беру бұл шағымдарды азайтады.;;;
Денеңізде ісіну пайда болуының тағы бір себебі — қимыл-қозғалыстың аздығымен қатар жүретін шамадан тыс салмақ қосу. Тамақтануды реттеу және жүктілік кезінде рұқсат етілген жаттығуларды орындау салмақты бақылауға көмектесіп қана қоймай, алдағы айларда пайда болуы мүмкін бел мен шаттың ауырсынуын да жеңілдетеді.;;;
Жаяу жүру мен жүзу жүкті әйелдерге ең қолайлы жаттығулар болып саналады. Екеуі де болашақ ананың жүрегіне, тепе-теңдігіне, буындары мен бұлшықеттеріне қауіп төндірмей орындай алатын спорт түрлері. Жаттығу кезінде қысқа үзілістер жасап, денені қатты шаршатпау керек. Жүзу үшін мүмкіндігінше бассейннің орнына теңізді таңдаған жөн. Тиісті деңгейде бақыланатынына сенімді емес бассейндерден аулақ болыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан көлемі артқандықтан, темірді жеткілікті мөлшерде қабылдауға ерекше көңіл бөліңіз. Байламдардың ауырсынуын азайту үшін кенет қимыл жасамауға тырысыңыз. Ішіңіз қышыса, күн сайын кешке ылғалдандыратын майлармен массаж жасаңыз. Күніңізді жағымды өткізу үшін сүйікті кітабыңызды бөпеңізге дауыстап оқып бере аласыз.') WHERE id = 'abd207ad-c924-457f-b115-c38d8e842b83';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішкі құлағының құрылымы осы аптада қалыптаса бастағанымен, оның шын мәнінде ести бастауы үшін әлі бірнеше апта қажет. Ішкі құлақ — дыбыстарды естуге де, дененің тепе-теңдігін сақтауға да жауап беретін өте күрделі жүйе.;;;
Бөпеңіз толық дамыған кезде осы жүйе арқылы 20-дан 20.000 hertz-ке дейінгі барлық дыбыстарды ести алады. Қазір бұл ғажайып «құрылғы» жасалып жатыр, алайда оның толық іске қосылуы жүктіліктің кейінгі кезеңдерінде (шамамен 30-шы аптаға қарай) жүзеге асады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сізді сеземін! 🤗 Anacan, Сіз ішіңізді сипағанда, мен сол қысым мен жылуды сезе аламын. Кейде қолыңыз тұрған жерге қарай жүзіп барамын. Арамызда тек тері мен су бар, бірақ жанымыз бір. Сіз күйзеліске түскенде мен де мазасызданамын, ал Сіз күлгенде мен де тынышталамын. Өтінемін, әрдайым күлімсіреп жүріңіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Апельсин'), body_changes_kk = COALESCE(body_changes_kk, 'Кейде өзіңізді эмоцияға берілген, күйзелген және түрлі күрделі сезімдердің арасында қалғандай сезінуіңіз мүмкін. Жүктілік кезінде денеңізде бірқатар өзгерістер болады. Бұл физикалық және гормондық өзгерістер психологиялық күйіңізге де әсер етуі мүмкін. Эмоцияға берілу, өкпелегіштік және сезімталдық — осы кезеңде ең жиі кездесетін күйлер. Жүктілік кезінде туындайтын мұндай қиындықтардың уақытша екенін ұмытпаңыз. Бұл мәселеде жұбайыңыздың қолдауын алу екеуіңізге де оң әсер етеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентіккен кезде тік тұрып, иықтарыңызды артқа қарай жіберіңіз. Бұл өкпеге көбірек орын ашады. Баяу әрі терең тыныс алу Сізді де, бөпеңізді де оттегімен қамтамасыз етеді.') WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіздің басының өсу қарқыны сәл баяулайды, осылайша денесі басының өлшеміне сай өсіп үлгереді. Сонымен қатар өкпесінде болашақта тыныс алуын қамтамасыз ететін ең маңызды бөліктер — альвеолалар қалыптасып үлгерді. Альвеолалар — өкпенің ең шеткі бөліктерінде орналасқан, іші ауаға толатын кішкентай қапшықтар. Олардың негізгі міндеті — газ алмасуды жүзеге асыру: қандағы көмірқышқыл газын сыртқа шығарып, ағзаға қажетті оттегіні қанға өткізу. Қазір бөпеңіз бұл жүйені ауамен емес, амнион сұйықтығымен "жаттықтырып" жүр. Бұл жаттығулар оның дүниеге келген сәтте алғаш рет тыныс алуы үшін өте маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Құлақтарым өз орнында! 👂 Құлақтарым енді басымның екі жанындағы түпкілікті орнына жайғасты. Қазір мен Сізді бұрынғыдан да анық естимін. Ішектеріңіздің дыбысы мен тыныс алғаныңыз мен үшін симфония секілді. Бірақ маған ең ұнайтын дыбыс — Сіздің сөйлегеніңіз бен күлкіңіз. Маған жиі бесік жырын айтып беріңізші, мен оларды есімде сақтап жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Апельсин'), body_changes_kk = COALESCE(body_changes_kk, 'Алдағы күндері мұрныңыздан қан кетуі мүмкін. Көптеген әйелде жүктіліктің белгілі бір кезеңінде мұндай жағдай кездеседі. Алаңдаудың қажеті жоқ. Бөпеңіз жатырда өсе бастаған сайын ағзаңыздағы қан көлемі мен қан тамырларына түсетін қысым артады. Бұл қысым әсіресе жіңішке әрі беткей орналасқан қан тамырларына әсер етіп, мұрыннан қан кетуіне әкелуі мүмкін. Қысым салдарынан мұрынның ішкі қабатындағы нәзік тамырлар жарылып, қанайды. Мұрыннан қан кеткенде жатуға немесе басты шалқайтуға болмайды. Өйткені қан тамағыңызға ағып, оны жұтып қоюыңыз және жүрегіңіздің айнуы мүмкін. Оның орнына отырып немесе тік тұрып, басыңызды сәл алға еңкейтіңіз де, мұрныңыздың жұмсақ бөлігін қысып, қан тоқтағанша күтіңіз. Сонымен қатар қан тамырларыңызды нығайту үшін дәрігеріңіздің ұсынымымен С дәрумені қоспасын қабылдауға болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қызыл иектің қанауын болдырмау үшін жұмсақ тіс щеткасын пайдаланыңыз. Артқан тәбетіңізді пайдалы тағамдармен басуға тырысыңыз. Беліңіз ауырмауы үшін бір қалыпта ұзақ тұрмаңыз. Күніңізді көтеріңкі көңіл күймен өткізу үшін сүйікті әндеріңізден ойнату тізімін құрып, оны бөпеңізбен бірге тыңдаңыз.') WHERE id = '785f2466-b995-4db8-a286-7f765b7f2877';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз қазірдің өзінде авокадоның көлеміндей болды!  Осы аптадағы ең қызықты жаңалық — бөпеңіздің дәм сезу қабілетінің дамуы.;;;
Бөпеңіздің тілінің бетінде дәм сезу бүртіктері қалыптасып үлгерді. Дәм сезу механизмі өте күрделі әрі қызық: тағам ауыздағы сілекейде ериді, содан кейін тілдің үстіңгі бөлігіндегі рецепторлар дәмді қабылдап, мидағы сезім орталығына жеткізеді.;;;
Кез келген тіршілік иесі секілді, бөпеңіз де айналасындағы тітіркендіргіштерге (бұл жағдайда өзі жұтатын амнион сұйықтығының дәміне) жауап беруді үйреніп жатыр. Бір қызығы, тілдің әр бөлігі барлық дәмді бірдей қарқынмен сезбейді:;;;
Сіз жеген тағамдардың дәмі амнион сұйықтығына өтетіндіктен, бөпеңіз қазірдің өзінде әртүрлі дәмдермен танысып жүр. Бұл тіпті оның болашақтағы тағам таңдауына әсер етуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүрегім мықты! 💪 Менің кішкентай жүрегім күніне шамамен 25 литр қан айдайды! Осындай кішкентай дене үшін бұл — орасан зор жұмыс. Қан бүкіл денемді айналып, маған оттегі мен қоректік заттарды жеткізеді. Сіздің арқаңызда менің жүрегім мықты. Бұл жүрек өмір бойы тек Сізді сүю үшін соғады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Авокадо'), body_changes_kk = COALESCE(body_changes_kk, 'Кейде өзіңізді қатты шаршағандай сезінуіңіз мүмкін. Ал кей күндері керісінше, әдеттегіден әлдеқайда сергек боласыз. Алғашқы үш айда прогестерон деңгейінің жылдам жоғарылауы ұйқышылдық тудыруы мүмкін. Зат алмасу үдерісі де жеделдеп, ағзаңыз көбірек қуат жұмсайды, бұл жүктіліктің бастапқы кезеңіндегі шаршауды күшейтеді. Сонымен қатар қан қысымының төмендеуі мен қан көлемінің артуы да қуатыңызды азайтады. Ал жүктіліктің 2-ші триместрі жүктіліктің "бал айы" деп аталады. Ағзаңыз жүктілік гормондарының өзгерісіне бейімделіп үлгерді, сондықтан алғашқы триместрмен салыстырғанда өзіңізді азырақ шаршағандай сезініп, бөпеңіздің дүниеге келетініне толық дайындала бастай аласыз. Шаршаған кезіңізде оны жеңілдету үшін дұрыс тамақтануды, мол су ішуді, ұйқы режимін сақтауды және жеткілікті қимылдауды ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Тік отыруға және жүргенде иығыңызды артқа қарай ұстауға тырысыңыз; бұл белдің ауыруын азайтады. Теріңіздің серпімділігін сақтау үшін ылғалдандырғыш құралдарды қолдануды жалғастырыңыз. Бөпеңіздің сүйектері нығайып, өзіңізде аяқ құрысуы болмауы үшін кальций мен магнийге бай тағамдарға (бадам, жасыл көкөністер) басымдық беріңіз.') WHERE id = '6a2c14a8-03ef-4ac3-8457-485f9afcbef3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ультрадыбыстық зерттеу кезінде бөпеңіздің қаңқасы анық көрінетіндей деңгейде дамып үлгерген. Қаңқа жүйесі сүйектерден және оларды байланыстыратын буындардан тұрады. Бұл сүйектер бұлшықеттермен бірге жұмыс істеп, бөпеңіздің құрсағыңыздағы икемді қимылдарын қамтамасыз етеді.;;;
Жаңа туған бөпенің денесінде 270 сүйек болса, ересек адамда бұл сан 206-ға тең. Оның себебі — бөпенің сүйектері әлі де шеміршек тәрізді және бір-бірінен бөлек болады. Мұндай иілгіштік бөпенің босану жолынан өткен кезде жарақаттануына жол бермейді. Дүниеге келгеннен кейін бұл кішкентай сүйектер (мысалы, бас сүйегінің бөліктері) уақыт өте келе бір-бірімен бітісіп, ірі әрі берік сүйектерді қалыптастырады.'), baby_message_kk = COALESCE(baby_message_kk, 'Басымды тік ұстаймын! 🦒 Anacan, мойнымның бұлшықеттері қатты нығайғаны сонша, қазір басымды тік ұстай аламын. Бұрын басым кеудеме қарай иіліп тұратын, ал қазір айналама еркінірек қарай аламын (қараңғы болса да). Денем ұзарып, сымбатты әрі тік тұлғалы болып келемін. Сіздің құрсағыңызда гимнастика жасау сондай керемет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Авокадо'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде гормондық теңгерімнің өзгеруіне байланысты ағзаңызда әдеттегіден өзгеше үдерістер жүреді. Әсіресе жүктіліктің алғашқы үш айында жүрек айну, құсу, көздің қарауытуы, бас айналу және естен тану секілді шағымдар жиі кездескенімен, олар жүктіліктің кез келген кезеңінде ара-тұра пайда болуы мүмкін. Жүктілік кезінде жатыр әдеттегіден әлдеқайда үлкейетіндіктен, ағзадағы қанның едәуір бөлігі бөпеңіз орналасқан жатырға бағытталады. Осыған байланысты миға және басқа ағзаларға кейде қажетті мөлшерде қан жетпей қалуы мүмкін. Мұндай жағдайда ағзаңыз қанға деген кенет қажеттілікті өтей алмай, бас айналу немесе естен тану орын алуы ықтимал. Орныңыздан тым жылдам әрі күрт тұрмау, шалқаңыздан жатпау, аш әрі шөлдеп жүрмеу және қаназдық болса, тиісті ем қабылдау осы кезеңдегі бас айналу мен естен танудың алдын алуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Іш тұсының қышуын азайту үшін табиғи майлармен массаж жасауды ұмытпаңыз. Беліңіз ауырмауы үшін бір қалыпта ұзақ отырмауға тырысыңыз. Сұйықтықты мол ішу Сіздің де, бөпеңіздің де зат алмасуы үшін өте маңызды. Келесі аптада бізді бұдан да үлкен тосынсыйлар күтеді!') WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпенің серігі саналатын плацента бөпеңізбен бірге өсуін жалғастырады. Жүктіліктің алғашқы апталарында жасушалар тобы бөпеңізді қалыптастыру үшін бөліне бастағанда, олардың кейбірі плацентаны түзетін жасушаларға айнала бастайды. Бөпе амниотикалық қапшықтың ішінде өсіп жатқанда, онымен қалыптасып келе жатқан кіндік бауы арқылы байланысқан плацента да дамуын жалғастырады. Жүктілігіңіздің 4-ші аптасына жеткенде, ағзада деңгейі жоғарылай бастайтын жүктілік гормондары бөпенің ғана емес, плацентаның да дамуын қолдайды, осылайша қапшық ішінде бөпе мен плацента қатар өседі. Плацента — жүктілік бойы Сіз бен бөпеңіздің арасындағы қоректік заттар алмасуын қамтамасыз ететін, жатырда бөпеңізбен бірге өсетін және бөпе дүниеге келгеннен кейін ағзадан шығып, өз қызметін аяқтайтын уақытша мүше. Жүктіліктің едәуір бөлігінде бөпеңізбен шамалас болатын бұл мүше соңғы апталарда орта есеппен 20-25 см көлемге, 2-3 см қалыңдыққа және 500 грамм салмаққа жетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Көбелектің қалықтауы! 🦋 Anacan, мені сезіп тұрсың ба? Мен мұнда аунап, сальто жасап жүрмін! Кейбір аналар мұны «ішімде көбелек ұшып жүргендей» немесе «балық жүзіп жүргендей» деп сипаттайды. Егер әлі сезбесең, мұңайма, мен әлі кішкентаймын, ал қимылдарым әлсіз. Бірақ көп ұзамай сені бір тепкенімде, бірден түсінетін боласың!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жүрек-қантамыр жүйесінің, яғни жүрек пен қан тамырларының саулығы өте маңызды. Сондықтан дәрігеріңіз қандай да бір қарсы көрсетілім анықтамаса, мамандар жүктілік кезінде дене жаттығуларын жасауға кеңес береді. Жүктілік кезінде жаттығу жасау белдің ауыруы, аяқтың құрысуы және шаршау секілді жиі кездесетін шағымдарды жеңілдетіп, күш-қуатыңызды арттырады. Сондай-ақ жаттығу гестациялық қант диабеті мен жоғары қан қысымының қаупін азайтады. Босанғаннан кейінгі депрессияның туындау ықтималдығын едәуір төмендетеді. Төзімділік пен бұлшықет күшін арттырып, босану үдерісін жеңілдетеді. Жаттығудың арқасында нығайған іш пен бел бұлшықеттері жүктілік кезінде кездесетін ауырсынуларды азайтады. Денені жүйелі түрде созу (stretching) кернеу жиналған тұстарды анықтап, ауырған бұлшықеттерді босаңсытуға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кешке тыныш бөлмеде жатып, қолыңызды ішіңізге қойып, зейініңізді шоғырландырыңыз. Кейде қимылды сезіну үшін тыныштық пен зейін қоюдың өзі жеткілікті. Тәтті нәрсе жеу бөпені қимылдатуы мүмкін.') WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің терісі қалыңдай түссе де, бұл кезеңде әлі де мөлдір болып көрінеді. Осы мөлдірліктің арқасында бөпеңізді көре алсаңыз, жұқа терісінің астынан қан тамырларын, қаңқасы мен мүшелерін байқар едіңіз. Бөпеңіздің көзді жыпылықтату рефлексі дамуын жалғастыруда. Қабақтары минутына орта есеппен 15-20 рет жыпылықтайды, ал тәулігіне бұл көрсеткіш шамамен 30 мыңға жетеді.Көзді жыпылықтату көз алмасын қорғап қана қоймай, көздің іші мен мөлдір қабықтың үнемі жеткілікті ылғалды болуын қамтамасыз етеді. Сондай-ақ қабақтар ұйқы кезінде оттегін ала алмайтын көздің сыртқы қабатын қоректендіреді. Бұл әрекет еріксіз орындалады және соның арқасында көздер қарқынды жарық пен бөгде заттардан қорғалады. Қабақ жабылған кезде жас бездерінен бөлінген сұйықтық бүкіл көз алмасын ылғалдандырып, көздің құрғауына және тітіркендіргіш заттардың зақым келтіруіне жол бермейді. Сонымен қатар қозғалыс кезінде көздің белгілі бір нүктеге назар аударуына көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Тер бездерім пайда болып жатыр! 💦 Менің терім әлі дамып келеді, енді тер бездерім қалыптаса бастады. Әрине, судың ішінде терлемеймін, бірақ дүниеге келгеннен кейін дене қызуымды реттеу үшін олар маған өте қажет болады. Мұның бәрі — болашақ өміріме дайындық. Сенің ағзаң қандай керемет мектеп!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіз үлкейген сайын оның терісі қышып, жіңішке сызықтар түріндегі созылу белгілері пайда бола бастауы мүмкін. Жүктіліктің белгілі бір кезеңінде кеуде, бөксе және іш аймағында қызғылт, күлгін немесе қызыл түсті, сәл ойыңқы әрі қышитын сызықтар пайда болуы ықтимал. Бұл сызықтар тері астындағы тірек тін қабаттарының шамадан тыс созылуынан туындайтын ұсақ жыртылулар болып табылады. Созылу белгілерінің пайда болуына әсер ететін ең маңызды фактор — генетикалық ерекшелігіңіз. Генетикадан бөлек, дене салмағының кенеттен және шамадан тыс артуы да іштегі созылу белгілерінің қауіп факторына жатады. Іштің тез өсуі теріні керіп, оның серпімділігін төмендетеді, соның салдарынан созылу белгілері пайда болуы мүмкін. Сондықтан дене салмағын бірқалыпты және ұсынылған шекте қосу олардың алдын алу үшін өте маңызды. Созылу белгілерінің пайда болуына жол бермеу немесе санын азайту үшін терінің ылғалдылығын сақтау, салмақты бірқалыпты қосу, мол су ішу, дұрыс тамақтану және жүйелі түрде жаттығу қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бас айналудың алдын алу үшін отырған немесе жатқан жеріңізден асықпай тұрыңыз. Сұйықтықты мол ішу күш-қуатыңызды сақтап қана қоймай, қағанақ суының жаңаруына да көмектеседі. Кальцийге қажеттілігіңіз артатындықтан, ас мәзіріңізде сүзбе мен айран сияқты өнімдерге басымдық беріңіз. Күнді баяу серуенмен аяқтау Сіздің де, бөпеңіздің де жайлылығына көмектеседі.') WHERE id = '011238e0-e01a-4bb0-b882-82b96d90dc82';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ішіңізде анда-санда кішкентай қимылдарды сезесіз бе? Бұл, сірә, бөпеңіз шығар! 😊Сүйектері мен бұлшықеттері жеткілікті дамып, әжептәуір күшейген бөпеңіздің қимылдарын енді сезе бастауыңыз мүмкін. Осы кезеңнен кейін бөпеңіз Сіз сезе алатындай күштірек қимылдайды. Сонымен қатар жатырдың ұлғаюы мен қағанақ суы көлемінің артуының арқасында оның қозғалуына жеткілікті кеңістік бар. Жүктіліктің осы кезеңінде бөпеңіздің жатыр қабырғасына бір секундтан артық жанасатын қимылдарын сезуге болады. Жақсы дамыған сүйектері мен бұлшықеттерінің арқасында бөпеңіз бұрынғыдан да белсенді. Ол барлық бұлшықеттерін қозғалтып, оларды одан әрі дамытуда. Егер бөпеңізді әлі сезбесеңіз, алаңдаудың қажеті жоқ. Жақын арада сезе бастайсыз. Бөпенің қимылдарын кеш сезінуге алғашқы жүктілікте іш бұлшықеттерінің тығыз болуы, кіндік тұсындағы май қабатының жұмсартқыш қызметін атқаруы және қағанақ суының мөлшері қажетті деңгейден артық болуы себеп болуы мүмкін. Жүкті әйелдердің 90%-і бөпесінің қимылдарын 16-22-ші апталар аралығында сезеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен «ірімшікке» оранып жатырмын! 🧀 Күлкілі естіледі, бірақ менің терімде ақ түсті, крем тәрізді зат түзіле бастады. Оны «Верникс» (Vernix Caseosa) деп атайды. Бұл зат менің жұқа терімді суда жібіп кетуден қорғайды. Егер верникс болмаса, суда ұзақ жатқандықтан терім қатпар-қатпар болып кетер еді. Бұл — менің табиғи ылғалдандырғышым.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде плацента мен жатырда прогестерон көп мөлшерде өндіріледі. Соның салдарынан қандағы прогестерон гормонының жоғары деңгейі асқазанның жиырылуы мен перистальтикасын баяулатып, асқазан мен өңеш арасындағы қақпақшаның босаңсуына әкеледі. Нәтижесінде асқазан қышқылы өңешке өтіп, қыжыл пайда болады. Майлы немесе ащы тағамдар мен кофеині бар сусындарды тұтынбау, газдалған сусындардың орнына су ішу, дайын тағамдардан, кетчуп пен тұздалған өнімдер секілді өңделген азық-түліктен бас тарту қыжылдың алдын алуға көмектеседі. Сондай-ақ тамақтануды ұйықтардан үш сағат бұрын аяқтауға тырысыңыз. Жатқан кезде асқазанның босаңсыған қақпақшасы арқылы асқазан қышқылы өңешке оңайырақ өтеді. Кешкі асты кеш ішсеңіз, одан кейін кемінде бір сағат жатпауға тырысыңыз. Бұған қоса, қыжылды жеңілдету үшін салқын сүт пен айран ішуге, түймедақ, жалбыз және зімбір шайын ішуге, аз-аздан әрі жиі тамақтануға және асты жақсылап шайнауға болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Шонданай жүйкесінің ауырсынуын жеңілдету үшін арнайы созылу жаттығуларын жасаңыз. Бір қалыпта ұзақ отырмаңыз. Жылы душ қабылдау немесе ауырған аймаққа жылы компресс қою бұлшықеттерді босаңсытуы мүмкін.') WHERE id = '3902a1df-6463-4c00-82b6-0534aaec9c0a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Көптен күткен апта келді! Осы аптадан бастап дәрігер тексеруі кезінде бөпеңіздің жынысын білуге дайын болыңыз. Жүктіліктің 16-аптасында сапалы ультрадыбыстық аппарат пен тәжірибелі дәрігер бөпеңіз қолайлы қалыпта жатса, оның жынысын 90% дәлдікпен анықтай алады. Бұл кезеңде қыз және ұл бөпелердің жыныс мүшелері ультрадыбыстық зерттеуде бір-бірінен ажыратуға болатындай деңгейде дамып үлгерген. Ұл бөпелердегі осы кезеңнің басты жаңалығы — бұған дейін құрсақ қуысында орналасқан аталық бездер ұмаға қарай түсе бастайды.;;;
Кейде диагноз қою кезінде қателіктер болуы мүмкін. Мысалы: Қыз бөпелерде: Кіндік бауы кейбір бұрыштан қарағанда ұл баланың жыныс мүшесіне ұқсап көрінуі мүмкін. Ұл бөпелерде: Аталық бездер ұмаға әлі толық түспесе, оны қыз бөпемен шатастыруы мүмкін. Дәл осы себепті дәрігерлер бөпені бірнеше түрлі қалыптан қарап тексеруге тырысады. Егер дәрігеріңіз нақты айтпай, тек болжам жасаса, көп зат сатып алуға кіріспес бұрын егжей-тегжейлі ультрадыбыстық зерттеуді (әдетте 18-22-апталарда) күткен дұрыс.'), baby_message_kk = COALESCE(baby_message_kk, '16 АПТА АЯҚТАЛДЫ! 🥑 Менің көлемім авокадодай! Мен үшін ең маңызды жаңалық: қан айналымым керемет жұмыс істеп тұр. Кішкентай жүрегім күн сайын бірнеше литр қан айдайды. Мен өсіп, күш жинап, Сізбен кездесетін күнімді күтіп жүрмін. Сіз менің бүкіл әлемімсіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Авокадо'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қуықтың үстінде орналасқан жатырдың қысымы мен гормондық өзгерістерге байланысты жиі зәр шығарғыңыз келуі мүмкін. Алайда сонымен қатар зәр шығарғанда ашыту, шаншу, шап тұсында қысым мен ауырсыну сезілсе және зәріңіздің түсі күңгірттенсе, несеп жолдарының инфекциясына күмәндануға болады. Несеп жолдарының инфекциясын көбіне ішектен түсетін бактериялар тудырады. Жыныс аймағына дұрыс әрі жеткілікті күтім жасамау, қорғанышсыз жыныстық қатынас, иммундық жүйені әлсірететін аурулар, болашақ анада қант диабетінің болуы, бүйректің құрылымдық аурулары, бүйректе тастың болуы және бұрын несеп-жыныс жүйесіне жасалған операциялар да жүктілік кезінде бұл мәселенің туындау жиілігін арттыруы мүмкін. Несеп жолдарының инфекциясын ерте анықтау маңызды. Өйткені инфекция асқынып, бүйректеріңізде белгілі бір асқынулар туғызуы мүмкін. Дене қызуының қатты көтерілуі жатырдың мерзімінен бұрын жиырылуына, соның салдарынан түсікке, тіпті мерзімінен бұрын босануға әкелуі мүмкін. Жүктілік кезінде күніне кемінде 2 литр су ішу және сұйықтық мөлшерін арттыру несеп жолдарындағы ағынды жылдамдатып, оларды тазартуға көмектеседі. Сондай-ақ пробиотиктерге бай йогурт пен айран сияқты өнімдерді тұтыну микрофлораны нығайтып, иммундық жүйені белсендіру арқылы инфекцияларға бейімділікті азайтуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Сіз жүктіліктің ең тамаша кезеңдерінің біріндесіз, сондықтан әр сәттен ләззат алыңыз. Бір қырыңызбен жатуды жалғастырыңыз және қаназдықтың алдын алу үшін рационыңызға темірге бай тағамдарды қосыңыз. Терідегі созылу белгілеріне қарсы оны үнемі ылғалдандыруды ұмытпаңыз. Келесі аптада бөпенің есту қабілеті одан әрі жетіле түседі!') WHERE id = '4db5e35d-0bef-4624-aa7c-2dbb50189eef';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз қазір авокадоның көлеміндей болды. Алдағы бірнеше апта ол үшін қарқынды даму кезеңі болмақ; салмағы да, бойы да шамамен екі есе артады. ;;;
Осы аптада ультрадыбыстық зерттеу кезінде бөпеңізді шалқасынан жатқан күйде көру ықтималдығы жоғары. Оның омыртқасы мен арқа бұлшықеттері айтарлықтай күшейді, сондықтан ол басы мен мойнын тік ұстай алады. Ал аяқтары алдыңғы апталармен салыстырғанда ұзарып, денесіне сай пропорцияға келе бастады.;;;
Бөпеңіздің бет қимылдары да алуан түрлі бола түсуде: енді ол қабағын түйе алады және қабақтары жабық болса да, көз алмаларын қозғалта алады.;;;
Ең қуанышты жаңалықтардың бірі — бөпеңіздің ести бастауы. Ішкі құлақ құрылымы дамығандықтан, ол енді дыбыстарды қабылдайды. Оның алғашқы еститін дыбыстары Сіздің денеңізден шығады: жүрек соғысыңыз, тыныс алуыңыз және ішектеріңіздің қозғалысы. Жақында оның миы бұл дыбыстарды тереңірек талдап, Сіздің даусыңызды сырттан келетін басқа дыбыстардан ажыратуды үйренеді. Сондықтан онымен қазірден бастап сөйлесіп, ән айта беруіңізге болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Май қабатын жинап жатырмын! 🧈 Осы уақытқа дейін өте арық болдым, терім сүйектерімнің үстінде бос жатты. Ал қазір "қоңыр май" деп аталатын ерекше май қабатын жинай бастадым. Бұл май мені жылы ұстап, қуат береді. Біртіндеп сүйкімді, томпақ бөпенің кейпіне еніп келемін. Сіздің құшағыңызға барғанда жұмсақ болғым келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Авокадо'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде өз денсаулығыңыз, бөпеңіздің дамуы және терідегі кемшіліктерді азайту үшін С дәруменіне деген күнделікті қажеттілігіңіздің өтелетініне көз жеткізуіңіз керек. С дәруменінің антиоксиданттық қасиеті инфекциялармен күресіп, иммундық жүйе сезімтал болатын жүктілік кезеңінде ағзаңызды токсиндерден қорғайды. Ол тіндердің қалпына келуі, жаралардың жазылуы, терінің серпімділігін арттырып, созылу белгілерінің пайда болуының алдын алу, сүйектердің өсуі мен қалпына келуі үшін, сондай-ақ сау теріге қажетті әрі шеміршек, сүйек, сіңір және тері құрамында болатын құрылымдық ақуыз — коллагеннің түзілуі үшін аса маңызды. С дәрумені ағзаңызға қажетті темірдің сіңуіне көмектесуімен де маңызды. Соның арқасында гемоглобин деңгейін қалыпты ұстап, Сізді қаназдықтан қорғайды. Бұған қоса, ол бөпеңіздің тіндерінің қалыптасуына көмектесіп, плацентаның қан тамырларын нығайтады; осылайша шаранаға көбірек оттегі жеткізіп, плацентаның мерзімінен бұрын ажырау қаупін азайтады. С дәрумені іш қатуға қарсы да тамаша көмектесіп, ішектің қалыпты жұмыс істеуіне ықпал етеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Теріңізге күтім жасағанда құрамында "ретиноидтер" (А дәруменінің туындылары) немесе "салицил қышқылы" бар кремдерден аулақ болыңыз. Бұл заттар бөпеге зиян келтіруі мүмкін. Табиғи майларды немесе жүкті әйелдерге арналған косметиканы таңдаңыз.') WHERE id = '15cf9597-2ec2-4fe2-8400-f9a4938a8ee5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің 16-аптасында бөпеңіздің көздері қараңғылық пен күшті жарықты ажырата алатын деңгейге жетті. Алайда бұл айырмашылықты сезінуі үшін жарық өте айқын болуы керек. Себебі жатыр қабырғасы жарықтан мықты қорғайды. Қазір сырттан түсетін жарықтың тек 1%-і ғана бөпеңізге жетеді. Тағы бірнеше қызықты жайт: Қабақтары: Әзірге бөпеңіздің қабақтары бір-біріне жабысып тұр. Олар тек 20-аптаның ортасынан бастап ашылып-жұмыла бастайды. Күн мен түннің айырмашылығы: Алдағы апталарда ішіңіздің терісі созылып, жұқарған сайын ішке көбірек жарық түседі. Бұл бөпеңіздің күн мен түнді ажыратуына, тіпті жарық көзіне қарай бұрылуына көмектеседі. Қарашықтың жарық рефлексі: 30-аптадан бастап бөпеңізде қарашық рефлексі пайда болады. Көздің түрлі түсті бөлігі — нұрлы қабықтағы бұлшықеттер жарыққа жауап береді: жарық күшті болғанда қарашық кішірейеді, ал жарық аз болса, үлкейеді. Бұл — көзді қорғап, көруді реттейтін ғажайып механизм.'), baby_message_kk = COALESCE(baby_message_kk, 'Кіндік бауым жуандап келеді! 🔌 Бұл — менің өмірмен байланыстыратын арнам. Сізден маған келетін қоректік заттар мен оттегі осы "кабель" арқылы өтеді. Қазір ол жуандап, берік болды, ішінен көп қан өтеді. Кейде оны қолыммен ұстап ойнаймын, бірақ алаңдамаңыз, мен оны қысып, қан ағынын тоқтата алмаймын, өйткені ол өте иілгіш әрі тайғанақ.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Жатырыңызда өсіп келе жатқан бөпеңіздің дамуы үшін енді шалқасынан жатпағаныңыз дұрыс. Бөпеңізге қанның еркін баруы үшін сол қырыңызбен жатуыңыз керек. Шалқасынан жатқанда денеңіздің бүкіл салмағы омыртқа мен арқа бұлшықеттеріне түседі. Бұл тамырларға қосымша қысым түсіріп, бөпеңізге баратын қан ағынын азайтады. Жүктілік кезінде сол қырыңызбен жатып, тізеңізді бүгіп, аяқтарыңыздың арасына жастық қою — бөпеңіз үшін ең қолайлы ұйықтау қалпы. Бұл қалып бүйректеріңіздің қалыпты жұмыс істеуіне көмектесіп, денеңізде, әсіресе қолдарыңыз бен тізелеріңізде пайда болуы мүмкін ісінуді азайтады. Ұйқыңыз жайлы болуы үшін осы кезеңде жүкті әйелдерге арналған жастықты қолдану да пайдалы болуы мүмкін. Салауатты әрі ұзақ ұйықтау үшін кофе, шай және кола сияқты құрамында кофеин бар сусындарды рационыңыздан алып тастағаныңыз жөн. Күндіз жеткілікті мөлшерде сұйықтық ішіп, ұйықтардан 2-3 сағат бұрын сұйықтық ішуді тоқтатып, ауыр тағамдардан бас тартуыңыз керек. Бұған қоса, тұрақты жаттығу жасау, ұйықтар алдында жылы душ қабылдау және сүт ішу жақсы ұйықтауға айтарлықтай көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Көзіңіз құрғаса, күн ішінде жиі үзіліс жасап, экран алдында аз уақыт өткізіңіз. Кальцийге деген қажеттілігіңіз артқандықтан, рационыңызға күнжіт, ірімшік және жасыл жапырақты көкөністерді міндетті түрде қосыңыз. Беліңіз сәл тартылса, отырған орныңызда иықтарыңызды артқа тартып, жеңіл қимылдар жасаңыз. Біз күн сайын біртіндеп өсіп келеміз!') WHERE id = 'c27b671d-4d70-44eb-80ea-7aedfd97f434';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізді 9 ай бойы көтеріп жүретін жатырыңыз осы аптадан бастап кіндігіңіздің дәл астында орналасады. Жүктіліктің басында орта есеппен 60 грамм болған жатырыңыздың салмағы осы кезеңде 250 грамға жетті. Бұл аптада жатырдың ішінде, бөпеңіз жатқан қағанақ қабында орта есеппен 100 мл амниотикалық сұйықтық бар. Бұл шамамен 10 ас қасық суға тең. Бұл сұйықтық бөпеңіз үшін тұрақты температураны сақтайтын орта қалыптастырады және оны механикалық жарақаттар мен сыртқы әсерлерден қорғайтын жастықша қызметін атқарады. Сондай-ақ бактерияға қарсы қасиетінің арқасында бөпеңіздің айналасында стерильді орта қалыптастырып, оны инфекциялардан қорғайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Сізді естіп жатырмын, Анашым! 🗣️ Енді құлақтарым толық жұмыс істей бастады. Сіздің сөйлегеніңіз, күлкіңіз, тіпті айтқан әндеріңіз де маған жетеді. Дыбыс бәсең естілсе де (су астындағыдай), дауыс ырғағыңызды түсінемін. Маған «Сізді жақсы көремін» деп жиі айтыңызшы, мен осы сөзді жаттап алғым келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы апталарында жатырдың өсе бастауы мен қан айналымының күшеюіне байланысты пайда болатын шап тұсындағы ауырсыну кейінгі апталарда салмақтың артуы және жатырды ұстап тұратын байламдардың созылуы салдарынан туындауы мүмкін. Сонымен қатар жүктілік кезінде ағзаңыз релаксин деп аталатын гормон бөледі. Релаксин байламдарды байланыстыратын тығыз тіндерді жұмсартады. Соның әсерінен жүктілік кезінде жамбас пен шап аймағындағы буындар қозғалғыш бола түседі. Жүктіліктің екінші триместрінде бөпеңіз өскен сайын жатырыңызды ұстап тұратын жұмыр байламдар созыла бастайды, бұл да шап тұсындағы ауырсынуға себеп болуы мүмкін. Мұндай ауырсынудың алдын алу үшін өзіңізді шаршатпай, мүмкіндігінше белсенді болыңыз және күнделікті істер кезінде оқыс қимылдардан аулақ болыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бөпеңізбен сөйлесіңіз! Оған кітап оқып, күніңіздің қалай өткенін айтып беріңіз. Бұл араларыңыздағы эмоциялық байланысты нығайтады. Зерттеулер бөпелердің дүниеге келгеннен кейін ана құрсағында естіген дауыстар мен әндерді танитынын көрсетеді.') WHERE id = '16510ace-04bb-4c83-9c44-82e27d7b140c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз осы аптада дүниеге келетін күніне дайындалуын жалғастыруда. Қазір ол жаттықтырып жүрген ең маңызды дағдылар — ему және жұту рефлекстері! Ол Сіз беретін алғашқы жұтым сүтке дайындалып жатыр. Жұту — бөпеңізде дамитын алғашқы рефлекстік механизмдердің бірі. Бұл үстіңгі еріннің қалыптасуы аяқталып, қызмет атқара бастауы және соның арқасында ауыздың жабылуы арқылы басталады.;;;
Жұту іске қосылғаннан кейін ему инстинкті түрде дамиды. Яғни бұл екі рефлекс қызметі жағынан бірінен кейін бірі қалыптасады. Бөпеңіздің қазірдің өзінде жасап жатқан бұл қарқынды жаттығуы тек 32-ші аптаға қарай толық жетіледі.;;;
Осы кезеңде амниотикалық сұйықтықты жұтуды үйренген бөпеңіз тыныс алу қызметі секілді, дүниеге келгенде бәрі дайын болуы үшін жаттығып жатыр. Соның арқасында бөпеңіз дүниеге келген кезде омырауыңыздағы сүтті еме алатындай жетілген жұту дағдысына ие болады. Сілекей мөлшеріне байланысты жұту рефлексі сергек кезде шамамен минутына екі рет, ал ұйқы кезінде шамамен минутына бір рет іске қосылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Қолдарым бір сәт те бос тұрмайды! ✊ Менің ұстау рефлексім өте күшті. Қолдарымды жұдырық етіп түйіп, саусақтарымды қимылдатамын. Кейде кіндік бауымды, кейде екінші қолымды ұстаймын. Бұл қимылдар саусақтарымды күшейтеді. Дүниеге келгенде Сіздің саусағыңызды қатты ұстайтыным сонша, таңғалатын боласыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Жатырыңыз кіндік деңгейіне жетуге жақын, оны қазірдің өзінде қолыңызбен сезе аласыз. Осы аптадан бастап бөпеңіз алдыңғы апталарға қарағанда жылдамырақ салмақ қосып, қарқынды дами бастайтындықтан, Сіздің де салмағыңыз сәл тезірек өсуі ықтимал. Осы кезеңге дейін орта есеппен 2.5-5 кг салмақ қосуыңыз керек. Кейбір болашақ аналардың іші жүктілік мерзіміне қарағанда үлкенірек немесе кішірек болуы мүмкін. Бұған көбіне ішекте жиналған газ немесе терінің тығыздығы себеп болады.;;;
Осы аптаның соңына дейін үштік скринингтен өтуіңіз керек. Кейбір зертханалар қолданатын компьютерлік бағдарламалардың көмегімен үштік тест нәтижесін 20-шы аптаға дейін, тіпті одан кейін де бағалай алса да, ықтимал қауіпті ертерек анықтаған пайдалы. Кейбір дәрігерлер 11-14-ші апталар аралығында жасалған қосарлы тест төмен қауіп көрсетсе, үштік тест өткізуді міндетті деп санамайды. Ал басқа дәрігерлер қосарлы тесті де, үштік тесті де жасауды ұсынуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Сіз жүктіліктің ең жайлы кезеңдерінің біріндесіз, сондықтан өзіңізге уақыт бөліңіз. Қан айналымы Сізге де, бөпеңізге де оңтайлы болуы үшін сол қырыңызбен жатуды әдетке айналдырыңыз. Сұйықтықты жеткілікті ішіп, кальцийге бай тағамдарды тұтынуды жалғастырыңыз. Келесі аптада бөпеңіздің қимылдарын анығырақ сезіну мүмкіндігіңіз артады!') WHERE id = '0f424a2a-4630-431c-9be8-af0ad1977c5a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесі жан-жақты дамып, өз қызметін атқаруға дайындалуын жалғастыруда. Өкпесі көмірқышқыл газы мен оттегінің алмасуын қамтамасыз ете алатын деңгейге әлі жетпесе де, бөпеңіз дүниеге келгенде тыныс алуына қажетті қызметті атқара алатындай қалыптасқан. Әзірге бұл тыныс алу қимылдары бөпеңізді қоршап тұрған амниотикалық сұйықтықтың ішінде орындалады.;;;
Бөпеңіздің дүниеге келген сәттегі алғашқы демі өміріндегі ең қиын тыныс болады. Себебі суға толы тыныс алу жүйесіндегі сұйықтықтың орнын ауа басуы керек.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім қатайып келеді! 🦴 Бұрын қаңқам резеңке секілді жұмсақ шеміршектен тұратын, ал қазір ол нағыз сүйекке айналып жатыр (оссификация). Енді мен әлдеқайда мықтымын. Қабырғаларым, омыртқам және аяқ сүйектерім қатайып келеді. Мен енді кішкентай желе емеспін, мен мықты ұлмын (немесе қызбын)!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Алмұрт'), body_changes_kk = COALESCE(body_changes_kk, 'Егер Сізде жүктілікке дейін қант диабеті болса, жүктілік кезінде ерекше мұқият болуыңыз керек. Жүктілік барысында қандағы қант деңгейін бақылауда ұстау жүктілікке дейінгі кезеңмен салыстырғанда қиынырақ болуы мүмкін. Сондай-ақ инсулин дозасын өзгерту қажет болуы ықтимал. Мұндай жағдайда дәрігер тексеруінен жиірек өтесіз.;;;
Қант диабеті — қандағы қант деңгейінің жоғарылауына әкелетін ауру. Бұрын қант диабеті болмаған күннің өзінде, жүктілік кезінде гестациялық диабет деп аталатын жүктілік диабеті пайда болуы мүмкін. Жүктіліктің 24-28-ші апталарында қант сынамасы ретінде белгілі глюкозалық жүктеме тесті арқылы скрининг жүргізіледі. Нәтижелер 50-75-100 грамдық пероральді глюкоза тесті арқылы нақтыланып, нақты диагноз қойылады. Шамамен әрбір 150 жүктіліктің бірінде жүктілікке байланысты қант диабеті дамуы мүмкін. Егер Сізде шөлдеу, салмақ жоғалту, шамадан тыс тамақ жеуге қажеттілік, әдеттегіден көп су ішу және жиі зәр шығару, үнемі шаршау сияқты белгілер болса, дәрігеріңізбен кеңесіңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кенеттен бас айналмас үшін жатқан жеріңізден тұрарда алдымен отырып, содан кейін баяу орныңыздан тұрыңыз. Арқа мен белдің ауырсынуына жеңіл пренаталдық йога немесе серуендеу өте пайдалы. Темір мен кальцийді жеткілікті қабылдауға ерекше назар аударыңыз. Бүгін бөпеңізге ертегі оқып немесе онымен болашақ жоспарларыңыз туралы сөйлесіп көрсеңіз қайтеді?') WHERE id = 'ae23805e-1ec4-470c-a370-e36eb29268eb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Май тіні тері астына және ішкі ағзалардың айналасына жиналады. Бұл май қабаты энергия қоры қызметін атқарады. Ұрықтың жүрек соғысын ми реттей бастайды, сондықтан ол бірқалыптырақ болады (минутына 140-150 рет). Қанайналым жүйесі толық қуатымен жұмыс істейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен «толысып келемін», Anacan! 🧸 Денемде май тіні жинала береді. Бұрын өте арық едім, ал қазір қолдарым мен аяқтарым толыса бастады. Бұл май қабаты маған өте қажет, өйткені дүниеге келгенде дене қызуымды реттеуге көмектеседі. Мен үшін алаңдама, мұнда маған жылы әрі қарным тоқ. Сіз тек пайдалы тағамдармен тамақтаныңыз, қалғанын өзім реттеймін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен пияз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы кезеңінде физикалық және психологиялық тұрғыдан көптеген өзгерісті сезінуіңіз мүмкін. Қан ағымының артуына байланысты қынаптық бөлінді, тер, шырыш және басқа да сұйықтықтар көбейеді. Ерекше түстер көруіңізге гормондар, көңіл күйіңіз бен алдағы күндерге қатысты ойларыңыз себеп болуы мүмкін. Жүктілік кезінде өзіңізге немесе бөпеңізге зиян келтіріп аламын деп қорқып, дене жаттығуларын жасаудан тартынуыңыз ықтимал. Алайда дұрыс таңдалған жаттығулар босануды жеңілдетіп қана қоймай, бөпенің денсаулығына да оң әсер етеді. Осы кезеңде омыртқаңызды нығайтатын арқа мен белге арналған жаттығуларды жүйелі түрде орындай аласыз. Жүктілерге арналған йога мен пилатес те жүктіліктің алғашқы апталарынан бастап ұсынылады. Аптасына 3-5 күн жасалатын 30 минуттық қарқынды серуен жүктілік кезінде өте пайдалы. Дегенмен мұның бәрін өзіңізді шаршатпайтындай етіп жасауыңыз керек. Егер жаттығуды ұнатпасаңыз, қимыл-қозғалыс үшін билеуге болады. Жүктілік кезінде билеу денеңізді нығайтып, икемділігіңізді арттырады, күйзеліс деңгейін төмендетіп, көңіл күйіңізді жақсартады. Сондай-ақ бұл бөпеңізбен бірге көңіл көтеруді қазірден бастаудың тамаша тәсілі!'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кальцийге бай тағамдарды мәзіріңізге міндетті түрде қосыңыз. Сүт өнімдерін, брокколи, бадам және күнжіт жеңіз. Егер кальцийді жеткілікті мөлшерде қабылдамасаңыз, бөпе өзіне қажет кальцийді Сіздің сүйектеріңіз бен тістеріңізден алады.') WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің күн сайын ұзарып келе жатқан қол және аяқ саусақтарында саусақ іздері қалыптаса береді. Бөпеңіздің денесін құрайтын әрі оның қалыптасуына қатысатын әрбір жасушада ДНҚ молекуласы бар. Адамдардың ДНҚ-сы 99% ұқсас болғанымен, қалған 1% бөлігі бөпеңізді бірегей етеді.;;;
Саусақ ұшының терісіндегі әртүрлі иілімдерден құралған, көзге көрінетін бедерлердің өрнегі және терінің сыртқы қабатындағы осы бедерлер папиллярлық сызықтар деп аталады. Осындай құрылымның арқасында әр адамның саусақ ізі бірегей болады. Ешкімнің, тіпті бір жұмыртқалы егіздердің де саусақ іздері бірдей болмайды. Басқаша айтқанда, саусақ ізі — қолымыз тиген әр жерде қалатын, тек өзімізге ғана тән белгі. Саусақ ізіндегі сызықтар ауыр жарақаттар мен терең кесілген жерлер болмаса, өмір бойы өзгермейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен түс көре аламын! 💤 Anacan, ғалымдардың айтуынша, мен қазірдің өзінде «REM ұйқысы», яғни Rapid Eye Movement -Көздердің жылдам қозғалысы фазасына өте аламын. Бұл менің түс көре алатынымды білдіреді! Түсімде не көреді екенмін? Мүмкін, Сіздің даусыңызды еститін немесе жүзіңізді елестететін шығармын. Күннің көп бөлігінде ұйықтаймын, бірақ ояу кезімде өте белсендімін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен пияз'), body_changes_kk = COALESCE(body_changes_kk, 'Соңғы жылдары пилатес болашақ аналар жиі таңдайтын жаттығулардың біріне айналды. Ол денені босаңсытып қана қоймай, көңіл күйді жақсартады, арқа мен белдің ауыруының алдын алады және болашақ анаға өз денесін жақсырақ сезінуге көмектеседі. Пилатеспен осы саладағы білікті маманның жетекшілігімен айналысу маңызды. Жаттығулардың жүктілік кезеңіне сай таңдалуына ерекше назар аудару қажет.;;;
Йогадағы кейбір қалыптарды жүктілік кезінде мүлде жасауға болмайды. Сондықтан сабақты жүкті әйелдерге арналған йогадан тәжірибесі бар нұсқаушыдан ғана алғаныңыз жөн. Жүкті әйелдерге арналған йога топтарын зерттеп, өзіңізге ең қолайлысын таңдаңыз. ;;;
Бір тізеңізді жерге қойып, екінші аяғыңызды алға шығарыңыз да, төмен отырыңыз. Аяқтарыңыз бен жамбас аймағыңыздың созылғанын сезесіз. Содан кейін аяқтарыңызды ауыстырыңыз. Бұл жаттығу аяқтарыңызды нығайтады. Соның арқасында аяқтарыңыз үлкейген ішіңізді жеңілірек көтереді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ерекше түстерден қорықпаңыз, бұл — жүктіліктің қалыпты бөлігі. Ұйықтар алдында тыныштандыратын музыка тыңдау немесе кітап оқу миыңызды тынықтыруы мүмкін. Жатын бөлменің салқын болуына назар аударыңыз.') WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тіс эмалі қалыптаса бастады. Тістің құрылымына эмаль, дентин, цемент және тіс ұлпасы деп аталатын пульпа кіреді. Эмаль — адам ағзасындағы ең қатты зат. Ол тісті сыртынан қаптап, қорғаныш қабат қызметін атқарады.;;;
Осы кезеңде бөпеңіздің тіс эмалінің құрамына кіретін кальций тұздары тістің органикалық негізіне біртіндеп жиналып, кристалданады. Бұл үдеріс бөпеңіздің тістері шыққанға дейін жалғасады. Жүктілік кезінде қабылданатын кейбір дәрілер тіс эмалінің қалыптасуын баяулатуы мүмкін. Соның салдарынан тістерде сары, сұр немесе қоңыр түсті дақтар пайда болуы ықтимал. Кейде эмаль гипоплазиясы деп аталатын тіс эмалінің жеткіліксіз қалыптасуы немесе дамуының тежелуі де кездеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен дыбыстардан селк етемін! 🔊 Егер Сіз кенеттен түшкірсеңіз, есік қатты жабылса немесе қатты музыка ойнаса, мен орнымнан селк ете қаламын. Мұны «Моро рефлексі» деп атайды. Қолдарым мен аяқтарымды кенеттен жайып, қайта жинаймын. Есту қабілетім өте сезімтал болып қалды. Өтінемін, тыныш ортада болыңыз, қатты дыбыстар мені мазалайды.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен пияз'), body_changes_kk = COALESCE(body_changes_kk, 'Тыныс алу жаттығулары жүктілік кезіндегі дене қалпының бұзылуын түзетуге және белдің ауыруын азайтуға көмектеседі. Олар босану кезінде қажет болатын тыныс алу және босаңсу тәсілдерін үйретіп, іш пен шап аймағындағы бұлшықеттердің икемділігі мен күшін арттырады. Сізді босануға психологиялық тұрғыдан дайындайды, толғақ кезінде тынысыңызды бақылап, дұрыс күшенуге және босану барысында энергияңызды тиімді пайдалануға көмектеседі.;;;
Дұрыс тыныс алу қандағы оттегі деңгейін арттырып, ағзадан токсиндердің шығарылуына көмектеседі, жүйке жүйесі мен гормондардың жұмысын реттейді, иммунитетті нығайтады. Сондай-ақ жасушалардың жұмысын жақсартып, теріні сергітеді, зейін қоюды жеңілдетеді, есте сақтау қабілетін күшейтеді, түсіну мен қабылдауды жылдамдатады, шығармашылық және шапшаң ойлауды дамытады. Бұған қоса ұйқыны реттеп, оның сапасын арттырады және ойды тыныштандырады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер әлі сезбеген болсаңыз, осы күндері бөпенің алғашқы әлсіз қимылдарын байқау үшін тыныш жерде жатып, назарыңызды ішіңізге аударып көріңіз. Белдің ауыруын азайту үшін аласа өкшелі аяқ киім киіңіз. Кальцийге қажеттілігіңіз артқандықтан, мәзіріңіздегі сүт өнімдері мен жасыл көкөністердің мөлшерін көбейтіңіз. Бүгін өзіңізге шағын сыйлық сатып алыңыз!') WHERE id = '5dba3d5c-bb87-4502-8385-7f27405dc9b2';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '18 апталық бөпеңіздің осы кезеңінде ана мен бөпе арасындағы ең маңызды байланысты қамтамасыз ететін плацента толық жұмыс істейді. Ол бөпеңіздің дамуына қажетті қоректік заттар мен оттегін тікелей Сіздің қаныңыздан алып, оған жеткізеді. Плацентаның тағы бір өте қызықты әрі маңызды міндеті — қорғау қызметі. Қалыпты жағдайда ағзаңыз бөпені «бөгде дене» деп қабылдап, оған шабуыл жасауы мүмкін, алайда плацента тосқауыл қызметін атқарып, иммундық жасушаларыңыздың бөпеге зиян келтіруіне жол бермейді.;;;
Дәрігер тексеруінде анық көрінетін плацента 18-аптада көлемі жағынан бөпеңізбен шамалас болады. Осы кезеңнен кейін екеуі де өсуін жалғастырғанымен, бөпеңіз плацентаға қарағанда жылдамырақ өседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен есінеймін және ықылық атаймын! 🥱 Менің көкетті бұлшықетім өте белсенді жұмыс істейді. Мен жиі ықылық атаймын. Бұл саған оғаш көрінуі мүмкін, бірақ мен үшін өте пайдалы. Осылайша өкпем мен тыныс жолдарымды тазартамын. Ал шаршағанда тәтті есінеймін. Сен де менімен бірге демалшы, жарай ма?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Тәтті бұрыш'), body_changes_kk = COALESCE(body_changes_kk, 'Осы апта көптеген аналар үшін бөпенің қимылын сезіну тұрғысынан бетбұрыс кезеңі болады. Егер әлі сезбесеңіз, мұқият бақылаңыз: ішіңізде «газ көпіршігі» немесе «қанат қағысы» секілді жеңіл сезім пайда болуы мүмкін. Қан қысымыңыз әлі де төмен болуы ықтимал, сондықтан өзіңізді әлсіз сезінуіңіз мүмкін. Тәбетіңіз ең жоғары деңгейге жетуі ықтимал. Зат алмасуыңыз жылдамдап, ағзаңыз бөпе үшін қосымша энергияны қажет етеді. Алайда қыжыл тамақтан кейін мазалауы мүмкін. Жатыр асқазанға қысым түсіретіндіктен, үлкен порциямен тамақтану қиындайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан қысымыңызды бақылаңыз. Басыңыз жиі айналса, күні бойы жеткілікті мөлшерде сұйықтық ішіңіз және тұзды тағамдарды (айран, тұзды крекер) аз мөлшерде тұтынуға болады (егер дәрігеріңіз басқаша айтпаса).') WHERE id = '1343d008-0806-4770-8e2d-0452ed215751';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің денесінде май қабаты қалыптаса бастады. Бұл — оның өсуін жылдамдататын ең маңызды факторлардың бірі. Майлар негізгі үш түрге бөлінеді: қарапайым, күрделі және туынды майлар.;;;
Майлардың ең танымал түрі — холестерин тағам арқылы қабылданады немесе жасушалардың ішінде синтезделеді. Бұл үдерісте бауыр ең белсенді рөл атқарады. Майлар ағзада өте маңызды қызметтер атқарады: олар энергияның ең ірі көзі, ішкі ағзаларды қорғайды және денені суықтан сақтап, жылу түзеді.;;;
Сондай-ақ майлар A, D, E және K дәрумендерінің ағзаға сіңуіне көмектесетін тасымалдаушы қызметін атқарады. Бөпеңіздің май қабаты толық қалыптасқанда, бұл майлардың 90%-ы тері астына жиналады. Қалған бөлігі құрсақ қуысында, бұлшықет талшықтарының арасында, сондай-ақ бүйрек, жүрек және бауыр секілді өмірлік маңызды ағзаларды қорғау үшін олардың айналасына орналасады.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақтарым және олардың іздері! 🧬 Anacan, менің саусақ іздерім толық қалыптасып болды. Бұл өрнектер өмір бойы өзгермейді. Мен бірегеймін! Қолдарым мен аяқтарымды да еркін қимылдата аламын. Кейде аяғымды айқастырып отырамын, ал кейде «жүземін». Мен үшін бұл жер — ең жайлы мекен.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Тәтті бұрыш'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіз бір күні үлкен, ал келесі күні кішкентай болып көрінсе, алаңдамаңыз. Ішіңіз әдеттегіден үлкенірек көрінетін күндері ішектің жұмысы біршама баяулап, газ жиналуы немесе кебу болуы мүмкін. Ультрадыбыстық зерттеудегі (УДЗ) өлшемдер жүктілік мерзіміне сай болса, ішіңіздің кішкентай немесе үлкен болуы маңызды емес. Бұл жағдай толығымен құрсақ бұлшықеттерінің құрылымына, дененің анатомиялық ерекшеліктеріне және ағзаның жүктілік кезіндегі өзгерістерге қалай жауап беретініне байланысты.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұзақ уақыт тік тұрып қалмауға тырысыңыз, себебі бұл белдің ауырсынуын күшейтуі мүмкін. Егер отырып жұмыс істесеңіз, әр сағат сайын орныңыздан тұрып, 5 минут жүріп қайтыңыз. Көзіңіз аздап құрғаса, дәрігермен кеңесіп, жасанды көз жасын қолдануға болады. Бөпеңіз қимылдарыңызды бұрынғыдан да анық сезеді, сондықтан онымен байланыс орнатуды жалғастырыңыз.') WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің сезім мүшелері қазірдің өзінде өте сезімтал. Зерттеулер бөпеңіз құрсақта жатқанда-ақ Сіздің даусыңызды басқа дыбыстардың бәрінен ажырата алатынын көрсетеді. Бөпелер ер адамның даусы мен төмен дыбыстарға қарағанда әйел даусы мен жоғары дыбыстарға көбірек жауап береді. Мұның себебі — жатыр қабырғасының дыбыс толқындарын әртүрлі өткізуі; осы кезеңде бөпе жоғары дыбыстарды анығырақ естиді. Бөпеңіз алғаш еститін дыбыстар — Сіздің денеңізден шығатын жүрек соғысы, қан айналымы және ағзалардың жұмыс істеу дыбыстары. Сезім мүшелері дамыған сайын, бөпеңіз сыртқы дыбыстарды қабылдап, жадында сақтай бастайды. Бір қызығы, туғаннан кейін шаңсорғыш, фен немесе ыдыс жуғыш машина секілді құрылғылардың дыбысын естігенде тынышталады, өйткені бұл дыбыстар оған құрсақтағы ортаны еске салады. «Ақ шу» (white noise) деп аталатын бұл дыбыстар, әсіресе шаншуы бар (колик) бөпелерді тыныштандырудың ең тиімді тәсілдерінің бірі.'), baby_message_kk = COALESCE(baby_message_kk, 'Жынысым анық! 🩷💙 Егер мен қыз болсам, жатырым мен жатыр түтіктерім қалыптасып, өз орнында тұр. Ал ұл болсам, жыныс мүшелерім анық көрінеді. Сен менің кім екенімді білесің бе? Әлде тосынсый ретінде сақтағың келе ме? Қалай болғанда да, мен сенің бөпеңмін және сені қатты жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Тәтті бұрыш'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің жартысына жуықтаған осы кезеңде қажетті мөлшерден артық салмақ қоссаңыз немесе салмағыңыз тым жылдам өсіп жатыр деп ойласаңыз, өзіңіздің де, бөпеңіздің де денсаулығы үшін мұқият болуыңыз керек. Жүктілікке дейін салмағы қалыпты болған әйелдердің күнделікті калорияға қажеттілігі небәрі 300 ккал-ға артады. Бұл орта есеппен 1900 бен 2500 ккал аралығын құрайды. Бұл көрсеткіш әр әйелде әртүрлі болады, ал қажетті мөлшерден артық калория тұтыну денсаулыққа зиянды салмақ қосуға әкеледі. Жүктілік кезінде салмақты бақылау үшін аз мөлшерде, бірақ жиі тамақтанған дұрыс. Негізгі ас аралығында жеңіл тағам жеу негізгі тамақтану кезінде шамадан тыс жеудің алдын алады. Темірге бай тағамдар жүктілік кезінде пайда болатын әлсіздікті азайтуға көмектеседі. Бұршақ, балық және майсыз ет тұтыну артық салмақ қосудың алдын алып қана қоймай, гипертония мен преэклампсия қаупін де азайтады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бел ауырсынуын жеңілдету үшін «жамбас сағаты» жаттығуын жасаңыз. Шалқаңыздан жатып, жамбасыңызды алға-артқа қозғалтыңыз. Бұл бел бұлшықеттерін босаңсытады. Сондай-ақ жүктілікке арналған тірек белбеу тағу беліңізге түсетін жүктемені азайтуы мүмкін.') WHERE id = '10652607-2e60-42fd-8695-4db1781a35b4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің денесі енді біркелкі әрі үйлесімді өсіп келеді. Сондықтан жүректің денеге айдайтын қан мөлшері белгілі бір деңгейде тұрақты сақталуға бейімделеді. Жасушалар жіктеліп, дамыған сайын өзіндік пішінге ие болатын жүректің дамуы ұрықтанудан кейінгі екі ай ішінде аяқталады. 60 күннің ішінде ол 4 қақпақшасы және 4 камерасы бар ағзаға айналып, бөпеңіздің бүкіл өмірі бойы жұмысын жалғастырады.;;;
Бұл кезеңде бөпеңіздің жүрегі минутына 140-160 рет соғады. 3 айлығында жүрек соғу жиілігі минутына 135-140, 6 айлығында минутына 130, 9 айлығында минутына 120-125, 12 айлығында 115-120, 24 айлығында минутына 115, 4 жасқа келгенде минутына 100, ал 15 жасқа келгенде шамамен 75-80 деңгейінде тұрақталады.;;;
Сондай-ақ осы кезеңде ультрадыбыстық зерттеу кезінде бөпенің жүрегінде тесіктер көрінуі мүмкін. Егер ата-анасы жақын туыс болмаса, жақын туыстарының арасында жүрек аномалиялары бар адам кездеспесе, жүктілік кезінде дәрі-дәрмектер бақылаусыз қолданылмаса, қызамық сияқты ауыр инфекциялар жұқпаса, Даун немесе Тернер синдромы анықталмаса және алкоголь қолданылмаса, бұл тесіктердің бөпе дүниеге келгенге дейін жабылу ықтималдығы 80% құрайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Кіндік бауыммен ойнап жатырмын! ➰ Менің ең сүйікті ойыншығым — кіндік бауым. Оны ұстаймын, қысамын, бұраймын. Бірақ қорықпаңыз, ол өте сырғанақ әрі берік, сондықтан мен оған зақым келтіре алмаймын. Бұл ойын менің ұстау рефлексім мен қол-көз үйлесімділігімді дамытады. Сіз немен айналысып жүрсіз? Мен мұнда мүлде жалықпаймын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен пияз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік варикоздың пайда болуына ықпал етеді. Өйткені бөпенің қажеттіліктерін қамтамасыз ету үшін қан көлемі едәуір артады. Соның салдарынан тамырлардағы қан мөлшері көбейіп, әсіресе аяқтарда қанның іркілуіне әкеледі. Жүктілік кезінде байқалатын варикоз көбіне жатырда өсіп келе жатқан бөпенің шап аймағындағы көктамырларға түсіретін қысымынан пайда болады.;;;
Теріде күлгін немесе көк түсті, жуандаған, өрмекші торына ұқсайтын тамырлар түрінде көрінетін варикоз асқынған сайын қатты ауырсыну, құрысу, аяқтың шаршауы, ысып және керіліп тұрғандай сезім қосылуы мүмкін. Қарапайым, бірақ маңызды бірнеше кеңеске мән беріп, оларды әдетке айналдыру варикоздың пайда болуының алдын алуға көмектеседі.;;;
Ұзақ уақыт бойы аяғыңызды айқастырып отырмауға тырысыңыз. Отырған кезде қан айналымын жақсарту үшін аяқтарыңызды қимылдатыңыз. Демалғанда аяқтарыңызды дене деңгейінен жоғары ұстаңыз. Ауыр зат көтермеңіз. Суды мол ішіп, тым тұзды тағамдарды тұтынбаңыз. Автокөлікті ұзақ уақыт жүргізбеңіз. Биік өкшелі аяқ киім кимеңіз. Арнайы компрессиялық шұлықтарды қолданыңыз. Шалқаңыздан емес, сол қырыңызбен жатыңыз. Тым ыстық суға шомылмаңыз және қатты тар киім кимеңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңізге түсетін салмақты азайту үшін тік отыруға тырысыңыз және ұзақ уақыт тік тұрып қалмаңыз. Кешке аяқтарыңызды жүрек деңгейінен сәл жоғары көтеріп, 15 минут демалу ісінуді азайтып, өзіңізді жеңіл сезінуге көмектеседі. Кальцийге қажеттілік артқандықтан, ас мәзіріңізге сүзбе, ірімшік немесе бадам сияқты тағамдарды қосыңыз. Күнді өзіңізге ұнайтын хоббимен аяқтаңыз.') WHERE id = '1282e899-e7f6-47fc-b213-e93601a67a84';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Дәрігер тексеруі кезінде бөпеңіздің сүйектерін біртұтас құрылым ретінде көргеніңізбен, қаңқа жүйесінің құрылысы өте күрделі. Ол тірі сүйек жасушалары — остеоциттерден және осы жасушалардың арасын толтырып, солар бөліп шығаратын жасушааралық заттан тұрады. Бұл заттың құрамында сүйекке қаттылық беретін кальций фосфаты, кальций карбонаты, магний фосфаты, сондай-ақ аз мөлшерде темір мен натрий сияқты минералдар бар.;;;
Сары сүйек кемігі, тығыз сүйек тіні, кемік сүйек тіні, сүйекқап, шеміршек және қан тамырлары сүйекті құрайтын құрылымдарға жатады. Шеміршек сүйектердің түйіскен жерлерінде орналасады. Жұмсақ құрылымының арқасында ол сүйектердің бір-біріне үйкеліп, мүжілуіне жол бермейді. Сонымен қатар сүйектің ұзарып өсуін қамтамасыз етеді. Ал қан тамырлары қанды сүйек жасушаларына жеткізеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім қатайып келеді! 🦴 Менің қаңқам күн сайын нығая түсуде. Кальций сүйектеріме жиналып, оларды қатайтады. Енді мен кішкентай резеңке адам емеспін. Қабырғаларым, омыртқам, аяқ сүйектерім... Бәрі нағыз сүйекке айналып келеді. Сіз ішкен сүт пен жеген ірімшік маған құрылыс материалы болып жетеді. Рақмет, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен пияз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде кейбір ауырсынулардың болуы қалыпты жағдай. Солардың бірі — аяқтың ауыруы. Оның ең айқын белгісі — аяқтың ісінуі. Балтыр да, табан да ісінуі мүмкін. Табанның ісінуі ауырсыну мен жайсыздық тудырады. Ісінудің бар-жоғын анықтау үшін тобықты саусақпен басып көруге болады. Кальций мен магний тапшылығы, артық салмақ қосу, аз қимылдау, қанның жүрекке қайтуының қиындауы, калий, магний және кальций деңгейінің төмен болуы ауырсынуды күшейтуі мүмкін. Аяғыңыз ауырса, мүмкіндігінше демалдырыңыз. Түнде бір қырыңызбен жатқан дұрыс. Салмақ қосу қарқынын бақылауда ұстаңыз. Ұйықтағанда аяқтарыңызды жоғары көтеру жеңілдік береді. Суық су ісінген бұлшықеттерді тыныштандырып, қан тамырларының тарылуына көмектеседі. Сондықтан салқын душ қабылдау және мұзды компресс жасау жақсы әсер етуі мүмкін. Бұған қоса, массаж бен дене жаттығулары да ауырсынуды жеңілдетеді. Денедегі ісінуді азайту үшін жеткілікті мөлшерде сұйықтық ішуді ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтың құрысуының алдын алу үшін магнийге бай тағамдарды тұтыныңыз. Ұйықтар алдында аяқ бұлшықеттерін созу және жылы душ қабылдау көмектесуі мүмкін.') WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миы құрсақта жатқан кезінде қажет мөлшерден көбірек нейрон түзеді. Ал туғаннан кейін қолданылмаған және жеткілікті ынталандырылмаған нейрондар «қырқу» деп аталатын үдеріс арқылы жойылады.;;;
Мидағы 100 миллиард нейронның әрқайсысы мыңдаған басқа нейронмен арнайы байланыс нүктелерін құрады. Екі-үш жасқа қарай бұл байланыстардың саны шамамен 15.000-ға жетеді. Ми тыныс алу мен жүрек соғуы сияқты өмірлік маңызды қызметтермен қатар, ойлау, есте сақтау және сөйлеу секілді жоғары функцияларды да реттейді.;;;
Бөпеңіз қолымен сезген әртүрлі бет, сезген әрбір иіс және естіген әрбір дыбыс осы жүйкелік байланыстардың қалыптасуына ықпал етеді. Ал бұл байланыстардың нығайып, тұрақты сақталуы сол тітіркендіргіштердің жүйелі түрде қайталануына байланысты.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, Anacan! Менің көлемім тәтті бұрыштай. Жүйкелерім дамып келеді. «Миелин» деп аталатын ерекше зат жүйкелерімді қоршап жатыр. Соның арқасында миымнан денеме жіберілетін хабарлар жылдамырақ жететін болады. Мен күн сайын ақылдырақ болып келемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Тәтті бұрыш'), body_changes_kk = COALESCE(body_changes_kk, 'Жүкті екеніңіз енді сырт көзге анық байқалады. Жүктілік кезінде жатыр бөпеге, плацентаға және қағанақ суына орын беру үшін үлкейеді, ал жүктіліктің соңына қарай оның салмағы шамамен 1100 qram болады. Бұл жатырдың қалыпты салмағынан шамамен 20 есе көп. Көлемі жағынан босануға жақындағанда шамамен 5 litr сыйдыра алатын деңгейге жетіп, қалыпты көлемінен 500-1000 есе ұлғаяды. Бұл өзгеріс жатырды құрайтын бірыңғай салалы бұлшықет жасушалары санының емес, көлемінің ұлғаюы есебінен жүреді.;;;
Жүктіліктің алғашқы айларында жатыр алмұрт тәрізді пішінін сақтайды, ал 12-ші аптаға қарай шар тәрізді болып, жамбас сүйектерінің үстіне көтеріледі. Осы аптадан кейін жатыр алдыңғы шат сүйегінің үстінен сезілетіндей көлемге жетеді. Келесі апталарда құрсақ қуысында жоғары қарай өсу үшін сопақша пішінге енеді. Өсуін жалғастырған сайын құрсақтың алдыңғы қабырғасына тіреліп, ішектерді екі жаққа және жоғары қарай ығыстырып, бауырға дейін көтеріледі.'), daily_tip_kk = COALESCE(daily_tip_kk, '18 апталық жолыңызды шағын серуенмен атап өтіңіз! Белдің ауырсынуын азайту үшін тік отыруға және ыңғайлы аяқ киім киюге тырысыңыз. Ұйықтағанда міндетті түрде сол қырыңызбен жатыңыз: бұл бөпеге баратын қан ағымына да, бүйректеріңіздің жұмысына да оң әсер етеді. Сұйықтықты мол ішіп, кальцийге бай өнімдерді (сүт, айран, бадам) тұтынуды ұмытпаңыз.') WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Егер бөпеңіз қыз болса, осы кезеңде оның аналық бездерінде жұмыртқа жасушалары түзіле бастайды. Дамудың бастапқы кезеңінде ұл эмбрионда да, қыз эмбрионда да екі жұп жыныс өзегі болады. Ұлдарда "мезонефриялық" өзектер ерлердің ұрпақ өрбіту жүйесін қалыптастырса, қыздарда "парамезонефриялық" өзектер әйелдердің ұрпақ өрбіту жүйесінің дамуын қамтамасыз етеді. Жыныс мүшелері ерекшелене бастаған кезде, қыз бөпелерде бұл өзектер жатыр мен қынапқа айналады. Бір қызығы, қыз бөпенің аналық бездерінде дүниеге келгенге дейін 2 миллионнан астам жұмыртқа жасушасы түзіледі. Бұл — оның бүкіл өміріндегі жұмыртқа жасушаларының ең көп саны.;;;
Жасөспірімдік кезеңге дейін бұл көрсеткіш шамамен 400,000–500,000-ға дейін азаяды. Ал ұрпақ өрбіту кезеңі басталғаннан кейін ай сайын шамамен 1000 жұмыртқа жасушасы жоғалады. Жас ұлғайған сайын жұмыртқа жасушаларының саны ғана емес, сапасы да өзгереді: мысалы, 30 жастағы әйелде әрбір 2-3 жұмыртқа жасушасының біреуі хромосомалық тұрғыдан қалыпты болса, 40 жаста бұл көрсеткіш әрбір 5-6 жұмыртқа жасушасының біреуіне дейін төмендейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүйкелерім жылдам жұмыс істеп жатыр! ⚡ Миымнан денеме баратын сигналдар енді "аса жылдам" жолмен беріледі. Миелин қабатының арқасында қимылдарымды жақсырақ басқара аламын. Енді ретсіз қимылдамаймын, белгілі бір мақсатпен жанасамын және бұрыламын. Миым алып компьютер секілді бағдарламаланып жатыр. Сіз менімен мақтана аласыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Тәтті бұрыш'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілікті мүлде салмақ қоспай немесе небәрі бірнеше килограмм ғана қосып аяқтау мүмкін де емес, дұрыс мақсат та болмайды. Жүктілік кезінде салмақтың артуы — табиғи құбылыс. Сіз аяқ басқан жүктіліктің екінші триместрі — бөпеңіз қарқынды өсіп, дами бастайтын кезең. Сондықтан дәл осы уақытта салмақ айтарлықтай қосыла бастайды. Бөпеңіз өскен сайын Сізден алатын қоректік заттар мен энергия мөлшері артады, сол себепті көбірек тамақтану қажеттілігі туындайды. Осылайша, жүктіліктің бұл кезеңінде аптасына шамамен 500 грамм салмақ қосу қалыпты деп есептеледі.;;;
Сосиска, салями және суджук сияқты өңделген ет өнімдерін дайындауда қолданылатын нитриттер мен нитраттар секілді қоспалар бөпенің денсаулығына зиян келтіруі мүмкін. ;;;
Көмірсуға бай тағамдар жүрек айнуын азайтады. Алайда ақ күріш пен макарон сияқты крахмалды өнімдер қандағы қант деңгейінің жоғарылауына әкеледі. Жүктілік кезінде дәрумендерді жеткілікті мөлшерде алу үшін жеміс тұтынуды арттыру өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Көруіңіз қатты бұлыңғырласа немесе көзіңіздің алдында "жарық жарқылдарын" байқасаңыз, дереу дәрігерге жүгініңіз. Бұл қан қысымының жоғарылауының белгісі болуы мүмкін. Ал көрудің аздап бұлыңғырлануы қалыпты жағдай.') WHERE id = '29db8583-08d7-4065-8fa7-18665ece5422';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Келесі бір айдың ішінде бөпеңіздің денесі верникс казеоза деп аталатын ерекше қабатпен жабыла бастайды. Бұл ақ түсті, крем тәрізді зат — бөпеңіздің ана құрсағындағы алғашқы қорғаныш қалқаны, ол бөпені алғаш шомылдырғанға дейін қорғайды.;;;
Зерттеулер верникстің құрамында иммунитетті қолдайтын 40-қа жуық түрлі ақуыз бар екенін көрсетеді. Бір қызығы, осы ақуыздардың жартысы табиғатта верникстен басқа еш жерде кездеспейді. Бұл бірегей заттардың микробтарды жоятын қасиеті бар және олар бөпені инфекциялардан сенімді қорғайды.;;;
Верникс қабаты бөпеңіз үшін бір мезгілде табиғи ылғалдандырғыш әрі дене температурасын реттеуші қызметін атқарады. Ол бөпе денесінің сұйықтық жоғалтуына жол бермейді, жаңа тері жасушаларының түзілуін қолдайды және сырғанақ құрылымының арқасында босану үдерісін жеңілдетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Миымда шамдар жанып жатыр! 🧠 Anacan, менің миым қазір алып компьютер секілді жұмыс істейді. Көру, есту, дәм сезу, иіс сезу және жанасуға арналған арнайы орталықтар қалыптасып жатыр. Мен жай ғана өсіп жатқан жоқпын, әлемді танып-білуге дайындалып жатырмын. Сіздің даусыңызды естігенде, миымдағы "есту орталығы" белсендіріледі. Біздің байланысымыз енді ғылыми деңгейде!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызанақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде тері сезімтал болып, күн сәулесінің әсеріне көбірек ұшырайды. Жүктілік кезінде гипофиз безінен бөлінетін, тері түсіне жауап беретін меланин өндіруші жасушаларға әсер ететін меланоцитті ынталандырушы гормон деңгейінің жоғарылауы теріні қараюға өте бейім етеді.;;;
Күн сәулесінің әсерінен жүктілік дақтарының пайда болуы немесе бұрыннан бар дақтардың қоюлана түсуі жиі кездеседі. Бұған қоса, күн астында ұзақ уақыт болу дене температурасының шамадан тыс көтерілуіне де, ағзадағы су мөлшерінің азаюына да әкелуі мүмкін. Екі жағдай да жүктілікке кері әсер етуі ықтимал. Осы себептердің барлығына байланысты жүктілік кезінде күн астында ұзақ уақыт жүру ұсынылмайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Белдің ауырсынуын азайту үшін биік өкшелі аяқкиімнен толық бас тартыңыз. Отырған кезде беліңіздің артына кішкентай жастық қойыңыз. Ішіңіздің ортасындағы бұлшықеттерді қатты ширықтырмаңыз, төсектен тұрған кезде алдымен қырыңызға бұрылып, содан кейін тұрыңыз.') WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз енді түс көре алады! Дамуын жалғастырып жатқан миының арқасында бөпеңіз енді REM ұйқысына өте алады. REM ұйқысы — ұйқы кезінде түстер мида қалыптасатын кезең. Ол ұйқының 4-ші сатысында байқалады және жалпы ұйқы ұзақтығының орта есеппен 15-20%-ін қамтиды. Бұл ұйықтап кеткеннен кейінгі 30-90 минут аралығына сәйкес келеді.;;;
Ұйқының 4 түрлі сатысы бар. 1-ші сатыда адам толық ұйықтай алмай, биіктен құлап бара жатқандай сезімге бөленуі мүмкін. 2-ші сатыда ағза нағыз ұйқыға дайындалады. Жүрек соғу жиілігі мен дене температурасы төмендей бастайды. 3 және 4-ші сатылар — терең ұйқы кезеңдері, дәл осы кезде ұйқыда жүру жағдайлары болуы мүмкін. Терең ұйқы деп аталатын бұл сатыларда ағза қалпына келеді, тіндер жазылады, қызметін тоқтатқан жасушалар жойылып, иммундық жүйе қажетсіз заттардан тазарады. Бөпелер ұйқының осы сатыларында өсіп, дамиды.;;;
Ми REM ұйқысында болған кезде тыныс алу жиілеп, көздер ретсіз әрі жылдам қозғала бастайды. Соның арқасында түстер шынайы өмірдегідей әсерлі болады. Ең маңыздысы — бұл кезеңде ми ояу кездегідей белсенді жұмыс істейді. Ана құрсағындағы және жаңа туған бөпелер уақытының көп бөлігін REM ұйқысында өткізеді. Бұл бөпелерге дамуының ең маңызды кезеңінде алған тәжірибелерін жақсырақ біріктіруге көмектеседі. REM ұйқысы бөпелердің ұйқы кезеңінің шамамен 50%-ін құрайды. Бөпе өскен сайын бұл кезең біртіндеп қысқара бастайды, ал жас ұлғайған сайын оның үлесі жылдам азаяды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сізді қорғаймын! 🥚 Егер мен қыз болсам, кішкентай аналық бездерімде қазірдің өзінде 6 миллион жұмыртқа жасушасы бар! Бұл Сіздің болашақ немерелеріңіз қазірдің өзінде менің ішімде деген сөз. Ал егер мен ұл болсам, жыныс мүшелерім дамып жатыр. Ұрпақ жалғасады, Anacan. Сіз тарих жасап жатырсыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қызанақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде тән және психикалық денсаулығыңызды сақтау үшін дәрумендерді дұрыс әрі тиісті мөлшерде қабылдаудың маңызы зор. Ағзадағы барлық мүшелер мен жүйелерге әсер ететін дәрумендерді жеткіліксіз қабылдау кейбір мәселелерге әкелуі мүмкін. Дәрумендер — табиғи тағам көздерінде болатын, жасушалардың жаңаруына және энергия өндіруге көмектесетін, ағзаға күн сайын белгілі бір мөлшерде қажет, ал тапшылығы кезінде қосымша қабылдануы тиіс реттеуші әрі ағзаның төзімділігін арттыратын заттар.;;;
Жүктілік кезінде дәрумендерді жеткілікті мөлшерде қабылдамау көру қабілетінің бұзылуына, басылмайтын шаршауға, тіл мен терінің жарылуына, қаназдыққа, ойдың қажуы мен депрессиялық белгілерге, терідегі көгерулер мен дақтарға, сүйектің ауырсынуы мен бұлшықет массасының азаюына әкелуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтағанда міндетті түрде сол қырыңызбен жатуға тырысыңыз; бұл бөпеге де, жатырға да қанның барынша жақсы ағуын қамтамасыз етеді. Бел ауырса, жеңіл созылу жаттығуларын жасаңыз. Артқан тәбетіңізді жемістер мен көкөністер арқылы теңестіріңіз. Бөпеңіз енді Сізді анық естиді, сондықтан бүгін оған ұнайтын музыканы баяу ырғақпен тыңдатыңыз.') WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің Сіз алғаш сезетін қимылы ықылық болуы мүмкін! Ықылық — құрсақ пен кеуде қуысын бөліп тұратын көкет бұлшықетінің кенеттен жиырылуы және дауыс байламдарының арасындағы саңылаудың жабылуы нәтижесінде пайда болатын шұғыл тыныс алу. Жаңа туған нәрестелерде жиі кездескенімен, бұл үдеріс шын мәнінде ана құрсағында басталады.;;;
Бөпеңіз жатыр ішінде қағанақ суын жұтқандықтан ықылық атады. Бұл жағдай кейбір аналарды алаңдатуы мүмкін, алайда ол бөпенің дамуына өте пайдалы. Ықылықтың арқасында бөпеңіздің ему рефлексі күшейеді, бұл оған дүниеге келгеннен кейін бірден қоректенуге көмектеседі.;;;
Қағанақ суын жұтқан кезде көкет бұлшықетінің жиырылып-босаңсуы бөпенің өкпесін жаттықтырады. Ему, жұту және ықылық кезінде өкпеге түскен сұйықтық оның тыныс алуға дайындалуына және дамуына ықпал етеді. Босану жақындаған сайын бөпе сұйықтықты көбірек жұтатындықтан, ықылық жиілеуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, Anacan! Менің көлемім мангодай. Қолдарым мен аяқтарым енді денеме сай қалыптасты. Мен кішкентай адаммын! Енді саған қаттырақ тебе аламын. Дайын бол!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде тамақтануыңызға ерекше мән беруіңіз керек. Мырыш — тамақтану рационыңызда міндетті түрде болуы қажет негізгі қоректік элементтердің бірі. Ол ақуыздар мен жасуша жарғақшаларының құрамына кіретін аса маңызды минералдардың бірі саналады. Сонымен қатар, мырыш гендер басқаратын ақуыздардың түзілу үдерісіне де қатысады. Ағзадағы мырыштың жеткілікті мөлшері 100-ден астам ферменттің қалыпты әрі дұрыс жұмыс істеуін қамтамасыз етеді.;;;
Жүктілік кезінде ағзаның мырышқа деген қажеттілігі артады. Осы кезеңде мырышты жеткілікті мөлшерде қабылдау ДНҚ мен ақуыз құрылымының қалыптасуында маңызды рөл атқарады. Сондықтан жасушалар өте жылдам түзілетін жүктілік кезеңінде мырыш қабылдау аса маңызды. Жүкті емес әйелдің мырышқа тәуліктік қажеттілігі 8 мг болса, жүкті әйелде бұл көрсеткіш 11 мг-ға дейін артады. Ал бала емізетін ана тәулігіне 12 мг мырыш қабылдауы керек. Мырыш көбіне ет пен теңіз өнімдерінде кездеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жолдың жартысына жеткеніңізді шағын қуанышпен атап өтіңіз! Белдің ауырсынуын азайту үшін арқаңызды тік ұстап отыруға тырысыңыз және ауыр зат көтермеңіз. Аяқтарыңыз ісінсе, күн соңында оларды сәл жоғары көтеріп демалыңыз. Суды көп ішуді және рационыңызға талшыққа бай тағамдарды қосуды жалғастырыңыз. Ертең бізді үлкен «экватор» күні күтіп тұр!') WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Құттықтаймыз! Жүктілігіңіздің жартысын артқа қалдырдыңыз.;;;
Егер бөпеңіз қыз болса, оның аналық бездерінде жұмыртқа жасушалары белсенді түрде түзіліп жатыр. Ал ұл бөпелерде аталық бездер қалыптасып, өз орнына қарай түсуін жалғастырады. Аталық бездер — ерлердің жыныстық жүйесінің негізгі бөлігі. Сперматозоидтардың дұрыс дамуы үшін оларға дене температурасынан шамамен 2 градус төмен орта қажет. Ұманың денеден тыс орналасуының басты себебі де осы: төменірек температура сперматозоидтардың бұзылуына жол бермейді.;;;
Аталық бездердің бірнеше маңызды қызметі бар: тестостерон гормонын бөлу, ерлерге тән дене ерекшеліктерінің дамуын қамтамасыз ету және сперматозоидтар түзу. Даму толық аяқталған кезде бұл жүйе тәулігіне 200 миллионға дейін сперматозоид түзе алады.'), baby_message_kk = COALESCE(baby_message_kk, 'Шашым өсіп келеді! 💇‍♂️ Бас терімде нағыз шаш өсе бастады. Әзірге ол өте жұқа әрі түссіз, бірақ дүниеге келгенде қалың шашты бөпе болуым да мүмкін. Сенің қыжылың ұстағанда әжелер «баланың шашы өсіп жатыр» дейді ғой, бәлкім, рас айтатын шығар?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл кезеңде жатырыңыз жүктілікке дейінгі орнына қарағанда үш есе жоғары орналасады. Осы аптадан бастап босанғанға дейін ол әр апта сайын шамамен 1 см жоғары көтеріледі. Жатырдың жоғары қарай өсуі ішкі ағзаларыңыздың орнын өзгертеді. Солардың бірі — асқазан. Оның қақпақшасы босаңсыған кезде қышқыл бөлінділер өңешке өтіп, қыжыл тудыруы мүмкін.;;;
Қыжыл мен асқазанның ашуы жүктілік кезінде жиі кездеседі. Оның алдын алу үшін қызанақ, пияз, сарымсақ, газдалған және қышқыл сусындар, темекі, балмұздақ, шәрбатты тәттілер, шоколад, қуырылған тағамдар, томат пастасы, дәмдеуіштері көп тағамдар, тұздалған өнімдер, апельсин және ащы бұрыштан бас тартқан жөн. Қыжыл сезілген кезде алдымен жылы сүт ішуге болады. Жылы сүт қыжылды азайтады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жолдың жартысына жеткеніңізді атап өту үшін өзіңізге жағымды күн сыйлаңыз! Белдің ауырсынуын болдырмау үшін арқаңызды тік ұстап отыруға тырысыңыз және міндетті түрде сол жақ қырыңызбен жатып демалыңыз. Темірді жеткілікті қабылдауға ерекше назар аударыңыз, өйткені бөпенің қан түзуі үшін темірге қажеттілік артады. Күн сайын 20-30 минут жеңіл серуендеу өзіңізді сергек сезінуге көмектеседі.') WHERE id = 'ac85f07b-25b5-4dda-969a-4a8dfc9a2528';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы апталарда бөпеңіздің бүкіл денесін лануго түктері жауып тұрады, ал қасы мен басындағы түктер қалыңырақ болғандықтан, анық көріне бастайды. Қас тек сыртқы көрік үшін ғана емес, сонымен қатар көзді жоғарыдан ағуы мүмкін тер тамшыларынан, судан және басқа да зиянды заттардан қорғау үшін маңызды қызмет атқарады. Бір қызығы, қыз және ұл бөпелердің қасының ұзындығы бірдей (шамамен 10 мм) болғанымен, қалыңдығы әртүрлі болады. Бөпеңіздің қас аймағында орта есеппен 200-300 қас талшығы қалыптасады. Егер бөпеңіз ұл болса, оның қасының құрылымы болашақта өсетін мұрты мен сақалының құрылымына ұқсас болады. Қас пен кірпік — денедегі ең төзімді түктер: олар ең соңынан ағарады және денсаулыққа қатысты ерекше мәселе болмаса, өте сирек түседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүйректерім керемет жұмыс істеп тұр! 💧 Мен қағанақ суын жұтамын, бүйректерім оны сүзіп, таза зәр түрінде қайта шығарады. Бұл сұйықтық мені қорғайды, дене жылуымды сақтайды және қозғалуыма көмектеседі. Мен өз бассейнімді өзім тазалаймын. Менің суым таза әрі мол болуы үшін сен де суды көп іш.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жамбастағы қалыпты жағдайда қозғалмайтын буындар босану кезінде бөпеңіздің оңай өтуі үшін кеңейеді. Сондықтан осы кезеңде тепе-теңдікті сақтау қиындауы мүмкін. Жамбас қуысының шығаберісі алдыңғы-артқы бағытта ұзындау, ал оң-сол бағытта қысқалау сопақ пішінді болады. Бұл жолдың ең тар тұсы — сүйек шығыңқылары орналасқан ортаңғы бөлігі. Бөпенің басы мен жамбас сүйегінің сопақ бөлігі арасындағы аралық небәрі 20 см-ге дейін жетеді. Бөпе ана құрсағында жатқанда, оның басы иегі кеудесіне тиетіндей алға қарай иіліп тұрады. Осының арқасында бас жамбас қуысына ең кіші диаметрімен кіреді. Бөпенің басы да, жамбас сүйегі де толық қатты әрі қозғалмайтын құрылым емес. Жүктілік барысында екеуі де бір-біріне бейімделе өзгереді. Бөпенің бас сүйектері бір-бірінің үстіне ығыса алады және ересек адамның сүйектеріне қарағанда жұмсағырақ болады. Соның арқасында бөпе босану жолынан өте алады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңыздағы шаршау мен ісінуді азайту үшін күн ішінде дене қалпыңызды жиі өзгертіп, ұзақ уақыт қимылсыз отырмаңыз. Темірді көбірек қабылдау үшін рационыңызға қызыл ет, жасымық және қою жасыл түсті көкөністерді қосыңыз. Бөпеңіз енді барлық дыбысты естиді, сондықтан бүгін оған сүйікті кітабыңызды дауыстап оқып бере аласыз.') WHERE id = '34d9ab3e-6f7e-4354-93cc-e6f91180c7df';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіз уақытының 90%-ын ұйқымен өткізеді. Қағанақ сұйықтығында қалқып жүрген бөпеңіз күні бойы Сіздің қимылдарыңызбен тербеліп, жайлы ұйқыға кетеді. Ал түнде Сіз қозғалыссыз жатқанда және сұйықтықтың қозғалысы баяулағанда, ол ояна бастайды. Жаңа туған бөпелердің түнде жиі оянуының бір себебі дәл осы әдет болуы мүмкін деп есептеледі.;;;
Жатыр іші мен сыртқы әлем арасындағы күн мен түн айырмашылығы жатыр қабырғасымен көмескіленетіндіктен, бөпеңіздің бұл ырғаққа бейімделуіне босанғаннан кейін 1-2 ай кетуі мүмкін. Бөпеңіздің тәуліктің басым бөлігін ұйқымен өткізуінің ең маңызды себебі — өсу гормоны.;;;
Гипофиздің алдыңғы бөлігінің жасушалары өндіретін бұл гормон ақуыздан тұрады және дененің бой өсуі мен тіндердің дамуын қамтамасыз етеді. Ең маңыздысы — бұл гормон негізінен бөпе ұйықтап жатқанда синтезделеді. Яғни бөпеңіз неғұрлым көп ұйықтаса, соғұрлым дені сау болып, тез өседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің ұйқы режимім бар! 🌙 Anacan, мен күні бойы ояу жүрмеймін. Менің де ұйықтайтын және ояу болатын уақытым бар. Әдетте Сіз жүргенде немесе қозғалғанда, мен тербеліп ұйықтап қаламын. Ал Сіз жатып демалғыңыз келгенде, мен оянып алып, дискотека бастаймын. Режимдеріміз сәл өзгеше, кешіріңіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілікке дейін әр омыраудың орташа салмағы 230-250 грамм болады. Жүктілік кезінде сүт өзектерінің кеңеюіне байланысты омыраудың көлемі ұлғайып, сезімталдығы артады. Омырауда ауырлық сезілуі мүмкін. Оң және сол омыраудың көлемі әртүрлі болуы ықтимал. Омырау айналасындағы тері астынан қан тамырлары көріне бастауы мүмкін. Осыған байланысты омыраудың салмағы қалыпты мөлшерден екі есе артуы ықтимал. Қалыпты жағдайда шамамен 60 грамм болатын жатырдың салмағы бұл кезеңде шамамен 300 граммға жетеді. Ал босанатын күнге дейін оның салмағы 1000 грамм болады. Бөпеңіз жатқан қағанақ сұйықтығының салмағы бұл кезеңде шамамен 350-400 грамм болса, жүктіліктің соңына қарай 800 граммға дейін артады. Осы аптада плацентаның көлемі мен салмағы бөпеңіздікімен шамалас болады, ал жүктіліктің соңында оның салмағы шамамен 600-650 граммға жетеді. Бұған қоса, тінаралық сұйықтық мөлшері жүктілікке дейінгі кезеңмен салыстырғанда 1500-2000 граммға артады. Босанғаннан кейін сүт өндіруге дайындалу үшін ағза жинайтын май мөлшері бұл кезеңде 400-500 граммға жуықтаса, жүктіліктің соңына дейін 3500-4000 граммға жетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қолыңыздағы қызару мен ыстық сезімін азайту үшін оларды салқын сумен жуыңыз. Химиялық тазартқыш заттарды қолыңызға тигізбеңіз. Бетіңізді күннен қорғау үшін міндетті түрде бас киім киіп, SPF кремін қолданыңыз.') WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бас терісінде басқа түктерден ерекшеленетін нағыз шаш түбірлері дами бастайды. Шаш берік кератин ақуызынан түзіледі. Оның ішкі құрылымындағы ерекше байланыстар шаштың беріктігін қамтамасыз етеді. Егер шаштың сыртқы қорғаныш қабаты зақымданса, шаш сына бастайды.;;;
Шаш түбірі терінің астыңғы қабатындағы фолликулдың ішінде пайда болып, кейін ұзарып, терінің үстіңгі қабатын тесіп сыртқа шығады. Бөпеңіздің шаш түсін Сіз бен жұбайыңыздың ДНҚ-сындағы меланин пигменті анықтайды. Осы пигменттің мөлшеріне қарай шаш ашық немесе қою түсті болады.;;;
Ал шаштың түрін дисульфидті байланыстардың тығыздығы анықтайды; бұйра шашта бұл байланыстар көбірек болады. Шаш талшығы өте жіңішке болып көрінгенімен, шын мәнінде ол бірнеше қабат пен көптеген талшықтан тұрады. Шаш ұшының айырлануы да дәл осы талшықты құрылымдардың бір-бірінен ажырауынан пайда болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен верникспен қапталғанмын! 🧼 Денемдегі ақ, крем тәрізді зат қазір қалыңдай түсті. Ол мені су ішінде шамадан тыс жібіп кетуден қорғайды. Сондай-ақ дүниеге келгенде босану жолымен сырғып шығуыма көмектеседі. Табиғат бәрін ойластырған, солай емес пе? Сізге аман-сау жетуім үшін менде барлық қорғаныс бар.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезіндегі гормондық өзгерістерге байланысты мұрынның шырышты қабығы ісініп, мұрын бітелуі мүмкін. Бұл мұрыннан бөлінетін шырыш мөлшерінің артуына әкеледі. Синусит кезіндегідей, мұндай жағдайда синус қуыстары жабылып, мұрын бітелуі ықтимал. Бұл қорылдың пайда болуына әсер ететін себептердің бірі. Сонымен қатар бөпе өсе бастаған сайын дене салмағы жылдам артады. Бұған қоса, тамақтану тәртібінің өзгеруінен артық салмақ қосылуы мүмкін. Артық салмақтың әсері дененің әр бөлігінде байқалады. Май жиналғандықтан, дененің түрлі аймақтарындағы тіндердің көлемі ұлғаяды. Жүктілік кезінде артық салмақ қосқан әйелдер қорылдауға бейім келеді. Сондықтан жүктіліктің қалыпты барысына сай келмейтін артық салмақтың алдын алу үшін қажетті шаралар қабылдануы керек. Дұрыс тамақтану тәртібін қалыптастырып, салмақтың өсуін бақылауда ұстаған жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылдың алдын алу үшін тамақтанғаннан кейін бірден жатпаңыз және аз мөлшерде, бірақ жиі тамақтануға тырысыңыз. Беліңіз ауырса, отырғанда арқаңызға кішкентай жастық қойып, тік отырыңыз. Сіздің де, бөпеңіздің де қанға деген қажеттілігі толық қамтамасыз етілуі үшін темір қабылдауды ұмытпаңыз. Бүгін кешке өзіңізге біраз уақыт бөліп, баяу музыка тыңдаңыз.') WHERE id = '481d4a59-0854-49d1-ad3d-0f418a6738b5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіздің салмағы шамамен 300 граммға жуықтайды. Дәрігер тексеруінде бөпеңіздің дамуы есептелген мерзімнен сәл ілгері немесе кейін болуы — қалыпты жағдай. 2 апталық айырмашылық қалыпты деп есептеледі.;;;
Дамудың алғашқы айларында бөпелердің 60%-ы соңғы етеккір күні бойынша есептелген мерзімнен ілгері болуы мүмкін. Екінші триместрдің соңына қарай бұл айырмашылық әдетте азайып, өлшемдер жүктілік аптасына сәйкестене бастайды. Егер айырмашылық 2 аптадан асып кетсе, дәрігеріңіз жағдайды мұқият бақылау үшін Сізді перинатологтың тексеруіне немесе қосымша зерттеулерге жіберуі мүмкін.;;;
Бөпеңіздің өз аптасынан сәл "кейін" болуы бірден дамудың тежелгенін білдірмейді. Ультрадыбыстық зерттеу кезіндегі өлшемдерге көптеген фактор әсер етеді: бөпенің қалпы, дәрігердің өлшеу тәсілі және құрылғының техникалық мүмкіндігі. Тіпті бірнеше минут аралықпен жүргізілген өлшеулердің өзінде аздаған айырмашылық болуы мүмкін. Сондықтан 2 аптаға дейінгі айырмашылыққа алаңдауға негіз жоқ.'), baby_message_kk = COALESCE(baby_message_kk, 'Үлкен тексеруге дайынбыз ба? 🩺 Жақын күндері "Анатомиялық сканерлеу" (Доплер) өтеді. Дәрігер менің әрбір ағзамды — жүрегімді, миымды, саусақтарымды бір-бірлеп тексереді. Мен Сізге қол бұлғаймын! Бағымыз жанса, жынысымды да анық көресіз. (Әрине, жасырып қалмасам).'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Манго'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптадан бастап омырауыңыздағы қоңыр аймақ біртіндеп үлкейе бастайды. Ареола деп аталатын бұл аймақ омырауыңыздың жартысына жуығын қамтуы мүмкін. Омыраудың өсуіне байланысты емізік пен ареоланың орналасуы өзгереді. Бұл қалыпты жағдай және босанғаннан кейінгі 12-ші айға дейін жалғасуы мүмкін. Ареола — емізікті айнала қоршаған қою түсті шеңбер. Ареоланың пішіні, түсі мен көлемі әр адамда және терінің түсіне қарай әртүрлі болады. Алғашқы жүктіліктен кейін ареоланың түсі қоюланып, сол қалпында қалуы мүмкін. Ареоланың ішінде Монтгомери бездері деп аталатын ұсақ май бездері орналасқан.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңізге түсетін жүктемені азайту үшін тік отыруға тырысыңыз және ұзақ уақыт тік тұрып қалмаңыз. Кешке аяқтарыңызды жүрек деңгейінен сәл жоғары көтеріп, 15 минут демалу ісінуді азайтып, қан тамырларын тынықтырады. Темір мен кальций қабылдауға ерекше көңіл бөліңіз. Күнді өзіңізге ұнайтын кітаптың бірнеше бетін бөпеңізге дауыстап оқумен аяқтаңыз.') WHERE id = '6ad08d05-7381-4d47-abac-7c50836b90a0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ас қорыту жүйесі маңызды даму кезеңіне жетті. Оның асқазаны тек сүтті қорытуға арналған ерекше затты — ұйытқы ферментін өндіруге толық дайын.;;;
Сүттің қорытылуы оның құрамындағы казеин деп аталатын ақуыздың ұюынан басталады. Бөпеңіз дүниеге келгеннен кейін сүт емген кезде, асқазанындағы ұйытқы ферменті сүтті бірден ұйытады. Содан кейін пепсин ферменті іске қосылып, бұл затты бөпеңіздің жасушалары сіңіре алатын аминқышқылдарына дейін ыдыратады. Ұйытқы ферментінің әсерінен сүт айранға немесе ірімшікке ұқсас біркелкі емес құрылымға айналады. Ал пепсин ферменті осы ақуыздарды ыдыратып, олардың қан арқылы бүкіл денеге таралуын қамтамасыз етеді.;;;
Бөпелер туғаннан кейін кейде артық сүтті құсып тастайды. Егер бөпеңіздің аузынан шыққан сүт сұйық емес, қою әрі ұйыған күйде болса, бұл асқазандағы ұйытқы ферменттерінің сүтті жылдам әрі дұрыс қорыта бастағанын көрсетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Даусымды дайындап жатырмын! 🎤 Менің көмейім мен дауыс желбезектерім толық дайын. Енді тек ауа жетіспейді. Дүниеге келген бойда алғашқы деміммен Сізге "Сәлем, Анашым!" (яғни "Іңгәә!") деймін. Сол сәтті елестетіп жүрсіз бе? Мен күн сайын сол сәтке дайындалып жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Банан'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қандай шөп шайларын ішуге болатынына мұқият қарау қажет. Мелисса мен зімбір шайын дәрігеріңіздің рұқсатын алғаннан кейін ішуге болады. Тыныштандыратын әсері бар мелисса шайының жүктілік кезінде зиян келтіретіні анықталмаған. Әсіресе ұйықтай алмай қиналатын немесе ұйқысыздықтан зардап шегетін әйелдер жатар алдында бір кесе мелисса шайын іше алады. Антиоксиданттарға бай зімбірді шай түрінде ішу де пайдалы. Жүрек айну мен құсу жиі кездесетін бірінші триместрде зімбір шайы бұл белгілерді азайтуы мүмкін. Таңқурай жапырағынан дайындалған шай бұлшықеттерге әртүрлі әсер етуі мүмкін. Босану толғақтарын азайтуы ықтимал таңқурай шайын жүктіліктің соңғы апталарында ішу қауіпті болуы мүмкін. Көк шайдың құрамында антиоксиданттар көп болғандықтан, ол өте пайдалы. Сондай-ақ ағзадан токсиндердің шығарылуына көмектеседі. Алайда фолий қышқылының сіңуін төмендететіндіктен, бөпеге кері әсер етуі мүмкін. Сондықтан жүктілік кезінде көк шай ішу әдетте ұсынылмайды. Жүктілік кезінде сәлбен шайын ішу толғақтың азаюына немесе қан кету қаупінің артуына әкелуі мүмкін. Сол себепті қанды сұйылтатын шөп шайларын ішуге болмайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Іш қатудың алдын алу үшін жасұныққа бай тағамдарды көбірек жеп, су ішіңіз. Ұзақ уақыт бойы тік тұрмаңыз немесе отырмаңыз. Кегель жаттығулары жамбас түбі аймағындағы қан айналымын жақсартып, геморрой кезінде де көмектесуі мүмкін.') WHERE id = '0c65c176-54fc-4e82-af61-c7b6cff2d77a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүкті әйелдердің шамамен 70%-ы осы аптадан бастап бөпесінің алғашқы қимылдарын сезе бастайды. Бұл — бөпеңізбен орнаған алғашқы физикалық байланыс әрі жүктіліктің ең толқынысты сәттерінің бірі.;;;
Бөпеңіз әлі оның қимылдарын күн сайын тұрақты түрде сезе алатындай үлкен емес. Бір күні қозғалысын сезіп, келесі бірнеше күн бойы ештеңе сезбеуіңіз — қалыпты жағдай. Қимылдар әдетте 20-апталардың ортасынан кейін тұрақты бола бастайды. Егер әлі бірде-бір қимыл сезбесеңіз, алаңдамаңыз: 24-ші аптаға дейін бұл қалыпты болып саналады. Бұған іш байламдарының керілуі, бөпенің орналасуы немесе іш аймағындағы май тіні себеп болуы мүмкін.;;;
Жатыр ұлғайған сайын ішектерді екі жаққа қарай ығыстырады. Осы қысымнан туындайтын ішек қозғалысы, газ немесе ас қорыту үдерістері кейде бөпенің қимылдарымен шатастырылуы мүмкін. Уақыт өте келе Сіз бұл екі түрлі сезімді бір-бірінен ажыратуды үйренесіз.'), baby_message_kk = COALESCE(baby_message_kk, 'ЖОЛДЫҢ ЖАРТЫСЫ! 🏁 Құттықтаймын, Anacan! Біз 40 апталық марафонның тура жартысын (50%-ын) аяқтадық. Менің бойым банандай болды! Керемет, солай емес пе? Осы уақытқа дейін қалай өскеніме қараңызшы. Жатырыңыз енді кіндік деңгейіне жетті. Біз мәреге қарай бет алып келеміз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Банан'), body_changes_kk = COALESCE(body_changes_kk, 'Минералдардың жасушаларды қорғау, тістердің, сүйектердің және терінің сау құрылымын сақтау үшін маңызы зор. Бұған қоса, олар қан қысымын, жүрек ырғағын, бұлшықет қызметін, ағзадағы сұйықтық тепе-теңдігін сақтау, көбею және басқа да көптеген үдерістерде маңызды рөл атқарады. Осы минералдардың ішінде жүктілік бойы ең маңыздысы — кальций. Ағзадағы кальций мөлшері сүйектер үшін ғана маңызды емес, ол ағзадағы барлық қызметке қатысады. Сондай-ақ кальций сау әрі мықты тістер үшін қажет. Ол бұлшықеттердің жұмысында да үлкен рөл атқарады. Әсіресе ағзадағы темірдің пайдаланылуы және тағамнан алынған қоректік заттардың жасуша жарғақшасы арқылы өтуі үшін аса қажет зат.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жолдың жартысын аяқтағаныңызды өзіңіз жақсы көретін бір нәрсемен атап өтіңіз! Белдегі ауырсынуды азайту үшін аяғыңызды айқастырып отырмауға тырысыңыз. Түнде міндетті түрде сол қырыңызбен жатып, тізелеріңіздің арасына жастық қойыңыз. Өзіңіздің де, бөпеңіздің де қан түзуге қажеттілігін толық қамтамасыз ету үшін темірге бай тағамдарды (жасымық, қызыл ет, саумалдық) тұтынуды жалғастырыңыз.') WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің салмағы 250–280 грамм. Неткен жылдам өсу, солай емес пе?Керемет жылдамдықпен өсіп жатқан бөпеңіздің денесіне көбірек қан айдау үшін жүрегі бір сәт те тоқтамай жұмысын жалғастыруда. Соның арқасында жүрек бұлшықеттері дамып, нығая береді.;;;
Жүрек бұлшықетінің жиырылуы арқылы бөпеңіздің денесіндегі әрбір жасушаға оттегі мен қоректік заттар жеткізіледі. Яғни, бұл қозғалыстар өмірге қажетті қызметтердің орындалуы үшін аса маңызды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен "тамақ" ішіп жатырмын! 🍽️ Anacan, менің ас қорыту жүйем іске қосылды. Мен қағанақ суын жұтамын, ал ішектерім одан қант пен суды сіңіреді. Бұл сұйықтықтың дәмі күн сайын өзгереді – кеше Сіз жеген сарымсақты тағамның дәмін сездім! Ішегімде "меконий" деп аталатын алғашқы нәжіс жиналып жатыр. Уайымдамаңыз, оны жөргегіме дейін сақтаймын, айналамды былғамаймын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде өз денсаулығыңыз үшін темірді жеткілікті мөлшерде қабылдауға ерекше мән беріңіз. Жүктілік кезінде темірге қажеттілік екі есеге жуық артады. Жүкті емес кезеңмен салыстырғанда, жүктілік кезінде ағзадағы қан мөлшері 50% артық болады. Ал қан жасушаларының түзілуі үшін темір міндетті түрде қажет.;;;
Сонымен қатар темір бұлшықеттер мен дәнекер тіндерді оттегімен қамтамасыз ететін құрылымдардың жұмысы және иммундық жүйені қолдау үшін маңызды. Қандағы темір деңгейіне Сіз қабылдайтын басқа заттар да әсер етеді. Кальций, сондай-ақ шай мен кофе секілді құрамында кофеин бар сусындар ағзаның темірді сіңіруіне кедергі келтіруі мүмкін.;;;
Ал C дәрумені темірдің сіңуіне көмектеседі. Сондықтан құрамында темірі көп тағамдарды жегеннен кейін бір стақан жеміс шырынын ішу немесе жеміс жеу пайдалы болуы мүмкін.;;;
Темір, әсіресе екінші және үшінші триместрде, бөпеңіздің дамуы мен плацента үшін өмірлік маңызға ие. Қанға қажетті темірді теңгерімді тамақтану арқылы алуға болады. Анемия қаупін азайту үшін жүйелі түрде тексеруден өтуді ұмытпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяғыңыздың ісінгенін сезсеңіз, күн ішінде дене қалпыңызды жиі өзгертіп, кешке аяқтарыңызды жастықтың үстіне қойып демалыңыз. Теріңіздің серпімділігін сақтау үшін көп су ішіп, ылғалдандыратын майларды қолданыңыз. Аяқтың құрысуына жол бермеу үшін кальций мен магнийді жеткілікті мөлшерде қабылдауға көңіл бөліңіз.') WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз енді Сізді ести алады!;;;
Жүктіліктің 20-аптасына қарай бөпеңіздің құлағы негізінен қалыптасып бітеді. Алайда оның дамуы 24-аптаға дейін жалғасады. Сырттан келетін дыбыстарды ішкі құлағы арқылы қабылдай алатын бөпеңіз енді Сіз сөйлеген кезде даусыңызды естиді.;;;
Бірнеше апта ішінде бөпеңіздің есту қабілеті Сіздің даусыңызға, эмоциялық күйіңізге және әрекеттеріңізге жауап беріп, жүрек соғысы мен қимылдарын өзгертетіндей сезімтал болады. Сіз жай сөйлегенде, бөпеңіз де тынышталып, жүрек соғысы баяулайды. Әсіресе 24 аптадан кейін қатты дыбыстан бөпеңіз селк етіп, кейде артынша ықылық ата бастауы мүмкін.;;;
Осы кезеңде бөпеңізге ырғағы баяу, даусы тым қатты емес музыка тыңдату оны тыныштандырады. Мұны музыканы әдеттегідей қосып немесе ішіңізге тағуға арнайы жасалған құлаққаптарды пайдаланып жасай аласыз.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің қасым мен кірпігім бар! 👁️ Anacan, енді менің бетім нағыз адамдікіндей. Көздерімнің үстінде жіңішке қасым, ал қабақтарымда ұзын кірпіктерім өсіп шықты. Енді мен одан да әдемімін (немесе сымбаттымын). Көзімді жыпылықтатуға дайындалып жүрмін, бірақ көзімді ашуыма әлі бірнеше апта бар. Сен мені елестетесің бе? Мен сені елестетемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде теріңізде кейбір мәселелер пайда болуы мүмкін. Мысалы, терінің майлануы безеудің шығуына себеп болуы ықтимал. Осындай жағдайға тап болсаңыз, теріңізді табиғи тазартқышпен күніне екі рет тазалаңыз. Қолданатын кремдеріңіздің майсыз болуына мән беріңіз. Ауыз арқылы қабылданатын безеуге қарсы дәрілерді қолданбаңыз. Бұл дәрілер бөпеде ауыр даму ақауларын тудыруы мүмкін. Бөпеңіздің дамуы үшін дәрігеріңізбен кеңесіп, омега қоспаларын қабылдай бастауға болады. Омега — ағзаңызға қажет маңызды май қышқылдары. Омега май қышқылдары бөпеңіздің, әсіресе миы мен көздерінің дамуы үшін өмірлік маңызға ие. Зерттеулер омеганың мерзімінен бұрын босанудың алдын алуға көмектесетінін және бөпелердің салмағы жоғарырақ болып туылуына ықпал ететінін көрсетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Тоңазытқышыңызды пайдалы тағамдармен толтырыңыз. Қолыңызда жуылған жеміс-жидек, көкөніс, йогурт немесе сүзбе болса, зиянды "тіскебасарлардан" аулақ болу оңайырақ болады.') WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ұйқы тәртібі әлі толық тұрақты болмаса да, өзіне тән ұйқы ырғағы қалыптаса бастады. Дәрігер тексерулерінде оның жиі ұйықтап жатқанын көруіңіз қалыпты жағдай. Күні бойы қозғалыста жүруіңіз шарана суын тербетіп, бөпеңізге бесік жырындай әсер етеді әрі оны тыныштандырып, ұйықтатады.;;;
Бөпеңіз ең белсенді болатын уақыт — Сіз демалуға жатқан, қан қысымыңыз төмендеп, айнала тынышталған түнгі мезгіл. Күні бойы ұйқысын қандырып алған кішкентайыңыз түнгі тыныштықта "ойнағанды" ұнатады. Осы кезеңде ұйқы тәртібінің қалыптасуы жатырдағы даму үшін де, туғаннан кейінгі дұрыс ұйқы әдеттері үшін де негіз қалайды.;;;
Зерттеулер жүктілік кезіндегі зиянды әдеттердің (алкоголь, есірткі заттары және т.б.) бөпенің ұйқы сапасын күрт төмендететінін көрсетеді. Мұндай жағдайда бөпелер "тиімсіз ұйқы" мәселесіне тап болады: олар басқа бөпелерге қарағанда 5 есе жиі оянады және жалпы ұйқы уақыты айтарлықтай қысқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Қаным қызарып келеді! 🩸 Сүйектерімнің ішіндегі кемік енді қан жасушаларын түзіп жатыр. Бұл менің болашақ иммунитетім мен оттегін тасымалдауым үшін өте маңызды. Менің қан тобым да белгілі болды. Сенікі ме, әлде әкемдікі ме? Мұны мен туылғанда білесің. Мен күн сайын тәуелсіз бола түсіп келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер білектеріңіз бен саусақтарыңызда басылмайтын ұю сезілсе, бұл шағым карпальды туннель синдромымен байланысты болуы мүмкін. Карпальды туннель синдромы медиандық жүйкенің білектегі өзек ішінде қысылуынан туындайды. Бастапқы кезеңде ол ұю түрінде байқалады. Жүктілік кезінде білектер мен аяқтарда жиі кездесетін ісіну білектегі жүйкелерге қысым түсіреді. Бұл білектер мен саусақтардың ұюына, шаншуына және ауыруына себеп болады. Егер бұл жүйке қысылу синдромы тек жүктілікке байланысты болса, босанғаннан кейін көп ұзамай емдеуді қажет етпей, өздігінен басылады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңіздің қышуын азайту үшін душтан кейін теріңіз әлі ылғал кезде табиғи майлармен массаж жасаңыз. Аяқтарыңызға түсетін салмақты азайту үшін отырғанда оларды сәл жоғары көтеріңіз. Магнийге бай тағамдарға басымдық беріңіз, бұл аяқтың құрысуының алдын алуға көмектеседі.') WHERE id = '374d8324-b6d6-473c-83ac-7fb12f83f44c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада лануго түктері бөпеңіздің денесін жабуын жалғастырады, ал жынысына қарамастан оның емізіктері қалыптаса бастайды. Емізіктің негізгі қызметі — емізуді қамтамасыз ету. Бір қызығы, емізікте жалғыз саңылау емес, сүт бөлетін 20-ға дейін ұсақ өзек (саңылау) болады. Мұны босанғаннан кейін сүтіңіз келе бастағанда анық байқай аласыз.;;;
Бөпе әлі эмбрион кезеңінде, яғни жыныс мүшелері ажырап қалыптаса бастағанға дейін, емізіктерді түзетін жасушалар бірігіп үлгереді. Ал жыныс аймағына тән ерекшеліктердің қалыптасуы 8-аптадан ерте басталмайды. Ұл бөпелерде ер жыныс жүйесін қалыптастыратын SRY гені белсенген кезде емізіктер қалыптасып қойғандықтан, бұл ген олардың дамуын толығымен тоқтата алмайды. Сондықтан екі жыныста да емізік болады.'), baby_message_kk = COALESCE(baby_message_kk, '🥕 Мен үлкен бір сәбіздің көлеміндеймін! Қазір көбірек ұйықтаймын әрі күштірек тебемін. Менің ұйқы тәртібім сенікіне қарама-қарсы болуы мүмкін. Сен ұйықтағанда, мен оянамын, өйткені сен қимылсыз жатқанда мені тербететін "әткеншек" тоқтап қалғандай сезіледі де, мен оянып кетемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің екінші триместрінде мезгіл-мезгіл ісіну пайда болуы мүмкін. Ісіну көбіне қан айналымының бұзылуынан туындайды. Босануға дайындалу үшін ұлғайып жатқан жатыр мен жамбас аяқтарыңыздағы қан тамырларына қысым түсіреді. Бұл қысым қан айналымын баяулатып, ісінуге әкеледі. Ісінудің тағы бір себебі — тамақтану әдеттері. Қатты ісінетін адамдардың едәуір бөлігі ақуызды жеткілікті мөлшерде тұтынбайтыны анықталған. Қажетті ақуызды ет және соған ұқсас тағамдардан алуға болады, сондай-ақ күніне кемінде үш порция сүт немесе сүт өнімдерін тұтыну да жеткілікті болуы мүмкін. Тамақтануға қатысты тағы бір маңызды мәселе — тұзды тиісті мөлшерде тұтыну. Көп адам тұзды шамадан тыс қолдану ағзада судың жиналуына және соның салдарынан ісінуге әкеледі деп ойлайды. Бұл дұрыс болғанымен, тұзды жеткіліксіз тұтыну да ісінуге себеп болуы мүмкін. Ең бастысы — тұзды жеткілікті мөлшерде тұтынып, әрдайым теңгерімді әрі дұрыс тамақтану. Ісіну мәселесі болса, жатып демалыңыз, аяқтарыңызды жоғары көтеріңіз, сұйықтықты мол ішіңіз, қысқа уақыт серуендеңіз, денеңізді қыспайтын киім киіңіз және тамақтануыңызға мән беріңіз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңізге түсетін салмақты азайту үшін тік отыруға тырысыңыз және ұзақ уақыт тік тұрып қалмаңыз. Кешке аяқтарыңызды жүрек деңгейінен сәл жоғары көтеріп, 15 минут демалу ісінуді азайтып қана қоймай, өзіңізді жайлы сезінуге де көмектеседі. Кальцийге қажеттілігіңіз артқандықтан, ас мәзіріңізге сүзбе, ірімшік немесе бадам секілді тағамдарды қосыңыз. Күнді өзіңіз ұнататын музыкамен аяқтаңыз.') WHERE id = '4291c964-97b5-4aa4-a48e-b3cb8e0fe5cb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүрек соғысын стетоскоппен тыңдауға енді болады! Дәрігер тексеру кезінде осы құралмен бөпеңіздің жүрек соғысын тексере алады. Өзіңіздің және бөпеңіздің жүрек соғысын бір-бірінен ажырату өте оңай: бөпеңіздің жүрегі Сіздікінен шамамен 2 есе жылдам соғады.;;;
Бөпеңіздің қарқынды дамуына ықпал ететін басты мүшелердің бірі — кіндік бауы (umbilical cord). Ол бүкіл жүктілік бойы бөпеңізге тіршілік үшін маңызды қоректік заттар мен оттегінің жеткізілуін қамтамасыз етеді. Кіндік бауының орташа ұзындығы 50-55 сантиметр және оның пішіні шиыршық тәрізді болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен сенің күйзелісіңді сеземін. 😟 Anacan, сен мазасызданғанда ағзаңда түзілетін гормондар (кортизол) маған да жетіп, мен де алаңдаймын. Жүрегім жылдамырақ соғады. Ал сен тыныш әрі бақытты болғанда, мен де "бақыт гормондарымен" қоректенемін. Өтінемін, өзіңді қинама. Біз біргеміз, бәрі жақсы болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде геморрой пайда болуы немесе бұрыннан бар геморройға байланысты шағымдар күшеюі мүмкін.;;;
Тері бетіне жақын орналасқан тамырлар ісініп, варикоз бен геморройдың пайда болуына әкеледі. Сонымен қатар осы кезеңде деңгейі жоғарылайтын прогестерон гормоны тамырлардың айналасындағы бірыңғай салалы бұлшықеттерді босаңсытып, олардың оңай ісінуіне себеп болуы мүмкін. Геморройдың алғашқы белгісі, әдетте, үлкен дәретке отырғанда байқалатын қан дақтары болады. Қан кетуден бөлек, артқы өтіс аймағында кернеу сезілуі, дәретханадан кейін тазаланған кезде қолға білінетін ісік және үлкен дәрет кезінде басталып, ұзақ уақытқа созылатын ауырсыну болуы мүмкін. Геморройдың алдын алудың ең маңызды жолы — іш қатуға жол бермеу. Талшық пен жасұныққа бай тағамдарға басымдық беріп, су, көкөніс пен жеміс-жидек тұтынуды арттыру арқылы күшенбей, жеңіл дәретке отыруды қамтамасыз ету керек. Егер бұл тәсілдер мәселені шешпесе, дәрігеріңіз тағайындаған нәжісті жұмсартатын қолайлы дәріні қолдануға болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер аяқтарыңыздың аздап ісінгенін байқасаңыз, күн соңында оларды сәл жоғары көтеріп, демалдырыңыз. Белдің ауырсынуын азайту үшін аласа өкшелі әрі ыңғайлы аяқ киім киіңіз. Кальцийге қажеттілігіңіз артқандықтан, рационыңыздағы сүт өнімдері мен жасыл көкөністердің мөлшерін көбейтіңіз. Бүгін бөпеңізге бесік жырын айтып беруге қалай қарайсыз?') WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ұйқы безі инсулин мен глюкагонды тұрақты түрде өндіре бастады. Инсулин бөпеңіздің ұйқы безіндегі Лангерганс аралшаларында орналасқан бета-жасушалардан бөлінеді. Қандағы қант мөлшері қажетті деңгейден артқанда, инсулин оның бауырда гликоген түрінде жиналуын қамтамасыз етеді. Осылайша қандағы қант деңгейін төмендетеді.;;;
Сондай-ақ инсулин қандағы глюкозаның, қажет болғанда аминқышқылдары мен бос май қышқылдарының жасушаларға енуіне көмектеседі. Соның арқасында жасушалар қажетті сәтте энергия алады. Инсулин жеткіліксіз бөлінген жағдайда қандағы қант мөлшері жоғарылап, несеп арқылы сыртқа шығарылады. Бұл жағдай халық арасында қант ауруы деп аталатын қант диабетіне әкеледі. Ал глюкагон ұйқы безінің альфа-жасушаларынан бөлінеді. Ол инсулинге мүлде қарама-қарсы қызмет атқарады. Бауыр мен бұлшықеттерде жиналған гликогеннің қажет кезде қанға өтуін қамтамасыз етіп, қандағы қант деңгейін жоғарылатады. Бұл тепе-теңдік ұзақ уақыт ашыққанда ағзаның энергиясыз қалмауы үшін қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен дәмді ажырата алатын нағыз гурманмын! 😋 Тілімдегі дәм сезу бүртіктері толық жұмыс істеп тұр. Сен ащы бұрыш жегенде мен ықылықтаймын, ал шоколад жегенде белсендірек қимылдаймын. Ғалымдардың айтуынша, сен қазір неғұрлым алуан түрлі тағам жесең, мен өскенде соғұрлым "тамақ талғамайтын" бала боламын. Кел, бірге дұрыс тамақтанайық!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңде шашыңыз түсіп, тырнағыңыз сынса, әлсіздік, тәбеттің төмендеуі, бас ауруы, бас айналу, ентігу, жүректің жиі соғуы, тез шаршау және ашушаңдық сияқты шағымдарыңыз болса, қан талдауын тапсыруыңыз керек. Жүктілік кезіндегі қаназдық әдетте екінші триместрде, бөпе өзіне қажетті темірді анасының ағзасынан алатын кезеңде байқалады. Жүктілік қаназдық қаупін арттырады. Анада пайда болған анемия оның денсаулығына ғана емес, бөпеге де кері әсер етуі мүмкін. Күнделікті тамақтануда темірдің сіңуін жақсарту үшін оның сіңуіне кедергі келтіретін шай, кофе және кола сияқты құрамында кофеин мөлшері жоғары сусындардан бас тартқаныңыз жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңіздің ауырсынуын азайту үшін отырғанда міндетті түрде арқаңызға жастық қойып, тік отыруға тырысыңыз. Тері қышыса, душтан кейін табиғи ылғалдандырғыштарды қолданыңыз. Суды мол ішуді ұмытпаңыз, бұл Сіз үшін де, шарана маңындағы судың жаңаруы үшін де маңызды. Күніңізді өзіңізге ұнайтын хоббимен аяқтаңыз.') WHERE id = 'f309c326-d1e8-4059-8ac7-ab4a84a92059';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тіршілігі үшін аса маңызды әрі оны қоршап тұрған амниотикалық сұйықтық осы кезеңде әр үш сағат сайын жаңарып отырады. Сондықтан ағзаңыздың сусызданбауы бөпеңіздің денсаулығы үшін өте маңызды. Бұл сұйықтықтың 99% судан тұрады, сондай-ақ оның құрамында бейорганикалық тұздар, органикалық заттар және бөпеңіздің ағзасынан бөлінетін заттар бар.;;;
Сонымен қатар бөпеңіз тыныс алу жүйесін дамыту үшін күн сайын өз салмағының төрттен біріне тең мөлшердегі сұйықтықты өкпесіне тартып, жаттығады. Ас қорыту жүйесінде де дәл осындай үдеріс жүреді. Бұл өмірлік маңызы бар сұйықтық бөпеңізді ықтимал жарақаттардан қорғайды, тыныс алу жүйесінің дамуына көмектеседі, еркін қимылдауына мүмкіндік беріп, қаңқасы мен бұлшықеттерінің дамуын қамтамасыз етеді. Сондай-ақ сұйықтықтағы электролиттер тепе-теңдігін сақтайды, иммундық жүйені нығайтады, бөпеге бактерияға қарсы орта қалыптастырады және босанар алдында қағанақ жарылып, су кеткенде бөпенің келуіне дайындық ретінде босану жолын тазартады.;;;
Амниотикалық сұйықтық мөлшері қажетті деңгейден аз болса, бұл олигогидрамнион, ал қажетті деңгейден көп болса, полигидрамнион деп аталады. Амниотикалық сұйықтық аз немесе көп болған жағдайда дәрігердің бақылауынан жиірек өтуіңіз қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жанасу арқылы үйренемін! 🖐️ Қолдарыммен бетіме, аяқтарыма, кіндік бауыма және жатырдың қабырғасына жанасамын. Бұл маған денемнің шекарасын түсінуге көмектеседі. Мен өзімді зерттеп жүрмін. Кейде бас бармағымды сорамын. Бұл мені тыныштандырады. Сен де ішіңе қолыңды тигізгенде, мен сол жылуды сеземін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Сәбіз'), body_changes_kk = COALESCE(body_changes_kk, 'Егер бетіңіз, көзіңіздің айналасы, буындарыңыз бен аяқтарыңыз қатты ісінсе, салмағыңыз кенет әрі тез артса, басыңыз қатты және тоқтаусыз ауырса, көзіңіз бұлдырап көрсе, ішіңіз қатты ауырып, құсу сияқты белгілер байқалса, Сізде преэклампсия болуы мүмкін. Преэклампсия немесе халық арасында жүктілік кезіндегі улану деп аталатын жағдай — жүкті әйелдердің 5%-на әсер ететін ауыр асқыну. Диагноз жүктіліктің 20-шы аптасында қан қысымының жоғарылауынан бөлек, кемінде тағы бір белгі болған жағдайда қойылады. Мұндай белгілерге несепте ақуыздың болуы, бауыр немесе бүйрек қызметінің бұзылыстары жатады. Кейде преэклампсия ешқандай белгісіз де дамуы мүмкін. Қан қысымы біртіндеп көтерілуі немесе кенеттен жоғарылауы мүмкін. Қан қысымын бақылау — босануға дейінгі күтімнің маңызды бөлігі, өйткені преэклампсияның алғашқы белгісі әдетте қан қысымының жоғарылауы болады. 18 жастан кіші және 35 жастан асқан жүкті әйелдерде, артық салмағы бар немесе тым арық әйелдерде, туыстық некедегі жұптарда, бұрын күрделі хирургиялық операция жасатқан пациенттерде, сондай-ақ жүктілікке дейін жүрек ауруы, қант диабеті, жоғары қан қысымы, эпилепсия, қалқанша без немесе басқа аурулары болған әйелдерде жүктілік кезіндегі уланудың пайда болу ықтималдығы жоғары.'), daily_tip_kk = COALESCE(daily_tip_kk, '21-ші аптаның аяқталуын шағын серуенмен атап өтіңіз! Белдің ауырсынуын азайту үшін аласа өкшелі әрі ыңғайлы аяқ киім киіңіз. Ұйықтағанда міндетті түрде сол қырыңызбен жатып, аяқтарыңыздың астына жастық қойыңыз, бұл қан айналымын жақсартады. Суды мол ішіп, рационыңызға талшыққа бай тағамдарды қосуды жалғастырыңыз.') WHERE id = '925057a2-a250-49b9-bcfa-f9f914c5c38f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл апта жүктілігіңіздің 4 ай 3 аптасына сәйкес келеді. Яғни 5-ші айдың аяқталуына небәрі 1 апта қалды! ;;;
Жүктілікті бақылау кезінде Сізді ең көп қызықтыратын тақырыптардың бірі — бөпеңіздің дамуы, осы аптадағы салмағы мен бойы. Ультрадыбыстық зерттеу арқылы анықталған көрсеткіштерді бағалау негізінде есептелетін салмақ пен бойдың медициналық маңызы зор; бұл көрсеткіштер әсіресе бөпеңіздің салмақ қосуын, дамуын және босану тәсілін анықтауға көмектеседі.;;;
Салмағы төмен немесе шамадан тыс ірі болып туған бөпелер босану кезінде немесе одан кейін кейбір асқынулар мен қауіптерге тап болуы мүмкін. Дүниежүзілік денсаулық сақтау ұйымының (ДДСҰ) мәліметі бойынша, салмағы 4500 грамм және одан жоғары бөпелер табиғи жолмен босануға қолайлы деп саналмайды. Әзербайжандағы тәжірибеде бұл жағдай Сіз бен дәрігеріңіздің шешіміне қарай өзгеруі мүмкін, дегенмен салмағы 4 кг және одан жоғары бөпелер үшін көбіне кесарь тілігі ұсынылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Әкемді естіп тұрмын! 👨 Енді тек сенің даусыңды ғана емес, сырттан шығатын төмен үндерді де жақсырақ естимін. Әкем ішіңе жақындап сөйлесе, оның даусын танимын. Оған маған ертегі айтып берсін немесе жай ғана "сәлем" десін деп айтшы. Мен оны да жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Алғашқы айларда байқалған жүрек айну, әлсіздік, бас ауруы және түйілулер сияқты белгілер біртіндеп басылып, өзіңізді физикалық тұрғыдан сергек сезіне бастайсыз. Сонымен қатар екінші триместр — жүктілікке психологиялық тұрғыдан бейімделу басталатын кезең.;;;
Жүктіліктің осы кезеңінде жыныс мүшелеріндегі қан тамырларының көбеюі және қан айналымының жылдамдауы салдарынан жыныстық құштарлық артуы мүмкін. Сондай-ақ жыныстық қатынас кезінде әйелдің оргазмға жетуі бөпеге ешқандай зиян келтірмейді. Керісінше, кейбір зерттеулер оргазм кезіндегі жатыр жиырылуы бөпенің жүрек соғысына оң әсер ететінін көрсеткен.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңіздің төменгі жағында жеңіл қатаюды сезсеңіз, біраз жатып демалыңыз және мол су ішіңіз. Қуатыңыз тұрақты болуы үшін темір мен магний қабылдауды жалғастырыңыз.') WHERE id = 'f395dae9-427a-4c8d-8ba3-bfb8922cadf2';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің шашы өсіп шыққанымен, шаш талдарында әлі пигмент болмағандықтан, олар түссіз болып көрінеді. Шаш негізінен әртүрлі ақуыздардан тұрады және табиғи түсін меланин деп аталатын пигменттен алады. Меланин пигменті ашық түсті шашта да, қою түсті шашта да болады. Шаш түсінің қою немесе ашық болуы меланин пигменттерінің мөлшеріне байланысты. Басқаша айтқанда, меланині көбірек шаш пигменті аз шашқа қарағанда қоюырақ көрінеді. Сонымен қатар шаш денедегі басқа түктерге қарағанда жылдамырақ өседі. Шаштың өсу жылдамдығы тәулігіне орта есеппен 0.3 mm-ден 0.5 mm-ге дейін болады. Ұл және қыз бөпелер дүниеге келген кезде шаш талдарының қалыңдығы бірдей болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен ырғақты сеземін! 🥁 Сен музыка тыңдасаң немесе билесең, мен сол ырғақты сеземін. Тіпті кейде музыканың екпініне сай қимылдауым мүмкін. Баяу музыка мені ұйықтатады, ал жылдам музыка оятады. Менің музыкалық талғамым қалыптасып келеді.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Тәбеттің артуы көбіне жүктіліктің екінші триместрінде, яғни 3-ші айдың басынан 6-шы айдың соңына дейін байқалады. Алғашқы 3 айда гормондар деңгейінің күрт жоғарылауы иістерге сезімталдық пен жүрек айнуын туғызады. Екінші триместрде ағза осы гормондық теңгерімге бейімделіп, жүрек айнуы азайғандықтан тәбет артады. Сондықтан бұл — жүктілік кезінде ең көп салмақ қосылатын кезең. Тәбетіңіз қаншалықты артса да, осы кезеңде дұрыс тамақтанып, майлы, тұзды және қанты көп тағамдардан бас тартуыңыз керек. Сондай-ақ аз мөлшерде, бірақ жиі тамақтану қандағы қант деңгейін тұрақты ұстап, бір мезетте шамадан тыс калория қабылдаудың алдын алады. Дене жаттығулары мен серуендер де осы кезеңде тәбетіңізді бақылауда ұстауға көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Түнде балтырыңыз құрысып қалса, аяқ саусақтарын бірден өзіңізге (тізеңізге) қарай тартып, өкшеңізді алға итеріңіз. Бұл қимыл балтыр бұлшықетін созып, ауырсынуды азайтады. Массаж жасау да пайдалы.') WHERE id = '68f0e92d-9dd8-4759-acc2-0054a8f6a53a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қимылдауы — оның бұлшықеттерін дамытатын ең маңызды факторлардың бірі. Бөпеңіз дүниеге келгенде бұлшықеттерінің салмағы дене салмағының шамамен бестен бір бөлігін құрайды. Жасөспірімдік кезеңге жеткенде бұлшықет салмағы жалпы дене салмағының үштен бірін, ал ересек шақта бестен екісін құрайтын болады. Бұлшықеттердің өсуі жалпы дененің өсуімен қатар жүреді. Бөпелер дүниеге келгенде көз және тыныс алу бұлшықеттері жақсы дамыған болады. Ал қол бұлшықеттері аяқ бұлшықеттеріне қарағанда жақсырақ дамиды. Жасөспірімдік кезеңге дейін ірі бұлшықеттер ұсақ бұлшықеттерге қарағанда жақсырақ жұмыс істейді. Сондықтан балалар ұсақ әрі дәл қимылдарға қарағанда кең ауқымды, ірі қимылдарды оңайырақ орындайды.'), baby_message_kk = COALESCE(baby_message_kk, '🥥 Менің көлемім кокостай! Қазір мен кішкентай ғана бөпемін. Қастарым, кірпіктерім, тырнақтарым — бәрі бар. Ендігі негізгі мақсатым — салмақ қосып, өкпемді дайындау. Мен әлі өте арықпын, бірақ сен мені жақсы қоректендіріп жүрсің.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Қан көлемінің артуы бөпеңіз бен өз денсаулығыңыз үшін қажет. Алайда осыған байланысты аяқтарыңызда варикозды кеңею пайда болуы мүмкін. Варикоз алғашқы жылдары көбіне тек сыртқы көрініс тұрғысынан жайсыздық туғызғанымен, кейін ауырсынуға әкелуі ықтимал. Варикоздың пайда болуына көптеген фактор әсер етеді. Жүктілік, артық салмақ, ұзақ уақыт тік тұру, жүктіліктен сақтануға арналған таблеткалар мен гормондық ем, тар киім кию, іш қату, егде жас және генетикалық факторлар варикозға себеп болуы мүмкін. Варикоздың алдын алу үшін жүйелі түрде жаттығу жасау, ұзақ уақыт тік тұрудан сақтану, аяқты айқастырып отырмау, тым қысып тұратын тар киім кимеу, биік өкшелі аяқкиімнің орнына ыңғайлы аяқкиім таңдау, іш қатудың алдын алу және талшыққа бай тағамдар тұтыну пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Түнде оң жаққа қарағанда сол жақ қырыңызбен жатуға тырысыңыз, бұл жатырға баратын қан ағымын және бүйрек қызметін жақсартады. Аяқтарыңыздағы жеңіл ісінуді азайту үшін тұзды мөлшермен тұтынып, мол су ішіңіз. Ентігу сезілсе, қимылдарыңызды баяулатып, кеудеңізді тік ұстап, терең тыныс алыңыз.') WHERE id = '0192bd32-2239-497b-af81-dc9dc504732a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасындағы эритроциттердің саны біртіндеп артып келеді. Бұл жасушалар ағзада оттегі мен көмірқышқыл газын тасымалдайтын негізгі бөлшектер болып саналады. Олар қандағы барлық жасушалардың 99%-ын құрайды және ашық қызыл түсімен ерекшеленеді.;;;
Бұл жасушалардың түзілуін бүйрек бөлетін эритропоэтин гормоны реттейді. Үдеріс сүйек кемігінде басталады, ал шамамен бір апта ішінде жетілген жасушалар қан айналымына қосылады. Жетілген эритроциттердің ядросы болмағандықтан, олар өте икемді келеді. Дәл осы икемділігінің арқасында олар тіпті ең жіңішке қантамырлардан оңай өтіп, ағзаның әр бөлігіне оттегі жеткізе алады. Эритроциттердің тіршілік ету ұзақтығы небәрі 3 айға созылады. Уақыт өте келе ескірген және зақымданған жасушалар көкбауырда, бауырда және сүйек кемігінде фагоцитоз деп аталатын үдеріс арқылы ыдырап, ағзадан шығарылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сіздің даусыңызды танимын! 🗣️ Anacan, енді Сіздің даусыңызды басқа адамдардың даусынан ажырата аламын. Сіз сөйлегенде мен тынышталып, жүрек соғысым баяулайды. Мен үшін бұл — әлемдегі ең сенімді дауыс. Маған ән айтуды жалғастыра беріңіз, мен оларды "естелік сандығыма" жинап жүрмін. Дүниеге келген соң сол әнді естіп, тыныштала қаламын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Кейбір жүкті әйелдерде жүктілік кезінде безеу мүлде шықпаса, енді бірінде оның көбейгені байқалуы мүмкін. Бұған әдетте қандағы мөлшері едәуір артатын гормондар себеп болады. Гормондар көбейген сайын терінің майлылығы да артады. Осылайша, тері бетіндегі майдың көбеюі безеудің пайда болуының негізгі себептерінің біріне айналады. Жүктілік кезінде қалың макияж жасамау, жеткілікті түрде тазартылмаған макияж құралдары мен қылқаламдарды қолданбау, әсіресе қуырылған тағамдардан және басқа да зиянды өнімдерден бас тарту, тері тазалығына әдеттегіден көбірек көңіл бөлу, жүктілікке қауіпсіз, су негізіндегі ылғалдандырғыштарды пайдалану қажет. Сондай-ақ шыққан безеулерді сығу немесе оларды қолмен ұстай беру ішіндегі іріңнің тері бетіне таралуына және жаңа безеулердің пайда болуына әкелуі мүмкін екенін ұмытпаңыз. Сондықтан бетіңізге көп қол тигізбеңіз және бұл уақытша үдеріс екенін есте сақтаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кешке аяқтарыңызға "салқын душпен" массаж жасаңыз. Қан айналымын жақсарту үшін суды төменнен жоғары қарай бағыттаңыз. Тұзды тағамдардан бас тартыңыз, өйткені тұз ағзада суды ұстап қалады.') WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің репродуктивті жүйесі жетіліп, дамуын жалғастыруда. Егер бөпеңіз ұл болса, осы күндері оның аталық бездерінде сперматозоидтардың түзілу үдерісі басталады. Құрсақтағы бөпеңіздің аталық безі түтікшелерінде орналасқан сперматозоидтардың бастапқы жасушаларында 2n хромосома жиынтығы бар. Яғни олар әлі жетілген сперматозоид құрылымына ие емес және жыныс жасушалары емес, дене жасушалары тәрізді әрекет етеді. Себебі жыныс жасушаларында n, ал дене жасушаларында 2n хромосома жиынтығы болады.;;;
Жасөспірімдік кезеңге жетпеген ұл балаларда сперматозоидтардың бастапқы жасушалары 2n хромосома жиынтығына ие болғандықтан, митоз арқылы көбейеді. Ал жасөспірімдік кезең басталғанда бұл жасушалар белгілі бір деңгейде жетіліп, мейоз арқылы бөлінуге қабілетті құрылымға айналады. Соның арқасында оларда болуы тиіс n хромосома жиынтығы қалыптасады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен бетімді ұстап жатырмын! 🤲 Қолдарыммен бетімді зерттеп жүрмін. Мұрын, иек және көздерімді ұстаймын. Терім әлі өте жұқа, бірақ сезімталдығым жоғары. Бұл қимылдар миымда денемнің картасын қалыптастырады. Мен өзімді тани бастадым. Сіз де ішіңізді сипағанда, мен оны сеземін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Күн соңына қарай аяқтарыңыздың ісінуі күшеюі мүмкін. Бұған ағзада сұйықтықтың жиналуы, қан көлемінің артуы және ыстық ауа райы себеп болады. Сондай-ақ сақинаңыздың саусағыңызды қысып тұрғанын сезуіңіз мүмкін. Бұл — жүктіліктің осы кезеңіне тән қалыпты физиологиялық жағдай. Сонымен қатар түнде аяқтарыңыздың құрысуы мазалауы ықтимал. Бұл қан айналымының баяулауына немесе кальций/магний/калий тапшылығына байланысты болуы мүмкін. Сондай-ақ "Мазасыз аяқтар синдромы" пайда болуы ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қышыған жерлерді тырнақпен қасудың орнына, ылғалдандыратын май немесе крем жағып, алақаныңызбен ақырын сипаңыз. Салқын компресс те қышуды басуға көмектеседі.') WHERE id = 'da8c9afd-1f7d-4478-b2fc-5b192ee0259f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада сүйектену үдерісінің жылдамдауымен бірге бөпеңіздің бас сүйегі қалыптасуын жалғастырады. Бас сүйек төменгі және артқы жағынан омыртқамен жалғасады, ал алдыңғы бөлігі бет сүйектерін ұстап тұрады. Бұл кезеңде бөпеңіздің бас сүйегі әлі толық дамымағанымен, ересек жасқа қарай оның алдыңғы жағынан артқы жағына дейінгі ұзындығы шамамен 18 см, биіктігі 13 см, ал диаметрі 14 см болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүрегім ән салып тұр! ❤️ Дәрігер енді менің жүрек соғысымды арнайы құрылғыларсыз-ақ, жай ғана стетоскоппен ести алады. Жүрегім минутына 140-150 рет соғады. Бұл дыбыс Сіз үшін өмірдің ырғағы ғой, солай емес пе? Менің жүрегім Сіздің арқаңызда осыншама күшті соғып тұр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Жылдам өсіп келе жатқан бөпеңіз кіндік деңгейіне дейін көтерілгендіктен, осы аймақтағы теріңіз созылып, онда созылу белгілері пайда болуы мүмкін. Олар көбіне іштің төменгі бөлігінде байқалғанымен, сан, бөксе, кеуде және қолда да көрінуі мүмкін. Созылу белгілері қызғылт-ақ түсті болып, сырттай тері жарасына ұқсайды. Олар тері бетінде терең емес, шағын ойықтар түрінде көрінеді. Егер теріңіз серпімді болса, алаңдаудың қажеті жоқ. Өйткені серпімді тері созылу белгілерінің пайда болуына бейім емес. Сондықтан қандай да бір өнімді немесе қорғаныш құралын қолданудың қажеті жоқ. Созылу белгілерін азайтудың ең қолайлы тәсілі — арнайы ылғалдандыратын кремдерді немесе бадам майы, өрік дәнінің майы секілді табиғи сыртқа қолданылатын құралдарды пайдалану.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін ішіңізді ақырын уқалап, бөпеңізбен сөйлесіңіз. Ол қолыңыздың қысымы мен жылуын қазірдің өзінде өте жақсы сезеді.') WHERE id = 'aa1f1ed4-15e9-4574-a163-232172e516be';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Сіз жүктіліктің 6-шы айына келдіңіз. Қарқынды салмақ қосу кезеңіне кірген бөпеңіздің ағзалары сыртқы ортаға бейімделе алатындай деңгейде дамыған, ал кішкентай аяқтары дүниеге келетін күнге дейін шамамен екі есе өседі.;;;
Бөпеңіздің рефлекстік қимылдары дамуын жалғастыруда. Сонымен қатар ол кейбір ерікті қимылдарды да жасай бастады. Рефлекс — сыртқы тітіркендіргіштің әсерінен ерікке бағынбай туындайтын физикалық жауап. Бөпеңіз дүниеге көптеген рефлекстік қимылдармен келеді. Алғашқы кезеңде ол бұл қимылдарды еріксіз жасайды және оларды басқара алмайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен салмақ қосып жатырмын! ⚖️ Терім әлі сәл қатпарлы, маған үлкен сияқты. Бірақ мен тез салмақ қосып, сол бос жерлерді толтырып келемін. Жақында сүйкімді бөпе боламын. Сен мені жақсы тамақтандырып жүрсің, рақмет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жүрек-қантамыр жүйеңізде көптеген өзгеріс болады. Әсіресе жүктіліктің алғашқы апталарынан бастап қандағы прогестерон гормонының деңгейі жоғарылап, жүйелік тамырлық кедергіні азайтады, соның салдарынан қан қысымы төмендейді. Алғашқы апталарда көздің қарауытуы, бас айналу және естен тану қан қысымының төмендеуінен болуы мүмкін. Жүректің соққылық көлемі, яғни әр соққан сайын қан айналымына айдайтын қан мөлшері шамамен 50% артады. Бір минутта қан айналымына айдалатын қан көлемі 4,5 литрден 6 литрге дейін көбейеді. Ал тамыр соғысы деп аталатын жүрек соғу жиілігі минутына 70-тен 90-ға дейін артуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'С дәрумені қызыл иекті нығайтады. Киви, қызыл бұрыш, апельсин сияқты тағамдарды жеңіз. Тіс жібін қолданғанда өте абай болыңыз.') WHERE id = '5f95650f-570c-4da1-a06d-ada1c9adbe04';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қимылдарын ең кеш дегенде осы аптаға дейін сезуіңіз керек. Жүктілік ұлғайған сайын оның қимылдары өзгеруі мүмкін. Алғаш сезіле бастаған кездегі әлсіз қозғалыстар осы кезеңде айқынырақ бола түседі.;;;
Бұл кезеңде бөпеңіз көбіне айналасында болып жатқан жағдайларға жауап ретінде қимылдайды. Қатты шу, жарқын жарық немесе оны белсендіретін кейбір тағамдар бөпеңіздің тебуіне және қозғалуына себеп болуы мүмкін. Бұл апталарда бөпеден тұрақты қимыл күтуге әлі ерте. Дегенмен ұзақ уақыт бойы қимылын сезбесеңіз, қандағы қант деңгейін жоғарылататын тағам жеп, тыныш жерде сол жақ қырыңызбен жату көмектесуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тепе-теңдік шеберімін! 🤸‍♂️ Құлағымдағы тепе-теңдік мүшесі толық жұмыс істеп тұр. Сен қозғалғанда, мен де іште тербелемін. Бұл мен үшін нағыз аттракцион!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қаназдық деп аталатын темір тапшылығы анемиясының пайда болу ықтималдығы өте жоғары. Гемоглобин мөлшерінің төмендеуі кейде ешбір белгісіз өтуі мүмкін. Жиі кездесетін белгілерге терінің бозаруы, әлсіздік, шаршау, зейіннің бұзылуы, бас ауруы, қол-аяқтың ұюы, ашушаңдық, құлақтың шыңылдауы, еріннің жарылуы мен ауыз бұрыштарындағы жаралар, шаштың түсуі, тырнақтың жұқаруы және тез сынуы жатады. Темір тапшылығы күшейгенде жүректің қатты соғуы, топырақ немесе мұз жегіңіз келуі, қалқанша без қызметінің баяулауы және "мазасыз аяқтар" синдромы сияқты жағдайлар туындауы мүмкін.;;;
Анемияның алдын алу үшін күніне кемінде 2-3 порция құрамында темір бар тағам жеуге тырысыңыз. Темірге бай тағамдарға ішкі ағзалар (бауыр және т.б.), ет, жасыл көкөністер, мейіз, қою жеміс шәрбаты, орман жаңғағы, жержаңғақ, жұмыртқа және кептірілген бұршақ тұқымдастар жатады. Темір препараттарын немесе құрамында темір бар тағамдарды апельсин шырынымен, қызанақ шырынымен не салатпен бірге тұтыну темірдің ағзаға сіңуін жақсартады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жамбас ауыруын азайту үшін Кегель жаттығуларын жасаңыз, олар бұлшықеттерді босануға да дайындайды. Ішіңіздің керілгенін сезсеңіз, сәл жылы душ қабылдаңыз — бұл Сізді де, бөпеңізді де тыныштандырады.') WHERE id = '3837da99-9708-4d97-b55a-0f688693e446';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадан бастап бөпеңіз қарқынды өсу кезеңіне кіреді. Бұл бөпеңіз тек осы аптаның өзінде шамамен 150 грамм салмақ қосады дегенді білдіреді. Осы аптаның соңына қарай бұлшықеттерінің күшеюіне, жатырдың ұлғаюына және қағанақ суы мөлшерінің артуына байланысты бөпеңіз бұрынғыдан да белсенді болады. Егер түні бойы тыныш ұйықтауды жоспарласаңыз, жоспарыңыз орындалмауы мүмкін. 😊 Бұл кезеңде тәулігіне шамамен 18 сағат ұйықтайтын бөпеңіз түнде белсендірек болады. Себебі күндіз Сіздің қозғалыстарыңыздан қағанақ суы толқын тәрізді тербеліп, бөпеңізді ұйқыға бөлейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Көздерім қозғалып жатыр! 👀 Қабақтарым әлі жабық болса да, көздерім олардың астында оңға-солға жылдам қозғалады. Бұл менің түс көріп жатқанымды білдіреді. Түсімде сені көріп жатқан шығармын. Мен түрлі-түсті түстер әлеміндемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Осы апталардан бастап ентігу мен ауа жетпей жатқандай сезім пайда болуы мүмкін. Бұған жатырдың ұлғаюы және гормондық жүйедегі өзгерістер себеп болады. Жүктілік кезінде бөпеңіздің өсуімен бірге кеңейген жатыр көкетті қысады. Сонымен қатар, әсіресе жүктіліктің соңғы кезеңдерінде көкет шамамен 4 см жоғары көтеріледі. Бұл өкпенің қысылуына және жұтылатын ауа көлемінің өзгеруіне әкеліп, ентігуді туындатады.;;;
Ал прогестерон гормоны белсендіретін мидағы тыныс алу орталығы жүктілік кезінде жиірек әрі тереңірек тыныстауды қамтамасыз етеді. Бұл плацентаға көп мөлшерде оттегі жеткізіп, көмірқышқыл газының қарқынды шығарылуы үшін қажет. Өкпенің әр тыныс алғанда әдеттегіден %30-40 көбірек ауа жұтып, шығару жиілігі тыныс алудың қиындауына және ентігуге себеп болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңыздағы ісінуді азайту үшін бір қалыпта ұзақ тұрмаңыз, ал отырғанда аяқтарыңызды жоғары көтеріңіз. Беліңіз ауырса, сол жақ қырыңызбен жатып, тізелеріңіздің арасына жастық қойыңыз. Суды молынан ішуді жалғастырыңыз, өйткені бұл ісінудің алдын алып қана қоймай, қағанақ суының тазалығын да қамтамасыз етеді. Бүгін өзіңізге аздап уақыт бөліп, тыныштандыратын музыка тыңдаңыз.') WHERE id = 'fd7b3482-d799-4c13-953a-cf2d0bbea122';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің есту қабілеті толық қалыптасқан сайын, ми нейрондары арасындағы байланыстардың түзілу үдерісі жеделдейді. Енді бөпеңіздің миы ересек адамның миы сияқты бес негізгі бөліктен тұрады және олардың әрқайсысы өз қызметін атқарады:;;;
Маңдай бөлігі: Саналы ойлау мен эмоцияларды басқаруға жауап береді.;;;
Төбе бөлігі: Сезім мүшелерінен келетін ақпаратты біріктіріп, кеңістікті қабылдауды қамтамасыз етеді.;;;
Шүйде бөлігі: Көру сезіміне қатысты ақпарат өңделетін орталық.;;;
Самай бөлігі: Дыбыстар мен иістерді қабылдауды, бет-әлпет пен орындарды тануды қамтамасыз етеді.;;;
Мишық: Тепе-теңдікті сақтап, қимылдарды сезімдермен үйлестіреді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің көлемім грейпфруттай! Салмағым шамамен 370 грамм, ал бойым 27.1 см. Терім әлі де әжімді, өйткені мен өте жылдам өсіп жатырмын, ал май қабатым терімді әлі толық толтырған жоқ. Бірақ уайымдамаңыз, дүниеге келгенше сүйкімді, томпақ бөпе боламын. Қазір менің басты міндетім — салмақ қосу!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Қандағы прогестерон гормонының мөлшері артуына байланысты асқазанның босау үдерісі баяулап, ішектің қимылы төмендейді. Соның салдарынан іш қатуы мүмкін.;;;
Бұл кезеңде ас қорыту жүйесі де ең көп өзгеріске ұшырайтын жүйелердің бірі. Гормондық өзгерістерге байланысты асқазан сөлінің қышқылдығы артуы, өңештің толқын тәрізді қимылдарының азаюы, асқазан қақпақшаларының босаңсуынан рефлюкстің пайда болуы және әсіресе жүктіліктің соңғы 3 айында үлкейген жатырдың асқазанды жоғары қарай ығыстыруы салдарынан тағамның қорытылуы баяулауы мүмкін.;;;
Осы үдерісте дене көлемі ұлғайғандықтан, бүйректер де үлкеюі мүмкін. Салмағы артқан бүйректерде несептің ағуы баяулап, оны бүйректен қуыққа жеткізетін өзектер кеңейеді. Сондықтан жүктілік кезінде несеп шығару жолдарының инфекциялары жиі кездеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Демалыс күні болғандықтан, өзіңізге көбірек уақыт бөліңіз. Ентігуді сезінбеу үшін тік отыруға және ұйықтағанда арқаңызға қосымша жастық қоюға тырысыңыз. Тәбеттің артуын пайдалы жаңғақтар мен кептірілген жемістердің көмегімен бақылаңыз. Ертең жаңа апта басталады, сондықтан бүгін кешке бөпеңізге арнап тыныштандыратын әуендер тізімін дайындаңыз.') WHERE id = 'dcc1b63f-cc53-4d60-9050-ad76c211d2c4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл апта — екінші триместрдің соңғы айының алғашқы аптасы. Қарапайым тілмен айтқанда, екінші триместрдің аяқталуына небәрі 1 ай қалды.;;;
Осы аптадан бастап май қабатының түзілуі жеделдейді, бірақ соңғы триместрмен салыстырғанда әлі де баяуырақ жүреді. Сондықтан бөпеңіздің терісі бұрынғыға қарағанда азырақ әжімді көрінеді. Май тіні жылдам көбейген сайын, терісіндегі әжімдер де біртіндеп азаяды. Өз көлемінен 6 есе үлкейе алатын май жасушаларының саны бөпеңіз жасөспірімдік кезеңге жеткенше 40 миллиардтан 100 миллиардқа дейін өзгереді. Қазірден қалыптасып, пішінделе бастаған бұл жасушалар тіршілік үшін өте маңызды және ағзаның энергетикалық жүйесін қолдайды. Сондай-ақ майдың арқасында майда еритін A, D, E және K дәрумендері ағзаға сіңеді. Бұдан бөлек, май ағзада кальцийдің сақталуына көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жаттығып жатырмын! 🏋️‍♂️ Anacan, қимылдарым қазір күшейе түсті. Кейде ішіңіздің бір жағы томпайып немесе қозғалып тұрғанын байқауыңыз мүмкін. Бұл менің шынтағымды немесе тіземді Сізге қарай итеріп жатқаным. Осылайша мен Сізге "Мен осындамын!" деймін. Сіз де қолыңызды қойған кезде мен тыныштала қаламын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Әсіресе кешкі уақытта аяқтарыңыздың әдеттегіден үлкенірек болып кеткенін байқауыңыз мүмкін. Жүктілік кезіндегі аяқ көлемінің ұлғаюы көбіне уақытша құбылыс. Оның негізгі себептерінің бірі — ағзада сұйықтықтың жиналуынан пайда болатын ісіну. Әсіресе соңғы айларға қарай ағзада судың іркілуі салдарынан қол мен аяқ ісінуі мүмкін. Соның нәтижесінде бұрын ыңғайлы болған аяқ киіміңіз тарлық ете бастайды. Тағы бір себебі — жүктілік кезінде шамадан тыс немесе тым жылдам салмақ қосу. Мұндай жағдайда аяқта жиналған майдың әсерінен аяқтарыңыз қаттырақ ісінгендей сезіледі. Аяқ көлемінің ұлғаюының тағы бір себебі — релаксин гормоны. Бұл гормон босану кезінде бөпенің босану жолынан өтуі үшін жамбас сүйектерінің айналасындағы және бүкіл денедегі дәнекер тіндердің жұмсарып, босаңсуына ықпал етеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңізді суретке түсіруге таптырмас уақыт! "Before/After" (Дейін/Кейін) коллаждарын жасауға бұл апталар өте қолайлы, өйткені ішіңіз қазір жинақы әрі дөңгеленген.') WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесінде сурфактант деп аталатын зат бөліне бастады. Қарапайым тілмен айтқанда, сурфактант — сұйықтықтың беттік керілуін азайтатын зат. Яғни ол өкпенің тыныс алу қызметін атқара бастауы үшін өте маңызды.;;;
Өкпесінде сурфактант өндіріле бастаған бөпеңіз осының арқасында өміршеңдік шегіне едәуір жақындады. Өкпеде біртіндеп көбірек өндірілетін сурфактант 37-аптаға қарай бөпеңіздің өкпесінің толық жетілуін қамтамасыз етеді.;;;
Мерзімінен бұрын туған шала бөпелердің өкпесінде сурфактант жеткіліксіз болады. Сурфактант тапшылығына байланысты өкпе тыныс алу қызметін толық атқара алмайды, сондықтан өкпені жасанды желдету аппараты қажет болуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен әлемді тыңдап жатырмын! 🌍 Енді тек Сіздің даусыңызды ғана емес, сырттағы қатты дыбыстарды да естимін. Ит үрсе, көлік сигнал берсе немесе шаңсорғыш жұмыс істесе, мұның бәрін сеземін. Кейде бұл дыбыстардан қорқып, селк ете қаламын. Сіз тыныш болсаңыз, мен де тынышпын. Біздің әлеміміз ортақ.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, '20-апталардың ортасына жақындаған сайын Брэкстон-Хикс деп аталатын жалған толғақтар пайда болуы мүмкін. Брэкстон-Хикс жиырылулары жатыр бұлшықеттерінің ширығуынан туындайды және жүктіліктің екінші триместрінің кез келген уақытында басталуы мүмкін. Нақты босану толғағынан айырмашылығы, бұл жиырылулардың қарқындылығы мен жиілігі әртүрлі болады. Олар әсіресе кешкі уақытта және шаршаған кезде жиірек пайда болуы мүмкін. Жалған толғақты нақты босану толғағынан ажырататын басқа белгілер: жалған толғақ ретсіз болады, уақыт өте жиілемейді, біртіндеп әлсірейді, дене қалпын өзгерткенде басылады және көбіне іштің алдыңғы жағында сезіледі. Бұл жиырылуларды жеңілдету үшін демалыңыз, серуендеңіз, жеткілікті мөлшерде су ішіңіз және беліңізге массаж жасаңыз. Жылы душ қабылдау да толғақтан туындайтын жайсыздықты азайтуы мүмкін. Егер жиырылулар белгілі бір аралықпен қайталанып, жиілігі мен қарқындылығы біртіндеп артып жатса, жақын жердегі медициналық мекемеге жүгіну қажет болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер жалған толғақтар Сізді мазаласа, бір стақан су ішіп, сол қырыңызбен жатып демалыңыз. Көбіне сусыздану немесе шаршау бұл жиырылуларды күшейтеді.') WHERE id = '97aa8d6c-1084-4919-a563-80230748cb6e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ағзасы өте аз мөлшерде болса да, антиденелер өндіре бастады. Бұл иммундық жүйесі әлі толық қалыптаспағанымен, оның негізі қаланып жатқанын білдіреді. Антиденелер — ағзаға түскен зиянды бактерияларға, микробтарға және бөгде заттарға жауап ретінде түзілетін пайдалы заттар. Ағзаның табиғи қорғаныс механизмі саналатын антиденелер иммундық жүйенің негізгі құрамдас бөліктерінің бірі болып табылады.;;;
Бөпеңізді туған сәтінен бастап алғашқы сүтіңіз — уызбен (колострум) емізу өте маңызды. Уыздың құрамында бөпе өзі өндіре алмайтын антиденелер бар. Олар қоректену кезінде жіңішке ішек арқылы сіңіп, бөпеңіздің қанына өтеді, иммундық жүйесінің дамуына көмектеседі және оны сырттан келетін зиянды микроорганизмдерден қорғайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен түс көріп жатырмын ба? 💤 Ми толқындарым менің "REM ұйқысында" екенімді көрсетеді. Бұл кезде көздерім жұмулы болғанымен, көз алмаларым жылдам қозғалады. Ғалымдар мұны түс көрудің белгісі дейді. Түсімде не көріп жатырмын? Мүмкін, сенің даусыңды, мүмкін, қағанақ суының дәмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Егжей-тегжейлі ультрадыбыстық зерттеу жүктіліктің 19-шы және 23-ші апталары аралығында жүргізіледі. Бұл кезеңде бөпенің ағзалары қалыптасып, қағанақ суының мөлшері артатындықтан, анық әрі егжей-тегжейлі кескіндер алуға болады. Бұл зерттеудің мақсаты — бөпенің дамуын бақылау және қандай да бір ауытқулардың бар-жоғын анықтау. Заманауи ультрадыбыстық құрылғылардың көмегімен кейбір даму ауытқулары немесе хромосомалық ақаулар байқалуы мүмкін. Тексеру кезінде бөпенің бассүйегі мен миы, омыртқа жотасы, кеуде қуысының ішкі құрылымдары, құрсақ қуысы ағзалары, асқазаны мен ішектері, жүрегі, қолдары мен аяқтары, сондай-ақ плацента сияқты әрбір құрылым жеке-жеке және егжей-тегжейлі зерттеледі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңызды қабырғаға тіреп жоғары көтеріңіз де, 15 минут жатыңыз. Бұл қанның кері ағуына көмектесіп, ісінуді азайтады. Тұзды тағамдарды азайтыңыз, бірақ суды аз ішпеңіз!') WHERE id = 'aebe9763-3910-4530-99d7-d5c87283c426';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ішкі құлағы дамып, есту қабілеті қалыптасқандықтан, мидың естуге жауап беретін бөлігі басқа бөліктеріне қарағанда жақсырақ жетілген.;;;
Қаңқа жүйесі мен бұлшықеттерінің нығайғаны сонша, қимылдары құрсақ қабырғасы арқылы сезіліп, тіпті көрінуі мүмкін. Ұрықтың омыртқа жотасы қатайып келеді. Қан тамырларының, әсіресе өкпедегі тамырлардың дамуы жалғасуда.'), baby_message_kk = COALESCE(baby_message_kk, 'Тепкілерім күшейіп келеді! 🥋 Anacan, сезіп тұрсың ба? Мен енді жай ғана "жүзіп" жүрген жоқпын, нақты соққылар жасап жүрмін. Кейде саған мен каратэмен айналысып жатқандай көрінуім мүмкін. Бұл қимылдар менің денім сау екенін көрсетеді. Менің қимылдарымды санай бастасаң болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің 24-ші және 28-ші апталары аралығында жасалатын глюкозаға төзімділік сынағы қандағы қант деңгейін тексеріп, диабет қаупінің бар-жоғын анықтауға көмектеседі. Жүктілікке дейін диабеті болмаған және оның белгілерін сезбеген әйелдің өзінде жүктілік кезінде инсулин теңгерімінің бұзылуына байланысты диабет пайда болуы мүмкін. Гестациялық диабет деп аталатын бұл жағдай жүкті әйелдердің шамамен 10%-інде кездеседі.;;;
Сонымен қатар жүктілікке дейін диабеті болған әйелдерге жүктілік кезінде қандағы қант деңгейін бақылауда ұстау қиындай түсуі мүмкін. Сондықтан диабеті бар жүкті әйелдер жүйелі түрде тексеріліп, ұсынылған тамақтану тәртібін сақтап, тиісті ем қабылдауы қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Пайдалы тіскебасар: жаңғақ, мейіз, кептірілген өрік немесе бір кесе йогурт. Бұл тағамдар әрі тоқ ұстайды, әрі бөпеге қажетті дәрумендерді береді. Фастфудтан аулақ болыңыз: ол тек бос калория беріп, артық салмақ қосуға әкеледі.') WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің денесінде қалыптаса бастаған май тіні ересек адамның денесіндегі майдан ерекшеленеді. Көпшілік біле бермегенімен, май жасушаларының екі түрі бар: ақ және қоңыр май. Ақ және қоңыр май жасушаларының негізгі айырмашылығы — олардың түсінде. Ақ май жасушасының ішінде бір үлкен липид, яғни май тамшысы болады. Осы майлы қабат жасушаға өзіне тән түс береді. Ақ май энергияны жинақтайды және ішкі ағзаларға жұмсақ тірек әрі қорғаныш қызметін атқарады. Сонымен қатар бұл жасушалар эстроген мен лептин секілді көптеген гормондарды өндіреді және инсулин сияқты басқа гормондардың қызметіне де қатысады. Осы кезеңде бөпеңіздің ағзасында негізінен қоңыр май жасушалары түзіледі. Бұл жасушаларда бір ірі май тамшысының орнына аз мөлшердегі ұсақ май тамшылары мен көптеген митохондриялар болады. Олардың түсінің қою болуы құрамындағы темір элементіне де байланысты. Ақ май жасушаларынан айырмашылығы, қоңыр май жасушалары денені жылы ұстау үшін белсенді түрде жылу өндіреді. Бұл әсіресе өзін жылыту үшін жеткілікті қимыл жасай алмайтын бөпелер үшін өте пайдалы.'), baby_message_kk = COALESCE(baby_message_kk, 'Тепе-теңдігімді сақтап жүрмін! ⚖️ Құлағымдағы "вестибулярлық аппарат" толық жұмыс істейді. Енді басымның төмен немесе жоғары қарап тұрғанын сезе аламын. Сен қозғалғанда, мен де тепе-теңдігімді сақтаймын. Біз бірге билей аламыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің басынан аяғына дейін Сіздің де, бөпеңіздің де қажеттіліктеріне сай ағзаңыздағы гормондық теңгерім толығымен өзгереді. Олардың қатарына hCG, эстроген, прогестерон, релаксин, окситоцин және LH гормондары жатады.;;;
Эстроген ағзаны бөпені көтеруге және емізуге дайындауда маңызды рөл атқарады. Сонымен қатар эмбрионның жатырдың ішкі қабатына дұрыс бекінуіне ықпал етеді. Жүктілік кезінде деңгейі қалыпты көрсеткіштен 50 есеге дейін жоғарылайтын бұл гормон жатыр бұлшықеттері мен емшектегі сүт түтіктерінің өсуіне, сондай-ақ жатырға жеткілікті қан баруына көмектеседі. Эстроген теріге түс беретін пигментті өндіруші меланоцит жасушаларының белсенділігін де арттырады. Сондықтан жүктілік кезінде емізік ұштары мен қынаптың түсі қоюланып, бетте секпілдер және "жүктілік маскасы" деп аталатын дақтар пайда болуы мүмкін. Эстроген қан айналымына да әсер етеді әрі жыныстық белсенділікке деген қалауды күшейтуі мүмкін.;;;
Жүктілік кезіндегі тағы бір маңызды гормон — прогестерон. Оның негізгі міндеті — бөпеңіз орналасқан жатырдың ішкі қабатын жүктілікке бейімдеу. Бұл қызметті ол эстрогенмен бірге атқарады. Прогестерон жүктілік кезінде бұлшықеттерді де босаңсытады. Әсіресе жатыр бұлшықеттерінің қажетсіз жиырылуын тежеп, жүктіліктің мерзімінен бұрын аяқталу қаупін азайтады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентігу сезілсе, қолдарыңызды желкеңізге қойып, терең тыныс алыңыз — бұл кеуде қуысының көлемін уақытша ұлғайтады. Түнде жайлы ұйықтау және жамбас ауыруын азайту үшін тізелеріңіздің арасына жастық қойыңыз. Суды жеткілікті ішумен қатар, бұлшықет кернеуін азайту үшін ас мәзіріңізге калийге бай тағамдарды көбірек қосыңыз.') WHERE id = 'b80a4824-be4e-45cc-b6d6-5d38c928227c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бүкіл денесін тор секілді қоршаған қан тамырлары жүйесі қазір қарқынды дамып жатыр. Елестетіп көріңізші, адам ағзасындағы қан тамырларының жалпы ұзындығы шамамен 100 000 km — бұл Жер шарын екі реттен артық айналып шығуға жететін таңғажайып қашықтық! Бұл керемет тасымалдау жүйесі үш түрлі "жолдан" тұрады: Артериялар — ағзаның "жоғары жылдамдықты магистральдары". Олар жүректен шыққан, оттегіге бай қанды бүкіл денеге жеткізеді. Ең үлкен әрі ең мықты артерия — қолқа жүректен шығып, қанды ұсақ тармақтарға таратады. Артериялар жүректің әр соққысында пайда болатын қысымға төтеп беру үшін әрі бұлшықетті, әрі серпімді болады. Веналар — оттегін жұмсап болған қанды қайтадан жүрекке жеткізетін "жинақтаушы жолдар". Веналардың өте қызық бір ерекшелігі бар: олардың ішінде кішкентай әрі нәзік қақпақшалар орналасқан. Бұл қақпақшалар қанның тартылыс күшінің әсерінен кері ағуына жол бермей, оның тек жүрекке қарай қозғалуын қамтамасыз етеді. Капиллярлар — артериялар мен веналарды байланыстыратын, тіпті қылдан да жіңішке микроскопиялық тамырлар. Олардың қабырғалары соншалықты өткізгіш әрі нәзік болғандықтан, жасушалар дәл осы тамырлар арқылы қоректеніп, қалдық заттардан тазарады. Капиллярлар ағзамыздың әрбір тінінде кездеседі және зат алмасудың негізгі орталығы саналады.'), baby_message_kk = COALESCE(baby_message_kk, 'Тырнақтарым өсіп жатыр! 💅 Қолымдағы тырнақтарым саусақтарымның ұшына жетуге жақын қалды. Олар өте жұқа әрі өткір. Кейде байқамай бетімді тырнап аламын. Бірақ терім тез жазылады. Мен күн өткен сайын Сізге көбірек ұқсап келемін, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпеңіздің ерекше жылдам өсуіне және оны қоршаған жатырдың жоғары қарай көтерілуіне байланысты денеңіздің ауырлық орталығы өзгереді.;;;
Аяқтың құрысуы әсіресе жүктіліктің екінші және үшінші триместрлерінде жиі кездесетін ауырсыну түрі. Мұндай құрысу аяқтағы қан тамырлары немесе жүйкелер қысылған кезде пайда болуы мүмкін. Тамақтану арқылы магнийге деген күнделікті қажеттілікті өтей алмау да аяқтың құрысуына себеп болуы ықтимал.;;;
Ал арқа мен белдің ауыруы жүкті әйелдердің шамамен үштен екісінде кездеседі. Әдетте бұл үлкейген іштің бел бұлшықеттеріне күш түсіруінен және дене қалпының өзгеруінен туындайды. Ауырсынуды азайту үшін жылы душ қабылдау, белге арналған корсет тағу, арқаны тірейтін орындықтарға отыру, ұзақ уақыт тік тұрып немесе бір қалыпта қалмау, оң немесе сол қырыңызбен жатқанда аяқтарыңыздың арасына жастық қою және оқыс қимылдардан сақтану қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қабаттап киініңіз. Ыстықта сыртқы қабатын шешіп қоя аласыз. Теріңіз тыныс алуы үшін табиғи маталардан (мақта, зығыр) тігілген киім киіңіз. Суды мол ішіп, дене температураңызды реттеңіз.') WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз дүниеге ми басқаратын еріксіз рефлекстік қимылдармен келеді. Оларға Моро рефлексі, қармау рефлексі, селк ету рефлексі, табан рефлексі, қадам басу рефлексі, ему және іздеу рефлекстері жатады.;;;
Бөпе өзін құлап бара жатқандай сезінгенде, қолдарын алға созып, алақандарын ашады да, саусақтарын барынша жаяды. Содан кейін бір нәрсені құшақтағандай қолдарын біріктіреді. Аяқтары бос болса, оларды да дәл осылай қозғалтады. Бұл Моро рефлексі деп аталады және туғаннан кейін көп ұзамай жоғалады.;;;
Селк ету рефлексі бөпенің жанында қатты немесе күтпеген дыбыс шыққанда байқалады. Соның әсерінен бөпенің денесі ширығып, иықтары бүгіліп, қолдары ықтимал қауіптен қорғанғысы келгендей жоғары көтеріледі. Қорғануға бағытталған бұл рефлекс басқа рефлекстер секілді жоғалмайды, керісінше, өмір бойы нығайып, дами береді.;;;
Ал ему рефлексі туғаннан кейін бөпенің аузының жоғарғы бөлігіне бір нәрсе тиген кезде іске қосылады. Бұл бөпенің ана сүтімен қоректену үшін емшек ұшын жеткілікті түрде мықтап ұстауына мүмкіндік береді. Бұл рефлекс 3-4 ай ішінде ерікті қимылдарға ауысады.;;;
Осы рефлекстердің кейбірі біраз уақыттан кейін жоғалуы мүмкін. Ал сақталып қалған еріксіз қимылдардың орнын мидың дамуына қарай саналы, ерікті әрекеттер басады.'), baby_message_kk = COALESCE(baby_message_kk, 'Ішіңіз неге секіріп жатыр? 🐇 Anacan, сездіңіз бе? Мен жаңа ғана ықылықтадым! Көкетім жаттығып жатыр, сондықтан денем ырғақты түрде қозғалады. Бұл Сізге ішіңізде сағат тықылдап тұрғандай оғаш сезілуі мүмкін. Уайымдамаңыз, бұл маған ауыртпайды, керісінше, өкпемді нығайтады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңде бөпеңізге темір өте қажет. Соның салдарынан ағзаңызда темір тапшылығы пайда болуы мүмкін. Егер әлсіздік, шаршау және бозару секілді шағымдарыңыз болса, дәрігеріңіз темір деңгейін тексеру үшін талдаулар тапсыруды ұсынуы ықтимал. Өсіп келе жатқан бөпеңіз бен плацентаға қосымша темір қажет болады. Әйелдердің көпшілігі жүктілікті осы қажеттілікті өтеуге жеткілікті темір қорымен бастамайды. Әсіресе екінші және үшінші триместрлерде темірге деген қажеттілік едәуір артады және оны тек тамақтану арқылы өтеу мүмкін болмайды. Дәрігер ұсынған темір препаратын қабылдаумен қатар, ет тағамдарымен бірге лимон шырыны қосылған салаттарды таңдау және көкөніс тағамдарын С дәруменіне бай салаттармен бірге жеу темірдің сіңуін арттырады.'), daily_tip_kk = COALESCE(daily_tip_kk, '23-аптаның сәтті аяқталуын өзіңізді еркелетіп атап өтіңіз! Белдің ауырсынуын азайту үшін аласа өкшелі аяқкиім киіп, ұзақ уақыт бір қалыпта тұрмаңыз. Бөпеңіздің сүйектері сау дамуы үшін кальций мен D дәруменін жеткілікті қабылдауға көңіл бөліңіз. Ертең жаңа аптаны — 24-аптаны бастаймыз!') WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Құттықтаймыз! Бөпеңіз өміршеңдік шегіне жетті. Бұл апта мерзімінен бұрын туған бөпелердің ауруханадағы жаңа туған нәрестелерге арналған қарқынды терапия бөлімінің мүмкіндіктеріне қарай тірі қалу ықтималдығы пайда болатын кезең саналады.;;;
Бөпеңіздің осы аптадан бастап өміршеңдік шегіне жетуінің ең маңызды себебі — өкпе дамуының шешуші кезеңге өтуі. Өкпеде қалыптасқан тыныс жолдарының тармақтары енді ауа қапшықтарымен байланысқан. Сонымен қатар ауа қапшықтарының ішкі бетін қаптайтын сурфактант өндіріле бастады. Сурфактант тыныс алу және дем шығару кезінде өкпедегі беткейлік керілуді азайтып, ауа қапшықтарының басылып қалмауын қамтамасыз етеді. Сурфактанттың өндірілуі осы аптада басталғанымен, қалыпты жағдайда бұл үдеріс 38-аптада аяқталады. Сондықтан мерзімінен бұрын босану қаупі бар жүктіліктің 24-34 аптасында уақыт ұту үшін босануды әртүрлі тәсілдермен тоқтатуға тырысады және сурфактант өндірілуін арттырып, өкпенің жетілуін жеделдететін кортизон құрамды дәрілер егіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тыңдап жатырмын! 👂 Anacan, үйдегі шаңсорғыштың дауысы өте қатты, солай емес пе? Мен енді қатты дыбыстардан селк етемін. Бірақ Сіздің жайлы даусыңыз мені тыныштандырады. Сіз менімен сөйлескенде, тыңдау үшін қимылымды тоқтата аламын. Біздің алғашқы диалогтеріміз басталып жатыр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен грейпфрут'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіздегі қимылдарды енді сырттан да көруге болады. Теріңіздегі пигментация қоюлана түсуі мүмкін. Сондай-ақ кіндігіңіз ішке кіріп тұрудың орнына сыртқа қарай шығып, "түйме" секілді көрінуі ықтимал. Бұл жатырдың қысымынан болады. Дене температураңыз әдеттегіден жоғары болуы мүмкін. Сіз тез терлейсіз. Денеңізге "ыстық құйылғандай" сезінуіңіз ықтимал. Бұл зат алмасудың жылдамдауына және қан айналымының артуына байланысты. Сондықтан салқын жер іздеуіңіз мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы аптада глюкозаға төзімділік тестін (OGTT) тапсыруды дәрігеріңізбен жоспарлаңыз. Іш терісінің қышуын және созылу іздерін азайту үшін ылғалдандырғыш кремдерді тұрақты қолдануды ұмытпаңыз. Бүгін өзіңізді қатты шаршатпаңыз, әр 1 сағат сайын аяғыңызды созып, 10 минут демалыңыз.') WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қылтамырлары қалыптаса бастады. Егер бөпеңізді көре алсаңыз, оның жұқа терісінің астында пайда болған тамырларды анық байқар едіңіз. Бұл тамырлар бастан аяқ саусақтарының ұшына дейінгі әрбір мүше мен тінге жетіп тұр.;;;
Бүкіл денеде тор секілді орналасқан қылтамырларды бір-біріне жалғағанда, олардың жалпы ұзындығы 40 километрден асуы мүмкін. Қылтамырлардың жалпы беткей ауданы басқа тамырларға қарағанда ең үлкен болғандықтан, олардағы қан ағымының жылдамдығы ең баяу болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің шашым түске еніп жатыр! 🎨 Осы уақытқа дейін шашым аппақ еді, ал енді генетикалық кодыма сәйкес түс ала бастады. Қара, сары, қоңыр... Қандай түсті болар екен? Мүмкін, Сіздікіндей, мүмкін, әкемдікіндей болар. Бұл да бір тосынсый!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің шамамен 10%-ы мерзімінен бұрын босанумен аяқталады. Сондықтан шынайы толғақ белгілерін жалған толғақ белгілерінен ажырата білуіңіз керек.;;;
Әдетте бел тұсынан басталатын тұрақты немесе белгілі бір уақыт аралығында қайталанатын ауырсыну, жиі әрі ырғақты жиырылу сезімі, іштің төменгі бөлігіндегі толғақ тәрізді ауырсыну, іш өту мен жүрек айну, қынап пен тік ішек аймағындағы қысым сезімі, қынаптан бөлінетін бөлінді мөлшерінің едәуір артуы және қан кету босанудың басталғанын білдіруі мүмкін.;;;
Жалған толғақ тұрақты аралықпен қайталанбайды. Дене қалпын өзгерткенде немесе қозғалғанда көбіне басылып қалады. Ал шынайы толғақ кезінде дене қалпын өзгерту мен қозғалу ауырсынуды жеңілдетпейді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қолдарыңыздың ұюын азайту үшін оларды жиі сілкіп тұрыңыз. Ұйықтағанда қолдарыңызды бүкпеуге тырысыңыз. Компьютермен жұмыс істесеңіз, жиі үзіліс жасаңыз. Босанғаннан кейін бұл белгілер басылады.') WHERE id = '5496d151-ca1f-41e0-a2f7-53fb1cdf1218';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің аузының айналасы мен ұртына тигенде аузын ашуға түрткі болатын ему рефлексі осы кезеңде айтарлықтай күшейеді. Бөпе өмір сүруі үшін ана сүтін еме алуы керек. Сондықтан бөпеге ешкімнің үйретуі қажет емес: ол ему рефлексінің арқасында қоректенеді. Бөпеңіз ему рефлексін тек қоректену үшін ғана емес, өзін қауіпсіз сезіну үшін де қолдана алады.;;;
Бөпелердің барлығы дерлік күшті ему рефлексімен дүниеге келеді. Бөпеде бұл рефлекстің болмауы өте күрделі себептердің бар екенін көрсетуі мүмкін. Босану кезіндегі жарақаттар, миға оттегінің жетіспеуі, ми бағанының бұзылыстары, жүйке жүйесіндегі мәселелер және менингит сияқты ауыр инфекциялар ему рефлексін жоюы мүмкін, сондықтан мұндай бөпелерді мұқият бақылау қажет.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қорыққанда селк ете қаламын! 😯 Менің рефлекстерім өте сезімтал. Кенеттен дыбыс шықса, бүкіл денеммен селк ете түсемін. Мұны "Startle reflex" деп атайды. Сіз де ішіңізде кенеттен қозғалыс болғанын сезуіңіз мүмкін. Мен қорыққанда ішіңізді қолыңызбен сипап, жай дауыспен сөйлесіңіз, сонда мен бірден тынышталамын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Зәр шығару жолдарының инфекциясы емделмей, асқынып кетсе, мерзімінен бұрын босануға себеп болуы мүмкін. Оның ең маңызды белгілері — зәр шығарғанда ашыту сезімі және жиі зәр шығару. Алайда инфекцияның орналасқан жеріне байланысты ол ешбір белгісіз де асқынуы мүмкін. Зәр шығару жолдарының инфекциясы әдетте антибиотиктермен емделеді және ем басталғаннан кейін көп ұзамай қабыну басыла бастайды. Дегенмен қайталанатын инфекциялар антибиотиктердің жоғарырақ дозасымен емдеуді қажет етуі мүмкін.;;;
Егер Сізде зәр шығару жолдарының инфекциясы болса, суды мол ішу бактериялардың ағзадан шығарылуына көмектеседі. Сондықтан тәулігіне кемінде 2 литр сұйықтық ішіп, бактериялардың көбеюі мен инфекцияның асқынуына жол бермеуге болады. Сондай-ақ сауығуды жылдамдату үшін қолдануға рұқсат етілген шөп шайларын ішу пайдалы болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтарыңызға түсетін қысымды азайту үшін күн ішінде дене қалпыңызды жиі өзгертіп, мүмкіндік болған сайын аяқтарыңызды жүрек деңгейінен жоғары көтеріп демалыңыз. Бұл ісінудің де алдын алады. Магнийге бай тағамдар бұлшықет құрысуын азайтады. Бүгін кешке тыныш ортада бөпеңізге болашақта бірге жасайтын алғашқы серуеніңіз туралы айтып беріңіз.') WHERE id = '6533fb18-848f-4cc6-b4c7-bf0dc1cff401';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қалыптасып жатқан қылтамырлары терісі әлі жеткілікті қалың болмағандықтан, денесіне қызғылт реңк береді. Осы күндері бөпеңіздің бұған дейін жабық болған танаулары да ашыла бастайды. Мұрын тыныс алудың маңызды бөлігі болумен қатар, бес сезім мүшесінің бірі — иіс сезу мүшесі болып саналады. Иіс сезу дәм сезумен бірге жұмыс істейді. Ағзада инфекция болғанда тағамның дәмі сезілмей қалатыны да сондықтан.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің терім енді мөлдір емес! 🎨 Anacan, бұрын маған қарағанда барлық тамырларым көрініп тұратын, ал қазір терім қалыңдап, түске еніп жатыр. Май қабатым ұлғайған сайын терім де мөлдірлігін жоғалтады. Мен енді әлгі "ғаламшарлық" кейіптен арылып, нағыз сүйкімді бөпеге ұқсап келемін. Мені көргенде бірден жақсы көріп қаласыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Шамамен 1 айдан кейін жатыр мойнының ұзындығы біртіндеп қысқара бастайды. Жүктілік кезінде жатыр мойнының ұзындығы 14-28-ші апталар аралығында тұрақты сақталады, ал 28-ші аптадан кейін біртіндеп қысқарып, жұқара бастайды.;;;
Жүргізілген бір зерттеуге сәйкес, 24-ші аптада жатыр мойнының ұзындығы 25 mm немесе одан аз болған әйелдердің шамамен жартысы 35-ші аптаға дейін босанған.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Белдің ауырсынуын азайту үшін бір қалыпта ұзақ отырмаңыз; әр 30 минут сайын орныңыздан тұрып, аздап жүріп қайтыңыз. Түнде жайлы ұйықтау үшін толықтай сол қырыңызбен жату Сіздің де, бөпеңіздің де оттегімен қамтамасыз етілуін жақсартады. Беліңіз қатты ауырса, міндетті түрде дәрігеріңізбен кеңесіп, ортопедиялық белдіктерді қолдану мүмкіндігін талқылаңыз.') WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің салмағының осылай тез артуының негізгі себебі — дамып келе жатқан бұлшықет пен сүйек массасы, жаңадан түзілген май тіндері және ағзаларының өсуі. Қозғалған сайын қол-аяқ бұлшықеттері дамып, қимылдары күшейе түседі, ал бұл белсенді қимылдар өз кезегінде бұлшықеттердің одан әрі дамуына жағдай жасайды. Бөпеңіздің май тіндерінің көбеюі оның бетінің томпайып, ұрттарының толысуына ықпал етеді. Соның арқасында бет әлпеті біртіндеп айқындала бастайды. Тіпті егжей-тегжейлі ультрадыбыстық зерттеу кезінде бөпеңіз ыңғайлы қалыпта жатса, оның кімге ұқсайтынын да көре аласыз. 😊;;;
Есту қабілеті айтарлықтай сезімтал бола түскен бөпеңіз енді тіпті төмен жиіліктегі дыбыстарды да ести алады. Ол Сіздің даусыңызды басқа дыбыстардан оңай ажыратады. Тіпті даусыңызды естігенде жүрек соғысы жиілеп, өзін қауіпсіз сезінеді және Сізді естігенін білдіру үшін белсенді қимылмен жауап беруі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің бет әлпетім қалыптасып болды! 👶 Anacan, егер мені қазір көрсеңіз, дүниеге келгенде қандай болатынымды анық білер едіңіз. Бет әлпетім, мұрным, ернім – бәрі толық қалыптасты. Тек әзірге сәл арықпын. Мен кімге ұқсаймын? Сізге ме, әлде әкеме ме?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңге дейін 5500 грамм мен 8500 грамм аралығында салмақ қосуыңыз керек. Егер бұдан көбірек салмақ қосқаныңызды байқасаңыз, мұқият болғаныңыз Сізде де, бөпеңізде де туындауы мүмкін мәселелердің алдын алуға көмектеседі.;;;
Қалыпты мөлшерден артық салмақ қосу жүктіліктің жайсыз өтуіне және гестациялық гипертензия мен гестациялық диабет сияқты аурулардың дамуына жағдай туғызуы мүмкін. Сонымен қатар бұл артық салмақ босанғаннан кейін тастау қиын болатын тұрақты артық салмаққа айналуы ықтимал.;;;
Егер жүктілікке дейін салмағыңыз тым артық та, тым төмен де болмай, қалыпты деңгейде болса, бірінші триместрде бөпеңіз үшін қосымша калория тұтынудың қажеті жоқ. Ал екінші триместрде күнделікті рационыңызға қосымша 300 калория қоссаңыз жеткілікті. Жүктіліктің соңғы триместрінде бұл қосымша қажеттілік шамамен 450 калорияға дейін артады. Бұл күн сайын қосымша екі-үш порция жеміс, 2 стақан майы аз сүт, 1 үлкен тостаған йогурт, 60 грамм бадам немесе 45 грамм сары май тұтынуға тең.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Көзіңізге демалыс беріңіз. Компьютер алдында көп жұмыс істесеңіз, жиі үзіліс жасаңыз. Табиғи құрамды «жасанды көз жасы» тамшылары көздің құрғауын азайтуы мүмкін.') WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің дәм сезу қабілеті айтарлықтай дамыған кезеңге жетті. Дәм сезу тілдің үстіндегі рецепторлар арқылы жүзеге асады. Дәм бүршіктері деп аталатын рецепторлар папилла деп аталатын құрылымдарда орналасады. Папиллалар — тілдің бетінде орналасқан кедір-бұдыр өсінділер.'), baby_message_kk = COALESCE(baby_message_kk, '🌽 Менің бойым бір жүгерідей! Бұл апта өте маңызды, Anacan. Дәрігерлер қазір мені «өмір сүруге қабілетті» деп санайтынын айтады. Яғни қазір дүниеге келсем де, заманауи медицинаның көмегімен өмір сүруге мүмкіндігім бар (бірақ әлі тым ерте, мен осында қала тұрғым келеді!). Бұл — үлкен белес!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіздің тез өсуіне, жиі зәр шығаруға және тыныс алудың қиындауына байланысты ұйқыңыз бұзыла бастауы мүмкін. Сонымен қатар бірнеше түн қатарынан дұрыс ұйықтай алмау өзіңізді барған сайын шаршаңқы сезінуіңізге әкелуі ықтимал.;;;
Бұл кезеңде дәретханаға жиі бару қажеттілігі — ұйқысыздықтың негізгі себептерінің бірі. Прогестерон гормоны деңгейінің жоғарылауы және жатырдың ұлғаюы қуыққа қысым түсіріп, дәретханаға жиі баруға мәжбүр етеді. Бұған қоса, ісіну, мазасыз аяқ синдромы, қыжыл және ас қорыту мәселелері сияқты шағымдар да ұйқысыздық туғызуы мүмкін.;;;
Кешкі асты ертерек ішу, майлы және ащы тағамдардан бас тарту, ұйықтар алдында жылы душ қабылдап, сүт ішу жақсырақ ұйықтауға көмектесуі мүмкін. Жиі зәр шығаруды азайту үшін күнделікті судың көп бөлігін күндіз ішіп, кешкі уақытта тым көп су ішпеуге тырысыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Дене температурасының жоғарылауы шөлдетуі мүмкін, сондықтан су ішуді әдетке айналдырыңыз. Қабырға тұсының ауырсынуын жеңілдету үшін қолдарыңызды жоғары көтеріп, терең тыныс алыңыз — бұл кеуде аймағын кеңейтуге көмектеседі. Егер беліңізде ауырлық сезілсе, тым жұмсақ емес төсекте ұйықтаған дұрыс. Бүгін өзіңізді қатты шаршатпай, біраз кітап оқып, демалыңыз.') WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада дәрігер тексеруі кезінде бөпеңіздің жымиғанын көруіңіз мүмкін. 😊 Бөпеңіздің тілін шығару, бетін тыржиту және жымию сияқты мимикалық қимылдары оның жатырда ми тінінің жақсы дамып келе жатқанын көрсететін белгілердің бірі болуы мүмкін.;;;
Қатты күйзеліске түскен күндері, психологиялық жарақаттайтын оқиғалар болғанда немесе өзіңізді бақытсыз сезінгенде ағзаңыз бөлетін гормондар бөпеңізге әсер етіп, оның азырақ қимылдауына себеп болуы мүмкін.;;;
Сол сияқты, Сіз күлгенде, қуанғанда немесе толқығанда ағзаңызда бөлінетін гормондар қан арқылы плацентадан тікелей бөпеңізге жетеді; соның нәтижесінде оның жүрек соғысы жиілеп, белсенді қимылдай бастайды және Сізге жауап беруі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Өкпем дайындалып жатыр! 🌬️ Менің өкпемде «сурфактант» деп аталатын ерекше зат түзіле бастады. Бұл зат алғаш рет тыныс алғанда өкпемнің ашылып, жабысып қалмауына көмектеседі. Мен әлі судың ішіндемін, бірақ бұл — болашаққа жасалып жатқан ең маңызды дайындық. Тыныс алу — еркіндік!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жүгері'), body_changes_kk = COALESCE(body_changes_kk, 'Емшегіңізден кейде сұйықтық бөліне бастауы мүмкін. Бұл қалыпты жағдай, сондықтан алаңдаудың қажеті жоқ. Емшекті босанғаннан кейін сүт бөлуге дайындайтын гормондар жүктілік кезінде сұйықтықтың бөлінуіне және емшектен сүт ағуына себеп болуы мүмкін. Тамшылап бөлінетін бұл сұйықтық кәдімгі сүттен өзгеше және уыз деп аталады. Уыздың құрамында кәдімгі сүтке қарағанда ақуыз, май және антиденелер көбірек болады.'), daily_tip_kk = COALESCE(daily_tip_kk, '24-ші аптаның аяқталуын өзіңізге уақыт бөлу арқылы атап өтіңіз! Белдің ауырсынуын азайту үшін аласа өкшелі ортопедиялық аяқ киімді таңдаңыз. Егер әлі жасатпаған болсаңыз, глюкозаға жүктеме сынағы туралы дәрігеріңізбен кеңесіңіз. Түнде сол қырыңызға жатып демалу Сіздің де, бөпеңіздің де қан айналымы үшін ең қолайлы.') WHERE id = 'f9782520-1096-410b-87b6-a06b825d2aa4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жұмыс істей бастаған дауыс байламдары оның күн ішінде мезгіл-мезгіл ықылықтауына себеп болуы мүмкін. Тіпті оны Сіз де сезе бастауыңыз ықтимал. Егер бөпеңіз белгілі бір аралықпен жүрек соғысына ұқсас ырғақты қимылдар жасаса, бұл оның ықылықтап жатқанын білдіреді. Көптеген жүкті әйелдер бұл ықылық бөпесіне зиян келтіреді деп ойлайды, алайда ықылық бөпеңіздің дамуы үшін өте маңызды. Ол бірнеше минутта басылуы мүмкін, ал кейде жарты сағатқа дейін созылады. Сондай-ақ ағзалары өсіп, дамуын жалғастырғандықтан, диафрагма мезгіл-мезгіл жиырылып, ықылық тудырады. Ықылықты диафрагманың өзіндік жаттығуы деуге болады. Осылайша диафрагма бөпеңіз дүниеге келгеннен кейін өздігінен тыныс алуға дайындалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мұрнымның тесіктері ашылып жатыр! 👃 Осы уақытқа дейін мұрнымның тесіктері жабық еді, ал бүгін олар ашылады. Енді амниотикалық сұйықтықпен мұрным арқылы еркінірек «тыныс ала» аламын. Бұл менің тыныс алу бұлшықеттерімді жаттықтырады. Кейде сұйықтық тамағыма кетіп қалса, ықылықтаймын. Сен сол «бүлк-бүлк» қимылдарды сезесің бе?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Беліңіздің ауыруы күшеюі мүмкін. Ішіңіз алға қарай өскен сайын, тепе-теңдікті сақтау үшін еріксіз беліңізді артқа шалқайтасыз. Бұл омыртқа маңындағы бұлшықеттерге күш түсіреді. Ұзақ уақыт тік тұру ауырсынуды күшейтеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентігуді азайту үшін денеңізді тік ұстап отыруға және иықтарыңызды артқа тартып, кеудеңізді ашуға тырысыңыз. Кальцийге деген қажеттілікті өтеу үшін күн ішінде сүт өнімдерін немесе жасыл жапырақты көкөністерді таңдаңыз. Ішіңіз қышыса, теріңізді табиғи бадам майымен немесе какао майымен ылғалдандырыңыз. Бүгін сәл тынығып, бөпеңізбен бірге алда күтіп тұрған тамаша күндерді елестетіңіз.') WHERE id = '637acaae-ce43-494a-a7b1-a90cc43779c0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесінде қалыптасқан қан тамырларының арқасында кіші қанайналым жүзеге асады. Алдымен оттегі аз, көмірқышқыл газы көп қан оң жақ қарыншадан өкпе артериясы арқылы өкпеге жеткізіледі. Оң және сол өкпеге жеткен бұл қан газ алмасу барысында көмірқышқыл газын бөліп, оттегін қабылдау арқылы тазарады. Тазарған қан өкпе венасы арқылы жүректің сол жақ жүрекшесіне келіп, одан әрі қолқа арқылы денеге айдалады. Осылайша кіші қанайналым шеңбері аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің омыртқам өте мықты! 🦴 Сүйектерім, буындарым мен байламдарым қатайғаны соншалық, енді денемді толықтай тік ұстай аламын. Арқамды түзеп, керілемін. Омыртқа жотам — болашақта денемді тік ұстайтын негізгі тірегім. Сен кальций қабылдауды жалғастыра бер, ол маған әлі де өте қажет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Көзіңіз құрғап немесе көруіңіз бұлыңғырлануы мүмкін. Жүктілік гормондары көз жасының бөлінуін азайтады. Сондай-ақ ағзада сұйықтықтың жиналуы қасаң қабықтың пішінін аздап өзгертуі мүмкін. Көзілдірігіңіздің диоптриясы уақытша өзгеруі ықтимал, сондықтан жаңа көзілдірік алуға асықпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтағанда тізеңіздің арасына жастық қою белдің ауырсынуын едәуір азайтады. Бұл омыртқаны түзу қалыпта ұстауға көмектеседі. Сондай-ақ жүктілік кезінде қаттылау төсек жайлырақ болуы мүмкін.') WHERE id = 'a0633b87-cd3d-42be-95e2-2574a37bda58';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Өміршеңдік шегіне жеткен бөпеңіздің барлық жүйке қимылдарын басқаратын жұлын жақсы дамыған және қалыптасуын жалғастырып жатыр.;;;
Жұлынның сыртқы бөлігінде ақ зат, ал ішкі бөлігінде сұр зат орналасады. Жұлынды сыртынан қоршайтын ақ зат миелин қабықшасы бар жүйке талшықтарынан, ал сұр зат миелин қабықшасы жоқ жүйке жасушаларынан тұрады. Оның ең маңызды міндеттерінің бірі — сопақша мидан келетін рефлекстерді басқару және мидан берілетін ерікті қимылдардың орындалуын қамтамасыз ету. Омыртқа жотасындағы омыртқалардың жалпы саны — 33. Жұлынды соққы мен жарақаттан қорғауға жұлын сұйықтығы көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің бойым гүлді қырыққабаттай! Қазір менің салмағым жылдам артып жатыр. Терімдегі әжімдер азайып, бетім толыса бастады. Енді мен сүйкімді бөпеге ұқсаймын. Шашымның түсі мен құрылымы да қалыптасып қойды.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Қан мен зәр талдауларын жүйелі түрде тапсыруды ұмытпаңыз. Ай сайын тұрақты тапсырылатын қан талдаулары темір тапшылығын, бұрын анықталмаған әрі жүктілік кезінде белсенді болуы мүмкін қалқанша без ауруларын, байқалмаған қан тобы сәйкессіздігін, токсоплазмоз бен қызамық секілді инфекцияларды, гепатитті және жасырын несеп жолы инфекцияларын дер кезінде анықтауға көмектеседі.;;;
Анықталмаған қалқанша без аурулары зат алмасуыңызға тікелей әсер ететіндіктен, бөпеңіздің дамуына да кері ықпал етуі мүмкін. Жүктіліктің алғашқы 12 аптасында бөпеңіздің қалқанша безі толық дамып үлгермегендіктен және гормон өндіре алмайтындықтан, Сіздің ағзаңыз өндіретін гормондардың бір бөлігі бөпеге өтеді. 12 аптадан кейін, әсіресе жүктіліктің үшінші триместрінде, плацента бөлетін кейбір гормондардың әсерінен TSH деңгейі біртіндеп жоғарылауы мүмкін.;;;
Жүктілік кезінде кездесетін жасырын несеп жолы инфекциялары ерте мерзімдегі түсіктің жиі кездесетін себептерінің бірі болуы мүмкін. Сондықтан жалпы зәр талдауын жүйелі түрде тапсыру өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Белдің ауырсынуын азайту үшін бір қалыпта ұзақ тұрмаңыз және ортопедиялық, ыңғайлы аяқ киімді таңдаңыз. Ішіңіз қышып немесе теріңіз тартылып тұрса, ылғалдандыратын майларды қолдануды ұмытпаңыз. Мол су ішумен қатар, ас қорыту жүйесінің жұмысын жеңілдету үшін рационыңыздағы талшыққа бай тағамдарды көбейтіңіз. Бүгін өзіңізге әдеттегіден де көбірек демалуға мүмкіндік беріңіз.') WHERE id = '3d485358-4a99-4889-8e24-ba3824e8665d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миы қарқынды дамыған сайын, оны жан-жағынан қоршап, қорғайтын күрделі қабаттар — ми қабықтары қалыптасады. Үш қабаттан тұратын бұл қабықтар бас сүйекпен бірге миды сыртқы соққылардан қорғайтын берік "сауыт" қызметін атқарады. Бұл қорғаныс жүйесі омыртқа аймағына дейін созылып, орталық жүйке жүйесінің барлық бөлігін қорғайды. Бөпеңіздің миында екі негізгі құрылым дамып келеді:;;;
Сұр зат: Жүйке жасушалары шоғырланған бөлік, оның қалыптасуына ми қабықтары қатысады.;;;
Ақ зат: Жүйке жүйесіндегі байланысты қамтамасыз ететін, миелин қабығымен қапталған ұзын жүйке талшықтары.;;;
Ең қызықтысы — ми кортексі (ми қыртысы). Қалыңдығы небәрі 3 mm болғанына қарамастан, мидағы барлық жүйке жасушаларының төрттен үш бөлігі дәл осы жерде орналасқан. Осыншама көп жасуша шағын аумаққа сыюы үшін ми қыртысы терең жүлгелері бар қатпарлы құрылымға ие болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Қылтамырларым қанға толып жатыр! 🩸 Терімнің астында мыңдаған ұсақ қан тамыры қалыптасып, қанға толуда. Соның арқасында терім әдемі қызғылт түске енеді. Қан айналымымның қуатты болғаны сонша, жүрегім бүкіл денемді оттегімен қамтамасыз етеді. Мен өмірге толымын, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде тері күтіміне ерекше мұқият болғаныңыз жөн. Жүктіліктің алғашқы және соңғы триместрлерінде терінің табиғи майы — себумның бөлінуі күшейетіндіктен, әдетте безеуге бейім емес әйелдердің өзінде акне пайда болуы мүмкін. Осы кезеңде теріңізді құрамында химиялық заттар жоқ, органикалық әрі қауіпсіз тазартқыш құралдармен тазалаңыз. Сонымен қатар теріні күннен қорғап, жүктілікке сай құрамды ылғалдандырғыштармен жүйелі түрде ылғалдандыруға мән берген жөн.;;;
Бұған қоса, зеңдік инфекциялардың алдын алу үшін душтан кейін құлақ ішін, құлақтың артын, мойынды, қолтықты, омырау арасы мен астын, кіндік ойығын, шап аймағын және аяқ саусақтарының арасын жақсылап құрғатыңыз. Құрамында мақтасы бар іш киім мен шұлықтарды таңдағаныңыз дұрыс.'), daily_tip_kk = COALESCE(daily_tip_kk, '25 апталық кезеңнен сәтті өткеніңізді атап өтіп, бүгін өзіңізге жайлы орта жасаңыз. Аяғыңыздағы ісінуді азайту үшін аяғыңызды созып отырғанда астына жастық қойыңыз. Суды мол ішумен қатар, тұзды сәл азайтыңыз. Егер әлі жасамаған болсаңыз, глюкоза жүктемесі тестін дәрігеріңізбен жоспарлаңыз. Ертең жаңа аптаға — 26-аптаға қадам басамыз!') WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз ашылған танаулары арқылы мезгіл-мезгіл тыныс алу жаттығуларын жасайды. Бұл жаттығулар оның тыныс алу жүйесінің дамуына көмектеседі. Тыныс алу жүйесі ретімен мұрыннан, жұтқыншақтан, көмейден, кеңірдектен және өкпеден тұрады. Мұрын ауаны қабылдайды. Оның ішкі бетіндегі түк тәрізді құрылымдар мен мұрын қуысын ылғал ұстайтын шырышты эпителий ағзаны инфекциялардан қорғайды. Жұтқыншақ жұтылған ауаны кеңірдекке өткізсе, "трахея" деп аталатын кеңірдек ауаны өкпеге бағыттайды. Кеңірдектің ішкі жағындағы кірпікшелі эпителий тіні бөлетін шырыштың (мукустың) арқасында ауа осы жерден өткенде ылғалданып, өкпе инфекциялардан қорғалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен қолымды пайдаланып жүрмін! 🖐️ Anacan, енді мен жай ғана кездейсоқ қимылдамаймын. Қай қолымды көбірек қолданатынымды таңдаймын. Яғни менің солақай немесе оңқай болатыным қазірдің өзінде белгілі. Саусақтарымды қимылдатып, кіндік бауымды ұстаймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптадан бастап денеңіздегі қанның жалпы көлемі шамамен 25% артқан. Бөпеңіздің артып келе жатқан қанға деген қажеттілігін өтеу үшін жатырға баратын қан мөлшері көбеюі керек. Жүктіліктің соңғы апталарында жатырға баратын қан ағымы минутына 1 литрге дейін жетеді. Қан көлемінің артуының тағы бір себебі — босану кезінде жоғалтатын қан мөлшеріне ағзаның алдын ала дайындалуы. Қынаптық босану кезінде 500-750 ml қан жоғалса, кесарь тілігі кезінде бұл мөлшер 1000 ml-ге жетеді. Босану кезіндегі тіліктер мен босанғаннан кейінгі қан кетуді де ескерсек, ағза осындай елеулі қан жоғалтуға дайын болуы қажет.;;;
Алайда қан көлемі қаншалықты артса да, апта өткен сайын үлкейетін жатыр, әсіресе шалқаңыздан жатқан кезде, жүрекке қайтатын қан мөлшерін азайтады. Сондықтан енді оң немесе сол қырыңызбен жату өзіңіздің де, бөпеңіздің де денсаулығы үшін өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қабағыңызда немесе аяғыңызда кенеттен әрі қатты ісіну байқалса, міндетті түрде дәрігеріңізге хабарлаңыз (қан қысымын тексеру үшін). Ентігуді азайту үшін тік отыруға тырысып, жеңіл тыныс алу жаттығуларын жасаңыз. Тағамдағы тұз мөлшерін азайтыңыз, бірақ ішетін су мөлшерін тұрақты ұстаңыз. Бүгін бөпеңізге оның болашақ бөлмесі немесе ойыншықтары туралы айтып беріңіз.') WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өкпесіндегі альвеолалар дамуын жалғастыруда. Альвеолалар — өкпе ішіндегі сансыз бронхиолалардың ұшында орналасқан, жүзім шоғына ұқсайтын ауа қуыстары. Бұл қуыстарда газ алмасу, яғни оттегінің қанға өтуі және көмірқышқыл газының сыртқа шығарылуы жүреді. Олар өте жұқа қабықпен қапталған. Альвеолалардағы ауа мен қылтамырлардағы қан арасындағы бөгеттің жалпы қалыңдығы небәрі 4 микрометр. Бұл қалыңдық бір эритроцит жасушасының радиусына тең. Бөгеттің аса жұқа болуы газ алмасудың екі бағытта да өте жылдам әрі тиімді жүруін қамтамасыз етеді. Сонымен қатар тыныс алу кезінде альвеолалар ашылып-жабылады. Оларды сурфактант деп аталатын зат қоршап тұрады және ол альвеолалардағы ауа қапшықтарының ашылып-жабылуына көмектеседі. Сондай-ақ осы заттың арқасында тыныс шығарғанда қапшықтар толық семіп қалмайды әрі өкпедегі беттік керілу реттеледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сіздің иісіңізді сеземін! 👃 Қағанақ суының иісі Сіздің жеген тағамыңызға және қоршаған ортаға қарай өзгереді. Менің иіс сезу қабілетімнің дамығаны сонша, бұл өзгерістерді сезе аламын. Дүниеге келгенде Сіздің иісіңізді мыңдаған адамның арасынан танимын. Ана иісі — әлемдегі ең тамаша хош иіс.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қан қысымыңыз жоғарыласа, бұл туралы міндетті түрде дәрігеріңізге хабарлаңыз.;;;
Қан қысымы жоғары болғанда плацентаға баратын қан ағымы баяулайды. Соның салдарынан бөпеңіз өзіне қажетті оттегі мен қоректік заттарды жеткілікті мөлшерде ала алмауы мүмкін. Нәтижесінде құрсақтағы бөпеңіздің дамуы баяулауы ықтимал. Қан қысымының жоғарылау себептеріне жүктілікке дейін гипертонияның болуы, 35 және одан жоғары жас, артық салмақ, көпұрықты жүктілік және иммундық жүйеге қатысты бұзылыстар жатады.;;;
Егер жоғары қан қысымымен бірге қатты ауырсыну, салмақтың тез артуы, қол мен беттің ісінуі, сондай-ақ көрудің бұлыңғырлануы байқалса, уақыт жоғалтпай дәрігерге барыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Асқазанның керілуін азайту үшін үлкен порциялардың орнына күніне 5-6 рет аз-аздан тамақтаныңыз. Белге түсетін жүктемені жеңілдету үшін отырғанда арқаңызды тірейтін жастықтарды қолданып, тік отырыңыз. Іш қатудың алдын алу үшін ас мәзіріңіздегі шикі көкөністер мен жемістердің мөлшерін көбейтіңіз. Бүгін кешке аяғыңызды сәл жоғары көтеріп, баяу музыка тыңдап демалыңыз.') WHERE id = 'ed58011e-092e-41ea-a45c-df149cb7fc4b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз ана құрсағында көзін аша алады! Осы кезеңге дейін жабық болған қабақтары енді ашыла бастайды. Қабақтар — көзді сыртқы әсерлерден қорғайтын, көз жасын біркелкі таратып, көздің құрғауына жол бермейтін және түсетін жарық мөлшерін реттейтін маңызды қорғаныс жүйесі.;;;
Қабақтардың кейбір қызықты ерекшеліктері: үстіңгі қабақ арнайы бұлшықетінің арқасында астыңғы қабаққа қарағанда қозғалғыш келеді. Астыңғы және үстіңгі қабақтардағы бұлшықеттер бір-біріне қарама-қарсы жұмыс істеп, көздің толық жабылуын қамтамасыз етеді. Қабақтар саналы түрде де, рефлекс арқылы да қозғалады. Көзді жыпылықтату рефлексі көз жасын көз бетіне таратып, оның қызметін жоғалтуына жол бермейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Май қабатым қалыңдап келеді! 🧈 Денемдегі әжімдер біртіндеп жазылып жатыр, өйткені олардың асты майға толуда. Қазір мен тегіс әрі жұмсақ болып көрінемін. Бұл май қабаты мені жылы ұстайды. Сіз мені құшағыңызға алғанда, сүйектері білініп тұрған емес, «томпақ» боламын. Сіздің сүтіңізбен одан әрі өсемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Осы аптаға дейін глюкозаға жүктеме сынағын тапсырып қойған болуыңыз керек. Егер нәтижелеріңіз шекті мәндерден жоғары болса, Сізге гестациялық қант диабеті диагнозы қойылуы мүмкін.;;;
Жүктілік кезінде ағзаға инсулин көбірек қажет болады. Алайда гормондық өзгерістер жасушалардың инсулинге сезімталдығын төмендетуі мүмкін. Қалыпты жағдайда қандағы қант деңгейі көтерілгенде, ұйқы безі инсулинді көбірек бөліп шығару арқылы жауап береді. Бірақ ұйқы безі қандағы қант деңгейін төмендетуге жеткілікті инсулин өндіре алмаса, глюкозаға төзімділіктің бұзылуы деп аталатын жағдай туындайды. Бұл жүктілік кезінде орын алса, гестациялық қант диабеті деп аталады.;;;
Гестациялық қант диабеті диагнозы қойылған әйелдердің қанындағы артық глюкоза плацента арқылы бөпеге өтіп, оның шамадан тыс салмақ қосуына себеп болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ісінуді азайту үшін күні бойы мол су ішуді ұмытпаңыз. Аяқтың құрысуын жеңілдету үшін ұйықтар алдында жеңіл массаж жасау немесе жылы душ қабылдау пайдалы. Бүгін бөпеңізбен бірге біраз уақыт өткізіп, оған болашақ жоспарларыңыз туралы айтып беріңіз; ол Сіздің даусыңыздағы толқу мен махаббатты бірден сезеді.') WHERE id = 'e581817d-cd7b-4e6d-a51b-e85acf339c0a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің көзіндегі торқабық қабаттарының қалыптасуы аяқталды. Көздің ең маңызды бөліктерінің бірі — торқабық. Торқабық — көз алмасының артқы бөлігін жауып тұратын жұқа қабат. Ішіндегі қан тамырлары торға ұқсайтындықтан, ол көздің торлы қабығы деп аталады. Бұл қабат көздің бүкіл ішкі қабырғасын жауып тұрады. Ол мимен байланысқан қан тамырлары мен жүйкелерден тұрады. Торқабықтың көз алмасының ішіне қараған бөлігінде жарық пен түске сезімтал миллиондаған жасуша бар. Бұл жасушалар көздің алдыңғы жағынан түсетін жарық сигналдарын қабылдап, оларды ми түсіне алатын электрлік сигналдарға айналдырады да, көру жүйкесіне жібереді. Көру жүйкесі бұл сигналдарды миға жеткізіп, бейненің қабылдануын қамтамасыз етеді. Көру жүйкесі арнаға ұқсас жүйе арқылы мидың көру сезімін басқаратын бөлігіне барады. Көру жүйкесі шығатын нүкте көру дискісі немесе папилла деп аталады. Торқабықтың ортасында орналасқан көру дискісінде жарыққа сезімтал жасушалар болмағандықтан, жарық қабылданбайды, сондықтан бұл аймақ «соқыр дақ» деп аталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Көзімді ашуға дайынмын! 👁️ Қабақтарымның арасындағы бітісу сызығы енді ажырауға жақын. Жақында, бәлкім, бірнеше күннен кейін көзімді ашамын! Қараңғы болса да, жан-жағыма қарағым келеді. Кірпіктерім көзімді қорғауға дайын. Сізді көруге асықпын, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Шашыңыздың бұрынғыдан жылтыр әрі қалың бола түскенін байқаған шығарсыз. Сонымен қатар жүктілікке дейінгі кезеңмен салыстырғанда денеңізде түктің көбірек өсуі мүмкін. Гормондық өзгерістерге байланысты пайда болатын бұл түктер көбіне босанғаннан кейін көп ұзамай түсіп қалады және әдетте жүктіліктің екінші триместрінде өсе бастайды.;;;
Егер жүктілік кезіндегі түктің өсуі Сізді мазаласа, ұстараны, эпиляторды немесе балауызбен эпиляциялау әдісін таңдаған жөн. Бұл әдістер бөпеңізге ешқандай зиян келтірмейді. Алайда жүктілік кезінде сезімтал бола түскен теріде қызару мен инфекцияға әкелуі мүмкін тітіркену қаупін ескеруіңіз керек. Сонымен қатар жүктілік кезінде түк кетіретін кремдерді қолданбаған жөн. Себебі олардың құрамындағы барий сульфаты және кальций тиогликоляты сияқты күшті химиялық заттар бөпеңізге зиян келтіруі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кегель жаттығуларын (жамбас түбі бұлшықеттерін қысып, босаңсытуды) күнделікті тәртібіңізге қосыңыз. Бұл бұлшықеттерді нығайту несеп ұстамаудың алдын алып, босануды жеңілдетеді. Күнделікті төсемелерді қолдану өзіңізді жайлырақ сезінуге көмектеседі.') WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің қасы мен кірпігі анық көрінетіндей қалыптасқан. Қас пен кірпік көзді бөгде заттардан қорғайтын табиғи тосқауыл қызметін атқарады. Кірпіктердің құрылымы денедегі басқа түктерден өзгеше: олардың түк түбін көтеретін бұлшықеті жоқ және көптеген басқа түктерге қарағанда кейбір гормондардың әсеріне ұшырамайды. Ал қас — қас сүйектерінің үстінде орналасқан доға тәрізді түктер. Қас түгінің фолликулдары құрылымы жағынан дененің басқа бөліктеріндегі түк фолликулдарына ұқсас болғанымен, олардың өсу кезеңі әлдеқайда жылдам өтеді.;;;
Қас көзді терден қорғайды және оған көлеңке түсіреді. Бет әлпетін білдіруде де маңызды рөл атқаратын қас кірпікпен, бет сүйектерімен, шаштың өсу сызығымен және мұрынмен бірге көз айналасын қоршап, адамның сыртқы келбетіне көрік береді.;;;
Бұл құрылымдарда аз мөлшерде су бар, сондай-ақ олар көмірсуларға, несепнәрге, несеп қышқылына, бос аминқышқылдарына, фосфолипидтерге, холестеринге, май қышқылдарына және негізгі құрылыс материалы — кератинге бай. Басқаша айтқанда, олардың негізін 18 аминқышқылынан тұратын және терінің астыңғы қабатындағы кератиноциттер түзетін кератин құрайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сіздің күйзелісіңізді бөлісемін. 😔 Anacan, Сіз мазасызданғанда қаныңыздағы кортизол маған да өтеді. Мен де алаңдап, қимылдарым өзгереді. Ал Сіз күліп, қуанғанда мен де тынышталамын. Өтінемін, өзіңізді күтіңіз. Біз бір командамыз, Сіздің сезімдеріңіз — менің де сезімдерім.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігер тексеруі кезінде ультрадыбыстық зерттеу бойынша есептелген бөпеңіздің жүктілік мерзімі соңғы етеккіріңіздің күніне қарай есептелген мерзіммен дәл сәйкес келмеуі мүмкін. Мұндай жағдайда алаңдамаңыз.;;;
Дәрігер бақылауындағы ультрадыбыстық тексерулер кезінде бөпенің дамуы күтілетін деңгейден төмен болса, құрсақішілік дамудың тежелуі болуы мүмкін деп есептеледі. Дамуы тежелген бөпелердің басым бөлігінде бұл жағдай ата-анасынан берілген тұқым қуалайтын гендерге байланысты болады. Әкесі мен анасы генетикалық тұрғыдан шағын денелі болса, бөпенің ана құрсағында ірі болуы күтілмейді. Дамудағы екі апта ілгері немесе екі апта кейінгі айырмашылық қалыпты деп саналады және генетикалық факторлардан басқа күмән тудырмайды. Егер айырмашылық 2 аптадан асса, егжей-тегжейлі ультрадыбыстық зерттеу, жоғары қауіп тобына жататын жүктілік бойынша маманның тексеруі және бөпеге баратын қан ағымын бағалау қажет болуы мүмкін. Бөпелерде кездесетін даму тежелуінің 75% жағдайы дене бітімінің ерекшелігіне байланысты екені белгілі. Бұдан бөлек, бөпеге баратын қан ағымының азаюы, плацентаның ерте қартаюы және қағанақ суының азаюы да дамудың тежелуіне себеп болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылды азайту үшін тамақтанғаннан кейін бірден жатпаңыз және ұйықтағанда басыңызды жастықпен сәл көтеріңіз. Белдің ауырсынуын жеңілдету үшін үнемі жеңіл созылу жаттығуларын жасаңыз. Қазірдің өзінде 1 kq ғажайыпты көтеріп жүрсіз, сондықтан ауыр заттарды көтеруден міндетті түрде аулақ болыңыз. Бүгін кешке ішіңізді сипап, бөпеңізбен сөйлесіңіз, ол Сіздің жанасуыңызды сезеді!') WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жүйке жүйесі және онымен байланысқан барлық бұлшықеттері сыртқы тітіркендіргіштерге саналы түрде жауап бере алатындай деңгейге дейін дамыған. Мінез-құлық дегеніміз — ішкі және сыртқы әсерлерге берілетін саналы жауап. Мінез-құлықты қарапайым қимылдан ажырататын негізгі ерекшелік — оның белгілі бір әсерге саналы түрде жауап болуы.;;;
Саналы әрекет өз мәні бойынша белгілі бір себепке негізделеді және міндетті түрде мақсаты болады. Қарапайым қимылдан айырмашылығы, саналы әрекет оны жасаушының еркі мен жеке уәждерін көрсетеді.;;;
Физиологиялық тұрғыдан алғанда, бұл — ішкі және сыртқы факторлардың әсерінен денеге бағытталатын энергия ағыны. Дене дамыған жүйке жүйесінің арқасында бұл ағынды қабылдап, түсіндіреді және кері байланыс ретінде қоршаған орта мен тітіркендіргіштерге бейімделу үшін пайдалануға тырысады.;;;
Мінез-құлықтың негізін құрайтын басты фактор — тітіркендіргіш пен оған жауап ретінде жасалатын әрекеттің сәйкестігі. Тітіркендіргіш пен әрекет арасындағы сәйкестік ағза мен оны қоршаған орта арасында тепе-теңдік қалыптастырады.;;;
Бұл тепе-теңдікті Сіз күлгенде бөпеңіздің де күлуі, ауырсынғанда ернін бүрістіріп алуы және қарны ашқанда сүт емуі арқылы түсіндіруге болады.'), baby_message_kk = COALESCE(baby_message_kk, 'КӨЗІМДІ АШТЫМ! 👀 Anacan, бүгін мен үшін нағыз төңкеріс күні. Осы уақытқа дейін жабысып тұрған қабақтарым ажырап, мен алғаш рет көзімді аштым. Әзірге айналамның бәрі бұлыңғыр, бірақ мен көзімді жыпылықтата аламын. Қараңғы болса да, қарауды үйреніп жатырмын. Сені көруге тағы бір қадам жақындадым!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Брэкстон–Хикс" жиырылулары (жалған толғақ) жиілеуі мүмкін. Ішіңіздің тас сияқты қатайып қалуынан қорықпаңыз. Бұл — жатыр бұлшықетінің "жаттығуы". Егер бұл жиырылулар дене қалпын өзгерткенде немесе су ішкенде басылса, демек, олар жалған. Нағыз босану толғағы біртіндеп күшейіп, басылмайды.;;;
Сонымен қатар қабырғаңыз ауыра бастауы мүмкін. Жатырдың жоғары көтерілгені сонша, енді қабырға доғасын кеңейте бастайды. Бөпенің басы немесе аяқтары қабырғаларыңызға тиіп тұруы мүмкін. Кейде терең тыныс алу қиындайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Преэклампсия белгілерін біліп жүріңіз: бет пен қолдың кенеттен ісінуі, қатты бас ауруы, көз алдында "жарықтың жарқылдауы" немесе қабырға астындағы ауырсыну. Осы белгілердің бірі байқалса, дереу дәрігерге хабарласыңыз.') WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізде май тінінің түзілуі жеделдеп, теріасты тінінің дамуына және соның арқасында салмағының тез өсуіне ықпал етеді. Сонымен қатар бұл май бөпеңіз дүниеге келген сәттен бастап оны суықтан қорғайтын тосқауыл қызметін атқарады.;;;
Құрсақтағы даму мерзімін толық аяқтаған бөпелердің туған кездегі салмағы 2500 грамнан 4000 грамға дейін болады. Бұл көрсеткіш көптеген факторға байланысты, олардың ішіндегі ең белгілісі — жыныс факторы. Қыз және ұл бөпелер арасында генетикалық айырмашылықтар бар; ұл бөпелерде май жасушалары қыздарға қарағанда көбірек болады.;;;
Құрсақтағы бөпелер салмағының орташадан төмен немесе жоғары болуының көптеген себебі бар. Салмағы орташадан төмен бөпелердің едәуір бөлігінде бұл генетикалық факторларға байланысты. Бұған қоса, жүктілік кезінде болған кейбір аурулар мен дұрыс тамақтанбау да осы мәселеге әкелуі мүмкін. Ал салмағы орташадан жоғары бөпелерде, егер бұл салмаққа артық сұйықтық та әсер етсе, алдымен гестациялық диабетке күмән туады. Сонымен қатар генетикалық және зат алмасу ерекшеліктері де бөпе салмағының орташадан жоғары болуына себеп болуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Кірпіктерім өсіп келеді! 👁️ Көзімді ашқан соң, оларды қорғау керек. Менің ұзын, жібектей кірпіктерім бар. Сен менің көзіме қарағанда, бұл кірпіктеріме сүйсінесің. Қастарым да толық қалыптасып, өз орнында тұр. Мен енді кішкентай қуыршаққа ұқсаймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл кезеңде гормондық тепе-теңдіктің өзгеруіне байланысты қынап микрофлорасы да өзгереді. Сондықтан жүктілік кезінде ағзаңыз қынап кандидозына бейім болады. Әсіресе түсік тастау қаупі бар болып, соған байланысты қынаптық суппозиторийлер немесе кремдер қолдансаңыз, қынаптың зеңдік инфекциясы жиірек пайда болуы мүмкін. Қынап кандидозы жыныс аймағының ашуы мен қышуы, қою ақ бөлінді, жиі зәр шығару және жыныстық қатынас кезіндегі ауырсыну сияқты белгілермен көрінеді. Әр адамда әртүрлі болғанымен, қынап кандидозы кезіндегі бөлінді көбіне ақ немесе ақшыл сары түсті, крем тәрізді қою, сүзбе не ірімшік түйіршіктеріне ұқсас және қышқыл иісті болады.'), daily_tip_kk = COALESCE(daily_tip_kk, '26-шы аптаның аяқталуын өзіңізді еркелетіп атап өтіңіз! Белдің ауырсынуын азайту үшін отырғанда арқаңызды тірейтін жастықты міндетті түрде пайдаланыңыз. Егер әлі жасамаған болсаңыз, глюкозаға төзімділік сынағы туралы соңғы мәліметтерді дәрігеріңізбен нақтылап алыңыз. Түнде сол жақ қырыңызбен жату Сіздің де, бөпеңіздің де қан айналымы үшін ең қолайлы қалып.') WHERE id = '3c253a83-3ac7-475e-8987-d27fab00a076';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тыныс алу, ас қорыту, жүйке және иммундық жүйелері дамуын жалғастыруда. Иммундық жүйе — ағзаны микробтар деп аталатын және инфекция тудыратын вирустар, бактериялар, зеңдер мен паразиттер сияқты микроағзалардың зиянды әсерінен қорғайтын жүйе.;;;
Иммундық жүйені құрайтын жасушалар, тіндер мен ағзалар өзара үйлесімді әрі өте тиімді әрекет етеді. Иммундық жүйенің жұмысы екі негізгі түрге бөлінеді: туа біткен және жүре пайда болған иммундық жүйе. Туа біткен иммундық жүйе — инфекция тудыратын микробтар ағзаға алғаш енгенде оларды анықтап, жоюға әрекет ететін, ағзада табиғи түрде болатын жүйе. Ал жүре пайда болған иммундық жүйе ағзаға зиян келтіретін микробпен кездескеннен кейін белгілі бір дайындық кезеңінен соң іске қосылады. Ол зиянды ағзаға қарсы қорғаныш құрылымдарын түзіп, ақпаратты жадында сақтайды. Оның негізгі элементтері — T және B лимфоциттері.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, 3-ші триместр табалдырықта! Мен енді "ауыр салмақтылар" санатына өтіп келемін. Орным тарылып барады, сондықтан қимылдарым қаттырақ сезілуі мүмкін. Қабырғаларыңа тиіп кетсем, кешірші, мен жай ғана керіліп жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл апталарда преэклампсия жиірек кездесетіндіктен, мұқият болып, қан қысымыңызды өлшетіп тұруыңыз керек. Жүктілік кезіндегі қауіпті асқыну саналатын преэклампсия жүктіліктің 20-шы аптасынан кейін қан қысымының 140/90 мм сынап бағанасынан жоғары көтерілуімен және зәрде ақуыздың анықталуымен көрінеді. Бұл жағдайлар көбіне ісінумен қатар жүреді.;;;
Преэклампсияның даму механизмін қан тамырларының зақымдануы деп сипаттауға болады. Мәселенің негізінде жатыр тінін қамтитын жіңішке әрі ирек артериялардың шамадан тыс тарылуы жатыр, соның салдарынан плацента бөпені жеткілікті қоректендіре алмайды.;;;
Преэклампсия барлық жүктіліктің шамамен 5%-інен 7%-іне дейін кездесуі мүмкін. Салмақтың күрт артуы, ісінудің пайда болуы, әлсіздік, сананың тұмандануы, іштің ауыруы немесе бөпе қимылының азаюы байқалса, дереу жақын жердегі медициналық мекемеге жүгіну қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтағанда аяқтарыңыздың арасына және ішіңіздің астына жастық қою белдің ауырсынуын азайтады. Сол жақ қырыңызбен жату бөпеге баратын қан ағымын арттырып, бүйректеріңіздің жұмысын жеңілдетеді.') WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз енді көзін ашып-жұма алады. Соның арқасында ол күн мен түнді ажырата алатындай деңгейге жетті. Жатыр қабырғасы жарық пен дыбыс сияқты сыртқы тітіркендіргіштердің жатыр ішіне өтуіне тосқауыл болғанымен, бөпеңіз едәуір үлкейгендіктен, бұл қабырға созылып, біршама жұқарады. Тіпті осы кезеңде ішіңізге күшті жарық түсірсеңіз, бөпеңіз оған жауап беріп, басын жарық түскен жаққа бұруға тырысуы мүмкін. Мұндай реакцияның болуы көздің қасаң қабығы мен көру жүйкесінің дамуына да байланысты.;;;
Сонымен қатар, бөпеңіз Сіздің даусыңызға жауап береді және әкесінің даусын да басқа дыбыстардан ажырата алады. Әйелдер мен балалардың дауысы ерлердің даусына қарағанда жоғары әрі жіңішке болғандықтан, жатыр қабырғасынан оңайырақ өтеді, сондықтан бөпеңіз мұндай дауыстарға көбірек жауап береді. Ал кенеттен шыққан қатты дыбыстан селк етіп, қатты тебуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, '⚖️ Салмағым артқан сайын Сізге де ауырлық түсіремін. Беліңіздің ауыратынын білемін. Бірақ менің күн сайын денім сау әрі күшті болып келе жатқанымды ойлаңызшы. Май қабатым мені жылы ұстайды. Дүниеге келгенде құшағыңызды толтырамын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Брокколи'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің кейінгі апталарында гормондық өзгерістерге байланысты көбейіп, сұйыла түсетін бөліндіні қағанақ суының кетуімен шатастырып алуыңыз мүмкін. Қағанақ қабы жарылғанда сұйықтық әдетте көп мөлшерде бөлініп, аяқтарыңыздың арасынан сарқырап ағады. Алайда кейбір жағдайларда белгілі бір себептермен қағанақ қабы бүйірінен немесе жоғарғы жағынан тесілуі мүмкін. Соның салдарынан қағанақ суы аз-аздан сыздықтап ағуы ықтимал.;;;
Егер қағанақ суы кетіп жатыр деп күмәндансаңыз, ауруханаға жүгініңіз. Қарапайым тест арқылы бөлініп жатқан сұйықтықтың қағанақ суы немесе қынаптық бөлінді екені анықталады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентігуді азайту үшін тік отыруға тырысып, иығыңызды артқа қарай жіберіп, кеудеңізді ашыңыз. Кальций қажеттілігін өтеу үшін күні бойы сүт өнімдерін немесе жасыл жапырақты көкөністерді таңдаңыз. Ішіңіз қышыса, теріңізді табиғи майлармен ылғалдандырыңыз. Бүгін сәл тынығып, бөпеңізбен бірге алда күтіп тұрған тамаша күндерді елестетіңіз.') WHERE id = 'e2245d19-3163-447c-8f3b-d37ca7523b57';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Сіз бөпеңіздің бүкіл жүктілік кезеңіндегі ең белсенді уақыты — 27 және 32-апталар аралығына келдіңіз. Сонымен қатар, осы апталардан бастап бөпеңіз тұрақты түрде қимылдайтын болады. Яғни ол ояу болған әр сағатта кемінде 10 қимылын сезуіңіз керек. Бөпеңіз қағанақ суы көп қозғала бермейтін түнгі уақытта ең белсенді болады. Күндіз Сіздің қимылдарыңыздан қағанақ суы тербеліп, бөпеңіздің ұйықтауына көмектеседі. Демек, бөпеңіз енді ұйқыңызды бұзуы мүмкін. 😊;;;
Осы кезеңде бөпеңіздің қимылдарын өте анық әрі жиі сезуіңіздің негізгі себебі — оның едәуір үлкейіп, сонымен бірге жатырда еркін қимылдауға жеткілікті қағанақ суының болуы.;;;
Апталар өткен сайын бөпеңіз жұтқан қағанақ суының мөлшеріне қарағанда, зәр арқылы қағанақ қуысына азырақ сұйықтық бөледі. Соның нәтижесінде оны қоршаған сұйықтықтың мөлшері біртіндеп азая бастайды. Бөпеңіз өскен сайын оған көбірек орын қажет болатындықтан, сұйықтық көлемінің азаюы — табиғи үдеріс.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің өз тәртібім бар! 📅 Anacan, байқадыңыз ба? Мен әдетте бір уақытта оянып, бір уақытта ұйықтаймын. Мысалы, Сіз кешке жатқанда мен оянамын. Ал таңертең тыныш боламын. Менің биологиялық сағатым іске қосылды. Дүниеге келгеннен кейін де біраз уақыт осылай боламын (түнде ұйықтамайтын бөпе боламын!).'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Брокколи'), body_changes_kk = COALESCE(body_changes_kk, 'Прогестерон гормонының әсерінен асқазан мен өңеш түйіскен жердегі бұлшықеттің босаңсуы қыжылға себеп болуы мүмкін. Жүктілік кезінде қыжылды күшейтетін тағамдардан бас тартқаныңыз жөн. Еңкею сияқты қимылдар да бұл мәселені ушықтыратындықтан, ауыр үй жұмыстарын істемеуге және еңкеюді қажет ететін әрекеттермен айналыспауға тырысыңыз. Тамақты асықпай, баяу ішіңіз; қышқыл, газдалған және құрамында кофеин бар сусындардан бас тартыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Таңертең ашқарынға бір стақан жылы су ішу немесе кептірілген өрік жеу ішектің жұмысын белсендіреді. Дәретханаға барғыңыз келсе, ешқашан шыдап жүрмеңіз.') WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Шамамен 24-аптадан бастап өміршеңдік шегіне жеткен бөпеңіз осы аптада мерзімінен бұрын дүниеге келсе де, оның тірі қалу мүмкіндігі 90%-дан жоғары болады. Мұның ең маңызды себебі — өкпеде сурфактанттың жеткілікті мөлшерде өндіріле бастауы. Сурфактант альвеолалардағы сұйықтықтың беттік керілуін азайтып, олардың жабысып, шөгіп қалуына жол бермейді; осылайша ісіну мен басқа заттардың жиналу қаупін төмендетеді. Газ алмасу кезінде тыныс жолдарының бетінің ылғалды әрі сырғанақ болуына көмектесетін бұл заттар ақуыздар мен липидтердің күрделі қоспасынан тұрады. Сонымен қатар, бөпеңіздің сипап сезу, дәм сезу, есту, иіс сезу және көру мүшелері толық қалыптасып болды.'), baby_message_kk = COALESCE(baby_message_kk, 'Даусыңызға жауап беремін! 🎵 Әкем ішіңізге жақындап сөйлегенде, жүрек соғысым өзгереді. Мен оның даусын өте жақсы естимін. Оған менімен сөйлессін деп айтыңызшы. Мен отбасы мүшелерін дауыстарынан тани бастадым.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Брокколи'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіздің едәуір үлкеюіне және бөпеңіздің түнде белсенді болуына байланысты ұйқыңыз бұзылуы мүмкін. Осы кезеңде жүкті әйелдерге арналған жастық Сізге пайдалы болуы ықтимал. Мұндай жастық арқаңыз бен беліңізді демеп, ауырсынуды азайтады және бүйректеріңіздің жақсы жұмыс істеуіне көмектеседі. Тыныс алуды жеңілдетіп, жүктілік кезінде жиі кездесетін ентігуді азайтады. Бөпеге қоректік заттар мен оттегінің жақсырақ жетуіне көмектеседі, сондай-ақ жүктілік кезінде жиі мазалайтын қыжылды бәсеңдетеді. Қан айналымын жақсартатындықтан, құрысу мен әсіресе аяқтағы ісінуді азайтуға ықпал етеді. ;;;
Әсіресе соңғы триместрде көбіне сол жақ қырыңызбен жату ұсынылады. Себебі шалқадан немесе оң жақпен жатқанда дененің оң жағындағы төменгі қуыс венаға қысым түсіп, дененің төменгі бөлігіндегі көктамырлар кеңеюі және соған байланысты мәселелер туындауы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін жүктіліктің сәтті өткен 27 аптасын жақсылап тынығып атап өтіңіз. Аяқтағы ісінуді азайту үшін тұзды шектеп, аяқтарыңызды жоғары көтеріп демалыңыз. Үшінші триместрді сергек бастау үшін ұйқы тәртібіңізді реттеңіз. Ертеңнен бастап кездесуімізге одан да аз уақыт қалады!') WHERE id = '7654580f-12f8-4fea-93bd-20d5a4e92397';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Екінші триместрдің соңғы аптасына қош келдіңіз! Уақыт неткен тез өтеді, солай емес пе? Бөпеңіздің бойы енді төбесінен құйымшағына дейінгі қашықтықпен емес, ортан жілік ұзындығын 7-ге көбейту арқылы анықталады.;;;
Үшінші триместрге өтуге аз уақыт қалғанда, дәрігер тексеру кезінде бөпеңіздің басын төмен қаратып, босануға қолайлы қалыпқа келгенін байқауы мүмкін. Бұл — қалыпты жағдай. Соңғы апталармен салыстырғанда әзірге қозғалуына көбірек орын бар болғандықтан, бөпеңіз қалпын оңай өзгерте алады. Сондай-ақ бөпеңіздің аузында дәм сезу бүртіктері көп болғандықтан, Сіз жеген тағамдардың дәмі қағанақ суы арқылы оған жетіп, әртүрлі дәмдерді ажыратуына мүмкіндік береді.;;;
Бұл кезеңде бөпеңіздің тілінде ересек адамға қарағанда дәм сезу бүртіктері көбірек болады. Соның арқасында ол дәмдерді ажыратып қана қоймай, оларға жауап та бере алады. Әсіресе кейбір дәмдеуіштері мол және өте ащы тағамдарға ықылық ату арқылы реакция білдіруі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен түс көріп жатырмын! 💤 Ғалымдар менің миымды зерттеп, "REM ұйқысы" кезеңінде екенімді анықтады. Яғни көздерім жұмық болса да, мен қиялдаймын. Түсімде нені көріп жатыр екенмін? Сіздің даусыңызды ма? Әлде Сіз жеген әлгі дәмді шоколадты ма? Мен де Сіз сияқты қиялшылмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің 28-ші аптасынан бастап ағзаңыздағы қорлардың көп бөлігі бөпеңізге жұмсалады. Сондықтан ағзаңыздағы үдерістер баяуламауы үшін кальцийге, магнийге, A, D, E және K дәрумендеріне бай тағамдарды тұтыну өте маңызды.;;;
Жүктілік кезінде кальций жеткілікті мөлшерде түспесе, бөпеңіздің дамуына қажетті кальций Сіздің сүйектеріңізден алынады. Бұл кальций тапшылығына және кейінгі жылдары остеопороз деп аталатын сүйек тінінің жұқаруына алғышарт жасайды. Сүт, айран және ірімшік — кальцийге ең бай тағамдар. Сонымен қатар кептірілген өрік, грек жаңғағы, орман жаңғағы, бадам, бақтақ, қою жасыл жапырақты көкөністер мен кептірілген бұршақ тұқымдастардың құрамында да кальций едәуір мөлшерде бар. Күнделікті ішетін бір стақан сүтте 250 мг кальций болады. Бір тілім ақ ірімшікте түріне қарай 100 мг, бір уыс шикі жаңғақта 50 мг, ал бір уыс мейізде 30 мг кальций бар.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Белдің ауырсынуын азайту үшін аласа өкшелі, ыңғайлы аяқ киім киіңіз және отырғанда арқаңызды міндетті түрде тіреп отырыңыз. Мұрынның құрғауын болдырмау үшін бөлмедегі ылғалдылық деңгейін сақтаңыз. Бүгін бөпеңізбен көбірек сөйлесіңіз немесе оған ертегі оқып беріңіз; ол Сіздің даусыңыздың әуезін болашақта есінде сақтайды. Суды мол ішіп, жасұныққа бай тағамдарды рационыңыздан шығармаңыз.') WHERE id = '1533383b-1c83-483c-ad7a-9958fe297dd1';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің салмағының жылдам артуы қоңыр май жасушаларының өте қарқынды түзілуіне байланысты. Қоңыр май жасушалары ағзадағы кейбір холестеринді жинақтаумен қатар, құрамындағы митохондриялардың көптігі арқасында жылу өндіреді. Қоңыр май жасушалары бөпеңіздің дене температурасын сақтауға көмектесетіндіктен, осы кезеңге дейін оны жылытып тұрған лануго түктері біртіндеп түсе бастайды. Лануго түктерінің түсу кезеңі әр бөпеде әртүрлі өтеді. Бұл даму ерекшеліктері мен зат алмасу белсенділігіне байланысты. Түскен лануго түктері бөпеңіз жатқан қағанақ суына араласады және ол осы сұйықтықты жұтады. Жұтылған қағанақ суының құрамындағы лануго түктері бөпеңіздің ішегінде жиналып, "алғашқы нәжіс" деп аталатын меконийдің құрамына кіреді. Сонымен қатар денесіндегі қоңыр май жасушаларының саны жылдам көбейіп, теріасты қабаты қарқынды дамып, толысады. Соның нәтижесінде терісіндегі әжімдер азайып, терісі тегістеле түседі. Бұған қоса, осы кезеңге дейін мөлдір болған терісі мен оның астынан көрініп тұрған қылтамырлар енді байқалмайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мені ықылық қысты! 🤭 Ішіңізде ырғақты "тық-тық-тық" сезіліп тұр ма? Бұл — менің ықылығым! Мен қағанақ суын жұтқанда көкеттің тітіркенуінен ықылық атамын. Бұл Сізге оғаш көрінуі мүмкін, бірақ мен үшін өкпемді нығайтатын жаттығу. Қорықпаңыз, мен тұншығып жатқан жоқпын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Гүлді қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Екінші триместрді аяқтауға жақын қалдыңыз. Жүктіліктің алтын кезеңі немесе бал айы деп аталатын осы уақыттың аяқталуы бірінші триместрде болған кейбір жайсыздықтардың қайта оралуы мүмкін екенін білдіреді.;;;
Бөпеңіз едәуір жоғары көтерілгендіктен, жатырдың қысымынан ішкі ағзаларыңыздың орны өзгереді. Бұл жағдайдан ең көп зардап шегетін ағзалардың бірі — асқазан. Қалыпты орнынан жоғары ығысқан асқазанда, әсіресе ауыр тағам жегенде қысым артып, құсу мен қыжыл пайда болуы мүмкін. Сонымен қатар ішектеріңіз шетке ығысқандықтан, ішек қимылы баяулап, іш кебуі мен іш қату байқалуы ықтимал. Бөпеңіз өскен сайын жатыр қуыққа қайтадан қысым түсіре бастайды, сондықтан дәретханаға жиі баруыңыз мүмкін. Қысым әсерінен қуықтың сыйымдылығы азайып, зәр шығару жиілейді және зәр ағынының жылдамдығы төмендеуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін өзіңізге бір шыныаяқ шөп шайын дайындап (дәрігеріңізбен кеңескеннен кейін), тыныш жерде бөпеңіздің қимылдарын бақылаңыз.') WHERE id = '0a949afb-87f2-4780-b137-5c4298637904';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіз салмағының бір бөлігін қоңыр май жасушалары құрайды. Қоңыр май жасушаларының құрылымында қалыпты дене және май жасушаларымен салыстырғанда митохондриялар өте көп болады. Жасушаның энергия өндіретін бөлігі саналатын митохондриялардың саны жасушаның энергияға қажеттілігіне қарай өзгеруі мүмкін. Әсіресе бұлшықет және жүйке жасушалары сияқты энергияны көп қажет ететін жасушаларда олардың саны көп болады. Мысалы, энергияға қажеттілігі өте жоғары ағзалардың бірі — бауыр жасушаларында олардың саны шамамен 2500 болады. Митохондрия органоиды оттекті тыныс алуға қабілетті барлық эукариот жасушаларында кездеседі. Сондықтан қан ағысымен тасымалданатындықтан энергияны қажет етпейтін эритроцит жасушаларында митохондрия болмайды.'), baby_message_kk = COALESCE(baby_message_kk, '"Lightning Crotch" деген не екенін білесіз бе? ⚡ Кейде мен төмен қарай тепкенде немесе басымды бұрғанда, Сіз шат аймағында электр тогы соққандай кенет ауырсынуды сезуіңіз мүмкін. Мұны ағылшынша "Lightning Crotch" (Найзағай жарқылы) деп атайды. Бұл менің жүйкеге тиіп кеткенімнен болады. Ауыртып қойғаным үшін кешіріңіз, мұнда жай ғана орын тар!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Брокколи'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпеңіз кейде өте белсенді қимылдап, кейде қимылы баяуласа, алаңдамаңыз. Қимылдары белгілі бір тәртіпке түскенімен, олардың қарқындылығын үнемі бірдей сезіне бермеуіңіз мүмкін. Мұның ең жиі кездесетін себебі — бөпеңіздің сол сәттегі қалпы. Босануға қолайлы қалыпқа келіп, басын төмен қаратып жатқан бөпе асқазан мен өкпеге көбірек қысым түсіретіндіктен, тынысыңыз тарылуы мүмкін. Бұған қоса, қабырғаға тиген тепкілер Сізге айтарлықтай ауырсыну сезімін тудыруы ықтимал. Ал бөпе аяғымен төмен қарап жатқанда (жамбаспен келу) тік ішек аймағында қысым сезіліп, қуыққа көбірек күш түседі.;;;
Сондай-ақ бөпелер үнемі қозғала бермейді. Бұл кезеңде бөпеңіз тәуліктің шамамен 18-20 сағатын ұйқымен өткізетінін ескеріңіз. Әсіресе Сіз қозғалыста болғанда бөпеңіздің азырақ қимылдауы, ал демалған кезіңізде өте белсенді болуы қалыпты жағдай. Алайда әдеттегіден ерекше тыныштық байқалып, бөпеңіз Сіз үйренгендей белсенді болмаса, дәрігеріңізге хабарласыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Шат аймағыңыз ауырса, аяқтарыңызды тым алшақ ашпаңыз. Көлікке отырғанда алдымен орындыққа отырыңыз, содан кейін екі аяғыңызды біріктіріп ішке кіргізіңіз. Ауыр зат көтеруден міндетті түрде бас тартыңыз.') WHERE id = 'e505d439-55d1-41af-8277-5a18a75a724e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің бұлшықет икемділігі дамуын жалғастыруда. Бұлшықет икемділігінің дамуы бөпеңіздің ұстау күшіне оң әсер етіп, рефлекстердің қалыптасуында маңызды рөл атқарады.;;;
Қимыл-қозғалыс жүйесінің негізін қаңқаға бекіген бұлшықеттер құрайды. Адам ағзасында 650-ге жуық бұлшықет бар, олардың жалпы салмағы орта есеппен бүкіл дене салмағының 40-50%-ын құрайды. Бұлшықеттер үш түрге бөлінеді: көлденең жолақты, бірыңғай салалы және жүрек бұлшықеті. Бұлшықеттердің өзіне тән бірнеше қасиеті бар: қозғыштық, өткізгіштік, жиырылғыштық, созылғыштық және тұтқырлық.;;;
Барлық тірі тіндер секілді, бұлшықеттер де тітіркендіргішке жауап беру қасиетіне ие. Бұлшықеттің мұндай әсерге жауабы жиырылу түрінде жүреді. Жиырылудың бес түрі бар: изометриялық, концентрлік, эксцентрлік, изокинетикалық және тетаникалық жиырылу.'), baby_message_kk = COALESCE(baby_message_kk, '3-ші триместрге қош келдіңіз! 👋 Anacan, біз үлкен бір кезеңді аяқтадық. Екінші триместр аяқталып, енді 3-ші триместр басталады. Мен қазір әжептәуір үлкен бөпе болдым. Ендігі басты міндетім — салмақ қосып, дүниеге келуге дайындалу. Сіздің шаршағаныңызды білемін, бірақ аз ғана қалды. Жақында кездесеміз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Брокколи'), body_changes_kk = COALESCE(body_changes_kk, 'Ішіңіз айтарлықтай үлкейгендіктен, киімдеріңіз тар болуы мүмкін. Әсіресе соңғы триместрде ішіңізді қысып тұратын киімдерден бас тартқан жөн, өйткені олар бөпеңізге жайсыздық тудырып, қан айналымын баяулатуы мүмкін. Сондай-ақ аяғыңызды қатты қысып тұратын шалбар көктамырлардың жұмысына кедергі келтіріп, варикоздың пайда болуына себеп болуы ықтимал.;;;
Тағы бір маңызды мәселе — жүктілік кезінде биік өкшелі аяқкиім кию. Жалаңаяқ тұрған кезде дене салмағының 50%-ы өкшеге, ал 50%-ы башпайларға түсіп, тепе-теңдік сақталады. Биік өкшелі аяқкиім кигенде бұл арақатынас шамамен 10% және 90% болып өзгереді, бұл тепе-теңдіктің елеулі бұзылуына әкеледі. Жүктілік кезінде жатырдың ұлғаюына байланысты дененің ауырлық орталығы онсыз да өзгеретіндіктен, биік өкшелі аяқкиім кию тепе-теңдікті жоғалтып, ауыр жарақат алуға себеп болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Үшінші триместр басталғандықтан, дәрігеріңізбен «резус (Rh) сәйкессіздігін» (егер қан тобыңыздың резус-факторы теріс болса) және глюкозаға жүктеме сынамасының нәтижелерін талқылайтын уақыт келді. Беліңіздің ауырсынуын азайту үшін жүкті әйелдерге арналған бандаж қолдануға болады. Күні бойы бөпеңіздің қимылдарын санай бастаңыз; әдетте 2 сағат ішінде 10 қимыл қалыпты деп есептеледі.') WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада жүктілігіңіздің 7-ші айы басталады. Сонымен қатар жүктіліктің соңғы үш айында, яғни соңғы триместрде бөпеңіз жатырдан тыс өмір сүре алатындай деңгейге дейін дамиды. Бұл кезеңде мерзімінен бұрын босану орын алса, бөпеңіздің өмір сүру ықтималдығы 80%-дан жоғары. 37-ші аптада толық жетілетін өкпе осы аптада мерзімінен бұрын босану болған жағдайда, бөпеңіздің жаңа туған нәрестелердің реанимация бөлімінде көрсетілетін қолдаудың көмегімен тыныс алуына мүмкіндік беретіндей деңгейде дамыған. Мұның басты себебі — сурфактанттың едәуір бөлігі өндіріліп қойған.;;;
Осы аптадан бастап дәрігеріңіз бөпеңіздің қимылдарын санауды ұсынуы мүмкін. Бөпеңіздің ұйықтау және сергек жүру кезеңдері болатынын әрі тәуліктің көп бөлігін ұйқымен өткізетінін ескере отырып, оның қимылдарын санай бастай аласыз. Бұлшықет күші мен дене салмағының артуының арқасында оның сергек кезіндегі әрбір қимылын сезе аласыз. Бөпеңіздің қимылдарын санау үшін оның сергек әрі белсенді болатын уақытын таңдаңыз. Тыныш жерде сол қырыңызбен жатып, әрбір қимылын белгілеп отырыңыз.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, Anacan! Біз үлкен жетістікке жеттік. Жүктіліктің соңғы кезеңіне аяқ бастық. Енді менің басты міндетім — салмақ қосып, дүниеге келуге дайындалу. Маған орын барған сайын тарылып келеді, бірақ күшім артуда. Сізді қатты бір теуіп, «Құттықтаймын!» деймін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Осы апталарда бөпеңізге аса қажет заттардың бірі — кальций. Күнделікті тағамнан кальцийді жеткілікті мөлшерде алмасаңыз, бұл қажеттілік Сіздің сүйектеріңіздегі қор есебінен өтеледі.;;;
Бөпеңіз бен Сіздің эритроциттеріңіздің түзілуіне қатысатын темірге деген қажеттілік тағам және дәрігеріңіз тағайындаған қоспалар арқылы жеткілікті өтелмесе, бөпеңіз өз қан жасушаларын қалыптастырады, ал Сізде қаназдық пайда болуы мүмкін.;;;
Темір мен кальцийден бөлек, үшінші триместрдегі аса маңызды заттардың бірі — осы апталарда бөпеңіздің қарқынды дамып жатқан ми тіндеріне көп мөлшерде қажет болатын Omega-3 май қышқылдары. Omega-3 соя бұршағы мен жаңғақ секілді өсімдік өнімдерінде де кездеседі, алайда оның негізгі көзі — балық. Сондықтан жүктілік кезінде балықты көбірек тұтынған пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы кезеңді атап өту үшін серігіңізбен шағын кешкі ас ұйымдастырыңыз немесе «Baby Shower» өткізуді жоспарласаңыз, оған қажет заттардың тізімін жасаңыз. Өзіңізді марапаттаңыз, Сіз үлкен жұмыс атқарып жүрсіз!') WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптадағы дәрігер тексерісінде бөпеңіздің босануға қолайлы қалыпта немесе жамбаспен жатқаны анықталуы мүмкін. Екі жағдайда да алаңдауға негіз жоқ. Жүктіліктің 34-ші аптасына дейін әр бөпеде жатыр ішінде еркін қозғалып, қалпын өзгертуге жеткілікті қағанақ суы болады. Бөпеңіз өскен сайын басы денесіне қарағанда ауырлай түсіп, тартылыс күшінің әсерінен басын төмен қаратып орналасады. Қынап арқылы босану дәл осы қалыпта жеңіл өтеді. Осылайша бөпелер табиғи жолмен босану кезінде туу жолымен жылжуға дайындалады.;;;
Жүктіліктің 32-34-ші апталарында бөпелердің шамамен 70-80%-ы басын төмен қаратып, босануға қолайлы қалыпқа орналасады. 37-ші аптаға қарай бұл көрсеткіш 95%-ға дейін артады. Кей жағдайларда бөпе жамбаспен жатуы немесе басқаша орналасуы мүмкін. Мұндай жағдайда дәрігер ауруханадағы бақылауды күшейтеді және қажет болса, босану кесарь тілігі арқылы жүргізіледі. Белгілі бір кезеңнен кейін бөпенің әлі де босануға қолайлы қалыпқа келмеуіне қағанақ суының шамадан тыс көп болуы, плацентаның жатыр мойнын жауып орналасуы, жатыр пішінінің ауытқулары және жамбастың тар болуы себеп болуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің ұйқы режимім бар! 🌙 Енді мен кез келген уақытта ұйықтай бермеймін. Менің нақты ұйықтайтын және сергек болатын уақыттарым бар. Әдетте Сіз демалып жатқанда, мен оянамын. Ал ұйықтаған кезде «REM ұйқысы» (көздің жылдам қозғалысы) кезеңінен өтемін. Демек, мен түс көремін! Мүмкін, түсімде Сізді көретін шығармын...'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңде физикалық шаршау қайта сезілуі мүмкін. Ішіңіз айтарлықтай үлкейгендіктен, қозғалу және жайлы ұйықтау қиындайды. Егер қан тобыңыздың резус-факторы теріс (-), ал серігіңіздікі оң (+) болса, осы аптада «Rhogam» (антирезус) инъекциясын алу туралы дәрігеріңізбен сөйлесуіңіз керек (резус-сәйкессіздіктің алдын алу үшін).'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтар алдында ауыр тағам жемеңіз және экрандардан (телефон, TV) аулақ болыңыз. Жылы душ пен бір стақан жылы сүт ұйықтап кетуіңізді жеңілдетуі мүмкін.') WHERE id = '65a58c5e-3cca-4355-b7cb-eb0f566d682e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіздің салмағы 850 грамм да, 1000 грамнан артық та болуы мүмкін. Егер бөпеңіздің салмағы орташа көрсеткіштен төмен немесе жоғары болса, алаңдамаңыз. Барлық бөпелердің бірдей салмақпен дүниеге келмейтінін және дені сау туған бөпелердің салмағы 2500-4000 грамм аралығында болуы мүмкін екенін ұмытпаңыз. Соңғы триместрге аяқ басқан осы күндерден бастап бөпеңіздің салмағы негізгі қарқынмен өсе бастайды.;;;
Соңғы триместрде бөпелер аптасына орта есеппен 250 грамм салмақ қосады. Денсаулығында қандай да бір мәселе болмаса, босану мерзімі кешіккен жағдайда да бөпеңіз салмақ қосуды жалғастырады. Егер Сізге немесе бөпеңізге байланысты қандай да бір мәселе болса, салмақ қосу қарқыны баяулауы немесе тоқтауы мүмкін. Мерзімінде туған бөпе үшін 2500-4000 грамм қалыпты туу салмағы болып саналады. Бөпелер көбіне 3000-3500 грамм салмақпен дүниеге келеді. Бұл көрсеткіш қыздар мен ұлдар арасында орта есеппен 10 пайызға ерекшеленуі мүмкін.;;;
Сонымен қатар, генетикалық факторлар да бөпеңіздің туу салмағын анықтайтын ең маңызды себептердің бірі. Бөпеңіздің жағдайын тек салмағына қарап бағалау дұрыс емес. Дұрыс тамақтанғаныңызға қарамастан, бөпеге қатысты мәселелер, созылмалы аурулар, темекі шегу және генетикалық факторлар туу салмағының төмен болуына әкелуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Көзімді жыпылықтатып жүрмін! 😉 Anacan, мен енді көзімді ашып-жұма аламын. Егер ішіңізге қатты жарық түссе, мен бетімді бұрамын немесе көзімді жыпылықтатамын. Көру қабілетім әлі толық жетілген жоқ, бірақ жарық пен қараңғылықты керемет ажыратамын. Дүниені көруге асығып жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қандағы прогестерон гормонының көбеюіне байланысты жамбас аймағы мен құрсақ қуысындағы байламдар және бұлшықеттер созылып, икемді бола түседі. Бұл өсіп келе жатқан жатырдың бекініп, тұрақты орналасуына көмектеседі. Жүктіліктің соңына қарай омыртқаның жоғарғы бөлігі сәл артқа шалқайып, жатырдың басқа ағзаларға түсіретін қысымын азайтуға тырысады. Жамбасты құрайтын буындар икемді болып, босануға дайындала бастайды. Бұл өзгерістердің барлығы ағзадағы мөлшері артып, деңгейі өзгеретін эстроген мен прогестерон сияқты жүктілік гормондарының әсерінен болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Беліңіз ауырса, йогадағы "Мысық-Сиыр" (Cat-Cow) жаттығуын жасап көріңіз (төрт тағандап тұрып, белді кезекпен бүгіп-жазу). Бұл омыртқаға түсетін қысымды азайтып, бөпеңіздің ыңғайлырақ қалыпқа ауысуына көмектеседі.') WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіз әртүрлі қалыпта жатуы мүмкін. Бөпеңіз үшін ең қолайлы қалып — беті арқаңызға қарай бұрылған "алдыңғы" қалып және басы төмен орналасқан "бастық" қалып. Бұл қалыптың мінсіз деп саналуының бірнеше себебі бар. Мұндай қалыпта бөпеңіз жамбас иініне ыңғайлы орналасады. Ал босану кезінде бөпеге арқасын бұрып, иегін кеудесіне жақындатуға қолайлы жағдай туады. Сонымен қатар, басының төбесі жатыр мойнына қысым түсіріп, толғаққа қажетті гормондардың бөлінуіне көмектеседі. Күшену кезеңі басталғанда бұл дұрыс бұрышты сақтап, бастың босану жолынан оңай өтуіне мүмкіндік береді. Соның арқасында толғақты жасанды түрде қоздырусыз немесе кесарь тілігінсіз босануыңыз мүмкін. Босану жылдамырақ әрі жеңілірек өтіп, ауырсыну аз сезіледі және өзіңізді тезірек жақсы сезіне бастайсыз. Жүктіліктің соңғы апталарына дейін бөпеңіз босануға қолайлы қалыпқа келмеуі мүмкін. Тіпті осы кезеңнің өзінде ол өздігінен бұрыла алады. Кей жағдайда бөпе босану басталған сәтте де бұрылуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тыныс алу жаттығуларын жасап жүрмін! 🌬️ Әрине, мұнда әлі ауа жоқ, бірақ мен кеуде қуысымды көтеріп-түсіріп, амнион сұйықтығын өкпеме тартамын. Бұл жаттығулар диафрагмамды нығайтады. Кейде осы кезде ықылықтаймын. Сол ырғақты соққыларды сезіп жүрсіз бе? Бұл — менің жаттығуым.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Ішек жұмысының бұзылуы мен іш қату — жүктілік кезінде ең жиі кездесетін мәселелердің бірі. Осы кезеңде деңгейі жоғарылайтын жүктілік гормондарының бірі — прогестерон ас қорыту жолындағы бұлшықеттерді босаңсытады. Соның салдарынан ішектегі химус деп аталатын жартылай қорытылған тағам баяу қозғалады.;;;
Сонымен қатар, үлкейген жатыр құрсақ қуысындағы тоқ ішектің әртүрлі бөліктеріне қысым түсіріп, тағам қалдықтарының ілгері жылжуына кедергі келтіруі мүмкін. Соның салдарынан іш қату пайда болады.;;;
Егер іш қату бір аптадан астам уақытқа созылса, мәселенің одан әрі асқынуына жол бермеу үшін міндетті түрде дәрігерге жүгініңіз. Ұзақ уақыт емделмеген іш қату геморройды (көкбауырды) қоса алғанда, көптеген мәселеге әкелуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Тамақтанғаннан кейін бірден жатпаңыз, кемінде 1 сағат тік қалыпта болыңыз. Басыңыздың астына биік жастық қойып ұйықтау асқазан қышқылының кері ағуына жол бермейді. Ас содасы қосылған су ішпеңіз (тұзды болғандықтан ісінуге әкеледі).') WHERE id = 'b00d6682-7d24-499f-8007-e3d98626d47b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ми жасушалары әр секунд сайын миллиондаған нейрон түзуді жалғастыруда. Ми жасушалары өте жылдам көбейіп жатқандықтан, ми көлемі оларға жеткіліксіз болып, оның бетінде қатпарлар қалыптаса бастайды. Бөпеңіздің жетіліп келе жатқан сезім мүшелері арқылы жаңа ақпаратты меңгеруіне қарай осы қатпарлы құрылымдардың қалыптасуы жеделдейді. Ми бетіндегі қатпарлы құрылым мидың көбірек қызмет атқаруы үшін ішке қарай бүктеліп, қосымша аумақ түзуіне мүмкіндік береді. Осы қатпарлардың арқасында адам миының беткі аумағы бас сүйектің ішіндегі шектеулі кеңістікте қатар жайылған екі газет бетінің көлеміндей болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сізді танимын! 🎤 Anacan, Сіздің даусыңыз — мен үшін ең жақын әрі таныс дауыс. Зерттеулер Сіздің даусыңызды естігенде менің жүрек соғысым тынышталатынын көрсетеді. Мен қазірдің өзінде Сіздің дауыс ырғағыңыз бен сөйлеу мәнеріңізді үйреніп жүрмін. Дүниеге келгенімде мені тыныштандыру үшін жай ғана сөйлесеңіз жеткілікті болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Осы апталарда сүт бездеріңіздің өзектерінде жиналған сүттің бір бөлігі ағуы мүмкін. Емізікті кез келген жолмен ынталандыру сүттің бөлінуін арттырып қана қоймай, окситоцин гормонының бөлінуін жеделдетіп, жатырдың жиырылуына әкелуі мүмкін. Сондықтан сүттің бар-жоғын тексеру үшін емізіктеріңізді ешқашан қыспаңыз. Қалыпты жағдайда сүт бездерінен сүттің ағуы мерзімінен бұрын босанумен байланысты емес. Алайда емізіктер ынталандырылса, жатыр бұлшықеттері жиырыла бастайтындықтан, бұл мерзімінен бұрын босануға әкелуі мүмкін. Пролактин гормонының бөлінуі овуляцияны да тежейді, сондықтан бала емізетін аналарда белгілі бір уақыт бойы овуляция болмайды. Аналық жасушалардың жетілуі мен дамуына кедергі келтіретін осы гормонның әсерінен босанғаннан кейін біраз уақыт етеккір келмейді. Кейбір әйелдерде етеккір циклі 6 ай ішінде қалпына келсе, 2 жылға дейін етеккірдің болмауы да қалыпты деп саналады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін кешке өзіңізге аздап уақыт бөліп, бөпеңізге болашақта бірге аттанатын алғашқы саяхатыңыз туралы айтып беріңіз.') WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің ми толқындары қалыптасып үлгерді. Соңғы жылдары жүргізілген зерттеулерге сәйкес, электр энергиясымен жұмыс істейтін ми және ми өндіретін электр толқындары ана құрсағында жатқан кезде-ақ пайда бола бастайды. Ми түзетін бұл толқындар бета, альфа, тета және дельта толқындары деп аталады және Герц (Hz) бірлігімен өлшенеді. Герц бір секундтағы циклдер санын білдіреді. Ми бета күйінде болғанда, дене сергек болады. Бұл — ойлау, сөйлеу, шешім қабылдау, мәселе шешу, жоспар құру және әрекет ету секілді күнделікті өмірде ең жиі қолданылатын ақыл-ой күйі. Күндіз көз жұмылып, дене босаңсыған кезде ми бета жиілігінен альфа жиілігіне ауысады. Бұл күй жеңіл гипноз деп аталады; осы кезде саналы бақылау әлсіреп, шығармашылық қабілет артады. Ал дельта күйі — біз білетін ұйқы режимі. Бұл сана астында емес, санадан тыс жүреді. Ми дельта толқындарында болған кезде дене тынығып, қалпына келу кезеңіне өтеді. Әр адамға ұйқы қажет, өйткені ұйқы кезінде дене жаңарып, жүйке жүйесі тынығады.'), baby_message_kk = COALESCE(baby_message_kk, '28 АПТА АЯҚТАЛДЫ! 👋 Біз ресми түрде 7-ші айға аяқ бастық. Маған орын барған сайын тар болып барады, сондықтан енді сен менің "жүзгенімді" емес, шынтағым мен тіземнің нақты соққыларын сезесің.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен баялды'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл кезеңде гормондар мен ағзалардың ішінара орын ауыстыруына байланысты ас қорыту жүйеңізде елеулі өзгерістер болады. Асқазан қақпақшасының босаңсуы салдарынан асқазан қышқылы өңешке өтіп, қыжыл пайда болуы мүмкін. Сондықтан тамақтанғаннан кейін бірден жатпағаныңыз жөн. Газдалған сусындар, ащы тағамдар және майлы қуырылған ас секілді өнімдермен асқазанды шамадан тыс толтыру қыжылды одан әрі күшейтуі мүмкін. Өңеш қышқылдан қорғалмаған, сондықтан қыжыл жиілеген сайын бұл аймақта тұрақты өзгерістер пайда болуы ықтимал. Сол себепті тамақтану тәртібіне мән беріп, аз мөлшерде, бірақ жиі тамақтану денсаулығыңыз үшін өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, '28 апталық жолды сәтті өткергеніңіз үшін бүгін өзіңізді қуантып, демалыңыз. Аяғыңыздағы ісінуді азайту үшін тұзды тұтынуға мән беріп, аяғыңызды жоғары көтеріп тынығыңыз. Егер әлі жасамаған болсаңыз, бөпеге қажет алғашқы заттардың тізімін құра бастаңыз. Ертеңнен бастап 29-шы аптаға — кездесуімізге тағы бір қадам жақындататын жаңа кезеңге аяқ басамыз!') WHERE id = 'bfd55361-27a4-4f83-b42f-472543bccd24';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Үшінші триместрге қадам басқан осы күндері бөпеңіз аптасына шамамен 150-200 грамм салмақ қосады. Мұндай салмақ өсімінің себебі — майдың жылдам түзілуі. Май жасушаларының саны артқан сайын бөпеңіздің терісі әжімді көріністен арылады. Сондай-ақ осы аптада бөпеңіздің амнион қабы толық жетілген күйде болады. Сыртқы әлемге дайындалып жатқан бөпеңіздің миы мен бас сүйегі қарқынды дамитын кезең басталды. Сезім мүшелері толық қалыптасып, мидағы оларды басқаратын аймақ жетілгендіктен, бөпеңіз сырттан келетін тітіркендіргіштер арқылы үйрене бастайды. Бұл жаңа мәліметтер миға белгілі бір көлемді қажет ететіндіктен, орынды үнемдеу үшін ми құрылымында қатпарлар пайда бола бастайды. Бөпеңіз дүниеге келген сәттен бастап жылдам үйреніп, үйренгендерін жадына сақтау үдерісіне кіріседі. Миындағы қажетті мөлшерден миллиардтаған артық ми жасушаларының бір бөлігі ішінара қырқылу деп аталатын үдеріс арқылы жойылып, жаңа білімге орын босатады.'), baby_message_kk = COALESCE(baby_message_kk, 'Сүйектерім қатайып келеді! 🦴 Anacan, енді мен саған көп мөлшерде кальций қарызбын. Сүйектерім жылдам қатайып жатыр. Күн сайын шамамен 250 mq кальций жинаймын. Егер сен сүтті жеткілікті ішпесең, бұл кальцийді сенің тістерің мен сүйектеріңнен "ұрлаймын". Өзіңді күт, ірімшік же!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде денеңізде ғана емес, миыңыздың биохимиясында да маңызды өзгерістер болады. Осы өзгерістерге байланысты, әсіресе сезімтал адам болсаңыз, депрессияға бейім болуыңыз мүмкін. Депрессия әдетте босанғаннан кейін күшейгенімен, кейде алғашқы белгілері жүктілік кезінде-ақ байқалуы ықтимал. Өзіңізді үнемі ашушаң, түкке тұрғысыз немесе кінәлі сезіну, тәбет пен тамақтанудың бұзылуы, емге басылмайтын ауырсынулар, бұрын қуантқан нәрселерден енді ләззат алмау, қызықтырған оқиғаларға қызығушылықтың төмендеуі, ұйқының қатты бұзылуы, зейін қою мен назарды шоғырландырудың қиындауы — депрессияның белгілері. Бұл кезеңде жұбайыңыз бен отбасы мүшелеріңіздің қолдауына сүйеніп, жақсы нәрселерге көңіл бөліп, ойыңызды мұңайтатын мәселелермен шамадан тыс жүктемеуге тырысыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Кальцийді (сүт, айран, ірімшік) жеткілікті қабылдауға ерекше мән беріңіз, өйткені осы кезеңде бөпеңіз кальцийді Сізден жылдам "ұрлайды". Белдің ауырсынуын азайту үшін отырғанда арқаңызды тірейтін жастықтарды міндетті түрде пайдаланыңыз. Егер әлі бастамаған болсаңыз, бөпенің сөмкесіне қажетті заттардың тізімін жасауға таптырмас уақыт. Бүгін бөпеңізбен бірге баяу музыка тыңдап, тынығыңыз.') WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Мимикалық бұлшықеттері толық жетілді. Ұрық жымиып, бетін тыржитып, тілін шығара алады. Бүйрекүсті бездері "Эстриол" гормонын өндіреді. Бұл гормон ананың ағзасында сүттің түзілуін ынталандырады.;;;
Сүйектену үдерісі шарықтау шегіне жетті. Ұрықтың қаңқасы қатайып келеді. Мидағы жылу реттеу орталығы жұмыс істей бастады. Енді бөпе дене температурасын ішінара реттей алады және амнион сұйықтығының температурасына азырақ тәуелді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен жымиып жатырмын! 😊 Ультрадыбыстық зерттеу кезінде дәрігерлер біздің жымиғанымызды жиі көреді. Бұл әдетте ұйықтап жатқанда болады. Мүмкін, періштелерді көріп жатқан шығармын? Әлде жай ғана бет бұлшықеттерімді жаттықтырып жатырмын ба? Себебі қандай болса да, мен бақыттымын. Сен де жымишы, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Плацента бөпеңіз дүниеге келгенге дейін өкпе, бүйрек және бауыр атқаратын қызметтерді өз мойнына алады. Бөпеңіздің өкпесі әлі өз қызметін атқара алмайтындықтан, бұл міндетті плацента орындайды. Плацента кіндік тамырларынан жинаған қанды Сіздің ағзаңыздан алынған оттегімен тазартып, қайтадан кіндік арқылы бөпеңізге жібереді. Дәл осылай бөпеңіздің ағзасында түзілген барлық қалдықтар бүйрек пен бауыр арқылы емес, плацентаға, одан әрі Сіздің қанайналым жүйеңізге өтіп, сыртқа шығарылады. Осындай өмірлік маңызы бар қызметті атқаратын плацентада кальцийлену, қартаю немесе қан ағымының бұзылуы секілді кез келген мәселе туындаса, бөпеңізге қоректік заттар жеткіліксіз түсуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Созылуға қарсы кремдерді жүйелі түрде қолданыңыз. Алайда созылу іздерінің пайда болуы көбіне генетикаға байланысты екенін ұмытпаңыз. Қышуды азайту үшін салқын душ қабылдап, синтетикалық киімдерден бас тартыңыз.') WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің миында орналасқан эпифиз безі осы аптадан бастап жұмыс істей бастайды. Мидың артқы бөлігінде орналасқан, жасымық дәніндей ғана эпифиз безі бөпеңіздің ағзасындағы мелатониннің бөлінуін реттеп, оның тепе-теңдігін қамтамасыз етеді. Сонымен қатар бұл мүше ағзаның биологиялық сағатын да реттейді. Яғни ұйқы тәртібі, ұйықтау және ояну сияқты көптеген қызметке қатысады. Эпифиз безі бөлетін мелатонин гормоны жыныстық жетілу кезеңін бастайды, жыныстық дамуды қамтамасыз етеді және ұрпақ өрбіту қабілетіне әсер етеді. Ол ағзаның биологиялық сағаты мен ырғағын реттейді. Жасушалардың жаңаруына ықпал етеді. Көздің тор қабығын қорғайды және ағзада қатерлі ісікке қарсы қызмет атқарады. Соңғы жылдары жүргізілген зерттеулер эпифиз безінің көбіне қараңғы ортада белсенді болатынын көрсетті. Қараңғы жерде біраз уақыт болғаннан кейін денеңізді ауырлық басып, ұйқыңыз келуінің себебі де осында. Эпифиз безі әсіресе қараңғы ортада тиімдірек жұмыс істейді. Бұған қоса, өсу кезеңіне белсенді қатысатын бұл без әсіресе жасөспірім шақта бөлетін гормондары арқылы жыныс бездерінің мерзімінен бұрын дамуына жол бермейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Дене қызуымды реттеп жатырмын! 🌡️ Бұрын мен сенің дене қызуыңа толығымен тәуелді едім. Ал қазір миым мен май қабатымның арқасында өз дене қызуымды реттей бастадым. Мен енді кішкентай пеш сияқтымын. Дүниеге келгенде тоңып қалмау үшін дайындалып жатырмын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Көпұрықты жүктілікке байланысты ең үлкен мәселелердің бірі — мерзімінен бұрын босану. Бөпелердің саны артқан сайын жүктіліктің ұзақтығы мен әр бөпенің туылғандағы салмағы азаяды. Егіздер кезіндегі жүктіліктің орташа ұзақтығы шамамен 37 апта болса, үшемдерде бұл мерзім 35 аптаны құрайды. Бөпелер жатырда болған әр апта сайын олардың ағзалары мен жүйелері жетіліп қана қоймай, туылғандағы салмағы да арта түседі. Көпұрықты жүктіліктегі мақсат — мерзімінен бұрын босануды болдырмау үшін жүктілікті мүмкіндігінше ұзақ сақтау. Мұның ең тиімді жолы — төсек режимі. Жүктілік бойы күнделікті әдеттегі істерді жалғастыру әрдайым мүмкін бола бермейді. Дәрігердің төсек режиміне қатысты ұсынымын орындау қажет болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Түнгі ұйқыңыздың сапасын жақсарту үшін сол қырыңызға жатып, аяқтарыңыздың арасына жастық қойыңыз; бұл беліңізге түсетін қысымды азайтады. Ішіңіздің қышуын жеңілдету үшін табиғи құрамды ылғалдандырғыштарды қолданыңыз. Кальций мен темірдің жеткілікті мөлшерде қабылдануына мән беріңіз, өйткені бөпеңіздің сүйектері қазір ең қарқынды қатаю кезеңінде. Бүгін өзіңізді қатты шаршатпаңыз.') WHERE id = '2a9f34ac-1247-4ead-b172-d62294531480';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз өскен сайын жатыр ішіндегі қозғалыс кеңістігі біртіндеп тарылады. Сондықтан ол қолдары мен аяқтарын денесіне қарай жинап, бізге таныс "фетальды қалыпқа" (эмбрион қалпы) енеді. Бұл ұтымды қалып орынды үнемдеп қана қоймай, дене қызуын сақтауға да көмектеседі. Осы кезеңде бөпеңіздің миы таңғаларлық жетілу деңгейіне жетеді. Оның ми орталықтары дүниеге келгеннен кейінгі өмір үшін аса маңызды қызметтерді — тыныс алу мен дене қызуын басқаруды үйреніп жатыр. Тыныс алу орталығы ырғақты қозғалыстарды реттеп, өкпені тыныс алуға дайындайды, ал гипоталамус бөпенің ішкі температурасын тұрақты ұстау үшін "термостат" қызметін атқарады. Бұл бөпеңіздің жатырдан тыс өмір сүруіне миының қаншалықты жақсы дайындалып жатқанын көрсетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Басымды төмен қаратып жатырмын ба? ⬇️ Мен біртіндеп босану қалпына дайындала бастауым мүмкін. Әзірге өте қимылшылмын, айналып жүрмін, бірақ басым ауырлай түскендіктен, тартылыс күші мені төмен қарай тартады. Егер әлі басымды төмен қаратпаған болсам, уайымдама, әлі уақытым көп!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Шап аймағында қысым немесе ауырсыну сезілуі мүмкін. Бөпе өскен және төмен қарай жылжыған сайын жамбас сүйектері мен қуыққа түсетін қысым артады. Дәретханаға жиі бару қажеттілігі қайта туындауы мүмкін. Сондай-ақ "Симфизит" (жамбас сүйектерінің ажырауынан болатын ауырсыну) пайда болуы мүмкін.;;;
Денеңіз ысып кеткендей сезінуіңіз мүмкін. Зат алмасуыңыз бөпеңіз үшін 20% жылдамырақ жүреді, сондықтан ағзада қосымша жылу түзіледі. Тіпті айналаңыздағылар тоңып тұрса да, Сіз үнемі ыстықтап жүруіңіз мүмкін. Тершеңдік күшейеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылды азайту үшін аз-аздан, бірақ жиі тамақтаныңыз және тамақтанғаннан кейін бірден жатпаңыз. Ұйықтағанда сол қырыңызға жату ас қорытуыңызға да, бөпенің қан айналымына да көмектеседі. Беліңіздің ауырсынуын жеңілдету үшін жылы душ қабылдаңыз немесе жеңіл созылу жаттығуларын жасаңыз. Бүгін өзіңізге аздап уақыт бөліп, бөпеңізге дайындап жатқан бөлменің немесе бұрыштың бөлшектерін ойластырыңыз.') WHERE id = '46d5df45-3974-471b-a1a7-d53afb295423';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің әлемді танып-білу үшін пайдаланатын алғашқы әрі ең жақсы дамыған сезімі — сипап сезу. Қазір ол жатыр ішінде нағыз зерттеуші сияқты әрекет етеді: қолдарымен жатыр қабырғаларын сипап байқайды, кіндік бауын ұстайды, саусақтарын сорады және өз бетін жиі сипайды.;;;
Бұл жанасулар жай ғана қимыл емес, мидың сенсорлық дамуы үшін маңызды сигналдар. Бір қызығы, осы кезеңде бөпеңіздің бүйрекүсті бездері де аса маңызды міндет атқарады. Олар кортизол деп аталатын арнайы гормонды бөле бастайды. Кортизол гормоны бөпеңіздің өкпесінің жетілуіне көмектесетін "сиқырлы кілт" қызметін атқарады. Ол өкпе тіндерінде сурфактант деп аталатын заттың түзілуін жылдамдатады. Ал сурфактант өкпедегі ұсақ ауа қапшықтарының бір-біріне жабысып қалуына жол бермейді. Осы үдерістің арқасында бөпеңіз дүниеге келген сәтте алғашқы демін оңай алып, өкпесі ауаға толық толады. Яғни дене қимылдары да, ішкі гормондар да бөпеңізді үлкен "ашылу күніне" — алғашқы демі мен алғашқы жанасуына мінсіз дайындап жатыр.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен сені сеземін! 🤗 Anacan, сен ішіңді сипағанда, әкем қолын қойған кезде мен сол жылу мен қысымды сеземін. Кейде мен де іштен дәл сол жерге қолымды тигіземін. Бұл — біздің "сәлемдесуіміз". Арамызда жұқа ғана қабырға бар. Ал жанымыз біртұтас.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Ұмытшақтық шегіне жетуі мүмкін. Зейін қою қиындауы ықтимал. Кілттерді тоңазытқыштан табу немесе сөйлемнің ортасында не айтқыңыз келгенін ұмытып қалу — қалыпты жағдай. Миыңыз "аналық режимге" ауысып, басымдықтарды өзгертіп жатыр.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде ұйқысыздық пайда болуы мүмкін, сондықтан күндіз қысқа үзілістер жасап, демалуға тырысыңыз. Бүгін кешке бөпеңізбен бірге баяу музыка тыңдаңыз, ол Сізбен бірге сол тыныштықты сезінеді.') WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің лануго түктерінен басқа тұрақты түктері шаш-түк фолликулаларында қалыптаса бастады. Осы тұрақты түктердің арқасында бөпеңіздің денесі су мен жылу тепе-теңдігін сақтай алады. Дененің белгілі бір бөліктеріндегі бұл түктер жылуды оқшаулауға да жауап береді. Шаш-түк фолликулаларында орналасқан кішкентай бұлшықеттер суық ортада жиырылып, түктерді тік тұрғызады және сол аймақта энергия, соның нәтижесінде жылу бөледі. Бөпеңіз дүниеге келгенде денесінде әлі түсіп үлгермеген лануго түктерімен қатар, көзге көрінбейтіндей жұқа тұрақты түктер де болады. Бөпеңіз өскен сайын бұл түктер де қалыңдайды. Алақан, табан және еріннен басқа адам терісінің барлығын түк жауып тұрады. Алайда көп жердегі түктер өте жұқа әрі ашық түсті болғандықтан көрінбейді. Түктердің қара, қоңыр, сары немесе қызыл болуы олардың сыртқы қабатының дәл астында орналасқан пигмент деп аталатын бояғыш заттарға байланысты. Егер түрлі түсті пигменттердің ешқайсысы болмаса, олардың орнын басатын көптеген ауа қуыстары бүкіл жарықты шағылыстырады, сондықтан шаш пен түктер ақ болып көрінеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен Сізді көріп тұрмын (деуге болады)! 💡 Көздерім ашық, егер Сіз ішіңізге қатты жарық түсірсеңіз, мен басымды сол жаққа бұрамын. Жарық көзін бақылай аламын. Менің әлемім қараңғы болса да, кейде ішіңіздің қабырғасынан сүзіліп өтетін әлсіз жарық сәулелерін көре аламын. Бұл мен үшін нағыз ғажайып!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Босануыңызға аз уақыт қалды. Осы кезеңнен кейін, әсіресе ішіңіз едәуір үлкейгендіктен, тіпті қозғалу да қиындауы мүмкін. Осы қиындыққа байланысты қимылсыз жүруді таңдасаңыз, денеңіз әлсіреп, босану қиындауы ықтимал. Сондықтан өзіңізді қатты шаршатпайтын қысқа серуендер жасап, жаттығулар орындауыңыз керек. Жаттығулардың арқасында денеңіз физикалық тұрғыдан нығайып, икемділігі артады. Қол және аяқ бұлшықеттеріңіз күшейіп, бұлшықеттер мен байламдар созылады. Сан мен жамбас аймағының икемділігі артып, жеңіл босануға дайындаласыз. Кегель жаттығулары жамбас түбі бұлшықеттерін нығайтып, жүктіліктің соңғы айларына, босануға және босанғаннан кейінгі қалпына келу кезеңіне дайындалуға көмектеседі.;;;
Зерттеулерге сәйкес, жүктілік бойы дене жаттығуларын жасаған әйелдер босанғанға дейін шамамен 7 килограмм аз салмақ қосады. Әсіресе соңғы кезеңдерде күшейетін аяқтың ісінуі мен домбығуының алдын жаттығулар арқылы алуға болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Варикозға арналған шұлық кию қан айналымын жақсартып, аяқтың ауырсынуын азайтады. Оны таңертең төсектен тұрмай тұрып кию — ең тиімді әдіс.') WHERE id = '98b2e2a6-b569-4828-8904-245e5d1bc37e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктіліктің 7-ші айындағы осы аптадан бастап босанғанға дейін бөпеңіз қазіргі салмағынан шамамен екі есе артық салмақ қосады. Мұның негізгі себебі — оның денесінде қоңыр маймен қатар қалыптасатын ақ май жасушалары. Ақ май тіні артық энергияны май жасушаларында триглицерид түрінде сақтайды және қажет болғанда оны қан айналымы жүйесіне тез қайтара алады. Май тіні — ағзадағы ең үлкен энергия қоры; ол энергияның май жасушаларында жиналуы мен босап шығуын гормондық сигналдар арқылы реттейді. Май тіні май жасушаларынан тұрады және қан тамырлары мен жүйкелерге бай. Ол ерлерде дене салмағының 15-20%-ын, ал әйелдерде 20-25%-ын құрайды. Май жасушалары бейтарап майларды сақтауға және жылу өндіруге бейімделген. Адам ағзасына тағам үзіліспен түсіп, ал энергия үздіксіз жұмсалатындықтан, бұл жасушалар энергия қоры ретінде маңызды қызмет атқарады. Олар жарақаттардан қорғайды және дененің жылуын оқшаулауға белсенді қатысады. Сонымен қатар жүйкелік және гормондық тітіркендіргіштерге өте сезімтал келеді.'), baby_message_kk = COALESCE(baby_message_kk, '29 АПТА! 🎃 Менің көлемім үлкен асқабақтай! Күн сайын адамға көбірек ұқсап келемін. Басым денеме сай пропорцияға жетті. Ендігі басты мақсатым — салмақ қосу. Мен тепкен кезде күшімді бұрынғыдан да жақсырақ сезесіз, солай емес пе?'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Терінің құрылымы серпімді болады. Жүктілік кезінде үлкейген іш пен омырау терінің қосымша созылуына әкеледі. Соның салдарынан тері ылғалын жоғалтып, қыши бастайды. Ішіңіз айқын көріне бастаған апталардан бастап қышу пайда болуы мүмкін. Сонымен қатар омырау мен іш аймағындағы созылу іздері де кейде қышытады. Терінің созылуы мен ылғал жоғалтуына байланысты қышыған жерлерге дәрігеріңіз ұсынған ылғалдандырғыш кремді немесе вазелинді жағуға болады. Бадам майы сияқты майлар да қышуды азайтуға көмектесуі мүмкін. Жүктілік кезінде хош иіссу немесе хош иісті косметикалық өнімдер қышуды күшейтуі мүмкін, сондықтан оларды қолданбағаныңыз жөн. Денеңіздің ылғал тепе-теңдігін сақтау үшін молынан су ішуіңіз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күнделікті тағамыңызды 5-6 шағын порцияға бөліңіз. Үлкен порциялар қыжылды күшейтеді. Тамақтанғаннан кейін бірден жатпаңыз, тік отырыңыз немесе серуендеп жүріңіз.') WHERE id = 'cad83eb0-58a7-4d1b-bb76-60f58c14c58f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің тұрақты тістерінің ұрықтары тіс бүршіктерінде дамуын аяқтады. Бөпеңіз дүниеге келгеннен кейін біраз уақыттан соң шығатын және белгілі бір кезеңге дейін сақталатын сүт тістері тұрақты тістердің дұрыс әрі сау шығуына өте маңызды рөл атқарады. Бөпеңіздің алғашқы тістері 5-8 айлығында қызыл иектің үстінен көріне бастайды. Алдымен төменгі алдыңғы күрек тістер шығады. Әдетте олар бөпеңіз 6 айға толғаннан кейін жарып шығады. Одан кейін шамамен 8-ші айдан бастап жоғарғы күрек тістер шыға бастайды. Артынша бүйір күрек тістер мен азу тістер шығады. Ең соңында артқы азу тістер көрінеді. Төменнен келе жатқан тұрақты тістер сүт тістеріне қысым түсіре бастағанда, сүт тістері түседі. Бұл қысым тіс түбірінің біртіндеп босауына, нәтижесінде тістің түсуіне әкеледі. Тұрақты тістер бөпеңіздің өсу қарқынына қарай 6-7 жасында шыға бастайды. "Ақыл тістері" шыққаннан кейін жалпы саны 32 болатын тұрақты тістердің қалыптасуы аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Маған кальций қажет! 🥛 Сүйектерім тез қатайып келеді. Қазір күн сайын Сіздің қаныңыздан шамамен 250 миллиграмм кальций аламын. Бұл қаңқамның мықты болуы үшін маңызды. Егер Сіз сүт ішпесеңіз, мен сол кальцийді тістеріңіз бен сүйектеріңізден "қарызға" аламын. Өзіңізді күтіңіз, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Шашыңыздағы өзгерісті байқаған боларсыз. Ол қалыңырақ әрі жылтыр болып көрінеді және өте тез өседі. Мұның себебі — жүктілік кезінде бөлінетін гормондар және ең бастысы, қандағы эстроген деңгейінің өте жоғары болуы. Бөпе дүниеге келгеннен кейін эстрогеннің өндірілуі айтарлықтай азайып, оның қандағы деңгейі қалыпқа түседі, соның салдарынан шаштың өсуі едәуір баяулайды. Осы кезде шаш фолликулалары жаппай түсу кезеңіне өтеді де, 2-3 ай ішінде шаш түсе бастайды. Бұл түсу кезеңі 6 ай ішінде аяқталып, түскен шаштың орнына жаңасы өседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы бөпеңіздің қимылын бақылаңыз; оның күрт азайғанын байқасаңыз, дәрігеріңізбен кеңесіңіз. Бүгін аздап демалып, өзіңізді жақсы көретін ісіңізбен қуантыңыз.') WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Күн өткен сайын бөпеңіздің миында миллиардтаған нейрон түзілуін жалғастыруда. Бұл кезеңде нейрондардың жалпы саны бірнеше триллионға жеткен. Бөпеңіздің денесіндегі жалпы саны шамамен 100 триллион жасушаның 7%-ға жуығын жүйке жүйесі құрайды. Бұл ақпарат жеткізудің өмірлік маңызы бар екенін көрсетеді. Жүйке жасушалары атқаратын қызметіне қарай 3 топқа бөлінеді: сезімтал жүйкелер, қозғалтқыш жүйкелер және аралық жүйкелер. Сезімтал жүйкелер сезім рецепторларынан қабылдаған тітіркендіргіштерді ми мен жұлын сияқты орталық жүйке жүйесінің мүшелеріне жеткізеді. Қозғалтқыш жүйкелер орталық жүйке жүйесінен алған пәрмендерді бұлшықеттерге немесе бездерге жеткізеді. Ал аралық жүйкелер орталық жүйке жүйесінде орналасып, қозғалтқыш және сезімтал жүйкелер арасындағы байланысты қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Миым қатпарланып жатыр! 🧠 Бұрын миым тегіс болатын, ал қазір грек жаңғағының дәніндей қатпар-қатпар болып келеді. Неліктен? Өйткені ми жасушаларымның жылдам көбейгені сонша, бас сүйегіме сыйып тұру үшін қатпарлануы керек. Бұл қатпарлар менің ақыл-ойымның, жадымның және қабілеттерімнің дамып жатқанын көрсетеді. Мен данышпан болуға дайындалып жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жалған толғақ жиілеп, айқынырақ сезілуі мүмкін. Ішіңіздің тастай қатуы күніне бірнеше рет болуы ықтимал. Бұл ауыртпайды, бірақ жайсыздық тудыруы мүмкін. Егер толғақ жүйелі болса (мысалы, әр 10 минут сайын) және ауыртса, бұл мерзімінен бұрын босанудың белгісі болуы мүмкін, дереу дәрігерге хабарласыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері босануға арналған сөмкеге қажет гигиеналық құралдарды тізімге біртіндеп қоса аласыз. Ұйқыңыз жайлы болуы үшін кешкі асқа жеңіл тағамдарды таңдаңыз.') WHERE id = '195a150b-6bd1-4a69-9196-35f5d6e3f9f4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бірнеше апта бұрын бөпеңіздің терісінде түзіле бастаған верникс қабаты қалыңдап келеді. Верникс қабаты — жүктіліктің соңғы 3 айында бөпенің терісінде түзіле бастайтын, кремге ұқсас қабат. Бөпелердің барлығы дерлік денесін жауып тұратын верникс қабатымен дүниеге келеді. Мерзімінен бұрын туған бөпелерде верникс қабаты қалыңырақ болса, 40 аптадан асып туған бөпелерде оның өте аз болатыны байқалады. Верникс деп аталатын бұл майлы қабаттың түсі ақ және қоюлығы крем тәрізді. Верникс — Сіз өндіретін гормондардың әсерінен бөпеңіздің терісіндегі май жасушалары бөліп шығаратын майлы секрецияның бір түрі. Құрамында 50-ге жуық ерекше ақуыз бар верникс бөпеңізді құрсақта да, дүниеге келгеннен кейін де кездесуі мүмкін түрлі инфекциялардан тиімді қорғайды. Бөпеңіз дүниеге келгеннен кейін қоршаған ортаға бейімделіп жатқан кезде де оның терісі верникстің арқасында қорғалады. Босанғаннан кейін бөпеңіздің терісі верниксті 1-2 күн ішінде толық сіңіреді. Бұл жаңа туған кезеңде пайда болуы мүмкін бөртпелердің азаюына көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Тебуімді санап жүрсіз бе? 🦶 Дәрігерлер менің қимылдарымды бақылауыңыз керек дейді. Мен әдетте Сіз тамақтанғаннан кейін немесе демалып жатқанда белсенді боламын. Егер ұзақ уақыт қимылдамай қалсам, бір стақан тәтті су ішіп, сол жақ қырыңызбен жатыңыз. Мен бірден белгі беремін. Кейде мен жай ғана қатты ұйықтап жатамын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Егер шап тұсыңыз ауырса, алаңдамаңыз. Бөпеңіздің өсуіне байланысты денеңіздің тепе-теңдік орталығы өзгеретіндіктен, денеңіздің әр жері ауыруы мүмкін. Соның бірі — шап аймағындағы ауырсыну. Шаптың ауыруы — жүктілік кезінде жиі кездесетін шағым. Ол жеңіл сыздап ауыруы да, ара-тұра шаншып қатты ауыруы да мүмкін.;;;
Жүктіліктің бірінші триместрінде шаптың ауыруы жатырдың өсуімен байланысты болса, соңғы триместрде дененің босануға дайындалуынан туындайды. Сондай-ақ ағзада магний жеткіліксіз болғанда мұндай ауырсыну жиілеп, күшеюі мүмкін. Авокадо, орман жаңғағы, бұршақ тұқымдастар, кебекті дәнді дақылдар, майлы балық және банан құрамында магний көп болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Аяқтағы ісіну мен ауырлықты азайту үшін ыңғайлы аяқ киім киіңіз және отырғанда аяқтарыңызды жоғары көтеріңіз. Күні бойы бөпеңіздің қимылдарын бақылауды жалғастырыңыз; әдетте 2 сағат ішінде 10 қимыл сезу қалыпты саналады. Бүгін кешке өзіңізге аздап уақыт бөліп, жылы душ қабылдаңыз және бөпеңізбен бірге алда күтіп тұрған тамаша күндерді елестетіңіз.') WHERE id = 'eadf5bb2-e6e7-4d41-83d0-6c1c3223ad40';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Егер бөпеңіз қыз болса, оның аналық бездері дамып, миллиондаған жұмыртқа жасушаларын қалыптастыруды жалғастырады. Аналық без — жатырдың екі жағында орналасқан және айналасын жалпақ байламдар қоршаған симметриялы екі бездің әрқайсысының атауы. Аналық без — аналық жыныс жасушалары болып саналатын жұмыртқа жасушаларын сақтайтын әйелдің репродуктивті мүшесі. Бөпеңіздің әр аналық безінде жұмыртқа жасушаларын түзуге қатысатын көптеген фолликул бар. Бұл жұмыртқа жасушалары негізінен бастапқы күйде болады және жыныстық жетілу кезеңіне дейін жетілмейді. Жыныстық жетілуден кейін гипофиз безінен бөлінетін гормондардың әсерімен ай сайын бір жұмыртқа жасушасы жетіліп, жатырға қарай жылжиды. Бұл гормондарға жұмыртқа жасушасының жетілуін қамтамасыз ететін FSH, овуляцияны қамтамасыз ететін LH, фолликулдардан бөлініп, екіншілік жыныстық белгілердің қалыптасуын қамтамасыз ететін эстроген және сары денеден бөлініп, жатырдың ішкі қабатын жүктілікке дайындайтын прогестерон жатады. Егер жетілген жұмыртқа жасушасы сперматозоидпен ұрықтанбаса, ол ағзадан шығарылып, етеккір басталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің өлшемім үлкен қырыққабаттай! Anacan, сену қиын, біз жолдың 3/4 бөлігін (75%-ын) аяқтадық! Енді небәрі 10 апта қалды (шамамен). Мен қазірдің өзінде үлкен бөпемін, тек өкпем мен миым әлі толық жетілуі керек. Мәреге аз қалды!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Дәрігер тексерулерінен уақтылы өтуіңіз қағанақ суының азаюы сияқты мәселелерді ерте анықтау үшін өте маңызды. Жүктілік кезінде қағанақ суының азаюы ультрадыбыстық зерттеу (УДЗ) арқылы жүргізілген өлшемдермен анықталады. Жүктілік кезінде қағанақ суы аз деп есептелуі үшін оның жалпы көлемі 500 ml-ден төмен болуы керек. Плацентадағы қан ағымының баяулауы қағанақ суының азаюына әкеледі. Қан тамырларының тарылуынан туындайтын гипертония немесе қандағы гемоглобин деңгейінің төмендеуіне байланысты жағдайларда бөпеге жеткізілетін қан мөлшері азаяды. Бұл өз кезегінде қағанақ суының азаюына себеп болады.;;;
Сонымен қатар ағзаңыздағы сұйықтықтың жалпы тапшылығы және кейбір жағдайларда қант диабеті де жүктілік кезінде қағанақ суының азаюына себеп болуы мүмкін. Дәрігердің хабарынсыз қабылданған кейбір дәрілердің жанама әсерінен де қағанақ суы азаюы ықтимал. Сондай-ақ жүктілік мерзімі өтіп кеткен, 42 аптаға және одан да ұзаққа созылған жүктілікте бұл мәселенің пайда болу ықтималдығы артады.'), daily_tip_kk = COALESCE(daily_tip_kk, '30-аптаның аяқталуын тыныш демалыспен атап өтіңіз. Белдің ауырсынуын азайту үшін отырғанда міндетті түрде арқаңызды тірейтін жастықтарды пайдаланыңыз. Егер әлі дайындамаған болсаңыз, бөпеге арналған сөмкеге негізгі қажеттіліктерді (жөргек, киімдер) жинай бастай аласыз. Ертеңнен бастап 31-аптаға — босануға апаратын соңғы үлкен кезеңге қадам басамыз!') WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы апталар — бөпеңіздің амниотикалық сұйықтығы көбейетін соңғы апталар. Алдағы бірнеше аптада амниотикалық сұйықтық мөлшері артпайды және босанғанға дейін тұрақты күйде қалады. Амниотикалық сұйықтық — бөпеңізді сыртқы орта әсерінен қорғайтын стерильді сұйықтық. Бөпеңіз бұл сұйықтықты жұтады, сондай-ақ ол өкпесі мен терісі арқылы сіңіп, қанға өтеді. Азайған сұйықтық бөпеңіздің зәр шығаруы арқылы қайта толықтырылады. Сұйықтық құрамында бөпеңіздің ағзасындағы биохимиялық үдерістерді көрсететін заттармен қатар, терісінен түскен жасушалар, верникс және лануго түктері де болады.;;;
Амниотикалық сұйықтық бөпеңіздің өсуі мен дамуына көмектеседі. Ол мидың дамуына ықпал етеді. Бөпеңізді дыбыс, соққы, жарық пен қысым сияқты сыртқы әсерлерден қорғайды. Дене температурасын реттеуге және оның тұрақты болуына қатысады. Сезім мүшелерінің дамуын қамтамасыз етеді. Ең алдымен бұлшықет пен жүйке жүйесінің, сондай-ақ көптеген ағза жүйелерінің дамуында маңызды рөл атқарады.;;;
Амниотикалық сұйықтықтың негізгі көзі — бөпеңіздің бүйрегі. Бөпеңіздің бүйрегінен бөлінетін зәр амниотикалық сұйықтықты қалыптастырады. Бөпеңіз бұл сұйықтықты жұтады, содан кейін ол қайтадан қан айналымына өтеді. Қан айналымына өткен сұйықтық бүйректе қайта сүзіліп, зәр түрінде амниотикалық сұйықтыққа қайта қосылады. Бұл айналым үздіксіз қайталанып отырады.'), baby_message_kk = COALESCE(baby_message_kk, 'Тістерім жасырынып жатыр! 🦷 Anacan, қызыл иегімнің астында сүт тістерімнің бастамалары дайын тұр. Тіпті олардың астында тұрақты тістерімнің де бастамалары бар. Мен тіссіз туыламын, бірақ бәрі дайын. Табиғат өте қызық, солай емес пе? Болашаққа қор жинап жатырмыз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қырыққабат'), body_changes_kk = COALESCE(body_changes_kk, 'Кесарь тілігін қажет ететін жағдай болмаса, қалай босанатыныңыз әзірге нақты белгісіз. Соңғы триместрге аяқ басқаннан кейін босану тәсілі туралы ойлана бастағаныңыз жөн. Босану түрлеріне табиғи босану, кесарь тілігі, эпидуралдық жансыздандырумен босану және суда босану жатады.;;;
Қалыпты босану деп аталатын қынап арқылы босану үдерісі айтарлықтай ұзаққа созылады. Қынап арқылы босану үшін жатыр мойны 10 sm ашылуы керек. Алғашқы 4 sm пассивті кезең деп аталады, жатыр мойнының 4 sm ашылуына тіпті 2 аптаға дейін уақыт кетуі мүмкін. Ал 4 sm-ден 10 sm-ге дейін ашылу орта есеппен 4 сағаттан 12 сағатқа дейін созылып, осы кезеңнің соңында жатыр мойны толық ашылады.;;;
Бөпенің теріс жатуы, шамадан тыс ірі болуы, басының босану жолына түспеуі, жүрек соғысының бұзылуы немесе плацентаның жатыр мойнын жауып тұруы сияқты бөпеге байланысты жағдайлар, сондай-ақ Сізде HPV вирусы, преэклампсия, шамадан тыс артық салмақ немесе жамбастың тар болуы анықталса, табиғи жолмен босану мүмкін болмай, міндетті түрде кесарь тілігі жасалады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қуығыңызды толық босату үшін дәретханада отырғанда денеңізді сәл алға еңкейтіңіз. Бұл қуықтың толық босауына көмектесіп, инфекция қаупін азайтады.') WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің секреция бездері дамуын жалғастырып жатыр. Ағзада секреция бездерінің екі түрі бар: ішкі және сыртқы секреция бездері. Сыртқы секреция бездері бөлінділерін арнайы өзектерге шығарса, ішкі секреция бездері өз өнімдерін тікелей қанға бөледі. Қанмен тасымалданатын гормондар қылтамырлар арқылы барлық жасушаларға жетеді.;;;
Осындай бездердің бірі — алдыңғы мидың төменгі бөлігінде орналасқан гипофиз. Онда көптеген гормон өндіріледі. Бұл гормондар бөпеңіздің өсуін, дамуын және жыныстық гормондарының қалыптасуын қамтамасыз етеді. Гипофиз өндіретін гормондар бөпеңіз ұл болса, сперматозоидтардың, ал қыз болса, жұмыртқа жасушаларының түзілуіне әсер етеді, сондай-ақ ағзадағы су теңгерімі мен қан қысымын реттейді. Қалқанша без өндіретін гормондар арқылы зат алмасу жылдамдығын реттеп, бөпеңіздің өсу кезеңінде сүйектену үдерісін жеделдетеді. Сонымен қатар жасушалардың оттегіні пайдалануын реттейді. Бүйрекүсті бездері ағзаны ықтимал қауіптен қорғау үшін адреналиннің бөлінуіне және минералдық теңгерімді реттеуге қатысады. Ал аралас секреция безі болып саналатын ұйқы безі инсулин мен глюкагон сияқты гормондарды, сондай-ақ ас қорыту ферменттерін бөліп, қандағы қант деңгейінің реттелуін қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, '200 КҮН! 🎉 Anacan, сенгісіз! Бірге болғанымызға 200 күн болды. Мен үлкен асқабақтаймын. Қазір мен өте күштімін. Тебуім кейде Сізге ауыр тиюі мүмкін, бірақ мен жай ғана күшімді сынап жатқанымды біліңіз. Кездесуімізге аз қалды!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Шамамен екі айдан кейін дәрігеріңіз жамбастың босануға жарамдылығын бағалау үшін оның өлшемдерін тексереді. Бұл тексерудің мақсаты — жоспарлы кесарь тілігі белгіленбеген жағдайда, жамбастың қынап арқылы босануға сәйкес келетінін анықтау. Жамбастың жоғарғы бөлігінің тар болуы сияқты құрылымдық ерекшеліктер анықталса, тарылу дәрежесіне қарай босанудың басқа тәсілдері таңдалуы мүмкін.;;;
Жамбас қуысы — айналасын бұлшықеттер мен дәнекер тіндер қоршаған, диаметрі шамамен 10 sm болатын жол. Бөпеңіз осы жол арқылы өтіп, дүниеге келеді. Оның ішкі құрылысы тегіс емес, ойлы-қырлы болады. Бөпеңіз бұл жолдан өтуі үшін босану кезінде белгілі бір қалыптарға келуі керек. Жатырдың жиырылуы бөпеңізді алға итеріп, оған бағыт береді.;;;
Бөпеңіз жамбас сүйектерінің жоғарғы шекаралары түзетін босану жолының кіреберісіне басын көлденең ұстап кіреді. Жолдың ортасына жеткенде басын 90 градусқа бұрып, жүзін Сізге қаратады, ал жолдың соңына жеткенде басы осы қалыпта шығады. Басы шыққаннан кейін иықтары да босану жолына енуі үшін басын Сіздің бір аяғыңыздың ішкі жағына қарай бұрады. Бұрылу аяқталған соң денесінің қалған бөлігі шығып, босану жүзеге асады.'), daily_tip_kk = COALESCE(daily_tip_kk, '200-ші күнді өзіңізге шағын сыйлық жасап немесе демалуға уақыт бөліп атап өтіңіз. Беліңіздегі ауырсынуды азайту үшін отырғанда аяғыңыздың астына кішкентай орындық қойыңыз. Ұйықтағанда сол жақ қырыңызбен жатып, тізелеріңіздің арасына жастық қоюды жалғастырыңыз; бұл қан айналымын жақсартады. Егер әлі бастамаған болсаңыз, бөпе бөлмесін дайындауға немесе перзентхана сөмкесіне қажетті заттар тізімін толықтыруға қолайлы уақыт.') WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің терісінің әрбір шаршы сантиметрінде шамамен 110 тер безі, 15 май безі және температураға сезімтал 3000-ға дейін жасуша бар. Тері астында қалыптасатын осы тер бездері арқылы жүзеге асатын терлеу — адамның еркінен тыс жүретін зат алмасудың табиғи қызметі. Оның міндеттеріне дене температурасын тұрақты ұстау және бөлу жүйесінің жұмысына көмектесу жатады. Бөпеңіздің денесінде қалыптасқан бұл бездердің шамамен жартысы иіссіз әрі мөлдір сұйықтық бөлетін тер бездері. Мөлдір тер бөлетін бездердің көбі табанда, алақанда және бет аймағында орналасады. Ал қою әрі иісті тер бөлетін бездер қолтық пен жыныс мүшелері аймағы сияқты белгілі бір жерлерде болады. Қолтық аймағында мөлдір және қою тер бөлетін бездердің саны бірдей болғанымен, дененің басқа бөліктерінде мөлдір тер бөлетін бездер он есе көп. Терлеудің негізгі қызметі — дене температурасын реттеу. Мөлдір тер бөлетін бездерден шыққан сұйықтық буланып, дененің салқындауына көмектеседі. Дене температурасын мидың гипоталамус аймағындағы жылу реттеу орталығы басқарады. Бұл үдеріс мөлдір тер бөлетін бездерден тердің шығарылуы және терідегі қан ағымының реттелуі арқылы жүзеге асады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен түс көріп жатырмын! 😴 Anacan, миымның дамығаны сонша, енді мен "REM ұйқысы" (көздің жылдам қозғалысы) кезеңіне өте аламын. Яғни мен ресми түрде түс көріп жатырмын! Түсімде нені көріп жүр екенмін? Сіздің даусыңызды ма, әлде әлгі дәмді тортты ма? Күннің көп бөлігін ұйқымен өткіземін, бірақ ояу кезімде өте белсендімін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен асқабақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің осы кезеңінде беліңіз бен арқаңыз қатты ауыруы мүмкін. Бұған бөпеңіз жатқан жатырдың жоғары қарай көтерілуі салдарынан денеңіздің ауырлық орталығының өзгеруі себеп болады. Мұны жеңілдетудің ең жақсы жолы — дене жаттығуларын жасау, жүкті әйелдерге арналған пилатеспен және йогамен айналысу. Бұл тәсілдер жүктілікке байланысты ауырсыну мен түйілуді жеңілдетіп қана қоймай, дене қалпының бұзылуын да түзетуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ауыр үй жұмыстарын істемеңіз. "Ұя дайындауға" деген күш-қуатыңызды жеңіл жұмыстарға (киім жууға, бөлмені безендіруге) жұмсаңыз. Перде ілуге немесе жиһаз жылжытуға қатаң тыйым салынады!') WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің көзіндегі түсті бөлік — нұрлы қабық құрылымында пигменттену жалғасуда. Нұрлы қабық көз қарашығының көлемін және көзге түсетін жарық мөлшерін реттейді. Көз түсі алуан түрлі болғанымен, нұрлы қабықтың түсіне пигменттің бір ғана түрі жауап береді. Егер нұрлы қабықтың алдыңғы қабатындағы пигмент көп болса, бөпеңіздің көзі қоңыр, аз болса жасыл, ал мүлде болмаса көк болады. Бөпеңіздің көз түсі ұрықтану орын алған алғашқы сәттен-ақ анықталады. Бұл пигменттену жүктіліктің 4-ші аптасынан бастап қалыптаса бастайды. Пигменттің түзілуі өте ерте кезеңде басталғанымен, бөпеңіздің көз түсін білу үшін ол дүниеге келгенге дейін күтуіңіз керек. Бөпеңіздің көзінде меланин пигменттері түзілгенімен, бұл жасушалардың жетілуіне белгілі бір уақыт қажет. Басқаша айтқанда, әзірге көздің түсі толық айқындалмаған. Әдетте бөпеңіз дүниеге келгеннен кейін 5 ай өткен соң көзінің тұрақты түсі анықтала бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен «түктерімді» түсіріп жатырмын! 🐻 Денемнің «лануго» деп аталатын түктермен жабылғанын айтқаным есіңізде ме? Енді май қабатым мені жылы ұстайтындықтан, бұл түктерге қажеттілігім азайып келеді. Олар біртіндеп түсе бастады. Менің терім тегіс әрі жұмсақ болып барады. Дүниеге келгенімде арқамда біраз түк қалуы мүмкін, бірақ олардың көбі түсіп қалады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен орамжапырақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің соңына жақындаған осы апталарда босанудың басталғанын түсіну үшін кейбір белгілерді білу маңызды. Шырышты тығын босануға 1 ай қалғанда да, босанудан бірнеше сағат бұрын да түсуі мүмкін. Ал босануға аз уақыт қалғанда қағанақ суының кетуі — босанудың тағы бір белгісі. Бұл сұйықтық су тәрізді, ағып тұратын және өте ашық сары түсті болуы мүмкін. Қағанақ суы кенеттен кетеді, мұндай жағдайда бірден ауруханаға барған дұрыс. Су кеткеннен кейін бөпеңіз микробтардан қорғансыз қалуы мүмкін.;;;
Қағанақ суы кеткеннен кейін босану ең кеш дегенде 48 сағат ішінде болуы керек. Одан ұзақ уақыт өтсе, бөпеңізге инфекция жұғу қаупі айтарлықтай артады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күндіз қысқа уақыт ұйықтау (15-20 минут) күш-қуатыңызды қалпына келтіруге көмектеседі. Алайда тым ұзақ ұйықтамаңыз, әйтпесе түнгі ұйқыңыз бұзылуы мүмкін. Баспалдақтан түскенде тұтқадан ұстаңыз.') WHERE id = '1dccc97f-570f-4f2a-ba96-d46cdb785a71';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілігіңіздің 30 аптасы артта қалды. Бөпеңіздің денесінде сүйектену үдерісі қарқынды жүріп, қаңқа жүйесі едәуір дамыды. Ал бассүйек сүйектері әлі толық сүйектенбеген. Бұл бөпеңіздің босану жолынан жеңіл өтуіне мүмкіндік береді.;;;
Еңбек — бөпеңіздің бассүйек сүйектері толық сүйектенгенге дейін олардың түйіскен жерлерінде болатын шеміршекті аймақ. Бассүйекте 6 еңбек бар және босануға жақын уақытта олардың 5-еуі жабылады. Бөпеңіз дүниеге келгеннен кейін тек бастың алдыңғы жағындағы еңбек ашық қалады. Бөпеңіздің басындағы еңбек аймағы дәнекер тіннен тұрады. Бұл құрылым сүйектердің бір-бірінің үстіне жылжуына мүмкіндік беріп, бассүйекке икемділік береді. Соның арқасында бас босану жолына еніп, босану жүзеге асады. Дүниеге келгеннен кейін де мидың өсуі бассүйектің ұлғаюы арқылы жалғасады. Бассүйектің осындай икемді құрылымының арқасында бөпеңіздің миы өсуінің шамамен 75%-і өмірінің алғашқы 2 жылында жүреді.'), baby_message_kk = COALESCE(baby_message_kk, 'Миым өсіп жатыр! 🧠 Anacan, қазір менің миым таңғажайып жылдамдықпен дамып келеді. Онда миллиардтаған жаңа байланыс түзіліп жатыр. Енді мен тек рефлекстермен қимылдамаймын, мен ойлаймын, сезінемін және есте сақтаймын. Сіздің даусыңыз — менің ең сүйікті естелігім.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен орамжапырақ'), body_changes_kk = COALESCE(body_changes_kk, 'Үшінші триместрдің басталуымен Сізде босанудан қорқу сезімі пайда болуы мүмкін. Осы кезеңде орташа деңгейдегі алаңдаушылық пен толқу қалыпты жағдай болып саналады. Алайда шамадан тыс уайымдау Сізге де, бөпеңізге де зиян тигізуі мүмкін. Әсіресе бұрын босанбаған болсаңыз, жағдай күрделірек көрініп, белгісіздіктен қосымша мазасыздық сезінуіңіз ықтимал. Бұл кезеңде жақындарыңыздың жаныңызда болуы және жұбайыңыздың қолдау көрсетуі өзіңізді жайлырақ сезініп, қорқынышыңызды жеңуге көмектеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жалған толғақ кезінде дене қалпыңызды өзгертіңіз, су ішіңіз және терең тыныстаңыз. Сол жақ қырыңызбен жату толғақты басуы мүмкін. Әрдайым жаныңызда су ұстаңыз, өйткені сусыздану толғақты күшейтеді.') WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің жас өзектері қалыптасқанымен, олардың бір бөлігі туылған кезде жабық болады. Сондықтан дүниеге келгеннен кейін біраз уақытқа дейін бөпеңіз жыласа да, көзінен жас ақпауы мүмкін. Жас бездері түзген жасты төменгі қабақтағы саңылаулар арқылы мұрын қуысына ағызады. Бұл жағдай бөпеңіз дүниеге келгеннен кейін шамамен 3 аптаға дейін жалғасуы мүмкін. Көз жасы — бөпеңіздің көзінің жоғарғы бөлігінде орналасқан жас бездері бөлетін мөлдір әрі тұзды сұйықтық. Ол көзді ылғалдандырып, үйкелістің алдын алуға көмектеседі. Сонымен қатар оның маңызды бактерияға қарсы қасиеттері бар. Көз жасы көз алмасының көз ұясында еркін қозғалуын қамтамасыз етіп, көзге түскен шаң мен бөгде заттарды залалсыздандыруға көмектеседі. Көз жасының шамамен 98%-і судан тұрады. Қалған бөлігінде қан плазмасындағыдай мөлшерде несепнәр, сондай-ақ аз көлемде глюкоза, тұздар және органикалық заттар бар. Жас бездері көз жасының 3 түрін түзеді. Олар: негізгі көз жасы, рефлекстік көз жасы және эмоциялық себептерден ағатын көз жасы.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің бассейнім тарылып барады! 🏊‍♂️ Мен өскен сайын айналамдағы су маған аздық етеді. Шамамен 1 литрге жуық су бар, бірақ мен соншалық көп орын алып жатырмын, тіпті қимылдау қиындай түсті. Енді Сіз менің шынтағым мен тіземнің әрбір қимылын анық сезесіз. Кейде Сізді ауыртып қоямын, кешіріңіз.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Үлкен орамжапырақ'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде құрма жеудің көптеген пайдасы бар. Құрма ақуызға, калийге, магнийге, марганецке, темірге, мысқа және B1, B2, B3, A1, C дәрумендеріне өте бай. Құрамында талшық көп болғандықтан, ұзақ уақыт тоқтық сезімін береді және ас қорыту жүйесінің жұмысын реттеуге көмектеседі. Құрманың құрамында әртүрлі антиоксиданттар бар және ол пайдалы табиғи көмірсулардың көзі болып саналады. Сондай-ақ ол тойымды, қандағы қант деңгейін реттеуге көмектеседі және сол арқылы жүктілік кезінде салмақты бақылауға пайдалы. Құрамындағы фолий қышқылы жүктілік бойы бөпеңіздің сау дамуына ықпал етеді. Құрманың құрамында окситоцин деп аталатын зат бар. Окситоцин жатыр мойнының сыртқы араласусыз жеңіл ашылуына көмектеседі. Сондықтан құрма табиғи жолмен босануды жеңілдететін маңызды тағамдардың бірі болып саналады.;;;
Бұл тақырып бойынша әзірге нақты зерттеу нәтижесі болмаса да, құрамындағы окситоцин жатыр мойнының мерзімінен бұрын ашылуына ықпал етуі мүмкін болғандықтан, жүктілік кезінде құрманы шамадан тыс жеуден бас тартқан жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ентіккен кезде тік тұрып, қолдарыңызды басыңыздан жоғары көтеріңіз. Бұл қабырғалардың кеңеюіне көмектеседі. Асқазан көкетті одан әрі қыспауы үшін аз мөлшерден жиі тамақтаныңыз.') WHERE id = '676af173-b90a-4c64-a591-ff651fa5a3ea';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз алғаш дүниеге келгенде оның терісі сұр, көк және күлгін реңктердің арасында болуы мүмкін. Сонымен қатар денесі амнион сұйықтығынан дымқыл болып, верникс қабатымен жабылады. Бөпеңіз тыныс ала бастағаннан кейін алдымен беті мен денесі, ал көп ұзамай қолдары мен аяқтары қызғылт түске еніп, терісінің түсі қалыпқа келеді. Жаңа туған бөпелердің терісінің сыртқы көрінісі жүктіліктің қай аптасында дүниеге келгеніне байланысты өзгеруі мүмкін. Шала туған бөпелердің терісі өте жұқа әрі мөлдір болып көрінеді. Олардың денесі лануго деп аталатын нәзік түктермен жабылады және құрсақта амнион сұйықтығының ішінде жатқанда терісін қорғайтын, ірімшік тәрізді верникс қабатымен дүниеге келеді. Жүктілік мерзімі ұзарған сайын бөпенің терісіндегі верникс қабаты мен лануго түктерінің мөлшері азаяды. Бөпелердің терісі өте жұқа болғандықтан, әдеттегіден қызғылттау көрінуі мүмкін. Терідегі бұл қызғылт реңк қылтамырларға байланысты пайда болады. Сондай-ақ бөпелердің жартысына жуығы бетінде ұсақ безеулерге ұқсайтын ақ немесе сары түйіршіктермен дүниеге келеді. Бұлар — бітелген май бездері, олар қысқа уақыт ішінде өздігінен жоғалады.'), baby_message_kk = COALESCE(baby_message_kk, 'Саусақтарымды сорып жатырмын! 👍 Бұл — менің ең сүйікті ісім. Ультрадыбыстық зерттеу кезінде менің бас бармағымды сорып жатқанымды жиі көре аласыз. Бұл мені тыныштандырып, жақ бұлшықеттерімді нығайтады. Дүниеге келгенде Сіздің сүтіңізді ему үшін жаттығып жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде қынап аймағында жайсыздық тудыратын қышу пайда болуы мүмкін. Бұған аллергиялық жағдайлар, тітіркендіргіш химиялық заттар, гестациялық диабет, экзема сияқты тері аурулары, жыныстық жолмен берілетін аурулар немесе зеңдік инфекция себеп болуы ықтимал.;;;
Жүктілік кезіндегі гормондық өзгерістерге байланысты қынап инфекцияларының пайда болу қаупі едәуір артады. Егер қышу қынап инфекциясынан туындаса, сол аймақта қызару мен ісіну байқалуы мүмкін. Қышумен бірге ақ түсті қою бөлінді де болуы ықтимал. Жүктілік кезінде қолдануға болмайтын кремдер мен жақпамайлар, жұмсартқыш сабындар мен жуғыш құралдар, қынапқа арналған спрейлер және хош иісті дәретхана қағазы қышуды күшейтуі мүмкін. Қынап аймағыңыз қышыса, дәрігеріңіздің кеңесімен емдік әрі тыныштандыратын кремдер мен жақпамайларды қолдану шағымдарыңызды жеңілдетуге көмектеседі. Сонымен қатар киімдеріңізді кір жуғыш ұнтақтың орнына сабын ұнтағымен жуып, мақта матадан тігілген іш киім киіңіз және оны күн ішінде жиі ауыстырыңыз. Денеңізді қыспайтын ыңғайлы киімдерді таңдап, қынап аймағын әрдайым таза әрі мүмкіндігінше құрғақ ұстаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қолдарыңыздың ұюын азайту үшін оларды жиі сілкіп, жоғары көтеріңіз. Түнде білезік-ортез тағу жүйкеге түсетін қысымды азайтуы мүмкін.') WHERE id = 'd4779c73-b7cd-4428-bca1-d013881798d5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '32-аптаға қарай бөпеңіздің қол тырнақтары саусақтарының ұшына дейін өседі. Ал аяқ тырнақтары саусақ ұшына 36-аптада жетеді. Бөпеңіздің 10-аптада дами бастаған тырнақтары кератиннен тұрады және өмір бойы өсе береді. Тырнақ құрылымындағы кератиннің құрамында күкірт мөлшері жоғары аминқышқылдары бар. Осы апталарда бөпеңіз жиі ықылықтауы мүмкін. Босану жақындаған сайын ықылықтың жиілігі де артады. Бөпелер ему рефлексімен дүниеге келеді. Бұл рефлекс бөпенің ана құрсағында амнион сұйықтығын жұтып, ықылықтауы нәтижесінде қалыптасады. Тіпті осы аптада дәрігер тексеруі кезінде ультрадыбыстық зерттеу арқылы бөпеңіздің ықылықтап, саусағын сорып жатқанын көре аласыз.'), baby_message_kk = COALESCE(baby_message_kk, '5 сезім мүшем де жұмыс істейді! 🖐️👃👂👀👅 Көру, есту, дәм сезу, иіс сезу және сипап сезу. Менің барлық сезімім сергек. Сіздің даусыңызды естимін, жеген тағамыңыздың дәмін сеземін, жарықты көремін, бетімді ұстаймын. Мен бәрін толық сезінетін тіршілік иесімін. Сіз — менің бүкіл әлемімсіз, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Эмоциялық тұрғыдан «ұя салу» түйсігі күшеюі мүмкін. Үйді тазалап, бөпенің киімдерін жуып, үтіктегіңіз келеді. Осы күш-қуатты пайдаланыңыз, бірақ өзіңізді қатты шаршатпаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ісінуді азайту үшін суды молынан ішуді жалғастырып, тұзды барынша азайтыңыз. Беліңіз ауырса, міндетті түрде жүкті әйелдерге арналған жастықты қолданып, тік отыруға тырысыңыз. Егер әлі жасамаған болсаңыз, бөпе бөлмесінің соңғы ұсақ-түйектерін аяқтап, балалар арбасы сияқты ірі заттарды сатып алуға ең қолайлы уақыт осы. Өйткені алдағы апталарда қозғалу қиындай түсуі мүмкін.') WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің сүйектері «бастапқы сүйек тіні» деп аталады, яғни олар әлі толық жетілмеген. Ана құрсағында бөпе сүйектерінің дәнекер тіні әлі толық қалыптасып, жеткілікті деңгейде қатаймаған. Сүйектер — денені қорғайтын, тік тұру мен тіректі қамтамасыз ететін және дене қимылдарын іске асыратын қаңқа жүйесінің бір бөлігі. Сондай-ақ олар қан түзілуін қамтамасыз ететін сүйек кемігінің орналасқан орны болып табылады. Сүйек тіні ағзадағы кальцийдің қоры қызметін атқарады және ағзаның күнделікті кальций қажеттілігі осы қордан қамтамасыз етіледі.;;;
Бөпеңіздің ішегінде меконий жинала береді. Меконий бөпенің сілекейінен, асқазан және ұйқы безінің сөлдерінен, жасуша қалдықтарынан, шырыш пен лануго түктерінен тұрады. Ішекте болған кезде ол стерильді болады. Дүниеге келгеннен кейін 48 сағат ішінде ағзадан шығарылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен зәр шығарып жүрмін! 🚽 Күлкілі естіледі, бірақ мен күніне шамамен жарты литр зәр шығарып, оны амнион сұйықтығына араластырамын. Содан кейін сол сұйықтықты қайта жұтамын. Бұл айналым менің бүйрегім мен ас қорыту жүйемнің сау екенін көрсетеді. Мен өз сұйықтығымды өзім реттеп жүрмін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Қолдарыңыз бен аяқтарыңыздағы ісіну таңертең де сақталуы мүмкін. Егер бетіңіз кенеттен ісінсе, қан қысымыңызды өлшеңіз. Сондай-ақ «Carpal Tunnel Syndrome» (білезік өзегі синдромы) салдарынан қолдарыңыз ұйып, ауыруы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ыңғайлы аяқ киім кию өте маңызды. Биік өкшелі аяқ киімнен толық бас тартыңыз. Бел ауырса, жүкті әйелдерге арналған бандаж тағу пайдалы болуы мүмкін.') WHERE id = 'b1c4365d-e81a-4bcf-93eb-e36cdbc64c30';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің өсу қарқыны қазір «рекордтық» деңгейге жетті — ол апта сайын шамамен 200 грамм салмақ қосады! Мұндай жылдам өсу тері астындағы май қабатының қалыңдауына да, ішкі ағзалардың салмағының артуына да байланысты. Осы апталарда өкпесі әлі де дамып жатыр. Бөпеңіз құрсақта тыныс алу жаттығуларын жасап жүргенімен, өкпесінің сыртқы ортада толық өздігінен жұмыс істеуі үшін әлі бірнеше апта қажет. Осы уақыт ішінде өкпедегі ауа қапшықтары одан әрі жетіледі. Ал бөпеңіздің ұйқы тәртібі біршама нақты әрі жүйелі бола бастады. Ол белгілі бір уақытта ұйықтап, белгілі бір уақытта оянып, «жаттығуларын» жалғастырады. Оның ұйқы кезеңдері жаңа туған бөпенің ұйқы тәртібіне ұқсайды.'), baby_message_kk = COALESCE(baby_message_kk, '31 АПТА! 🥥 Сәлем, Anacan! Менің көлемім кокостай (кокос). Салмағым 1.5 кг-ға жетті, ал бойым 41 см. Мен қазір айтарлықтай «салмақтымын». Ендігі басты мақсатым — өкпемді жетілдіріп, көбірек май жинау. Мен дүниеге келуге дайындалып жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Қабырғаның ауыруы мен ентігу Сізді мазалауы мүмкін. Жатыр көкетті және өкпені жоғары қарай қысады. Терең тыныс алу қол жетпес нәрседей көрінуі мүмкін. Бөпеңіздің аяқтары қабырғаларыңыздың арасына тірелуі ықтимал.;;;
Сондай-ақ шаршау мен әлсіздік қайта оралуы мүмкін. Ішіңіздің ауырлығы, ұйқысыз түндер және ағзаның энергияға деген қажеттілігінің артуы түстен кейін Сізді әбден қалжыратуы мүмкін. Өзіңізді батырдай көрсетуге тырыспаңыз, Сізге демалу қажет. Сонымен қатар тепе-теңдікті сақтау қиындап, сүрініп қалуыңыз мүмкін, абай болыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Босану сөмкесін жинай бастауға қолайлы уақыт. Тізім жасап, қажетті заттарды асықпай жинаңыз. Асығудың қажеті жоқ, бірақ алдын ала дайын болу Сізге тыныштық сыйлайды.') WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы кезеңде бөпеңіз тәулігіне шамамен жарты литр несеп бөледі. Ол амнион сұйықтығын жұтып, түзілген несебін қайтадан сол сұйықтыққа бөлу арқылы айналым жасайды, соның арқасында сұйықтық мөлшері қажетті деңгейде сақталады. Амнион сұйықтығының мөлшері мен құрамы жүктілік бойы үздіксіз өзгеріп отырады. Жүктіліктің алғашқы апталарында ол қаныңыздан сүзіліп түзіліп, бөпеңізді қоректік заттармен және оттегімен қамтамасыз ететін құрамға ие болады. Кейінгі апталарда амнион сұйықтығының құрамы өзгеріп, су, бейорганикалық тұздар, ақуыз, май, көмірсулар мен ферменттерден, сондай-ақ бөпеңіз 12-ші аптадан бастап бөлетін несептен тұрады. Бұл сұйықтық бөпеңіздің ему рефлексінің қалыптасуына және өкпесінің дамуына айтарлықтай ықпал етеді. Сонымен бірге оның созылу және бұрылу сияқты қимылдарды еркін жасауына мүмкіндік беріп, сүйек-бұлшықет жүйесінің дамуын қамтамасыз етеді. Сырттан соққы болған жағдайда амнион сұйықтығы бөпеңізді қорғайды. Амнион сұйықтығы орта есеппен әр 3 сағат сайын жаңарып, құрамы өзгеріп отырады. Бөпеңіз бөлетін несеп те амнион сұйықтығының жаңаруына әсер етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Көзімнің түсі қандай? 👁️ Қазір барлық бөпелердікі сияқты менің де көзім қою көк немесе сұр түсті. Туғаннан кейін жарықпен жанасқанда оның шынайы түсі (қоңыр, жасыл немесе жаңғақ түсті) белгілі болады. Бұған 6-9 ай кетуі мүмкін. Бірақ қалай болғанда да, мен Сізге сүйсіне қараймын.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Ұлғайған жатыр айналасындағы бұлшықеттер мен байламдардың созылуына байланысты қынапта ауырсыну пайда болуы мүмкін. Ішіңізде өсіп жатқан бөпеңіздің әсерінен ұлғайған жатыр денеңіздің ауырлық орталығын өзгертіп, беліңіз бен ішіңіздің төменгі бөлігін ауыртуы мүмкін. Іш айтарлықтай үлкейетін үшінші триместрде бұл байламдардың созылуы кенет қимылдағанда шап тұсында тартылу немесе пышақ сұққандай ауырсыну тудырады. Бұған жұмыр байламның созылуы себеп болады.;;;
Жүктілік кезінде жатырдың ауыруын көбіне қынаптағы ауырсынумен шатастырады. Жүктіліктің соңғы апталарында жатыр мойны жұмсарып, аздап ашыла бастауы мүмкін. Бұл босанудан бірнеше апта бұрын басталуы ықтимал. Жүктілік кезінде қынаптағы ауырсыну осындай ашылу барысында қатты және пышақ сұққандай сезілуі мүмкін. Бұл босану толғағы басталды дегенді білдірмейді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Шонданай жүйкесі ауырса, ауырған жақпен жатпаңыз. Жылы ванна қабылдаңыз немесе ауырған жерге жылы компресс қойыңыз. Дәрігеріңізбен кеңесіп, жүкті әйелдерге арналған физиотерапия немесе массаж жасатуға болады.') WHERE id = 'ef1f18bb-3c48-4a2a-96b2-7141d5fc2528';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіздің басында, шашты бөлігінде босану ісігі деп аталатын ісіну пайда болуы мүмкін. Бұл қалыптасу үдерісі деп аталады. Молдинг — босану кезінде бөпеңіздің бас пішінінің және белгілі бір дәрежеде көлемінің уақытша өзгеруі. Босану кезінде бөпеңіздің басы босану жолынан өтуі үшін сол жолдың пішіні мен көлеміне бейімделіп қалыптасуы қажет. Бөпеңіздің басы босану жолынан өткенде алға иілу, ішке бұрылу, шалқаю және сыртқа бұрылу сияқты қозғалыстар жасайды. Осы үдеріс барысында бас сүйектері олардың арасындағы иілгіш шеміршек тінінің арқасында бір-біріне жақындап, бірінің үстіне бірі ығысады. Босану жолынан өту кезінде жұмсақ тіндердің жылдам пішін өзгертуіне байланысты бас аймағында кейбір уақытша қисықтықтар байқалуы мүмкін. Жаңа туған бөпелердің бас сүйегі пішінінің өзгеруіне бөпенің ана құрсағындағы қалпы, босанудың ұзақ әрі қиын өтуі, бөпенің инкубаторда жатуы немесе мойын бұлшықеттерінің қысқалығы себеп болуы мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен басымды төмен қаратып жатырмын ба? 🙃 Мен қазірдің өзінде басымды төмен қаратып жататын қалыпқа (баспен келу) ауысуға тырысып жүрген шығармын. Бұл — босануға ең қолайлы қалып. Бірақ әлі бұрылмаған болсам, уайымдамаңыз, менің әлі уақытым бар. Маған тартылыс күші ұнайды, басым ауыр болғандықтан төмен түскен ыңғайлы.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Кокос'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік — әйел өміріндегі салмақ ең жылдам қосылатын кезеңдердің бірі. Жүктілік кезінде гормондар деңгейінің жоғарылауына және бөпеңіздің дамуын қолдау қажеттілігіне байланысты жиі ашығуыңыз мүмкін. Ашыққан кезде жеңіл тағамдармен жүрек жалғамасаңыз, калориясы жоғары тағамдарды үлкен мөлшерде жеуіңіз ықтимал. Жүктілікке дейін дене салмағының индексі қалыпты немесе төмен болған әйелдер бұл кезеңде орта есеппен 10-12 килограмм салмақ қосады. Ал жүктілікке дейін артық салмағы болған әйелдер осы кезеңде одан да көп салмақ қосуға бейім келеді. Мұның негізгі себебі — дұрыс тамақтанбау әдеті бар әйелдердің жүктілік кезінде де сол әдеттерін жалғастырып, тіпті күшейтуі.;;;
Құнарсыз әрі бос калориялы тағамдарды тұтынудың орнына күніне 3 порция жеміс жеп, ақуызы мол негізгі тағамдарды таңдаңыз, жеңіл ас мәзіріне сүт пен сүт өнімдерін міндетті түрде қосыңыз және жүйелі түрде жеңіл жаттығулар жасаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ұйықтардан 2-3 сағат бұрын тамақтануды тоқтатыңыз. Сүт ішу немесе бір уыс шикі бадам жеу асқазан қышқылын бейтараптандыруға көмектеседі. Қышқыл және ащы тағамдардан аулақ болыңыз.') WHERE id = '805cdfb6-2608-4845-b4aa-f6272786a6f0';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '8-айға аяқ басқан осы аптада өкпенің дамуы қарқынды жалғасады. 28-36-апталар аралығында өкпе «саккулярлық» кезеңде болады. Өкпе қапшық тәрізді болатын бұл кезеңде бронхтарды қалыптастыратын беткі қабат жұқарып, өкпедегі қылтамырлар жылдам көбейеді. Бөпеңіздің өкпесі толық дамып болғанда, шамамен 300 миллион ауа қапшығы қалыптасады. Көп ұзамай бұл ауа қапшықтарының айналасы сурфактант деп аталатын затпен толығымен қаптала бастайды. Сурфактант осы қапшықтардағы зат алмасуға көмектеседі және беткі керілуді азайтып, тіпті терең тыныс алғанда да өкпенің өз қызметін еш қиындықсыз атқаруын қамтамасыз етеді. Мерзімінен бұрын босану қаупі бар болашақ аналарға салынатын өкпені жетілдіретін екпелер өкпедегі сурфактант өндірісін жылдамдатады. Соның нәтижесінде шала туған бөпелер тыныс алу қиындығын қысқа уақыт сезінеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Өкпем жетіліп келеді! 🌬️ Өкпемдегі альвеолалар күн сайын дами түсуде. «Сурфактант» мөлшері артып жатыр. Егер қазір дүниеге келсем, маған әлі де көмек қажет болады, бірақ мүмкіндігім өте жоғары. Мен күн сайын күшейіп келемін. Сен маған тағы біраз уақыт берсең болғаны.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, '8-айға аяқ басқан осы күндері айына 2-4 килограмм, ал аптасына орта есеппен 500 грамм салмақ қосуыңыз қалыпты. Бұл апталарда бөпенің қарқынды дамуына байланысты ішіңіз едәуір үлкейіп, қимыл-қозғалысыңыз айтарлықтай шектеледі. Үлкейген іш қыжыл мен ентігуді туындатуы мүмкін. Мұндай жағдайда аз мөлшерде, бірақ жиі тамақтану және сол жақ қырыңызбен жату өте пайдалы. Бұл апталарда жүру немесе отырған жерден тұру секілді қимылдар айтарлықтай қиындауы мүмкін. Мұның себебі — жүктілік кезінде буындарыңыз бен бұлшықеттеріңіздің босаңсуы. Осыған байланысты қозғалу қиын болса да, қимылсыз қалу жағдайды одан әрі нашарлатуы мүмкін. Өзіңізді шаршатпай, қысқа уақыт серуендеп, жеңіл жаттығулар жасағаныңыз жеткілікті.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қыжылды азайту үшін аз мөлшерде, бірақ жиі тамақтаныңыз. Ұйықтағанда сол жақ қырыңызбен жатуға тырысыңыз; бұл ас қорытуыңызға да, бөпенің қан айналымына да көмектеседі. Беліңіз ауырса, арқаңызды тіреп тұратын жастықтарды міндетті түрде пайдаланыңыз. Бүгін өзіңізге біраз уақыт бөліп, босану сөмкесіне қажетті заттардың тізімін толықтыра бастаңыз.') WHERE id = '073c7d59-96b0-4ee4-a0d5-1e595fd135fb';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '8-ай басталатын 32-аптада май және бұлшықет тіндерінің өсуі қарқынды жалғасады. Соның арқасында терісі жұмсақ әрі тегіс бола түсті. Тері астына жиналған майдың арқасында терінің мөлдір көрінісі енді толығымен дерлік жоғалды. Осы аптадан бастап бөпеңіздің денесін жауып тұрған лануго түктері де түсе бастайды. Лануго — 20-аптадан кейін бөпеңіздің денесін жабатын жібектей жұқа түктердің атауы. Бұл түктер түссіз әрі жұмсақ болады және маңдайда, арқада және бетте тығызырақ өседі. Тері жұқа болатын кезеңде лануго түктері бөпеңіздің денесін жылы ұстап, инфекциялардан қорғауға көмектеседі. Шала туған бөпелерде жиі кездесетін бұл түктер босанғаннан кейін көп ұзамай түсе бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен тыныс алып жаттығудамын 🌬️ Anacan, менің кеуде қуысым бірқалыпты көтеріліп-түседі. Мен қағанақ суын өкпеме тартып, қайта шығарамын. Бұл дүниеге келгенде алғашқы әрі ең маңызды тынысымды алуым үшін бұлшықеттерімді нығайтады. Сен кейде менің ырғақты қимылдарымды (ықылықтағанымды) сезуің мүмкін. Бұл — менің жаттығуым!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жапырақты салат'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл кезеңде біржақты тамақтанудан аулақ болу қажет. Теңгерімді әрі жеткілікті тамақтану ағзаңыздың дәрумендер мен минералдарға деген барлық қажеттілігін өтейді. Алғашқы үш айда ұрықтың қажеттілігі үшін қосымша калория қажет емес. Екінші үш айлық кезеңнен бастап күніне қосымша 300 калория тұтынуыңыз бөпенің дамуы үшін жеткілікті. Қажетті мөлшерден артық калория бөпеңізге пайда әкелмейтінін, оның ағзаңызда май түрінде жиналатынын білгеніңіз жөн. Ауруханада өзіңізге және бөпеңізге қажет болатын киімдер мен басқа да заттарды қазірден дайындап қойғаныңыз пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күні бойы кальцийге бай тағамдарды міндетті түрде тұтыныңыз, өйткені бөпеңіздің сүйектері дәл қазір ең қарқынды қатаю кезеңінде. Беліңіз ауырса, жеңіл созылу жаттығуларын жүйелі түрде жасап, ұйықтағанда сол жақ қырыңызбен жатуға тырысыңыз.') WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';